def release_migration_report_text(
    version: str | None = None,
    wip_safe: bool = False,
    products_tested: list[str] | None = None,
) -> str:
    return json.dumps(
        release_migration_report_data(version=version, wip_safe=wip_safe, products_tested=products_tested),
        indent=2,
        sort_keys=True,
    ) + "\n"


def release_migration_report(args: argparse.Namespace) -> int:
    version = args.version or methodology_version()
    output = (args.output or release_migration_report_path(version)).resolve()
    products_tested = args.product_tested or []
    if args.check and not args.write and not args.product_tested and output.exists():
        try:
            existing = json.loads(output.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError):
            existing = {}
        if isinstance(existing, dict) and isinstance(existing.get("productsTested"), list):
            products_tested = [str(item) for item in existing["productsTested"]]
    text = release_migration_report_text(version=version, wip_safe=args.wip_safe, products_tested=products_tested)
    if args.write:
        write_text_atomic(output, text)
        print(f"release_migration_report_written: {output}")
    if args.check:
        try:
            current = output.read_text(encoding="utf-8")
        except OSError as exc:
            print(f"release_migration_report_check: missing/unreadable {output}: {exc}", file=sys.stderr)
            return 1
        if current != text:
            print(f"release_migration_report_check: stale {output}", file=sys.stderr)
            return 1
        print(f"release_migration_report_check: ok {output}")
    if args.print_report or not (args.write or args.check):
        print(text, end="")
    return 0


def audit(args: argparse.Namespace) -> int:
    data = load_project(args.project)
    target = args.target.resolve()
    files = [
        "CLAUDE.md",
        "AGENTS.md",
        ".clauderules",
        ".cursorrules",
        "scripts/codex-review-prompt.md",
        "docs/ai-pr-workflow.md",
        "docs/ops/codex-claude-operating-charter-v1.md",
        "docs/ops/claude-continuous-execution-model-v1.md",
    ]
    checks: list[tuple[str, re.Pattern[str], str]] = [
        ("routine-admin-merge", re.compile(r"gh pr merge .+--admin"), "Routine admin merge must be removed."),
        ("watch-until-merged", re.compile(r"watch the queue|until .*MERGED|block .*until .*merge", re.I), "Use queue-and-move-on policy for clean queued PRs."),
        ("wrong-merge-queue-signal", re.compile(r"(poll|watch|wait|wakeup|reschedul|still reports|reports AWAITING_CHECKS).{0,120}(mergeQueueEntry|estimatedTimeToMerge|AWAITING_CHECKS)|(mergeQueueEntry|estimatedTimeToMerge).{0,120}(poll|watch|wait|wakeup|reschedul|still reports|reports AWAITING_CHECKS)", re.I), "Exceptional merge checks must use PR state as the terminal signal."),
        ("merge-known-blockers", re.compile(r"(round|pass)\s*\d+.*(document|defer|deferred).*(merge|ship)|3 rounds maximum", re.I | re.S), "Round caps must not permit Critical/P1 defects."),
        ("local-readiness-fetch", re.compile(r"git\s+fetch\s+origin|Use only .+Lane\d+ workspace", re.I), "Readiness automation must be GitHub-only."),
        ("stale-lane", re.compile(r"(?:[A-Za-z][A-Za-z0-9_-]*-)?Codex-Lane\d+|[A-Za-z][A-Za-z0-9_-]*-Lane[2-9]\d*|Lane[- ]?[2-9]\d* workspace", re.I), "Stale lane reference."),
    ]
    findings: list[str] = []
    for rel in files:
        path = target / rel
        if not path.exists():
            continue
        text = path.read_text(encoding="utf-8", errors="replace")
        for name, pattern, message in checks:
            if pattern.search(text):
                findings.append(f"{name}: {path} - {message}")
    if findings:
        print("Process drift findings:")
        for finding in findings:
            print(f"- {finding}")
    else:
        print("No known process drift found.")
    # Both branches print the table: an audit that reports doc drift while staying silent about a
    # lane enforcing none of its quality controls answers the smaller question. The legacy lines
    # above are byte-identical and still first, and posture never sets the exit code.
    posture_rows = control_posture_rows(data, target)
    print(control_posture_summary_line(posture_rows))
    for row in posture_rows:
        print(control_posture_detail_line(row, "control_posture_row"))
    return 1 if findings else 0




def gh_content(repo: str, path: str, ref: str) -> str | None:
    try:
        data = gh_api(f"repos/{repo}/contents/{path}?ref={ref}")
    except subprocess.CalledProcessError:
        return None
    content = data.get("content")
    if not content:
        return None
    return base64.b64decode(content).decode("utf-8", errors="replace")








READINESS_ALARM_PATTERN = re.compile(r"error[_ -]?id|\balarm\b|\balert\b|on[_ -]?call|pagerduty|opsgenie|sentry|cloudwatch alarm", re.IGNORECASE)


def readiness_alarm_content_issues(contents: dict) -> list[str]:
    """An errorId-alarm content check (rec #9, P5): each declared alarm source must actually wire an
    errorId/alarm, so detection is not outsourced to a human happening to look."""
    issues: list[str] = []
    for path, content in contents.items():
        if content is None:
            issues.append(f"alarm source missing: {path}")
        elif not READINESS_ALARM_PATTERN.search(content):
            issues.append(f"alarm source {path} has no errorId/alarm wiring: detection is outsourced to humans (P5)")
    return issues


def readiness_review(args: argparse.Namespace) -> int:
    readiness: dict = {}
    if args.project:
        data = load_project(args.project)
        repo = data["repo"]
        readiness = data.get("readiness", {}) or {}
        sources = readiness.get("sources", [])
    elif args.repo:
        repo = args.repo
        sources = args.source or []
    else:
        raise SystemExit("readiness-review requires --project or --repo")
    if not sources:
        raise SystemExit("readiness-review requires readiness.sources in the project adapter or at least one --source")
    repo_data = gh_api(f"repos/{repo}")
    branch = repo_data["default_branch"]
    branch_data = gh_api(f"repos/{repo}/branches/{branch}")
    sha = branch_data["commit"]["sha"]
    print(f"repo: {repo}")
    print(f"default_branch: {branch}")
    print(f"sha: {sha}")
    print("sources:")
    for path in sources:
        content = gh_content(repo, path, sha)
        status = "present" if content is not None else "missing"
        print(f"- {path}: {status}")
        if content:
            first_heading = next((line for line in content.splitlines() if line.startswith("#")), "")
            if first_heading:
                print(f"  heading: {first_heading}")
    runs = gh_api(f"repos/{repo}/actions/runs?branch={branch}&per_page=20")
    workflow_runs = runs.get("workflow_runs", [])
    print("recent_workflow_runs:")
    for run in workflow_runs[:5]:
        print(f"- {run['name']}: {run['status']} / {run.get('conclusion')} @ {run['head_sha'][:12]}")

    # Detection-baseline gate (rec #9): fail-closed for a customer-facing target when opted in
    # (readiness.enforcement=block) or when --strict is passed. Default stays informational (return 0).
    enforcement = str(readiness.get("enforcement", "off")).strip().lower()
    if not (args.strict or enforcement == "block"):
        return 0
    required_checks = [str(c) for c in (readiness.get("requiredChecks") or [])]
    canary_name = str(readiness.get("canaryWorkflow", "")).strip()
    alarm_sources = [str(p) for p in (readiness.get("alarmSources") or [])]
    issues: list[str] = []
    issues.extend(branch_protection_issues(gh_api_opt(f"repos/{repo}/branches/{branch}/protection"), required_checks))
    canary_issue = canary_conclusion_issue(workflow_runs, canary_name, sha)
    if canary_issue:
        issues.append(canary_issue)
    if alarm_sources:
        issues.extend(readiness_alarm_content_issues({path: gh_content(repo, path, sha) for path in alarm_sources}))
    print("detection_baseline:")
    for issue in issues:
        print(f"readiness_issue: {issue}", file=sys.stderr)
    if issues:
        print("readiness_review: FAIL (detection baseline not met)", file=sys.stderr)
        return 1
    print("readiness_review: pass (detection baseline met)")
    return 0






def background_run_runs_dir(adapter_data: dict | None, adapter_root: Path | None) -> Path | None:
    """The lane's configured runs directory, or None when there is no adapter to configure it.

    Resolved from `laneState.runsDir` rather than hardcoded: the turn-end yield gate scans the
    CONFIGURED directory, and a lane that moved it would otherwise be told its run is inside the
    gate's scan when it is not -- an advisory that is wrong in the reassuring direction.
    """
    if adapter_data is None or adapter_root is None:
        return None
    configured = str((adapter_data.get("laneState") or {}).get("runsDir") or "").strip()
    if not configured:
        configured = str(DEFAULT_LANE_STATE["runsDir"])
    return (adapter_root / configured).resolve(strict=False)


def background_run(args: argparse.Namespace) -> int:
    if not args.command:
        raise SystemExit("background-run requires a command after --")
    env = os.environ.copy()
    codex_fast_mode_state = "unmanaged"
    adapter_data: dict | None = None
    adapter_root = find_adapter_root(Path.cwd())
    if adapter_root:
        adapter_data = load_project(adapter_marker_path(adapter_root))
        env = codex_fast_mode_env(adapter_data, adapter_root, env)
        codex_fast_mode_state = codex_fast_mode_status(adapter_data)
    timeout_seconds = int(args.timeout_seconds or 0)
    if timeout_seconds < 0:
        raise SystemExit("--timeout-seconds must be zero or positive")
    if timeout_seconds and not hasattr(os, "killpg"):
        raise SystemExit("--timeout-seconds requires POSIX process-group support")
    log = args.log.resolve()
    log.parent.mkdir(parents=True, exist_ok=True)
    # MISSING-cost (productization): fan-out runaway guard. Opt-in via the adapter's
    # costPreferences.fanOutCap; absent => no change. Too many concurrent agent/background runs
    # drive unbounded model spend, so refuse to exceed the cap (override with the env escape).
    fanout_cap = (adapter_data or {}).get("costPreferences", {}).get("fanOutCap")
    if (
        isinstance(fanout_cap, int)
        and fanout_cap > 0
        and util_module().resolve_env("MINERVIT_METHODOLOGY_ALLOW_FANOUT") != "1"
    ):
        live = count_live_background_runs(log.parent)
        if live >= fanout_cap:
            raise SystemExit(
                f"background-run refused: {live} live background run(s) already active in {log.parent} "
                f">= costPreferences.fanOutCap ({fanout_cap}). Fan-out runaway guard (MISSING-cost): "
                "concurrent agent runs drive unbounded model spend. Wait for runs to finish, raise "
                "costPreferences.fanOutCap, or set MINERVIT_METHODOLOGY_ALLOW_FANOUT=1 to override."
            )
    started_at = time.strftime("%Y-%m-%dT%H:%M:%S")
    pid_file = log.with_name(f"{log.name}.pid")
    meta_file = log.with_name(f"{log.name}.meta.json")

    with log.open("ab") as f:
        f.write(f"\n[minervit] starting at {started_at}: {redact_secrets(' '.join(args.command))}\n".encode())
        if timeout_seconds:
            f.write(f"[minervit] timeout_seconds: {timeout_seconds}\n".encode())
    # A REAPER OWNS THE COMMAND, and that is the whole point of this change.
    #
    # `background-run` used to Popen the command and return, which means nothing in this process
    # tree ever calls wait() -- so nothing can know the command's exit code, and nothing ever
    # records that it finished. A monitor could only guess from a dead pid, and "the pid is gone"
    # and "the pid never started" are the same observation. That is the completion-truth gap: the
    # tool that launches the work cannot say whether the work succeeded.
    #
    # So the launcher spawns a detached reaper, the reaper spawns the command and wait()s on it,
    # and the reaper writes both the terminal log line and the meta fields. This process then reads
    # the child pid back from the pid file the reaper wrote.
    #
    # Crash-safety, recorded rather than assumed: if the reaper dies, meta simply never gains
    # `finishedAt`. A consumer seeing a dead pid with no `finishedAt` must treat it as finished and
    # UNREAD, which is the fail-safe direction -- it reports an unknown as unfinished business
    # rather than as success.
    reaper_code = r"""
import json
import os
import subprocess
import sys
import time
from pathlib import Path

log_path = Path(sys.argv[1])
pid_file = Path(sys.argv[2])
meta_path = Path(sys.argv[3])
command = sys.argv[4:]

try:
    with log_path.open("ab") as handle:
        proc = subprocess.Popen(
            command, stdout=handle, stderr=subprocess.STDOUT, env=os.environ, start_new_session=True
        )
except OSError as exc:
    # A command that cannot START -- missing binary, not executable -- produced nothing at all:
    # no pid, no log line, and the launcher's bounded readback then reported only that the reaper
    # never named a pid, which is true and useless. The failure is written where a reader will
    # look, and recorded as a real exit code so `monitor-status` classifies it rather than
    # inferring staleness (Codex R3).
    finished_at = time.strftime("%Y-%m-%dT%H:%M:%S")
    with log_path.open("ab") as handle:
        handle.write(
            f"\n[tautline] launch failed: {exc}\n"
            f"[tautline] finished: exit=127 at {finished_at} log={log_path.name}\n".encode()
        )
    try:
        meta = json.loads(meta_path.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        meta = {}
    meta.update({"finishedAt": finished_at, "exitCode": 127, "launchError": str(exc)})
    meta_path.write_text(json.dumps(meta, indent=2) + "\n", encoding="utf-8")
    # No pid sentinel: "0" is not a pid, and anything reading it as one is being told a falsehood
    # about a process that never existed. Ownership is NOT unlinked here either -- this process is
    # about to exit, and a dead owner IS the release. Unlinking early let a later run claim the log
    # while the launcher was still in its bounded readback (Codex v2 R2).
    raise SystemExit(127)
pid_file.write_text(f"{proc.pid}\n", encoding="utf-8")
rc = proc.wait()
finished_at = time.strftime("%Y-%m-%dT%H:%M:%S")
# THE RECEIPT IS PUBLISHED FIRST, then the log marker. Both say the run finished, and this release
# tells consumers to trust the receipt -- so the marker must never appear while the receipt is still
# absent. Written the other way round, a consumer that saw the marker and then read the metadata got
# a run with no exitCode and would classify it as stale: the visible signal arriving before the
# authoritative one it points at (Codex v2 R4).
# Atomic: a consumer polling meta must never read a half-written object.
for _attempt in range(50):
    try:
        meta = json.loads(meta_path.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        time.sleep(0.1)
        continue
    # BOUND TO THE RUN THAT PRODUCED IT. If a later launcher has reused this --log path while
    # this command was still running, the metadata now describes ITS run, and writing our exit
    # result into it would report completion for a command that is still live -- a false success
    # on the very receipt this release adds. Only write when the metadata still names our pid.
    if meta.get("pid") not in (None, proc.pid):
        break
    # A watchdog kill is recorded DISTINCTLY. Reporting only the child's exit code conflates
    # "the command chose to exit with this" and "we terminated it for running too long" -- and a
    # SIGTERM-derived code is a plausible exit code for a program to return, so a consumer cannot
    # tell them apart from the number alone. The whole point of this release is a receipt that says
    # what happened (Codex R5).
    timeout_marker = Path(str(log_path) + ".timedout")
    timed_out = timeout_marker.exists()
    meta.update({"finishedAt": finished_at, "exitCode": rc, "timedOut": timed_out})
    tmp = meta_path.with_suffix(".tmp")
    tmp.write_text(json.dumps(meta, indent=2) + "\n", encoding="utf-8")
    tmp.replace(meta_path)
    break

with log_path.open("ab") as handle:
    handle.write(
        f"\n[tautline] finished: exit={rc} at {finished_at} log={log_path.name}\n".encode()
    )

# The lock is NOT unlinked. Ownership ends when this process does, which the staleness check reads
# from the lock's own pid -- and every "release it here" placement tried so far released it a moment
# too early for some path. A dead owner is the release; there is no ordering to get wrong.
"""
    # REFUSE to share a log path with a LIVE run. Three consecutive review rounds found attribution
    # defects that all reduce to one ambiguity: two runs writing one log cannot have distinguishable
    # receipts or terminal markers, so a completion from either can be read as the other's. Patching
    # each path -- the pid readback, the metadata write, the finished marker -- treats the symptoms
    # of a design that permits the collision. Refusing the overlap removes it (Codex R3).
    #
    # A DEAD previous run is fine and stays supported: its receipts are cleared below, which is the
    # ordinary case of rerunning a command into the same log.
    # Ownership is ACQUIRED ATOMICALLY, not checked. The previous version read the pid file, tested
    # liveness, then proceeded -- classic check-then-act: two launchers can both pass the test and
    # both proceed, which is the very collision the check was added to prevent (Codex R4). O_EXCL
    # makes exactly one creator win, with no window.
    # Clear the previous (now dead) run's receipts, or the readback below can accept the OLD pid and
    # arm the timeout watchdog against a process this launcher never started (Codex R1).
    for receipt in (pid_file, meta_file, log.with_name(f"{log.name}.timedout")):
        try:
            receipt.unlink()
        except FileNotFoundError:
            pass
        except OSError:
            raise SystemExit(
                f"background-run: could not clear the stale receipt {receipt}; refusing to launch "
                "rather than risk arming the watchdog against a previous run's pid"
            ) from None

    reaper = subprocess.Popen(
        [sys.executable, "-c", reaper_code, str(log), str(pid_file), str(meta_file), *args.command],
        stdout=subprocess.DEVNULL,
        stderr=subprocess.DEVNULL,
        env=env,
        start_new_session=True,
    )
    # Bounded, never unbounded: if the reaper cannot report a pid in five seconds it has failed,
    # and hanging here would turn a launcher into the very stalled process this cluster is about.
    command_pid: int | None = None
    deadline = time.time() + 5.0
    while time.time() < deadline:
        try:
            command_pid = int(pid_file.read_text(encoding="utf-8").strip())
            break
        except (OSError, ValueError):
            time.sleep(0.05)
    if command_pid is None:
        raise SystemExit(
            f"background-run: the reaper did not report a command pid within 5s (log {log}). "
            "The command may not have started; inspect the log and retry."
        )

    class _CommandHandle:
        pid = command_pid

    proc = _CommandHandle()
    pid_identity = process_identity(command_pid)
    watchdog_pid: int | None = None
    watchdog_pid_file: Path | None = None
    if timeout_seconds:
        watchdog_pid_file = log.with_name(f"{log.name}.watchdog.pid")
        watchdog_code = r"""
import os
import signal
import sys
import time
from pathlib import Path

pid = int(sys.argv[1])
timeout_seconds = int(sys.argv[2])
log_path = Path(sys.argv[3])
expected_identity = sys.argv[4]

def process_identity(pid):
    try:
        proc = __import__("subprocess").run(
            ["ps", "-p", str(pid), "-o", "lstart="],
            text=True,
            stdout=__import__("subprocess").PIPE,
            stderr=__import__("subprocess").DEVNULL,
            check=False,
        )
    except OSError:
        return None
    if proc.returncode != 0 or not proc.stdout.strip():
        return None
    return " ".join(proc.stdout.split())

time.sleep(timeout_seconds)
try:
    os.kill(pid, 0)
except ProcessLookupError:
    raise SystemExit(0)
except OSError:
    raise SystemExit(0)
current_identity = process_identity(pid)
if not expected_identity or not current_identity or current_identity != expected_identity:
    with log_path.open("ab") as handle:
        handle.write(
            (
                f"\n[minervit] timeout after {timeout_seconds}s; not terminating process group {pid} "
                f"because process identity could not be verified\n"
            ).encode()
        )
    raise SystemExit(0)
with log_path.open("ab") as handle:
    handle.write(f"\n[minervit] timeout after {timeout_seconds}s; terminating process group {pid}\n".encode())
# Written BEFORE the signal and RETRACTED if no signal lands. Both orderings are wrong on their own:
# after the kill, the reaper can wake from the terminated child and read the marker before the
# watchdog writes it, so a real timeout is missed; before the kill without retraction, a process
# that exited on its own in that window is labelled terminated. Write-then-retract has neither race,
# because the marker only survives when a signal was actually delivered (Codex v2 R2).
timeout_marker = Path(str(log_path) + ".timedout")
try:
    timeout_marker.write_text(f"{timeout_seconds}\n", encoding="utf-8")
except OSError:
    pass
try:
    os.killpg(pid, signal.SIGTERM)
except ProcessLookupError:
    # It finished on its own between the liveness check and the signal. Nothing was terminated, so
    # nothing is a timeout.
    try:
        timeout_marker.unlink()
    except OSError:
        pass
    raise SystemExit(0)
except OSError as exc:
    with log_path.open("ab") as handle:
        handle.write(f"[minervit] timeout SIGTERM failed: {exc}\n".encode())
time.sleep(5)
try:
    os.kill(pid, 0)
except ProcessLookupError:
    raise SystemExit(0)
except OSError:
    raise SystemExit(0)
try:
    os.killpg(pid, signal.SIGKILL)
    with log_path.open("ab") as handle:
        handle.write(f"[minervit] timeout SIGKILL sent to process group {pid}\n".encode())
except ProcessLookupError:
    pass
except OSError as exc:
    with log_path.open("ab") as handle:
        handle.write(f"[minervit] timeout SIGKILL failed: {exc}\n".encode())
"""
        watchdog = subprocess.Popen(
            [sys.executable, "-c", watchdog_code, str(proc.pid), str(timeout_seconds), str(log), pid_identity or ""],
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
            start_new_session=True,
        )
        watchdog_pid = watchdog.pid
        watchdog_pid_file.write_text(f"{watchdog_pid}\n", encoding="utf-8")
    # MERGED, never overwritten. The launcher writes this after spawning the reaper, so a command
    # that finishes quickly has already had `finishedAt` and `exitCode` published -- and a plain
    # write would erase exactly the completion record this release exists to produce, for precisely
    # the fastest runs. Reaper-owned keys win; launcher-owned keys fill in the rest (Codex R1).
    published: dict = {}
    try:
        existing = json.loads(meta_file.read_text(encoding="utf-8"))
        if isinstance(existing, dict):
            published = {
                key: existing[key]
                for key in ("finishedAt", "exitCode", "launchError")
                if key in existing
            }
    except (OSError, ValueError):
        published = {}
    meta_file.write_text(
        json.dumps(
            {
                **published,
                "command": args.command,
                "cwd": os.getcwd(),
                "startedAt": started_at,
                "pid": proc.pid,
                "pidIdentity": pid_identity,
                "pidFile": str(pid_file),
                "log": str(log),
                "timeoutSeconds": timeout_seconds,
                "codexFastMode": codex_fast_mode_state,
                "watchdogPid": watchdog_pid,
                "watchdogPidFile": str(watchdog_pid_file) if watchdog_pid_file else None,
                "reaperPid": reaper.pid,
                **published,
            },
            indent=2,
        )
        + "\n",
        encoding="utf-8",
    )
    print(f"pid: {proc.pid}")
    print(f"pid_file: {pid_file}")
    if timeout_seconds:
        print(f"timeout_seconds: {timeout_seconds}")
        print(f"watchdog_pid: {watchdog_pid}")
        print(f"watchdog_pid_file: {watchdog_pid_file}")
    print(f"meta_file: {meta_file}")
    print(f"log: {log}")
    # NOT `tail -F`. The tool that launches background work must not recommend the unbounded form
    # it refuses elsewhere: `tail -F` never exits, so it cannot report completion, and a lane that
    # follows this line is watching a stream that can go quiet for either reason -- finished, or
    # wedged. `monitor-status` reads the receipts the reaper writes and can tell those apart.
    # shlex.quote: this line is printed to be COPIED AND RUN, and a log path with a space or a
    # shell metacharacter would otherwise produce a command that silently monitors the wrong file
    # or fails. A remedy that does not survive being pasted is a dead end (Codex v2 R2).
    print(f"monitor: {CLI_NAME} monitor-status --target . --log {shlex.quote(str(log))}")
    runs_dir = background_run_runs_dir(adapter_data, adapter_root)
    if runs_dir is not None and runs_dir not in log.parents:
        print(
            f"advisory: {log} is outside this lane's configured runsDir ({runs_dir}), so the "
            "turn-end yield gate -- which scans that directory -- will not see this run. Move the "
            "log under the runsDir if the run should hold the turn open."
        )
    return 0






def monitor_status(args: argparse.Namespace) -> int:
    target = args.target.resolve()
    log = cli_path(target, str(args.log)).resolve(strict=False)
    max_stale_seconds = int(args.max_stale_seconds)
    if max_stale_seconds < 1:
        raise SystemExit("--max-stale-seconds must be positive")

    pid: int | None = args.pid
    if pid is not None and pid < 1:
        raise SystemExit("--pid must be positive")
    pid_source = "argument" if pid is not None else "none"
    meta_path = log.with_name(f"{log.name}.meta.json")
    meta: dict = {}
    if meta_path.exists():
        try:
            loaded_meta = json.loads(meta_path.read_text(encoding="utf-8"))
            if isinstance(loaded_meta, dict):
                meta = loaded_meta
        except (OSError, json.JSONDecodeError):
            meta = {}
    pid_file: Path | None = None
    if pid is None:
        if args.pid_file:
            pid_file = cli_path(target, str(args.pid_file)).resolve(strict=False)
        elif meta.get("pidFile"):
            pid_file = Path(str(meta["pidFile"]))
        else:
            candidate = log.with_name(f"{log.name}.pid")
            pid_file = candidate if candidate.exists() else None
        if pid_file is not None:
            pid = read_pid_file(pid_file)
            pid_source = str(pid_file) if pid is not None else f"{pid_file} (unreadable)"
    pid_state = "unknown"
    pid_identity_state = "not_checked"
    expected_pid_identity = None
    if pid is not None and meta.get("pid") == pid:
        expected_pid_identity = meta.get("pidIdentity")
    if pid is not None:
        if not pid_is_live(pid):
            pid_state = "dead"
        else:
            current_identity = process_identity(pid)
            if expected_pid_identity:
                if current_identity == expected_pid_identity:
                    pid_state = "live"
                    pid_identity_state = "verified"
                elif current_identity:
                    pid_state = "mismatched"
                    pid_identity_state = "mismatched"
                else:
                    pid_state = "unverified"
                    pid_identity_state = "unavailable"
            else:
                pid_state = "live"
                pid_identity_state = "unavailable"
    timeout_seconds_meta = int(meta.get("timeoutSeconds") or 0)
    watchdog_pid = meta.get("watchdogPid")
    watchdog_state = "not_configured"
    if timeout_seconds_meta:
        if isinstance(watchdog_pid, int) and watchdog_pid > 0:
            watchdog_state = "live" if pid_is_live(watchdog_pid) else "dead"
        else:
            watchdog_state = "missing"

    if not log.exists():
        print("monitor_state: missing")
        print(f"monitor_log: {log}")
        print(f"monitor_pid: {pid if pid is not None else 'unknown'}")
        print(f"monitor_pid_state: {pid_state}")
        print(f"monitor_pid_identity_state: {pid_identity_state}")
        print(f"monitor_timeout_seconds: {timeout_seconds_meta}")
        print(f"monitor_watchdog_pid: {watchdog_pid if watchdog_pid else 'none'}")
        print(f"monitor_watchdog_state: {watchdog_state}")
        print("monitor_reason: log file does not exist")
        print("monitor_next_action: treat as failed/stale monitor; inspect launch evidence and rerun or recover the command")
        # The receipt is written HERE TOO. If a completed run's log was deleted while its pid and
        # metadata sidecars remain, the yield gate reports the summary unread and names this
        # command -- which returned before writing anything, so running the prescribed remedy could
        # never clear the finding. A refusal whose own remedy cannot satisfy it is worse than the
        # gap it covers.
        _write_monitor_read_receipt(log, state="missing", finished_at=meta.get("finishedAt"), pid=meta.get("pid"))
        return 1 if args.strict else 0

    stat = log.stat()
    now = time.time()
    age_seconds = max(0, int(now - stat.st_mtime))
    modified_at = datetime.fromtimestamp(stat.st_mtime).astimezone().isoformat(timespec="seconds")

    tail_text = ""
    try:
        with log.open("rb") as handle:
            handle.seek(0, os.SEEK_END)
            size = handle.tell()
            handle.seek(max(0, size - 8192), os.SEEK_SET)
            tail_text = handle.read().decode("utf-8", errors="replace")
    except OSError:
        tail_text = ""

    success_marker = args.success_marker or ""
    failure_marker = args.failure_marker or ""
    has_success_marker = bool(success_marker and success_marker in tail_text)
    has_failure_marker = bool(failure_marker and failure_marker in tail_text)

    # The RECORDED completion outranks every inference below it, because it is the only
    # authoritative signal here: the reaper waited on the command and wrote what it returned.
    # Without this the printed `monitor:` line was a worse recommendation than the `tail -F` it
    # replaced -- both exit 0 and exit 3 classify as `stale` once the pid dies, so a caller
    # following the advice this release prints could not tell success from failure, which is the
    # exact confusion the reaper exists to end (Codex R1).
    recorded_exit = meta.get("exitCode")
    finished_at = meta.get("finishedAt")
    if pid is not None and meta.get("pid") not in (None, pid):
        # The receipt describes a DIFFERENT run than the pid the caller asked about, so it is not
        # evidence about this one. Trusting it would report another run's completion (Codex R3).
        recorded_exit = None
        finished_at = None
    if has_failure_marker:
        # An explicit caller-supplied failure marker is NOT an inference to be outranked -- it is
        # the caller declaring what failure looks like for a tool whose exit code is insufficient,
        # which is the entire reason the flag exists. Placing the recorded exit above it made a
        # command that exits 0 while printing that marker report `success` (Codex R2).
        state = "failed"
        reason = f"failure marker found: {failure_marker}"
        next_action = (
            "treat as failed monitor; inspect the log and repair before continuing dependent work"
        )
    elif isinstance(recorded_exit, int) and finished_at:
        if meta.get("timedOut"):
            # Checked BEFORE the exit code, not after. A process group terminated by the watchdog
            # can still leave a zero exit -- a wrapper that traps SIGTERM and exits cleanly, or a
            # shell reporting its last successful builtin -- and ordering success first reported
            # that run as a SUCCESS. The receipt says it was killed; the number does not (Codex R1).
            state = "failed"
            state = "failed"
            reason = (
                f"run was TERMINATED BY THE TIMEOUT WATCHDOG at {finished_at} "
                f"(exit {recorded_exit}); it did not choose to exit"
            )
            next_action = (
                "treat as timed out; raise --timeout-seconds or fix what made the command hang"
            )
        elif recorded_exit == 0 or has_success_marker:
            state = "success"
            reason = (
                f"success marker found: {success_marker}"
                if has_success_marker and recorded_exit != 0
                else f"run finished at {finished_at} with exit 0 (recorded by the reaper)"
            )
            next_action = "consume the result and continue with the next authorized action"
        else:
            state = "failed"
            reason = f"run finished at {finished_at} with exit {recorded_exit} (recorded by the reaper)"
            next_action = (
                "treat as failed; inspect the log tail and repair before continuing dependent work"
            )
    elif has_failure_marker:
        state = "failed"
        reason = f"failure marker found: {failure_marker}"
        next_action = "treat as failed monitor; inspect the log and repair before continuing dependent work"
    elif has_success_marker:
        state = "success"
        reason = f"success marker found: {success_marker}"
        next_action = "consume the result and continue with the next authorized action"
    elif pid_state == "mismatched":
        state = "stale"
        reason = "PID identity no longer matches the launched process; possible PID reuse"
        next_action = "treat as stale/hung; do not report this process as running"
    elif pid_state == "unverified":
        state = "stale"
        reason = "PID is live but process identity could not be verified"
        next_action = "treat as stale/hung until liveness is verified with process identity evidence"
    elif pid_state == "live" and timeout_seconds_meta and watchdog_state in {"dead", "missing"}:
        state = "stale"
        reason = "timeout watchdog is not live while the monitored process is still running"
        next_action = "treat as stale/hung timeout enforcement; inspect the log and recover or rerun with a live watchdog"
    elif age_seconds > max_stale_seconds:
        state = "stale"
        if pid_state == "live":
            reason = f"log has not changed for {age_seconds}s while PID is still live"
        elif pid_state == "dead":
            reason = f"log has not changed for {age_seconds}s and PID is dead"
        else:
            reason = f"log has not changed for {age_seconds}s and no live process was verified"
        next_action = "treat as stale/hung; inspect the log tail and rerun, kill/retry, or recover without asking whether to wait"
    elif pid_state == "dead":
        state = "stale"
        reason = "PID is dead and no terminal success marker was observed"
        next_action = "treat as stopped without verified success; inspect the log and recover or rerun"
    elif pid_state == "unknown":
        state = "unverified"
        reason = f"log updated {age_seconds}s ago but no PID/process identity was verified"
        next_action = "verify the PID or pid file before reporting the command as running"
    else:
        state = "running"
        if pid_state == "live":
            reason = f"PID is live and log updated {age_seconds}s ago"
        else:
            reason = f"log updated {age_seconds}s ago; PID not verified"
        next_action = "continue parallel-safe work or poll again before the stale threshold"

    print(f"monitor_state: {state}")
    print(f"monitor_log: {log}")
    print(f"monitor_log_size_bytes: {stat.st_size}")
    print(f"monitor_log_modified_at: {modified_at}")
    print(f"monitor_seconds_since_log_update: {age_seconds}")
    print(f"monitor_max_stale_seconds: {max_stale_seconds}")
    print(f"monitor_exit_code: {recorded_exit if isinstance(recorded_exit, int) else 'none'}")
    print(f"monitor_finished_at: {finished_at or 'none'}")
    print(f"monitor_pid: {pid if pid is not None else 'unknown'}")
    print(f"monitor_pid_source: {pid_source}")
    print(f"monitor_pid_state: {pid_state}")
    print(f"monitor_pid_identity_state: {pid_identity_state}")
    print(f"monitor_timeout_seconds: {timeout_seconds_meta}")
    print(f"monitor_watchdog_pid: {watchdog_pid if watchdog_pid else 'none'}")
    print(f"monitor_watchdog_state: {watchdog_state}")
    print(f"monitor_reason: {reason}")
    print(f"monitor_next_action: {next_action}")

    # The READ RECEIPT. Item 83 PR2's yield gate blocks a stop while a finished run's terminal
    # summary is unread, and this is the only thing that clears it -- so the receipt must be
    # written on EVERY path that actually printed a status, including a failed or stale one. A
    # receipt written only on success would leave a lane that correctly diagnosed a failure unable
    # to end its turn, which is the false refusal this whole chain is rationed against.
    #
    # Best-effort by contract: `monitor-status` is a read verb, and a read-only runs directory must
    # not make it fail. The cost of a lost receipt is one more poll, not a wrong answer.
    _write_monitor_read_receipt(log, state=state, finished_at=finished_at, pid=meta.get("pid"))

    bad_states = {"missing", "stale", "failed", "unverified"}
    return 1 if args.strict and state in bad_states else 0


def _write_monitor_read_receipt(
    log: Path, *, state: str, finished_at: object, pid: object = None
) -> None:
    receipt = log.with_name(f"{log.name}.read.json")
    payload = {
        "schema": MONITOR_READ_RECEIPT_SCHEMA,
        "readAt": datetime.now(timezone.utc).isoformat(timespec="seconds").replace("+00:00", "Z"),
        "state": state,
        # The finishedAt this read OBSERVED, so a later run of the same log does not read as
        # already-consumed off an older receipt -- AND the pid, because `finishedAt` is recorded to
        # one-second precision. Two quick runs of the same log that finish in the same second are
        # indistinguishable by timestamp alone, and the older receipt would clear the newer run.
        "finishedAt": finished_at if isinstance(finished_at, str) else None,
        "pid": pid if isinstance(pid, int) else None,
    }
    try:
        write_text_atomic(receipt, json.dumps(payload, indent=2) + "\n")
    except OSError:
        return


def run_git(target: Path, args: list[str]) -> str:
    return gitutil_module().run_git(target, args)


def methodology_rescue_ref_adapter_changes(repo: Path | None = None) -> list[tuple[str, list[str]]]:
    """Local `tautline-local-rescue/*` (and legacy `minervit-local-rescue/*`) refs in the
    methodology repo that carry canonical adapter
    changes (`adapters/projects/*.json`) not present on the base branch. Lane auto-sync can
    silently move a canonical adapter fix onto a rescue ref; a later lane re-render then
    reproduces the pre-fix adapter (RCA O17). Returns (ref, [adapter_paths]) per affected ref.

    Rescue refs only ever exist in the CANONICAL checkout (rescue is a write path), so a snapshot
    exec root would leave this detector permanently blind and reporting "clean"."""
    repo = repo or canonical_methodology_repo()
    listing = run_git(
        repo,
        [
            "for-each-ref",
            "--format=%(refname:short)",
            "refs/heads/tautline-local-rescue",
            "refs/heads/minervit-local-rescue",
        ],
    )
    if listing in ("", "unavailable"):
        return []
    base = (
        "origin/main"
        if run_git(repo, ["rev-parse", "--verify", "--quiet", "origin/main"]) not in ("", "unavailable")
        else "main"
    )
    results: list[tuple[str, list[str]]] = []
    for ref in [line.strip() for line in listing.splitlines() if line.strip()]:
        # A rescue ref that is an ANCESTOR of base (old main, merely behind -- e.g. a non-main
        # auto-rescue snapshot of a main that has since advanced) carries nothing un-landed: base
        # already contains it. Skip it. Two-dot tree diff alone would still flag it because base
        # advanced the same adapter files, producing a phantom "stranded fix" hint that has
        # confused operators and contributed to a lane wedge (RCA: rescue-ref detector ancestor
        # false-positive). Only code==0 (definitely an ancestor) skips; an error falls through to
        # report so a genuinely-divergent rescue ref is never silently dropped.
        if run_command(["git", "-C", str(repo), "merge-base", "--is-ancestor", ref, base])[0] == 0:
            continue
        # Two-dot (direct tree compare base vs ref), not three-dot (from merge-base): a rescue
        # adapter change already re-landed on base via cherry-pick/squash has matching content and
        # must not be reported as stranded (Codex P3).
        changed = run_git(repo, ["diff", "--name-only", f"{base}..{ref}", "--", "adapters/projects"])
        if changed in ("", "unavailable"):
            continue
        paths = [p.strip() for p in changed.splitlines() if p.strip()]
        if paths:
            results.append((ref, paths))
    return results


def print_methodology_rescue_ref_warnings(repo: Path | None = None) -> list[tuple[str, list[str]]]:
    """Print a blocking-style warning for each rescue ref that holds canonical adapter changes,
    naming the ref, the affected adapter paths, and a re-land command. Returns the findings."""
    repo = repo or canonical_methodology_repo()
    findings = methodology_rescue_ref_adapter_changes(repo)
    for ref, paths in findings:
        print(
            f"methodology_rescue_ref_adapter_drift: rescue ref {ref} holds canonical adapter changes "
            f"in {', '.join(paths)} that are not on the base branch. A re-render will reproduce the "
            f"pre-rescue adapter. Re-land them with `git -C {repo} cherry-pick`/PR from {ref} before "
            "rendering, or delete the rescue ref with an explicit decision."
        )
    return findings


