def strip_plan_review_evidence(text: str) -> str:
    pattern = re.compile(rf"^{re.escape(PLAN_REVIEW_EVIDENCE_HEADING)}\s*$", re.MULTILINE)
    match = pattern.search(text)
    if match:
        remainder = text[match.end() :]
        # The end marker bounds the section exactly; plans whose body after the
        # title is not `## `-headed would otherwise lose their preamble here.
        marker_match = re.search(rf"^{re.escape(PLAN_REVIEW_EVIDENCE_END_MARKER)}\s*$", remainder, re.MULTILINE)
        if marker_match:
            end = match.end() + marker_match.end()
        else:
            next_match = re.search(r"^##\s+", remainder, re.MULTILINE)
            end = match.end() + next_match.start() if next_match else len(text)
        head = text[: match.start()].rstrip("\n")
        tail = text[end:].lstrip("\n")
        if head and tail:
            text = head + "\n\n" + tail
        else:
            text = head or tail
    return text.strip() + "\n"


def upsert_plan_review_evidence(text: str, replacement_body: str) -> str:
    base = strip_plan_review_evidence(text)
    section = f"{PLAN_REVIEW_EVIDENCE_HEADING}\n\n{replacement_body.strip()}\n\n{PLAN_REVIEW_EVIDENCE_END_MARKER}\n"
    lines = base.splitlines()
    insert_at = 0
    if lines and lines[0].startswith("# "):
        insert_at = 1
    before = "\n".join(lines[:insert_at]).strip()
    after = "\n".join(lines[insert_at:]).strip()
    if before and after:
        return before + "\n\n" + section + "\n" + after + "\n"
    if before:
        return before + "\n\n" + section
    if after:
        return section + "\n" + after + "\n"
    return section


def terminate_process_group(proc: subprocess.Popen, log_handle, reason: str) -> None:
    log_handle.write(f"\n[minervit] {reason}; terminating process group {proc.pid}\n")
    log_handle.flush()
    if hasattr(os, "killpg"):
        try:
            os.killpg(proc.pid, signal.SIGTERM)
        except ProcessLookupError:
            return
        except OSError as exc:
            log_handle.write(f"[minervit] SIGTERM failed: {exc}\n")
            log_handle.flush()
        time.sleep(3)
        if proc.poll() is None:
            try:
                os.killpg(proc.pid, signal.SIGKILL)
                log_handle.write(f"[minervit] SIGKILL sent to process group {proc.pid}\n")
                log_handle.flush()
            except ProcessLookupError:
                pass
            except OSError as exc:
                log_handle.write(f"[minervit] SIGKILL failed: {exc}\n")
                log_handle.flush()
    else:
        proc.terminate()
        try:
            proc.wait(timeout=3)
        except subprocess.TimeoutExpired:
            proc.kill()


def run_process_with_no_output_watchdog(
    command: list[str],
    *,
    cwd: Path,
    env: dict[str, str],
    log_handle,
    log_path: Path,
    no_output_timeout_seconds: int,
) -> tuple[int, Path | None]:
    if no_output_timeout_seconds < 0:
        raise SystemExit("--no-output-timeout-seconds must be zero or positive")
    try:
        proc = subprocess.Popen(
            command,
            cwd=str(cwd),
            env=env,
            text=True,
            stdout=log_handle,
            stderr=subprocess.STDOUT,
            start_new_session=True,
        )
    except OSError as exc:
        log_handle.write(f"\nplan_review_run_error: {exc}\n")
        return 127, None
    last_size = log_path.stat().st_size if log_path.exists() else 0
    last_growth = time.monotonic()
    poll_seconds = 1.0 if no_output_timeout_seconds else 5.0
    stale_marker: Path | None = None
    while True:
        exit_code = proc.poll()
        if exit_code is not None:
            return exit_code, stale_marker
        time.sleep(poll_seconds)
        try:
            current_size = log_path.stat().st_size
        except OSError:
            current_size = last_size
        if current_size > last_size:
            last_size = current_size
            last_growth = time.monotonic()
            continue
        if no_output_timeout_seconds and time.monotonic() - last_growth >= no_output_timeout_seconds:
            reason = f"plan review produced no new output for {no_output_timeout_seconds}s"
            stale_marker = log_path.with_name(f"{log_path.name}.stale.json")
            stale_marker.write_text(
                json.dumps(
                    {
                        "schema": "minervit-plan-review-stale/v1",
                        "reason": "stale_no_output",
                        "noOutputTimeoutSeconds": no_output_timeout_seconds,
                        "log": str(log_path),
                        "detectedAt": now_iso(),
                        "pid": proc.pid,
                    },
                    indent=2,
                    sort_keys=True,
                )
                + "\n",
                encoding="utf-8",
            )
            terminate_process_group(proc, log_handle, reason)
            try:
                proc.wait(timeout=5)
            except subprocess.TimeoutExpired:
                pass
            return 124, stale_marker


def plan_review_text(path: Path) -> str:
    text = path.read_text(encoding="utf-8")
    return strip_plan_review_evidence(text)


def plan_content_sha256(path: Path) -> str:
    return hashlib.sha256(plan_review_text(path).encode("utf-8")).hexdigest()


def plan_content_sha256_from_text(text: str) -> str:
    return hashlib.sha256(strip_plan_review_evidence(text).encode("utf-8")).hexdigest()




def planning_source_root(data: dict, target: Path) -> Path:
    return configured_path(target, data["planningArtifacts"]["sourceOfTruth"])


def plan_root_containment_dirs(data: dict, target: Path) -> dict[str, Path]:
    """Every directory a plan may legitimately live under, keyed by root token.

    The lane contributes its planning source root -- not the whole checkout, because group A always
    gated on the plans directory rather than the repository. A configured planRepo contributes its
    own root.
    """
    roots = paths_module().configured_plan_roots(data, target)
    dirs = {paths_module().plan_reference.LANE_ROOT: planning_source_root(data, target)}
    for token, root in roots.items():
        if token != paths_module().plan_reference.LANE_ROOT:
            dirs[token] = root
    return dirs


def plan_is_under_a_configured_root(data: dict, target: Path, plan_path: Path) -> bool:
    """Whether a plan lives under ANY configured plan root, not merely under this lane's.

    Item 59 W3, group A. Thirteen surfaces each asked "is this plan under *this lane's* source of
    truth" and refused otherwise, which is exactly why a plan owned by the backlog repo could not be
    reviewed. Widening the question once, here, converts all thirteen without loosening what they
    guarantee: a path under no configured root is still refused, and the lane's contribution is
    still the plans directory rather than the whole checkout.
    """
    for root in plan_root_containment_dirs(data, target).values():
        if path_is_under(plan_path, root):
            return True
    return False


def render_plan_reference_for(data: dict, target: Path, plan_path: Path) -> str:
    """Render `plan_path` as a rooted reference against whichever configured root contains it.

    Item 59 W3, group B. The lane-only `path_relative_to_target(target, plan_path)` raised
    the lane, so converting only group A's containment checks moved the crash a few lines down --
    the trap the first attempt hit and reported as "seven sites, mechanical".

    Refuses a plan under no configured root rather than emitting something. A reference nothing can
    resolve is a dead record, and writing one is worse than failing where the mistake was made.
    """
    resolved = plan_path.resolve()
    for token, root in plan_root_containment_dirs(data, target).items():
        if path_is_under(resolved, root):
            base = target if token == paths_module().plan_reference.LANE_ROOT else root
            relative = paths_module().plan_reference.render_plan_reference(
                token, path_relative_to_target(base, resolved)
            )
            return relative
    raise ValueError(
        f"plan {plan_path} is under no configured plan root, so it has no reference to record; "
        f"configured roots are: {', '.join(sorted(plan_root_containment_dirs(data, target)))}"
    )


def plan_references_match(data: dict, target: Path, left: str, right: str) -> bool:
    """Whether two plan references name the same plan, whatever their spelling.

    Item 59 W3, category D. Recorded evidence holds the bare v1 spelling while recomputed values are
    rooted, so any consumer that MATCHES a recorded reference against a recomputed one must compare
    resolutions rather than strings. Comparing strings is what made
    :func:`plan_review_pending_block_reason` return ``None`` mid-conversion -- the plan-edit guard
    silently stopped blocking, which is strictly worse than refusing loudly.

    An unresolvable reference on either side matches nothing: the comparison cannot prove the two
    name the same plan, so it must not claim they do.
    """
    resolver = paths_module().resolve_plan_reference
    try:
        left_path = resolver(data, target, str(left or ""))
        right_path = resolver(data, target, str(right or ""))
    except ValueError:
        return False
    return left_path.resolve() == right_path.resolve()


def milestone_source_plan_matches(
    data: dict, target: Path, stored: str, plan_path: Path
) -> bool:
    """Whether a stored milestone `sourcePlan` names the same plan as `plan_path`.

    Item 59 W3. The retarget guard used to compare the stored and recomputed values as strings,
    so rendering `sourcePlan` as a rooted reference would have retarget-refused every ledger
    written before this release -- same plan, different spelling. Comparing what the references
    RESOLVE to is backwards-compatible and is the better comparison on its own terms: a guard
    against retargeting should care about the target, not how it is spelled.

    An unresolvable stored reference is a mismatch, never a match: the guard cannot prove the two
    name the same plan, so it must not claim they do.
    """
    stored = str(stored or "").strip()
    if not stored:
        return False
    try:
        stored_path = paths_module().resolve_plan_reference(data, target, stored)
    except ValueError:
        return False
    return stored_path.resolve() == plan_path.resolve()


def plan_relative_base(data: dict, target: Path, root: str) -> Path:
    """What a plan path is relativized against when it is RECORDED.

    Item 59 W3. This varies by the plan's root: a lane plan is measured from the lane, a plan owned
    by a configured planRepo from that repo. An unconfigured root raises rather than falling back to
    the lane, because a silent fallback is exactly how an external plan gets recorded as a lane
    path -- a reference that resolves to nothing on the next read.

    Not to be confused with :func:`plan_review_root`, which answers where the *evidence* lives.
    Conflating them silently rewrote every lane-local manifest on an earlier attempt at this item.
    """
    return paths_module().resolve_plan_root(data, target, root)


def plan_review_root(data: dict, target: Path) -> Path:
    """Where plan-review evidence LIVES -- always this lane, whoever owns the plan.

    Deliberately independent of the plan's root. The lane that ran the review is the lane that holds
    its receipts, so reviewing a plan owned by another repository still records here. Following the
    plan's root instead relocates all 61 existing manifests the moment a planRepo is configured.
    """
    return planning_source_root(data, target)


def plan_review_manifest_identity(data: dict, target: Path, plan_path: Path) -> str:
    """The manifest slug for a plan: its path relative to its ROOT, not its stem.

    Item 59 W2. Slugging the stem meant every `ready/<item>/plan.md` in an external backlog
    resolved to one `.plan-reviews/plan.json`, so two items silently overwrote each other's review
    evidence. Relative to the ROOT rather than the target is what keeps the 61 existing lane-local
    manifests exactly where they are: `<root>/2026-08-02-x.md` is `2026-08-02-x.md` relative to its
    root and slugs to the same name it always did.
    """
    # AGAINST EVERY CONFIGURED ROOT, not only the lane's. Consulting one root meant an external
    # backlog plan fell to the bare-name fallback below, so `ready/item-a/plan.md` and
    # `ready/item-b/plan.md` BOTH slugged to `plan` -- preserving the exact evidence collision this
    # change exists to remove. Codex R1 P1. The lane's root is still in this map and still wins for
    # lane-local plans, which is what keeps the existing manifests byte-identical.
    resolved = plan_path.resolve()
    for root in plan_root_containment_dirs(data, target).values():
        try:
            relative = resolved.relative_to(root.resolve())
        except ValueError:
            continue
        return slugify(relative.with_suffix("").as_posix(), "plan")
    # Under no configured root at all: the bare name rather than an absolute path leaking into a
    # filename. Reaching here means the containment gates above already refused, or should have.
    return slugify(Path(plan_path.name).with_suffix("").as_posix(), "plan")


def plan_review_legacy_manifest_is_claimed_by_another_plan(
    data: dict, target: Path, manifest_path: Path, plan_path: Path
) -> bool:
    """Whether a legacy stem-named manifest already belongs to a DIFFERENT, still-present plan.

    Keyed on the manifest's recorded reference, never on the manifest merely existing -- a file
    being there proves a manifest exists, not whose it is.

    A recorded reference pointing at a plan that no longer exists does NOT count as a claim. That
    is not a corner case: every nested `archive/` plan in this repository has a manifest still
    recording its pre-archive location, because the plans were moved after finalization and the
    records were never rewritten. Treating those as claimed would orphan them.
    """
    manifest = load_plan_review_manifest(manifest_path)
    if not manifest:
        return False
    recorded = str(manifest.get("plan_path") or "").strip()
    if not recorded:
        return False
    try:
        recorded_path = paths_module().resolve_plan_reference(data, target, recorded)
    except ValueError:
        # An unparseable or unresolvable reference names nothing, so it claims nothing.
        return False
    if not recorded_path.exists():
        return False
    return recorded_path.resolve() != plan_path.resolve()


def plan_review_manifest_path(data: dict, target: Path, plan_path: Path) -> Path:
    reviews_root = planning_source_root(data, target) / ".plan-reviews"
    preferred = reviews_root / f"{plan_review_manifest_identity(data, target, plan_path)}.json"
    if preferred.exists():
        return preferred
    legacy = reviews_root / f"{slugify(plan_path.stem, 'plan')}.json"
    if legacy == preferred or not legacy.exists():
        return preferred
    if plan_review_legacy_manifest_is_claimed_by_another_plan(data, target, legacy, plan_path):
        return preferred
    return legacy


def plan_review_import_manifest_path(data: dict, target: Path, plan_path: Path) -> Path:
    # Same stem collision as the review manifest, but zero `.imported.json` files exist yet, so
    # this takes the path-based identity outright. No adoption path: a compatibility rule with no
    # legacy to adopt is machinery no test could exercise honestly.
    slug = plan_review_manifest_identity(data, target, plan_path)
    return planning_source_root(data, target) / ".plan-reviews" / f"{slug}.imported.json"


def path_relative_to_target(target: Path, path: Path) -> str:
    return util_module().path_relative_to_target(target, path)














def validate_plan_substance(path: Path) -> list[str]:
    errors: list[str] = []
    text = plan_review_text(path)
    lower = text.lower()
    if len(text.strip()) < 800:
        errors.append("plan is too short to be decision-complete")
    missing = [
        label
        for label, patterns in PLAN_SUBSTANTIVE_REQUIREMENTS.items()
        if not any(re.search(pattern, lower, re.MULTILINE) for pattern in patterns)
    ]
    if missing:
        errors.append("plan missing substantive sections: " + ", ".join(missing))
    hits = plan_unfinished_marker_hits(text)
    if hits:
        # Name the line and quote what matched. The old message said only "plan contains
        # stub/TODO markers", so on a 1700-line plan the remedy was derivable only by
        # reimplementing this regex by hand (item 29: plan-precheck marker false positive).
        detail = "; ".join(
            f"line {number}: {matched} in {body[:80]!r}" for number, matched, body in hits[:5]
        )
        more = f" (+{len(hits) - 5} more)" if len(hits) > 5 else ""
        errors.append(
            f"plan contains unfinished-work markers -- {detail}{more}. "
            "Reword or finish those lines; text inside backticks or fenced blocks is exempt, "
            "so quote a marker you are discussing rather than writing it bare."
        )
    return errors




DONE_EVIDENCE_AC_TABLE_MODES = ("off", "warn", "strict")


def normalize_done_evidence(raw: object) -> dict:
    """`backlogProvider.doneEvidence`, the closure-verification knob block (item 81).

    Separate from `normalize_tracker_adapter_config` on purpose: that function is shared with the
    deprecated `goalTracker`, and a done-evidence policy on the legacy key would be a second place
    the mode could be set from.
    """
    if raw is not None and not isinstance(raw, dict):
        raise SystemExit("Project adapter backlogProvider.doneEvidence must be an object")
    config = {**DEFAULT_BACKLOG_PROVIDER["doneEvidence"], **(raw or {})}
    config["acTable"] = str(config.get("acTable", "warn")).strip().lower()
    if config["acTable"] not in DONE_EVIDENCE_AC_TABLE_MODES:
        raise SystemExit(
            "Project adapter backlogProvider.doneEvidence.acTable must be off, warn, or strict"
        )
    return config


def normalize_plan_acceptance(data: dict) -> dict:
    raw = data.get("planAcceptance")
    if raw is not None and not isinstance(raw, dict):
        raise SystemExit("Project adapter planAcceptance must be an object")
    cfg = {**DEFAULT_PLAN_ACCEPTANCE, **(raw or {})}
    if cfg["enforcement"] not in {"off", "warn", "block"}:
        raise SystemExit("Project adapter planAcceptance.enforcement must be off, warn, or block")
    headings = cfg.get("acHeadings")
    if not isinstance(headings, list) or not all(isinstance(h, str) for h in headings):
        raise SystemExit("Project adapter planAcceptance.acHeadings must be a list of strings")
    cfg["acHeadings"] = [h.strip().lower() for h in headings if h.strip()] or list(DEFAULT_PLAN_ACCEPTANCE["acHeadings"])
    return cfg



DEFAULT_AUTONOMY = {"standingDirective": True}


def normalize_autonomy(data: dict) -> dict:
    """Read-side merge-over-default for the `autonomy` knob. NEVER writes back into `data` and is
    never rendered, so the absent key stays absent on disk (no adapter_drift, the productDevelopment
    precedent). SystemExit on a malformed value (non-object, or non-bool standingDirective) -- fail
    loud, never silently on."""
    raw = data.get("autonomy") if isinstance(data, dict) else None
    if raw is not None and not isinstance(raw, dict):
        raise SystemExit("Project adapter autonomy must be an object")
    cfg = {**DEFAULT_AUTONOMY, **(raw or {})}
    if not isinstance(cfg.get("standingDirective"), bool):
        raise SystemExit("Project adapter autonomy.standingDirective must be a boolean")
    return cfg


def autonomy_directive_enabled(data: dict | None) -> bool:
    """Absent adapter or absent knob -> directive ON. Explicit standingDirective:false opts out."""
    if data is None:
        return True
    return bool(normalize_autonomy(data)["standingDirective"])


def standing_autonomy_directive_text(data: dict | None, target: Path | None = None) -> str:
    """Render the standing autonomy directive from CHEAP LOCAL SIGNALS ONLY -- adapter presence,
    stakeholderQuestions.enabled, and the startup-remediation marker file. NEVER shells out or
    touches the network (no `gh`, no subprocess): this text is emitted at session start, and the
    auth-issues helper's 20-second `gh` call would stall every startup."""
    if data is None:
        record = ("Record every non-obvious decision, with rationale and reversibility, "
                  "in your session notes or working artifacts for later operator review.")
        question = "leave one concise written question for the operator in the goal or PR artifacts"
        return STANDING_AUTONOMY_DIRECTIVE_CORE.format(record_line=record, question_line=question)
    record = "Record every non-obvious decision with `tautline decision-record` for later review."
    remediation_active = target is not None and startup_remediation_marker_path(target).exists()
    questions_enabled = bool((data.get("stakeholderQuestions") or {}).get("enabled", False))
    # Both fallbacks name the LITERAL flags --reversibility hard-to-reverse, --summary, --rationale,
    # and --next: decision-record defaults reversibility to "reversible" and next to "proceed as
    # decided", either of which would misrecord an unanswered operator-owned fork as authorized --
    # the exact thing the never-invent-approval sentence forbids.
    if questions_enabled and not remediation_active:
        question = ("queue it async via `tautline stakeholder-question-ask` (if that fails "
                    "for any reason, record it via `tautline decision-record "
                    "--reversibility hard-to-reverse` with the question as --summary, why "
                    "it is operator-owned as --rationale, and --next 'awaiting operator "
                    "answer; continuing unrelated safe work')")
    else:
        question = ("record it via `tautline decision-record --reversibility hard-to-reverse` "
                    "with the question as --summary, why it is operator-owned as --rationale, "
                    "and --next 'awaiting operator answer; continuing unrelated safe work'")
    return STANDING_AUTONOMY_DIRECTIVE_CORE.format(record_line=record, question_line=question)


def print_autonomy_directive(data: dict | None, target: Path | None) -> None:
    """Emit the standing autonomy directive UNLESS the adapter explicitly disables it. Cheap local
    signals only; safe as the first output on any session-start path."""
    if not autonomy_directive_enabled(data):
        return
    print(standing_autonomy_directive_text(data, target))








def plan_acceptance_binding_issues(plan_text: str, cfg: dict, pending_tags: list[str]) -> list[str]:
    """Every acceptance criterion must name an executable, non-@pending test/scenario id (rec #13).
    Definition-of-Ready with teeth: stops an untestable AC, or one parked behind @pending, being baked
    in at plan finalization (FM1/FM2)."""
    headings = [str(h).strip().lower() for h in cfg.get("acHeadings", DEFAULT_PLAN_ACCEPTANCE["acHeadings"]) if str(h).strip()]
    section = _extract_ac_section(plan_text, headings or DEFAULT_PLAN_ACCEPTANCE["acHeadings"])
    if not section.strip():
        return []
    tags = [str(t).strip() for t in pending_tags if str(t).strip()] or list(DEFAULT_BEHAVIOR_PENDING_TAGS)
    items = _split_ac_items(section)
    if not items:
        # A non-empty AC section with no parseable list bullets (prose paragraphs or a table) must not
        # silently pass -- that would let an author dodge the binding by avoiding a checklist.
        return [
            "acceptance-criteria section has no parseable list criteria: write each criterion as a "
            "checklist bullet that names an executable test/scenario id (test_*/*.feature/Scenario:/Test:)"
        ]
    issues: list[str] = []
    for item in items:
        summary = " ".join(item.split())[:80]
        low = item.lower()
        if any(tag.lower() in low for tag in tags):
            issues.append(
                f"acceptance criterion is bound to an inactive ({'/'.join(tags)}) scenario -- a "
                f"Definition-of-Ready AC needs live coverage: {summary}"
            )
            continue
        if not any(re.search(pat, item, re.IGNORECASE) for pat in PLAN_AC_TEST_ID_PATTERNS):
            issues.append(
                "acceptance criterion names no executable test/scenario id (name a test_*/*.feature/"
                f"Scenario:/Test: id): {summary}"
            )
    return issues


def _plan_pending_tags(data: dict) -> list[str]:
    behavior = data.get("behaviorSpecs", {}) if isinstance(data.get("behaviorSpecs"), dict) else {}
    return [str(t).strip() for t in behavior.get("pendingTags", DEFAULT_BEHAVIOR_PENDING_TAGS) if str(t).strip()]










def plan_review_exception_note(*candidates: str | None) -> str:
    """First candidate substantial enough to be a RECORDED exception, else ''.

    A rubber stamp is not an exception: the note must actually name why the extra round is needed.
    --structural-critical-evidence is accepted as one such reason among others.
    """
    for candidate in candidates:
        text = str(candidate or "").strip()
        if len(text) >= PLAN_REVIEW_EXCEPTION_NOTE_MIN_CHARS:
            return text
    return ""




def plan_review_hard_cap_refusal(
    round_number: int,
    *,
    unresolved_blockers: bool,
    observed_runs: int = 0,
    declared_label: str = "",
    finalizable_command: str = "",
    capped_evidence_bound: bool = False,
) -> str:
    """Past the hard cap, refusal is unconditional; only the message varies with state.

    `declared_label` is carried RAW: this function otherwise sees only the parsed integer, and
    `R01` / `rerun-R1` both parse to 1. The refusal must quote what the caller actually passed
    or it reads as if it were talking about some other round.

    `finalizable_command` is the runnable finalize invocation for an unbound successful run that
    matches the CURRENT plan hash. When one exists, that -- not a split -- is the exit that works
    from where the lane is standing.

    `capped_evidence_bound` says the bound manifest is already a `capped-with-open-findings`
    finalize for the current plan content (D2). That lane's exit is BUILD, and saying anything
    else here would send a lane that already holds its release valve back into planning.
    """
    cap = PLAN_REVIEW_HARD_CAP_ROUNDS
    lead = (
        f"plan review round {round_number} exceeds the hard cap of {cap} rounds; the cap is "
        "absolute and no exception note, structural Critical, or operator authorization can "
        "raise it"
    )
    if observed_runs >= cap:
        label = f" under label '{declared_label}'" if declared_label else ""
        lead += (
            f"; {observed_runs} successful review run(s) are already recorded for this plan"
            f"{label}, so the round budget is spent regardless of the label"
        )
    if capped_evidence_bound:
        return (
            f"{lead}; the bound evidence is already finalized as "
            f"`{PLAN_REVIEW_CAPPED_VERDICT}` for the current plan content and its unresolved "
            "Critical/P1 findings are binding implementation-review focus items, so the exit is "
            "BUILD: run plan-finalization-precheck and start implementation. Do not split this "
            "plan, do not launch another round, and do not ask the operator to choose a path"
        )
    if finalizable_command:
        return (
            f"{lead}; an unfinalized successful run already matches the current plan content, so "
            f"bind it instead of splitting: {finalizable_command}"
        )
    if unresolved_blockers:
        return (
            f"{lead}; the split is mandatory: decompose this plan into smaller source-of-truth "
            "plans, review each of those, and continue; do not ask the operator to choose a path"
        )
    return (
        f"{lead}; no unresolved blockers remain, so finalize the existing review evidence with "
        "finalize-plan-review and plan-finalization-precheck instead of launching another round; "
        "do not ask the operator to choose a path"
    )


def plan_review_round_cap_errors(
    *,
    round_number: int | None,
    allow_r3_structural_critical: bool = False,
    structural_critical_evidence: str | None = None,
    exception_reason: str = "",
    unresolved_blockers: bool = True,
    observed_runs: int = 0,
    declared_label: str = "",
    finalizable_command: str = "",
    capped_evidence_bound: bool = False,
) -> list[str]:
    """Round-budget gate.

    `observed_runs` defaults to 0 on purpose. A round is spent by LAUNCHING a reviewer, not by
    binding evidence, so only run_plan_review passes it. finalize-plan-review and
    record-plan-review keep declared-round semantics: capping them would refuse to bind evidence
    a lane already holds, which is the deadlock this ladder exists to remove.
    """
    del allow_r3_structural_critical  # subsumed by the general rounds 3-4 exception
    target = PLAN_REVIEW_TARGET_ROUNDS
    cap = PLAN_REVIEW_HARD_CAP_ROUNDS
    if round_number is None or round_number < 1:
        return [f"--round must include a numeric review round 1-{cap}, such as R1 or R2"]
    # The HARD cap counts invocations; the convergence TARGET below stays keyed to the declared
    # round so the rounds 3-4 exception-note ladder is byte-unchanged for a lane inside budget.
    effective_round = plan_review_effective_round(round_number, observed_runs)
    if effective_round > cap:
        return [
            plan_review_hard_cap_refusal(
                effective_round,
                unresolved_blockers=unresolved_blockers,
                observed_runs=observed_runs,
                declared_label=declared_label,
                finalizable_command=finalizable_command,
                capped_evidence_bound=capped_evidence_bound,
            )
        ]
    if round_number <= target:
        return []
    if round_number > cap:
        return [
            plan_review_hard_cap_refusal(
                round_number,
                unresolved_blockers=unresolved_blockers,
                capped_evidence_bound=capped_evidence_bound,
            )
        ]
    if plan_review_exception_note(exception_reason, structural_critical_evidence):
        return []
    return [
        f"plan review round {round_number} is past the {target}-round convergence target, so it "
        "is self-authorized only with a recorded exception: pass --exception-note '<reason>' "
        f"(at least {PLAN_REVIEW_EXCEPTION_NOTE_MIN_CHARS} characters) naming why this round is "
        f"needed. Rounds {target + 1}-{cap} never require operator authorization; take the round "
        "and record the reason, or transfer unresolved findings into the implementation review "
        "focus list"
    ]






def find_adapter_root(cwd: Path) -> Path | None:
    for candidate in [cwd, *cwd.parents]:
        if (candidate / LANE_ADAPTER_FILE).exists():
            return candidate
        if (candidate / LEGACY_LANE_ADAPTER_FILE).exists():
            sunset_warning("markers", LEGACY_LANE_ADAPTER_FILE, LANE_ADAPTER_FILE)
            return candidate
    return None


def adapter_marker_path(root: Path) -> Path:
    canonical = root / LANE_ADAPTER_FILE
    if canonical.exists():
        return canonical
    legacy = root / LEGACY_LANE_ADAPTER_FILE
    if legacy.exists():
        sunset_warning("markers", LEGACY_LANE_ADAPTER_FILE, LANE_ADAPTER_FILE)
        return legacy
    return canonical  # default write target


def onboarding_state(target: Path, invocation_cwd: Path) -> dict:
    """Classify a target's Tautline onboarding state by parent-walking evidence exactly like
    find_adapter_root (`[target, *target.parents]`). PURE and SHELL-FREE (only .exists() reads),
    so the SessionStart hook can call it under total containment. `root` is None for `unmanaged`
    (the VCS-toplevel resolution is a separate, shelling helper -- resolve_unmanaged_root -- that
    the hook path never calls). Precedence: managed > source-unrendered > interview-pending >
    unmanaged. `invocation_cwd` is the TRUE process cwd (distinct from --target) so a paste-able
    command renders from where the operator sits."""
    target = Path(target)
    invocation_cwd = Path(invocation_cwd)
    marker_root = find_adapter_root(target)
    source_root: Path | None = None
    source_path: Path | None = None
    interview_root: Path | None = None
    interview_path: Path | None = None
    for candidate in [target, *target.parents]:
        if source_root is None:
            canonical = candidate / REPO_LOCAL_ADAPTER_FILE
            legacy = candidate / LEGACY_REPO_LOCAL_ADAPTER_FILE
            if canonical.exists():
                source_root, source_path = candidate, canonical
            elif legacy.exists():
                source_root, source_path = candidate, legacy
        if interview_root is None:
            interview = candidate / DEFAULT_BOOTSTRAP_INTERVIEW_PATH
            if interview.exists():
                interview_root, interview_path = candidate, interview
    if marker_root is not None:
        state, root = "managed", marker_root
    elif source_root is not None:
        state, root = "source-unrendered", source_root
    elif interview_root is not None:
        state, root = "interview-pending", interview_root
    else:
        state, root = "unmanaged", None
    return {
        "state": state,
        "target": target,
        "invocation_cwd": invocation_cwd,
        "root": root,
        "source_path": source_path if state == "source-unrendered" else None,
        "interview_path": interview_path if state == "interview-pending" else None,
    }










def onboarding_info_for_offer(target: Path, invocation_cwd: Path) -> dict:
    """Classifier result for the NON-HOOK offer surfaces (goal-kickoff, launcher). Identical to
    onboarding_state except the `unmanaged` root is resolved to the VCS toplevel here (the one
    place the git shell-out is allowed), keeping onboarding_offer_lines pure."""
    info = onboarding_state(target, invocation_cwd)
    if info["state"] == "unmanaged":
        info = dict(info, root=resolve_unmanaged_root(target))
    return info








def no_adapter_message_for(target: Path) -> str:
    """Raise-site convenience: classify `target` from the true process cwd and compose the
    state-correct no-adapter message. Used by every direct raise site."""
    return no_adapter_message(onboarding_state(target, Path.cwd()))


def codex_fast_mode_enabled(data: dict) -> bool:
    return bool(data.get("review", {}).get("codexFastMode", DEFAULT_REVIEW["codexFastMode"]))




def resolve_real_codex(env: dict[str, str]) -> str | None:
    # Through the resolver, not straight off the mapping: `env` is dict(base_env or os.environ) --
    # the operator's environment by another name -- so a direct read left TAUTLINE_REAL_CODEX, the
    # rebranded spelling, silently dead. Setting it produced no shim and no error; codex was
    # resolved off PATH as if nothing had been configured.
    configured = util_module().resolve_env("MINERVIT_REAL_CODEX", environ=env).strip()
    if configured:
        return configured
    path_value = path_without_minervit_codex_shims(env.get("PATH", os.defpath))
    return shutil.which("codex", path=path_value)




def codex_fast_mode_env(data: dict, target: Path, base_env: dict[str, str] | None = None) -> dict[str, str]:
    env = dict(base_env or os.environ)
    enabled = codex_fast_mode_enabled(data)
    env["MINERVIT_CODEX_FAST_MODE"] = "1" if enabled else "0"
    if not enabled:
        return brand_env_pairs(env)
    real_codex = resolve_real_codex(env)
    if not real_codex:
        return brand_env_pairs(env)
    shim_dir = configured_path(target, data["laneState"]["runsDir"]) / "codex-fast-mode-bin"
    shim_dir.mkdir(parents=True, exist_ok=True)
    shim_path = shim_dir / "codex"
    content = codex_fast_mode_shim_content(real_codex)
    if not shim_path.exists() or shim_path.read_text(encoding="utf-8", errors="replace") != content:
        write_text_executable(shim_path, content)
    env["MINERVIT_REAL_CODEX"] = real_codex
    env["MINERVIT_CODEX_FAST_MODE_SHIM"] = str(shim_path)
    path_parts = [str(shim_dir)]
    existing_path = env.get("PATH", os.defpath)
    path_parts.extend(part for part in existing_path.split(os.pathsep) if part and part != str(shim_dir))
    env["PATH"] = os.pathsep.join(path_parts)
    return brand_env_pairs(env)


def codex_fast_mode_status(data: dict) -> str:
    return "enabled" if codex_fast_mode_enabled(data) else "disabled"


def find_plan_by_content_hash(data: dict, target: Path, content_hash: str) -> Path | None:
    root = planning_source_root(data, target)
    matches: list[Path] = []
    if not root.exists():
        return None
    for path in sorted(root.rglob("*.md")):
        if ".plan-reviews" in path.parts:
            continue
        try:
            if plan_content_sha256(path) == content_hash:
                matches.append(path)
        except OSError:
            continue
    return matches[0] if len(matches) == 1 else None


def find_source_plan_by_name(data: dict, target: Path, plan_name: str) -> Path | None:
    root = planning_source_root(data, target)
    matches: list[Path] = []
    if not root.exists():
        return None
    for path in sorted(root.rglob(plan_name)):
        if path.is_file() and ".plan-reviews" not in path.parts and source_plan_is_active_candidate(target, path):
            matches.append(path)
    return matches[0] if len(matches) == 1 else None






def find_source_plan_by_reference(data: dict, target: Path, text: str) -> Path | None:
    root = planning_source_root(data, target)
    if not root.exists() or not text.strip():
        return None
    haystack = text.lower()
    matches: list[Path] = []
    for path in sorted(root.rglob("*.md")):
        if not path.is_file() or ".plan-reviews" in path.parts:
            continue
        if not source_plan_is_active_candidate(target, path):
            continue
        try:
            rel = path_relative_to_target(target, path)
        except ValueError:
            continue
        references = {str(path), rel, path.as_posix()}
        if any(text_references_path(haystack, reference) for reference in references):
            matches.append(path)
    return matches[0] if len(matches) == 1 else None


def resolve_exit_plan_mode_plan(
    data: dict,
    target: Path,
    plan_file: str | None,
    plan_text: object,
    extra_reference_text: str = "",
) -> tuple[Path | None, str | None]:
    if plan_file:
        raw_plan = Path(plan_file)
        # Already checks EVERY configured root below, and resolved against only one -- so a rooted
        # value could never reach the check that would have accepted it. Found by the class test
        # rather than by a review round, which is the point of writing the property down.
        plan_path = plan_root_resolve(data, target, raw_plan)
        if plan_is_under_a_configured_root(data, target, plan_path):
            return plan_path, None
        reference_texts: list[str] = []
        if isinstance(plan_text, str) and plan_text.strip():
            reference_texts.append(plan_text)
            matched_plan = find_plan_by_content_hash(data, target, plan_content_sha256_from_text(plan_text))
            if matched_plan is not None:
                return matched_plan, (
                    f"ExitPlanMode provided scratch path {plan_path}; "
                    f"using matching source-of-truth plan {matched_plan}."
                )
        scratch_readable = False
        try:
            scratch_readable = (
                plan_path.suffix.lower() == ".md"
                and plan_path.exists()
                and plan_path.is_file()
                and plan_path.stat().st_size <= 1_000_000
            )
        except OSError:
            scratch_readable = False
        if scratch_readable:
            try:
                scratch_text = plan_path.read_text(encoding="utf-8", errors="replace")
                if scratch_text.strip():
                    matched_plan = find_plan_by_content_hash(data, target, plan_content_sha256_from_text(scratch_text))
                    if matched_plan is not None:
                        return matched_plan, (
                            f"ExitPlanMode provided scratch path {plan_path}; "
                            f"using matching source-of-truth plan {matched_plan}."
                        )
            except OSError:
                pass
        # A plan under the adapter's configured scratchPaths is scratch by construction: it must
        # reach the caller's plan-mode escape, never be hijacked to an unrelated repo plan just
        # because the recent transcript happened to name exactly one plan path. Content-hash
        # matching stays ahead of this so a scratch COPY of a real repo plan still binds to it.
        if path_is_configured_scratch_plan(data, target, plan_path):
            return plan_path, None
        if extra_reference_text.strip():
            reference_texts.append(extra_reference_text)
        referenced_plan = find_source_plan_by_reference(data, target, "\n".join(reference_texts))
        if referenced_plan is not None:
            return referenced_plan, (
                f"ExitPlanMode provided scratch path {plan_path}; "
                f"using referenced source-of-truth plan {referenced_plan}."
            )
        matched_plan = find_source_plan_by_name(data, target, raw_plan.name)
        if matched_plan is not None:
            return matched_plan, (
                f"ExitPlanMode provided scratch path {plan_path}; "
                f"using source-of-truth plan with the same filename {matched_plan}."
            )
        return plan_path, None

    if not isinstance(plan_text, str) or not plan_text.strip():
        return None, None
    matched_plan = find_plan_by_content_hash(data, target, plan_content_sha256_from_text(plan_text))
    if matched_plan is None and extra_reference_text.strip():
        matched_plan = find_source_plan_by_reference(data, target, plan_text + "\n" + extra_reference_text)
        if matched_plan is not None:
            return matched_plan, f"ExitPlanMode provided plan text; using referenced source-of-truth plan {matched_plan}."
    return matched_plan, None


def derived_document_context(data: dict) -> dict:
    explicit = data.get("documentContext", {})
    planning_source = str(data["planningArtifacts"]["sourceOfTruth"]).rstrip("/")
    source_path = Path(planning_source)
    default_index = str(source_path / "_index.md")
    default_historical = str(source_path / "archive")
    ignored = list(COMMON_IGNORED_DOC_PATHS)
    ignored.append(first_dir_pattern(data["laneState"]["runsDir"]))
    ignored.append(first_dir_pattern(data["laneState"]["executionPacket"]))
    ignored.append(first_dir_pattern(data["continuity"]["path"]))
    ignored.append(data["continuity"]["archiveDir"])
    if data.get("laneCoordination", {}).get("enabled", False):
        ignored.append(str(data["laneCoordination"]["root"]))
    ignored.extend(data["planningArtifacts"].get("scratchPaths", []))
    ignored.extend(explicit.get("ignoredDocPaths", []))
    return {
        "enforcement": explicit.get("enforcement", DEFAULT_DOCUMENT_CONTEXT["enforcement"]),
        "contextIndexPaths": explicit.get("contextIndexPaths") or [default_index],
        "trackedDocRoots": explicit.get("trackedDocRoots") or [planning_source],
        "historicalPaths": explicit.get("historicalPaths") or [default_historical],
        "ignoredDocPaths": [path for path in dict.fromkeys(ignored) if path],
        "maxIndexBytes": int(explicit.get("maxIndexBytes", DEFAULT_DOCUMENT_CONTEXT["maxIndexBytes"])),
        "maxIndexLines": int(explicit.get("maxIndexLines", DEFAULT_DOCUMENT_CONTEXT["maxIndexLines"])),
    }


def path_is_under(path: Path, root: Path) -> bool:
    return util_module().path_is_under(path, root)


def configured_paths(target: Path, values: list[str], *, allow_outside: bool = False) -> list[Path]:
    return [configured_path(target, value, allow_outside=allow_outside) for value in values if str(value).strip()]


lane_coordination_config = _lane_mod.lane_coordination_config


def lane_coordination_paths(data: dict, target: Path) -> dict[str, Path]:
    cfg = lane_coordination_config(data)
    # laneCoordination paths are an allowlisted external group: the coordination root can live
    # outside any single project (framework default is ~/Projects/...), and the contract/board/
    # status dir hang off it.
    return {
        "root": configured_path(target, cfg["root"], allow_outside=True),
        "contract": configured_path(target, cfg["contractPath"], allow_outside=True),
        "board": configured_path(target, cfg["boardPath"], allow_outside=True),
        "laneStatusDir": configured_path(target, cfg["laneStatusDir"], allow_outside=True),
    }


def current_branch_name(target: Path) -> str:
    branch = run_git(target, ["branch", "--show-current"])
    return "" if branch == "unavailable" else branch.strip()


def default_lane_coordination_name(target: Path) -> str:
    branch = current_branch_name(target)
    return slugify(branch or target.name, "lane")


def lane_coordination_status_files(data: dict, target: Path) -> list[Path]:
    status_dir = lane_coordination_paths(data, target)["laneStatusDir"]
    try:
        return sorted(path for path in status_dir.glob("*.md") if path.is_file())
    except OSError:
        return []


def git_relative_path(target: Path, path: Path) -> str:
    return path_relative_to_target(target, path).replace("\\", "/")


def git_path_tracked(target: Path, path: Path) -> bool:
    rel = git_relative_path(target, path)
    code, _stdout, _stderr = run_command(["git", "-C", str(target), "ls-files", "--error-unmatch", "--", rel], timeout=10)
    return code == 0


def git_path_clean(target: Path, path: Path) -> bool:
    rel = git_relative_path(target, path)
    code, stdout, _stderr = run_command(["git", "-C", str(target), "status", "--porcelain", "--", rel], timeout=10)
    return code == 0 and not stdout.strip()


def git_path_at_ref(target: Path, path: Path, ref: str) -> bool:
    rel = git_relative_path(target, path)
    code, _stdout, _stderr = run_command(["git", "-C", str(target), "cat-file", "-e", f"{ref}:{rel}"], timeout=10)
    return code == 0


def git_branch_upstream(target: Path) -> str:
    upstream = run_git(target, ["rev-parse", "--abbrev-ref", "--symbolic-full-name", "@{upstream}"])
    return "" if upstream == "unavailable" else upstream.strip()


def git_head_pushed_to_upstream(target: Path) -> bool:
    upstream = git_branch_upstream(target)
    if not upstream:
        return False
    code, _stdout, _stderr = run_command(["git", "-C", str(target), "merge-base", "--is-ancestor", "HEAD", upstream], timeout=10)
    return code == 0


def git_shared_base_refs(target: Path) -> list[str]:
    refs = []
    for ref in ["origin/main", "origin/master", "upstream/main", "upstream/master", "main", "master"]:
        if git_ref_exists(target, ref):
            refs.append(ref)
    return refs


def current_branch_is_shared_base(target: Path) -> bool:
    return current_branch_name(target) in {"main", "master"}


def lane_coordination_current_status_files(data: dict, target: Path) -> list[Path]:
    branch = current_branch_name(target)
    if not branch:
        return []
    expected_name = f"{slugify(branch, 'lane')}.md"
    matches: list[Path] = []
    for path in lane_coordination_status_files(data, target):
        if path.name == expected_name:
            matches.append(path)
            continue
        try:
            text = path.read_text(encoding="utf-8", errors="replace")
        except OSError:
            continue
        if re.search(rf"^Branch:\s*{re.escape(branch)}\s*$", text, re.MULTILINE):
            matches.append(path)
    return sorted(set(matches))


def lane_coordination_git_issues(data: dict, target: Path) -> list[str]:
    cfg = lane_coordination_config(data)
    if not cfg["enabled"]:
        return []
    if run_git(target, ["rev-parse", "--is-inside-work-tree"]) != "true":
        return ["strict coordination requires a Git worktree so artifacts can be tracked and shared"]
    paths = lane_coordination_paths(data, target)
    issues: list[str] = []
    shared_refs = git_shared_base_refs(target)
    head_is_pushed = git_head_pushed_to_upstream(target)
    for label, path in [("coordination contract", paths["contract"]), ("lane board", paths["board"])]:
        if not path.exists():
            continue
        if not git_path_tracked(target, path):
            issues.append(f"{label} is untracked: {path}")
            continue
        if not git_path_clean(target, path):
            issues.append(f"{label} has uncommitted changes: {path}")
            continue
        if not any(git_path_at_ref(target, path, ref) for ref in shared_refs) and not head_is_pushed:
            issues.append(f"{label} is not on the shared base or pushed branch: {path}")
    # Re-scoped to current-lane status files only: another (dead/idle) lane's untracked or dirty
    # status file must never block this lane's startup. Foreign untracked/dirty status files are
    # surfaced as an informational line only, via lane_coordination_foreign_status_git_notes.
    for path in lane_coordination_current_status_files(data, target):
        if not git_path_tracked(target, path):
            issues.append(f"lane status is untracked: {path}")
        elif not git_path_clean(target, path):
            issues.append(f"lane status has uncommitted changes: {path}")
    if not current_branch_is_shared_base(target):
        current_status = lane_coordination_current_status_files(data, target)
        if not current_status:
            expected = lane_coordination_paths(data, target)["laneStatusDir"] / f"{slugify(current_branch_name(target), 'lane')}.md"
            issues.append(f"missing current lane status for branch {current_branch_name(target)}: expected {expected} or a status file with Branch: {current_branch_name(target)}")
        elif not head_is_pushed:
            for path in current_status:
                issues.append(f"current lane status is not pushed to the branch upstream: {path}")
    return issues


def lane_coordination_foreign_status_git_notes(data: dict, target: Path) -> list[str]:
    """Informational notes for OTHER lanes' untracked/dirty status files (never issues: a dead
    lane's stray note must not block this lane's startup)."""
    cfg = lane_coordination_config(data)
    if not cfg["enabled"]:
        return []
    if run_git(target, ["rev-parse", "--is-inside-work-tree"]) != "true":
        return []
    current = set(lane_coordination_current_status_files(data, target))
    notes: list[str] = []
    for path in lane_coordination_status_files(data, target):
        if path in current:
            continue
        if not git_path_tracked(target, path):
            notes.append(f"{path} (untracked)")
        elif not git_path_clean(target, path):
            notes.append(f"{path} (uncommitted changes)")
    return notes


def lane_coordination_stale_partition(data: dict, target: Path) -> tuple[list[Path], list[Path]]:
    """Partition stale status files (by mtime vs maxStatusAgeHours) into (current-lane, other-lane)."""
    cfg = lane_coordination_config(data)
    max_age_seconds = int(cfg["maxStatusAgeHours"]) * 3600
    now = time.time()
    current = set(lane_coordination_current_status_files(data, target))
    current_stale: list[Path] = []
    other_stale: list[Path] = []
    for path in lane_coordination_status_files(data, target):
        try:
            age = now - path.stat().st_mtime
        except OSError:
            continue
        if age <= max_age_seconds:
            continue
        (current_stale if path in current else other_stale).append(path)
    return current_stale, other_stale


def lane_coordination_stale_files(data: dict, target: Path) -> list[Path]:
    # Re-scoped to current-lane status files only: other/dead lanes' rotting status files must
    # never block this lane's startup. See lane_coordination_stale_other_lane_files for the
    # informational (non-issue) counterpart.
    current_stale, _other_stale = lane_coordination_stale_partition(data, target)
    return current_stale


def lane_coordination_stale_other_lane_files(data: dict, target: Path) -> list[Path]:
    _current_stale, other_stale = lane_coordination_stale_partition(data, target)
    return other_stale


def lane_coordination_issues(data: dict, target: Path, *, strict: bool | None = None) -> list[str]:
    cfg = lane_coordination_config(data)
    if not cfg["enabled"]:
        return []
    effective_strict = cfg["enforcement"] == "strict" if strict is None else strict
    paths = lane_coordination_paths(data, target)
    issues = []
    if not paths["contract"].is_file():
        issues.append(f"missing coordination contract: {paths['contract']}")
    if not paths["board"].is_file():
        issues.append(f"missing lane board: {paths['board']}")
    if not paths["laneStatusDir"].is_dir():
        issues.append(f"missing lane status dir: {paths['laneStatusDir']}")
    for path in lane_coordination_stale_files(data, target):
        issues.append(f"stale lane status: {path}")
    if effective_strict:
        issues.extend(lane_coordination_git_issues(data, target))
    return issues


def print_lane_coordination_status(data: dict, target: Path, *, strict: bool | None = None) -> list[str]:
    cfg = lane_coordination_config(data)
    paths = lane_coordination_paths(data, target)
    status_files = lane_coordination_status_files(data, target)
    current_status_files = lane_coordination_current_status_files(data, target)
    stale_files = lane_coordination_stale_files(data, target)
    stale_other_lane_files = lane_coordination_stale_other_lane_files(data, target)
    foreign_status_git_notes = lane_coordination_foreign_status_git_notes(data, target)
    issues = lane_coordination_issues(data, target, strict=strict)
    print(f"lane_coordination: enabled={str(cfg['enabled']).lower()}")
    print(f"lane_coordination_enforcement: {cfg['enforcement']}")
    print(f"lane_coordination_root: {paths['root']}")
    print(f"lane_coordination_contract: {'present' if paths['contract'].is_file() else 'missing'} {paths['contract']}")
    print(f"lane_coordination_board: {'present' if paths['board'].is_file() else 'missing'} {paths['board']}")
    print(f"lane_coordination_status_dir: {'present' if paths['laneStatusDir'].is_dir() else 'missing'} {paths['laneStatusDir']}")
    print(f"lane_coordination_status_files: {compact_path_list(status_files, target)}")
    print(f"lane_coordination_current_status_files: {compact_path_list(current_status_files, target)}")
    print(f"lane_coordination_stale_status_files: {compact_path_list(stale_files, target)}")
    # Other lanes' staleness/untracked/dirty status is informational only, never a startup-blocking
    # issue: a dead or idle lane's rotting status file must not block this lane's startup.
    print(f"lane_coordination_stale_other_lanes: {compact_path_list(stale_other_lane_files, target)}")
    if foreign_status_git_notes:
        print(f"lane_coordination_foreign_status_git: {len(foreign_status_git_notes)} - {', '.join(foreign_status_git_notes)}")
    else:
        print("lane_coordination_foreign_status_git: none")
    print(
        "lane_coordination_instruction: Use tracked repo coordination artifacts for shared decisions; commit and push this lane's status file "
        "with active goal/milestone and owned files before multi-lane work; land shared contract/interface changes before large dependent PRs."
    )
    for issue in issues:
        print(f"lane_coordination_issue: {issue}")
    return issues


def ensure_lane_coordination_artifacts(data: dict, target: Path) -> list[Path]:
    cfg = lane_coordination_config(data)
    if not cfg["enabled"]:
        return []
    paths = lane_coordination_paths(data, target)
    created = []
    if not paths["laneStatusDir"].is_dir():
        paths["laneStatusDir"].mkdir(parents=True, exist_ok=True)
        created.append(paths["laneStatusDir"])
    for path, content in [
        (paths["contract"], lane_coordination_contract_template(data, target)),
        (paths["board"], lane_coordination_board_template(data, target)),
    ]:
        if not path.exists():
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(content, encoding="utf-8")
            created.append(path)
    return created


lane_coordination_contract_template = _lane_mod.lane_coordination_contract_template


lane_coordination_board_template = _lane_mod.lane_coordination_board_template


def lane_coordination_note_template(
    *,
    project: str,
    lane: str,
    branch: str,
    goal: str,
    current: str,
    depends_on: str,
    provides: str,
    blockers: str,
    pr: str,
) -> str:
    return (
        f"# Lane Status: {lane}\n\n"
        f"Project: {project}\n"
        f"Lane: {lane}\n"
        f"Branch: {branch or 'none'}\n"
        f"Updated: {now_iso()}\n\n"
        "## Current Goal\n\n"
        f"{goal or 'none recorded'}\n\n"
        "## Currently Changing\n\n"
        f"{current or 'none recorded'}\n\n"
        "## Depends On Other Lanes\n\n"
        f"{depends_on or 'none recorded'}\n\n"
        "## Provides To Other Lanes\n\n"
        f"{provides or 'none recorded'}\n\n"
        "## Blockers\n\n"
        f"{blockers or 'none recorded'}\n\n"
        "## Latest PR Or Commit\n\n"
        f"{pr or 'none recorded'}\n"
    )


def update_lane_coordination_board(
    data: dict,
    target: Path,
    *,
    lane: str,
    status_path: Path,
    goal: str,
    current: str,
    branch: str,
    pr: str,
) -> None:
    board = lane_coordination_paths(data, target)["board"]
    if not board.exists():
        board.parent.mkdir(parents=True, exist_ok=True)
        board.write_text(lane_coordination_board_template(data, target), encoding="utf-8")
    text = board.read_text(encoding="utf-8", errors="replace")
    start = "<!-- lane-status:start -->"
    end = "<!-- lane-status:end -->"
    if start not in text or end not in text:
        text = text.rstrip() + f"\n\n## Lane Status Files\n\n{start}\n{end}\n"
    rel = path_display(target, status_path)
    line = (
        f"- `{lane}` - `{branch or 'no-branch'}` - {goal or current or 'status updated'}; "
        f"status: `{rel}`; PR/commit: {pr or 'none'}; updated: {now_iso()}"
    )
    pattern = re.compile(rf"^- `{re.escape(lane)}` - .*$", re.MULTILINE)
    before, rest = text.split(start, 1)
    body, after = rest.split(end, 1)
    lines = [item for item in body.splitlines() if item.strip()]
    replaced = False
    updated_lines = []
    for existing in lines:
        if pattern.match(existing):
            updated_lines.append(line)
            replaced = True
        else:
            updated_lines.append(existing)
    if not replaced:
        updated_lines.append(line)
    body_text = "\n".join(updated_lines)
    board.write_text(before + start + ("\n" + body_text if body_text else "") + "\n" + end + after, encoding="utf-8")


def lane_coordination_bootstrap(args: argparse.Namespace) -> int:
    data, _, target = lane_project(args)
    cfg = lane_coordination_config(data)
    if not cfg["enabled"]:
        print("lane_coordination_bootstrap: disabled by adapter")
        return 0
    paths = lane_coordination_paths(data, target)
    print(f"lane_coordination_root: {paths['root']}")
    writes = [
        (paths["contract"], lane_coordination_contract_template(data, target)),
        (paths["board"], lane_coordination_board_template(data, target)),
    ]
    if args.write:
        paths["laneStatusDir"].mkdir(parents=True, exist_ok=True)
        print(f"lane_coordination_status_dir: present {paths['laneStatusDir']}")
    else:
        print(f"lane_coordination_status_dir: would-create {paths['laneStatusDir']}")
    for path, content in writes:
        if path.exists():
            print(f"lane_coordination_file: present {path}")
            continue
        if args.write:
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(content, encoding="utf-8")
            print(f"wrote {path}")
        else:
            print(f"lane_coordination_file: missing {path}")
    if not args.write:
        print("lane_coordination_bootstrap_next_action: rerun with --write to create missing coordination artifacts")
    return 0


def lane_coordination_status(args: argparse.Namespace) -> int:
    data, _, target = lane_project(args)
    effective_strict = args.strict or data["laneCoordination"]["enforcement"] == "strict"
    issues = print_lane_coordination_status(data, target, strict=effective_strict)
    if issues:
        print("lane_coordination_status: issues")
        return 1 if effective_strict else 0
    print("lane_coordination_status: ok")
    return 0


def lane_coordination_note(args: argparse.Namespace) -> int:
    data, _, target = lane_project(args)
    cfg = lane_coordination_config(data)
    if not cfg["enabled"]:
        print("lane_coordination_note: disabled by adapter")
        return 0
    lane = slugify(args.lane or default_lane_coordination_name(target), "lane")
    branch = args.branch or current_branch_name(target)
    paths = lane_coordination_paths(data, target)
    status_path = paths["laneStatusDir"] / f"{lane}.md"
    content = lane_coordination_note_template(
        project=data["project"],
        lane=lane,
        branch=branch,
        goal=args.goal or "",
        current=args.current or "",
        depends_on=args.depends_on or "",
        provides=args.provides or "",
        blockers=args.blockers or "",
        pr=args.pr or "",
    )
    print(f"lane_coordination_note_path: {status_path}")
    if not args.write:
        print("lane_coordination_note_write: dry-run")
        print(content)
        return 0
    paths["laneStatusDir"].mkdir(parents=True, exist_ok=True)
    status_path.write_text(content, encoding="utf-8")
    update_lane_coordination_board(
        data,
        target,
        lane=lane,
        status_path=status_path,
        goal=args.goal or "",
        current=args.current or "",
        branch=branch,
        pr=args.pr or "",
    )
    print(f"wrote {status_path}")
    print(f"updated {paths['board']}")
    return 0


def is_ignored_doc_path(path: Path, ignored_paths: list[Path]) -> bool:
    for ignored in ignored_paths:
        if path == ignored or path_is_under(path, ignored):
            return True
    return False


def markdown_files_under(data: dict, target: Path, roots: list[Path]) -> list[Path]:
    files: set[Path] = set()
    # ignoredDocPaths folds in scratchPaths (framework default ~/.claude/plans/), so this scan list
    # is an allowlisted external-capable group.
    ignored_paths = configured_paths(target, derived_document_context(data)["ignoredDocPaths"], allow_outside=True)
    for root in roots:
        try:
            if root.is_file() and root.suffix.lower() == ".md":
                files.add(root)
            elif root.is_dir():
                files.update(path for path in root.rglob("*.md") if path.is_file())
        except OSError:
            continue
    return sorted(path for path in files if not is_ignored_doc_path(path, ignored_paths))


def document_context_index_template(data: dict, target: Path, index_path: Path) -> str:
    ctx = derived_document_context(data)
    readiness = data["readiness"].get("sources", [])
    read_first = [
        "`CLAUDE.md` - generated Claude adapter.",
        "`AGENTS.md` - generated Codex adapter.",
        "`.minervit-ai-delivery.json` - generated project adapter.",
    ]
    read_first.extend(f"`{source}` - adapter readiness source." for source in readiness)
    historical = [
        f"`{path}` - historical evidence only; do not load routinely."
        for path in ctx["historicalPaths"]
    ]
    ignored = [f"`{path}`" for path in ctx["ignoredDocPaths"]]
    return (
        "# Document Context Index\n\n"
        "This index controls routine Markdown context loading. Read this file before loading project docs. "
        "Do not broad-load Markdown trees.\n\n"
        "## Read First\n"
        + "\n".join(f"- {item}" for item in read_first)
        + "\n\n## Active Work\n\n"
        "<!-- Add current execution plans/specs here. -->\n\n"
        "## Ready Next\n\n"
        "<!-- Add approved ready-for-development work here. -->\n\n"
        "## Historical Evidence Only\n"
        + "\n".join(f"- {item}" for item in historical)
        + "\n\n## Do Not Load Routinely\n"
        + "\n".join(f"- {item}" for item in ignored)
        + "\n\n## Needs Classification\n\n"
        "<!-- context-bootstrap --classify adds candidates here. Move them to Active Work, Ready Next, or Historical Evidence Only before strict enforcement. -->\n"
    )


def parse_index_sections(text: str) -> dict[str, set[str]]:
    sections: dict[str, set[str]] = {section: set() for section in DOCUMENT_CONTEXT_SECTIONS}
    current: str | None = None
    for line in text.splitlines():
        if line.startswith("## "):
            title = line[3:].strip()
            current = title if title in sections else None
            continue
        if current and line.lstrip().startswith("-"):
            matches = re.findall(r"`([^`]+)`", line)
            if matches:
                sections[current].update(match.strip().strip("/") for match in matches if match.strip())
    return sections


def read_document_index_entries(index_paths: list[Path]) -> dict[str, set[str]]:
    combined: dict[str, set[str]] = {section: set() for section in DOCUMENT_CONTEXT_SECTIONS}
    for path in index_paths:
        if not path.exists():
            continue
        try:
            parsed = parse_index_sections(path.read_text(encoding="utf-8", errors="replace"))
        except OSError:
            continue
        for section, entries in parsed.items():
            combined[section].update(entries)
    return combined


def archive_header_ok(path: Path) -> bool:
    try:
        lines = path.read_text(encoding="utf-8", errors="replace").splitlines()
    except OSError:
        return False
    start = 0
    if lines and lines[0].strip() == "---":
        for index, line in enumerate(lines[1:], start=1):
            if line.strip() == "---":
                start = index + 1
                break
    window = lines[start : start + 20]
    return any(line.strip().startswith(ARCHIVE_HEADER_SENTENCE.split("<index path>")[0].strip()) for line in window)


def insert_archive_header(path: Path, index_ref: str) -> bool:
    try:
        text = path.read_text(encoding="utf-8")
    except OSError:
        return False
    if archive_header_ok(path):
        return False
    lines = text.splitlines()
    header = ARCHIVE_HEADER_SENTENCE.replace("<index path>", index_ref)
    insert_at = 0
    if lines and lines[0].strip() == "---":
        for index, line in enumerate(lines[1:], start=1):
            if line.strip() == "---":
                insert_at = index + 1
                break
    elif lines:
        for index, line in enumerate(lines):
            if line.startswith("#"):
                insert_at = index
                break
    updated = lines[:insert_at] + ["", header, ""] + lines[insert_at:]
    path.write_text("\n".join(updated).lstrip("\n") + "\n", encoding="utf-8")
    return True


def document_context_status_data(data: dict, target: Path) -> dict:
    ctx = derived_document_context(data)
    # contextIndexPaths/trackedDocRoots/historicalPaths default to in-project paths and are not
    # documented in adapter-schema.json as containment-exempt, so they get the normal containment
    # backstop. (ignoredDocPaths, folded in via markdown_files_under, legitimately includes external
    # locations like the shared scratch dir and stays allow_outside=True there.)
    index_paths = configured_paths(target, ctx["contextIndexPaths"])
    tracked_roots = configured_paths(target, ctx["trackedDocRoots"])
    historical_roots = configured_paths(target, ctx["historicalPaths"])
    index_set = {path.resolve(strict=False) for path in index_paths}
    entries = read_document_index_entries(index_paths)
    classified = set()
    for section in ["Read First", "Active Work", "Ready Next", "Historical Evidence Only", "Do Not Load Routinely"]:
        classified.update(entries[section])
    historical_files = markdown_files_under(data, target, historical_roots)
    tracked_files = markdown_files_under(data, target, tracked_roots)
    unclassified: list[Path] = []
    for path in tracked_files:
        if path.resolve(strict=False) in index_set:
            continue
        if any(path_is_under(path, root) for root in historical_roots):
            continue
        rel = path_display(target, path).strip("/")
        if rel not in classified:
            unclassified.append(path)
    oversized_indexes: list[str] = []
    missing_indexes = [path for path in index_paths if not path.exists()]
    for path in index_paths:
        if not path.exists():
            continue
        try:
            raw = path.read_bytes()
            line_count = len(raw.decode("utf-8", errors="replace").splitlines())
        except OSError:
            oversized_indexes.append(f"{path} (unreadable)")
            continue
        if len(raw) > ctx["maxIndexBytes"] or line_count > ctx["maxIndexLines"]:
            oversized_indexes.append(f"{path} ({len(raw)} bytes, {line_count} lines)")
    archive_header_gaps = [path for path in historical_files if not archive_header_ok(path)]
    needs_classification = sorted(entries["Needs Classification"])
    issues: list[str] = []
    issues.extend(f"missing context index: {path}" for path in missing_indexes)
    issues.extend(f"oversized context index: {item}" for item in oversized_indexes)
    issues.extend(f"unclassified tracked markdown: {path}" for path in unclassified)
    issues.extend(f"needs classification index entry: {entry}" for entry in needs_classification)
    issues.extend(f"archive header missing: {path}" for path in archive_header_gaps)
    return {
        "config": ctx,
        "index_paths": index_paths,
        "tracked_roots": tracked_roots,
        "historical_roots": historical_roots,
        "missing_indexes": missing_indexes,
        "oversized_indexes": oversized_indexes,
        "unclassified": unclassified,
        "needs_classification": needs_classification,
        "archive_header_gaps": archive_header_gaps,
        "entries": entries,
        "historical_files": historical_files,
        "issues": issues,
    }


def compact_path_list(paths: list[Path], target: Path, limit: int = 5) -> str:
    return util_module().compact_path_list(paths, target, limit)


def print_document_context_status(data: dict, target: Path) -> list[str]:
    status = document_context_status_data(data, target)
    ctx = status["config"]
    print(f"document_context: enforcement={ctx['enforcement']}")
    print("document_context_instruction: Read indexes first; do not broad-load Markdown.")
    print(f"document_context_indexes: {compact_path_list(status['index_paths'], target)}")
    print(f"document_context_missing_indexes: {compact_path_list(status['missing_indexes'], target)}")
    print(f"document_context_tracked_roots: {compact_path_list(status['tracked_roots'], target)}")
    print(f"document_context_historical_paths: {compact_path_list(status['historical_roots'], target)}")
    print(f"document_context_unclassified: {compact_path_list(status['unclassified'], target)}")
    print(f"document_context_needs_classification: {len(status['needs_classification'])}")
    print(f"document_context_archive_header_gaps: {compact_path_list(status['archive_header_gaps'], target)}")
    print(f"document_context_oversized_indexes: {', '.join(status['oversized_indexes']) if status['oversized_indexes'] else 'none'}")
    return status["issues"]






def scratch_migration_lock_path(data: dict, target: Path) -> Path:
    scratch_paths = [
        str(configured_path(target, path_text, allow_outside=True).resolve(strict=False))
        for path_text in data["planningArtifacts"].get("scratchPaths", [])
    ]
    digest = hashlib.sha256("\0".join(sorted(scratch_paths)).encode("utf-8")).hexdigest()[:16]
    return Path.home() / f".minervit-methodology-scratch-migration-{digest}.lock"


@contextmanager
def directory_lock(lock_dir: Path):
    acquired = False
    deadline = time.time() + 30
    while True:
        try:
            lock_dir.mkdir(mode=0o700)
            acquired = True
            break
        except FileExistsError:
            if time.time() >= deadline:
                print(f"planning_migration_warning: lock busy after 30s; proceeding without lock {lock_dir}", file=sys.stderr)
                break
            time.sleep(0.1)
        except OSError as exc:
            print(f"planning_migration_warning: could not create fallback lock {lock_dir}: {exc}", file=sys.stderr)
            break
    try:
        yield
    finally:
        if acquired:
            try:
                lock_dir.rmdir()
            except OSError:
                pass


@contextmanager
def scratch_migration_lock(lock_path: Path):
    fallback_dir = lock_path.with_name(f"{lock_path.name}.d")
    try:
        lock_file = lock_path.open("a+", encoding="utf-8")
    except OSError as exc:
        print(f"planning_migration_warning: could not open lock {lock_path}: {exc}; using fallback lock", file=sys.stderr)
        with directory_lock(fallback_dir):
            yield
        return
    try:
        import fcntl  # type: ignore[import-not-found]
    except ImportError:
        lock_file.close()
        with directory_lock(fallback_dir):
            yield
        return
    try:
        try:
            fcntl.flock(lock_file.fileno(), fcntl.LOCK_EX)
        except OSError as exc:
            print(f"planning_migration_warning: could not acquire lock {lock_path}: {exc}; using fallback lock", file=sys.stderr)
            with directory_lock(fallback_dir):
                yield
            return
        yield
    finally:
        try:
            fcntl.flock(lock_file.fileno(), fcntl.LOCK_UN)
        except OSError:
            pass
        lock_file.close()


def migrate_relevant_scratch_plans(data: dict, target: Path) -> tuple[list[tuple[Path, Path]], list[tuple[Path, Path, str]]]:
    with scratch_migration_lock(scratch_migration_lock_path(data, target)):
        candidates = relevant_scratch_plan_candidates(data, scratch_plan_candidates(data, target))
        if not candidates:
            return [], []
        source_dir = configured_path(target, data["planningArtifacts"]["sourceOfTruth"])
        source_dir.mkdir(parents=True, exist_ok=True)
        migrated: list[tuple[Path, Path]] = []
        errors: list[tuple[Path, Path, str]] = []
        for source in candidates:
            if not source.exists():
                continue
            dest = unique_destination(source_dir, source.name)
            try:
                shutil.move(str(source), str(dest))
            except FileNotFoundError:
                continue
            except OSError as exc:
                errors.append((source, dest, str(exc)))
                continue
            migrated.append((source, dest))
        return migrated, errors


def write_generated_files(
    data: dict, project_path: Path, target: Path, *, trigger: str = ""
) -> tuple[list[Path], list[Path], list[Path]]:
    """Render the generated files into `target`. Returns (written, skipped, downgraded).

    `downgraded` is item 69's third outcome: the on-disk file was produced by a NEWER template
    than this runtime carries, so writing would silently roll it back -- the 2026-08-03 incident.
    The implicit path NARRATES and no-ops; it never fails lane-start, because a machine on a stale
    pin still has to be able to start a lane in order to run the repin that fixes it.
    """
    written: list[Path] = []
    skipped: list[Path] = []
    downgraded: list[Path] = []
    overwritten: list[Path] = []
    runtime_version = plugin_version()
    if is_repo_local_source_adapter(project_path, target):
        project_arg = project_path.resolve().relative_to(target.resolve()).as_posix()
        source_path_override = project_path
    else:
        project_arg = project_source_arg(data, project_path)
        source_path_override = None
    for rel, content in expected_files(data, project_arg, source_path_override, target).items():
        dest = target / rel
        if rel in GENERATED_MARKDOWN_FILES and dest.exists() and not is_methodology_generated_markdown(dest):
            skipped.append(dest)
            continue
        try:
            current = dest.read_text(encoding="utf-8") if dest.exists() else None
        except OSError:
            current = None
        if rel == LANE_ADAPTER_FILE and current is not None:
            if current == adapter_stamp_equivalent_content(content, current):
                # Provenance-stamp-only difference: leave the file untouched (bytes AND mtime) so
                # lane-start stops churning the adapter on every session and a wheel-stamped and
                # a checkout-stamped render stop rewriting each other.
                continue
            if adapter_render_is_downgrade(content, current):
                downgraded.append(dest)
                continue
        elif rel in GENERATED_MARKDOWN_FILES and current is not None:
            if current == markdown_stamp_equivalent_content(content, current):
                # Stamp-only difference, or byte-identical. Both used to be rewritten
                # unconditionally on every lane-start; that churn is adapter dirt in exactly the
                # review scope the codex-run guard exists to protect.
                continue
            if markdown_render_is_downgrade(current, runtime_version):
                downgraded.append(dest)
                continue
        if current is not None:
            overwritten.append(dest)
        dest.write_text(content, encoding="utf-8")
        written.append(dest)
    _narrate_adapter_render(
        data, target, trigger=trigger, written=written, overwritten=overwritten,
        downgraded=downgraded, runtime_version=runtime_version,
    )
    return written, skipped, downgraded


def adapter_render_refs(trigger: str, runtime_version: str, paths: list[Path]) -> dict:
    """Who rendered, from where, with which template.

    `trigger` alone is too coarse to answer the question the incident posed: it is a constant per
    call site, so every render reached through lane-start reports "lane-start" no matter what
    launched it. The incident was two concurrently launched sessions in SIBLING WORKTREES, so the
    useful discriminators are process and location. Paths and ids only -- no product narrative.
    """
    session = (
        util_module().resolve_env("CLAUDE_CODE_SESSION_ID")
        or util_module().resolve_env("MINERVIT_SESSION_ID")
        or "unknown"
    )
    return {
        "trigger": trigger or "unknown",
        "pid": os.getpid(),
        "argv0": sys.argv[0] if sys.argv else "",
        "session": session,
        "runtime_version": runtime_version,
        "cwd": str(Path.cwd()),
        "files": sorted(path.name for path in paths),
    }


def _narrate_adapter_render(
    data: dict,
    target: Path,
    *,
    trigger: str,
    written: list[Path],
    overwritten: list[Path],
    downgraded: list[Path],
    runtime_version: str,
) -> None:
    """Item 69 control 3: make the next unexpected render self-identifying instead of forensic.

    The EVENT is emitted only when a pre-existing generated file was OVERWRITTEN. Creating these
    files for the first time -- onboarding, a fresh worktree, every test fixture -- cannot be the
    skew this exists to diagnose, and an always-on producer on the shared lane event log is noise
    that buries the one record anybody will ever look for. The stdout line still names every
    render that wrote, because that costs nothing and reads in context.
    """
    if written:
        joined = ", ".join(
            str(path.relative_to(target)) if path.is_relative_to(target) else str(path)
            for path in written
        )
        print(f"adapter_render_trigger: {trigger or 'unknown'} wrote {joined}")
    if overwritten:
        try_write_event(
            data,
            target,
            event="adapter_render",
            severity="info",
            plain=(
                f"{trigger or 'unknown'} overwrote {len(overwritten)} existing generated adapter "
                f"file(s) at {runtime_version}"
            ),
            next_action=(
                "none -- informational; if this render was unexpected, run "
                "`git diff -- CLAUDE.md AGENTS.md .tautline.json` and compare "
                "`refs.runtime_version` against the on-disk template stamp"
            ),
            refs=adapter_render_refs(trigger, runtime_version, overwritten),
        )
    for dest in downgraded:
        stamp = on_disk_template_stamp(dest)
        refs = adapter_render_refs(trigger, runtime_version, [dest])
        refs["on_disk_stamp"] = stamp
        try_write_event(
            data,
            target,
            event="adapter_render_refused",
            severity="warn",
            plain=(
                f"{trigger or 'unknown'} refused to downgrade {dest.name} "
                f"(on-disk template {stamp})"
            ),
            next_action=(
                "update or repin the runtime past the on-disk template, or re-render deliberately "
                "from the newer runtime with `tautline render-adapters --write "
                "--allow-template-downgrade`"
            ),
            refs=refs,
        )


def methodology_upstream() -> tuple[str, str, str] | None:
    args = ["rev-parse", "--abbrev-ref", "--symbolic-full-name", "@{u}"]
    upstream = run_git(canonical_methodology_repo(), args)
    if upstream == "unavailable" or "/" not in upstream:
        return None
    remote, branch = upstream.split("/", 1)
    return remote, branch, upstream


def methodology_release_upstream(channel: str = "stable") -> tuple[str, str, str] | None:
    branch_name = framework_channel_branch(channel)
    if run_git(canonical_methodology_repo(), ["remote", "get-url", "origin"]) != "unavailable":
        return "origin", branch_name, f"origin/{branch_name}"
    upstream = methodology_upstream()
    if upstream and upstream[1] == branch_name:
        return upstream
    return None


METHODOLOGY_UPDATE_POLICY_ENV = "MINERVIT_METHODOLOGY_UPDATE_POLICY"
METHODOLOGY_UPDATE_PINS_ENV = "MINERVIT_METHODOLOGY_UPDATE_PINS"
METHODOLOGY_UPDATE_SIGNERS_ENV = "MINERVIT_METHODOLOGY_UPDATE_SIGNERS"
METHODOLOGY_UPDATE_PINS_FILE = Path.home() / ".config" / "minervit" / "methodology.update-pins"


def methodology_update_policy() -> str:
    policy = util_module().resolve_env(METHODOLOGY_UPDATE_POLICY_ENV).strip().lower()
    if policy in ("signed", "pinned", "unverified", "warn"):
        return policy
    return "warn"  # backward-compatible default; public distribution should set signed|pinned


def effective_methodology_update_policy(config_env: Path | None = None) -> str:
    """Effective policy for install-time gating: live env wins, else the installed methodology.env
    value (which the launcher sources at runtime), else the backward-compatible 'warn' default.

    Used by the --dangerously-skip-permissions interlock so launcher install sees the same policy the
    launcher will run under, even before the operator re-sources methodology.env.
    """
    env_policy = util_module().resolve_env(METHODOLOGY_UPDATE_POLICY_ENV).strip().lower()
    if env_policy in ("signed", "pinned", "unverified", "warn"):
        return env_policy
    if config_env is None:
        config_env = resolve_user_config_env()
    # Compat-sunset (roadmap #16, PR2): read the config FILE TAUTLINE_-first, then the MINERVIT_
    # spelling -- mirroring _managed_config_value's file precedence. A config carrying only the
    # TAUTLINE_ alias (both spellings are managed) must resolve, not fall through to 'warn'. First
    # non-blank spelling decides, then it is validated (same shape as the single-read before).
    taut_key = "TAUTLINE_" + METHODOLOGY_UPDATE_POLICY_ENV[len("MINERVIT_"):]
    for spelled in (taut_key, METHODOLOGY_UPDATE_POLICY_ENV):
        file_policy = util_module().user_config_env_value(spelled, config_env).strip().lower()
        if not file_policy:
            continue
        if file_policy in ("signed", "pinned", "unverified", "warn"):
            return file_policy
        return "warn"
    return "warn"


def _methodology_update_pins() -> set[str]:
    raw_pins = util_module().resolve_env(METHODOLOGY_UPDATE_PINS_ENV)
    pins: set[str] = {p for p in re.split(r"[,\s]+", raw_pins) if p}
    try:
        for line in METHODOLOGY_UPDATE_PINS_FILE.read_text(encoding="utf-8").splitlines():
            entry = line.strip()
            if entry and not entry.startswith("#"):
                pins.add(entry)
    except OSError:
        pass
    return pins


def verify_upstream_trust(new_head: str) -> tuple[bool, str]:
    """Decide whether code at new_head may be re-exec'd after an auto-update (sec-trust-exec-1).

    The auto-update fast-forwards then os.execve's the NEW code. Without a trust check, one upstream
    compromise = fleet-wide RCE for every adopter pointed at a shared upstream. Policy is read from
    MINERVIT_METHODOLOGY_UPDATE_POLICY:
      - signed:     require a valid signature on new_head (git verify-commit); optional signer
                    allowlist via MINERVIT_METHODOLOGY_UPDATE_SIGNERS.
      - pinned:     require new_head to match a pinned commit/tag (MINERVIT_METHODOLOGY_UPDATE_PINS
                    or ~/.config/minervit/methodology.update-pins).
      - unverified: explicit opt-out for a single trusted operator on a trusted machine.
      - warn (default): allow, but emit a loud warning recommending a strict policy. This keeps the
                    existing single-operator workflow working while making the gate available and
                    enforceable; public distribution MUST set signed or pinned (see SECURITY.md).
    Returns (allowed, message); the caller refuses the re-exec when allowed is False.
    """
    policy = methodology_update_policy()
    if policy == "unverified":
        return True, ""
    # Trust is decided against the CANONICAL checkout: the candidate commit was fetched into it,
    # and a snapshot exec root holds no objects to resolve a pin or verify a signature against.
    canonical = canonical_methodology_repo()
    if policy == "pinned":
        pins = _methodology_update_pins()
        if not pins:
            return False, (
                "update policy 'pinned' but no pins configured; set "
                f"{METHODOLOGY_UPDATE_PINS_ENV} or {METHODOLOGY_UPDATE_PINS_FILE}"
            )
        if new_head in pins:
            return True, ""
        for pin in pins:
            if run_git(canonical, ["rev-parse", "--verify", f"{pin}^{{commit}}"]) == new_head:
                return True, ""
        return False, f"new upstream commit {new_head[:12]} is not in the pinned allowlist"
    if policy == "signed":
        code, _out, _err = run_command(["git", "-C", str(canonical), "verify-commit", "--raw", new_head])
        if code != 0:
            return False, f"new upstream commit {new_head[:12]} is not validly signed (git verify-commit failed)"
        raw_signers = util_module().resolve_env(METHODOLOGY_UPDATE_SIGNERS_ENV)
        signers = [s for s in re.split(r"[,\s]+", raw_signers) if s]
        if signers:
            _code2, _out2, info = run_command(["git", "-C", str(canonical), "verify-commit", "--raw", new_head])
            if not any(signer in (info or "") for signer in signers):
                return False, f"new upstream commit {new_head[:12]} signer not in allowlist {signers}"
        return True, ""
    return True, (
        f"WARNING: re-executing updated methodology at {new_head[:12]} WITHOUT upstream trust "
        f"verification. Set {METHODOLOGY_UPDATE_POLICY_ENV}=signed or =pinned to verify the upstream "
        "before re-exec (strongly recommended for any shared upstream)."
    )


def _generic_pinned_advance_remedy() -> str:
    """The channel-unresolved pin remedy the trust gate falls back to.

    Shared verbatim with the held-status formatter in update_methodology_repo, which swaps this
    exact text for a resolved, runnable offer when it knows the held candidate -- one definition, so
    the generic remedy and the text the swap looks for can never drift apart.
    """
    return f"advance the trusted pin with `{CLI_NAME} update-repin --channel <stable|experimental>`"


def gate_methodology_upstream_advance(candidate_head: str) -> str | None:
    """Return None when the checkout may advance to candidate_head, else a refusal detail (sec-trust-exec-1).

    Verify-before-advance: callers fetch the upstream commit WITHOUT moving the checkout, call this against
    the FETCHED sha, and only reset/merge/switch when it returns None. Advancing first and verifying after
    is the ungated-RCE bug this closes -- a bare `git pull --ff-only` (or an eager reset/switch) moves the
    on-disk bin/minervit-methodology to unverified code, and the next shim invocation then executes it even
    though this process refuses to re-exec it. Fail-closed = the working tree never advances to code the
    trust policy would reject. (The warn-policy advisory is emitted by the post-advance re-exec gate, so
    this helper stays silent on the allow path to avoid a duplicate warning.)
    """
    allowed, trust_msg = verify_upstream_trust(candidate_head)
    if not allowed:
        # Recovery guidance must match the failing policy: update-repin only rewrites the
        # pinned allowlist and is ignored by the signed policy, so routing a signed-policy
        # failure to repin would leave the operator blocked after following the advice.
        if methodology_update_policy() == "signed":
            recovery = (
                "ensure the new upstream head carries a valid signature from a trusted key "
                f"(and that the signer is listed in {METHODOLOGY_UPDATE_SIGNERS_ENV} when a signer "
                "allowlist is set); see SECURITY.md"
            )
        else:
            recovery = (
                "review the incoming commits (git log <current>..origin/<branch> in the methodology checkout), then "
                f"{_generic_pinned_advance_remedy()}; see SECURITY.md"
            )
        return (
            f"refusing to advance methodology checkout to unverified upstream {candidate_head[:12]}: {trust_msg}; "
            + recovery
        )
    return None




def create_methodology_reexec_token(expected_head: str) -> str:
    """Write a single-use re-exec handoff token (sec-trust-exec-4).

    The token lives in a private 0700 directory under ~/.config/minervit with a 0600,
    unpredictable mkstemp name — not the shared, world-writable system tempdir where another
    local user could pre-create, read, or race the file.
    """
    token_dir = methodology_reexec_token_dir()
    token_dir.mkdir(parents=True, exist_ok=True)
    try:
        token_dir.chmod(0o700)
    except OSError:
        pass
    fd, token_name = tempfile.mkstemp(dir=str(token_dir), prefix=f"reexec-{expected_head[:12]}-", suffix=".json")
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as handle:
            json.dump({"expected_head": expected_head, "created_at": time.time(), "pid": os.getpid()}, handle)
    except BaseException:
        try:
            os.unlink(token_name)
        except OSError:
            pass
        raise
    try:
        Path(token_name).chmod(0o600)  # mkstemp already restricts, but be explicit
    except OSError:
        pass
    return token_name


def consume_methodology_reexec_token() -> bool | None:
    token = os.environ.get(METHODOLOGY_REEXEC_TOKEN_ENV)
    if not token:
        return None
    token_path = Path(token)
    try:
        token_stat = token_path.stat()
    except OSError:
        return False
    # Reject a token planted by another local user: only trust one this uid owns.
    if hasattr(os, "getuid") and token_stat.st_uid != os.getuid():
        try:
            token_path.unlink()
        except OSError:
            pass
        return False
    try:
        payload = json.loads(token_path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return False
    finally:
        try:
            token_path.unlink()
        except OSError:
            pass
    if not isinstance(payload, dict):
        return False
    expected_head = payload.get("expected_head")
    created_at = payload.get("created_at")
    if not isinstance(expected_head, str) or not isinstance(created_at, (int, float)):
        return False
    if time.time() - float(created_at) > METHODOLOGY_REEXEC_TOKEN_MAX_AGE_SECONDS:
        return False
    if not expected_head:
        return False
    manifest = snapshot_manifest()
    if manifest is not None:
        # A snapshot is an exported tree with no `.git`: `rev-parse` returns run_git's
        # "unavailable" sentinel, so the git check below could never match and EVERY post-advance
        # re-exec would be rejected as an invalid token. The manifest carries the truthful commit,
        # and an immutable tree cannot be dirty, so the porcelain check is vacuous here.
        return str(manifest["commit"]) == expected_head
    canonical = canonical_methodology_repo()
    current_head = run_git(canonical, ["rev-parse", "HEAD"])
    dirty = run_git(canonical, ["status", "--porcelain"])
    return bool(current_head == expected_head and dirty == "")


def methodology_rescue_state_dir() -> Path:
    configured = util_module().resolve_env(METHODOLOGY_RESCUE_STATE_ENV)
    if configured:
        return Path(configured).expanduser()
    # write-new/read-both: default to the tautline dir, but keep using a pre-existing legacy dir so
    # in-flight rescue state written under the old brand is not orphaned. No lock/mutex lives here.
    base = Path.home() / ".local" / "state"
    tautline = base / "tautline" / "methodology-rescue"
    legacy = base / "minervit" / "methodology-rescue"
    if not tautline.exists() and legacy.exists():
        return legacy
    return tautline


def move_untracked_methodology_files(rescue_branch: str) -> tuple[Path | None, str | None]:
    canonical = canonical_methodology_repo()
    code, stdout, stderr = run_command(["git", "-C", str(canonical), "ls-files", "--others", "--exclude-standard", "-z"])
    if code != 0:
        return None, stderr or stdout or "could not list untracked files"
    paths = [part for part in stdout.split("\0") if part]
    if not paths:
        return None, None
    safe_branch = re.sub(r"[^A-Za-z0-9_.-]+", "_", rescue_branch)
    rescue_dir = methodology_rescue_state_dir() / safe_branch / "untracked"
    moved: list[tuple[Path, Path]] = []
    for rel in paths:
        source = canonical / rel
        if not source.exists():
            continue
        dest = rescue_dir / rel
        try:
            dest.parent.mkdir(parents=True, exist_ok=True)
            shutil.move(str(source), str(dest))
            moved.append((source, dest))
        except OSError as exc:
            rollback_errors: list[str] = []
            for original, moved_dest in reversed(moved):
                try:
                    original.parent.mkdir(parents=True, exist_ok=True)
                    shutil.move(str(moved_dest), str(original))
                except OSError as rollback_exc:
                    rollback_errors.append(f"{moved_dest} -> {original}: {rollback_exc}")
            rollback_detail = f"; rollback errors: {'; '.join(rollback_errors)}" if rollback_errors else ""
            return rescue_dir, f"could not preserve untracked file {rel}: {exc}{rollback_detail}"
    return rescue_dir, None


def tracked_private_source_adapter_paths(repo: Path | None = None) -> list[str]:
    repo = repo or canonical_methodology_repo()
    code, stdout, _stderr = run_command(["git", "-C", str(repo), "ls-files", "-z", "--", "adapters/projects/*.json"])
    if code != 0:
        return []
    paths = []
    for rel in [part for part in stdout.split("\0") if part]:
        path = Path(rel)
        if (
            path.as_posix().startswith("adapters/projects/")
            and not path.name.startswith(".")
            and path.name not in PUBLIC_RELEASE_ALLOWED_SOURCE_ADAPTERS
        ):
            paths.append(path.as_posix())
    return sorted(dict.fromkeys(paths))


def copy_private_source_adapters_for_reset(
    repo: Path | None = None,
    *,
    reason: str = "release-reset",
) -> tuple[list[tuple[str, Path]], str]:
    repo = repo or canonical_methodology_repo()
    paths = tracked_private_source_adapter_paths(repo)
    if not paths:
        return [], ""
    stamp = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%SZ")
    safe_reason = re.sub(r"[^A-Za-z0-9_.-]+", "-", reason).strip("-") or "release-reset"
    rescue_dir = methodology_rescue_state_dir() / "private-adapters" / f"{stamp}-{os.getpid()}-{safe_reason}"
    copied: list[tuple[str, Path]] = []
    try:
        for rel in paths:
            source = repo / rel
            if not source.exists() or not source.is_file():
                continue
            dest = rescue_dir / rel
            dest.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(source, dest)
            copied.append((rel, dest))
    except OSError as exc:
        return [], f"private adapter preservation failed before reset: {exc}"
    if not copied:
        return [], ""
    return copied, f"; preserved private source adapters at {rescue_dir}"


def restore_private_source_adapters_after_reset(
    copied: list[tuple[str, Path]],
    repo: Path | None = None,
) -> tuple[bool, str]:
    repo = repo or canonical_methodology_repo()
    if not copied:
        return True, ""
    restored: list[str] = []
    for rel, source in copied:
        dest = repo / rel
        if dest.exists():
            continue
        try:
            dest.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(source, dest)
            restored.append(rel)
        except OSError as exc:
            return False, f"; failed to restore private source adapter {rel} from {source}: {exc}"
    if not restored:
        return True, ""
    return True, f"; restored private source adapters: {', '.join(restored)}"


def methodology_git_path(path_name: str) -> Path | None:
    canonical = canonical_methodology_repo()
    git_path = run_git(canonical, ["rev-parse", "--git-path", path_name])
    if not git_path or git_path == "unavailable":
        return None
    path = Path(git_path)
    return path if path.is_absolute() else canonical / path


def methodology_release_main_pre_commit_hook() -> str:
    return "\n".join(
        [
            "#!/bin/sh",
            "# Generated by minervit-methodology. Protects release main from local commits.",
            "set -u",
            f'case "${{{METHODOLOGY_MAIN_COMMIT_OVERRIDE_ENV}:-}}" in',
            "  1|true|TRUE|yes|YES)",
            "    exit 0",
            "    ;;",
            "esac",
            'branch="$(git branch --show-current 2>/dev/null || true)"',
            'if [ "$branch" = "main" ]; then',
            "  printf '%s\\n' 'Minervit methodology release main is protected from local commits.' >&2",
            "  printf '%s\\n' 'Create a feature branch and merge through GitHub PR instead.' >&2",
            f"  printf '%s\\n' 'Break-glass only: set {METHODOLOGY_MAIN_COMMIT_OVERRIDE_ENV}=1 for this single commit.' >&2",
            "  printf '%s\\n' 'If local main already diverged, run: bin/tautline repair-methodology-main' >&2",
            "  exit 1",
            "fi",
            "exit 0",
            "",
        ]
    )


def install_methodology_release_guards() -> str:
    if running_from_installed_package():
        # Same standdown, same rationale as update_methodology_repo: this writer sets
        # `git config --local pull.ff only` and installs hooks INTO the canonical checkout,
        # which in package mode is at best a leftover the wheel never executes (PP-R1-P1-1).
        return "skipped - installed package runtime; no methodology checkout to guard"
    canonical = canonical_methodology_repo()
    if run_git(canonical, ["rev-parse", "--is-inside-work-tree"]) != "true":
        return "skipped - methodology checkout is not a Git worktree"
    code, _stdout, stderr = run_command(["git", "-C", str(canonical), "config", "--local", "pull.ff", "only"])
    if code != 0:
        return f"failed - could not set pull.ff=only: {stderr or 'git config failed'}"
    hook_path = methodology_git_path("hooks/pre-commit")
    if hook_path is None:
        return "skipped - could not resolve git hooks path"
    hook_path.parent.mkdir(parents=True, exist_ok=True)
    desired = methodology_release_main_pre_commit_hook()
    head = run_git(canonical, ["rev-parse", "HEAD"])
    if hook_path.exists():
        existing = hook_path.read_text(encoding="utf-8", errors="replace")
        if existing == desired:
            return f"already ok - {hook_path}"
        if "Generated by minervit-methodology. Protects release main from local commits." not in existing:
            stamp = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%SZ")
            preserved = hook_path.with_name(f"{hook_path.name}.pre-minervit-{stamp}")
            shutil.move(str(hook_path), str(preserved))
            hook_path.write_text(desired, encoding="utf-8")
            hook_path.chmod(0o755)
            detail = f"installed - {hook_path}; preserved previous hook at {preserved}"
            append_methodology_write_journal(
                "install-methodology-release-guards", head, head, "ok", detail=detail
            )
            return detail
    hook_path.write_text(desired, encoding="utf-8")
    hook_path.chmod(0o755)
    detail = f"installed - {hook_path}"
    # Journaled only when it CHANGED something: this runs on every launch, and an "already ok"
    # entry per lane per launch would bury the mutations the journal exists to attribute.
    append_methodology_write_journal(
        "install-methodology-release-guards", head, head, "ok", detail=detail
    )
    return detail


def preserve_release_branch_pointer(branch_name: str, upstream_ref: str, reason: str) -> tuple[bool, str]:
    """Preserve the prior release branch on a rescue ref before a reset --hard to upstream.

    Returns (preserved_ok, detail). `preserved_ok` is False ONLY when a preservation that was
    genuinely required (local release branch carries unique commits) could not be created -- the caller must
    then abort before resetting so divergent work is never dropped. Nothing-to-preserve (main equals
    or is an ancestor of upstream) returns (True, "")."""
    canonical = canonical_methodology_repo()
    branch_ref = f"refs/heads/{branch_name}"
    main_sha = run_git(canonical, ["rev-parse", branch_ref])
    upstream_sha = run_git(canonical, ["rev-parse", upstream_ref])
    if main_sha in ("unavailable", upstream_sha):
        return True, ""
    # Preserve only when local main carries commits the upstream does not. A main that is merely
    # behind/fast-forwardable to upstream (an ancestor of it) has nothing unique to rescue, so a
    # reset --hard loses nothing and a rescue ref would be pure pollution -- it later trips the
    # rescue-ref drift detector and, on an intentionally-non-main checkout, contributed to a lane
    # wedge (RCA: non-main auto-rescue phantom ref). Only code==0 (definitely an ancestor) skips;
    # an error (code not in {0,1}) falls through to preserve so divergent work is never dropped.
    ancestor_code, _stdout, _stderr = run_command(
        ["git", "-C", str(canonical), "merge-base", "--is-ancestor", branch_ref, upstream_ref]
    )
    if ancestor_code == 0:
        return True, ""
    short_main = run_git(canonical, ["rev-parse", "--short", branch_ref])
    stamp = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%SZ")
    safe_reason = re.sub(r"[^A-Za-z0-9_.-]+", "-", reason).strip("-") or branch_name
    rescue_branch = f"tautline-local-rescue/{stamp}-{os.getpid()}-{safe_reason}-{short_main}"
    code, stdout, stderr = run_command(["git", "-C", str(canonical), "branch", rescue_branch, branch_ref])
    if code != 0:
        return False, f"; warning: could not preserve prior {branch_name} before reset: {stderr or stdout or 'command failed'}"
    return True, f"; preserved prior {branch_name} at {rescue_branch}"


def preserve_release_main_pointer(upstream_ref: str, reason: str) -> tuple[bool, str]:
    return preserve_release_branch_pointer("main", upstream_ref, reason)


def switch_release_branch(
    upstream_ref: str,
    branch_name: str,
    reason: str,
    preserve_existing_main: bool = True,
) -> tuple[bool, str]:
    canonical = canonical_methodology_repo()
    preserved_detail = ""
    if preserve_existing_main:
        # Fail closed: if a required preservation could not be created, abort before reset --hard so
        # divergent local main commits are never dropped (Codex P2: preservation was fail-open).
        preserved_ok, preserved_detail = preserve_release_branch_pointer(branch_name, upstream_ref, reason)
        if not preserved_ok:
            return False, f"auto-rescue aborted before reset because prior release {branch_name} could not be preserved{preserved_detail}"
    copied_private_adapters, private_adapter_detail = copy_private_source_adapters_for_reset(reason=reason)
    if private_adapter_detail.startswith("private adapter preservation failed"):
        return False, private_adapter_detail
    code, stdout, stderr = run_command(["git", "-C", str(canonical), "switch", branch_name])
    if code != 0:
        code, stdout, stderr = run_command(["git", "-C", str(canonical), "switch", "-c", branch_name, upstream_ref])
        if code != 0:
            return False, f"auto-rescue failed during return to release {branch_name}: {stderr or stdout or 'command failed'}"
    code, stdout, stderr = run_command(["git", "-C", str(canonical), "reset", "--hard", upstream_ref])
    if code != 0:
        return False, f"auto-rescue failed during reset release {branch_name} to upstream: {stderr or stdout or 'command failed'}"
    restored_ok, restore_detail = restore_private_source_adapters_after_reset(copied_private_adapters)
    if not restored_ok:
        return False, f"auto-rescue reset release {branch_name} but private adapter restore failed{restore_detail}{private_adapter_detail}"
    return True, preserved_detail + private_adapter_detail + restore_detail


def switch_release_main(upstream_ref: str, reason: str, preserve_existing_main: bool = True) -> tuple[bool, str]:
    return switch_release_branch(upstream_ref, "main", reason, preserve_existing_main)


def methodology_main_divergence(upstream_ref: str, branch_name: str = "main") -> tuple[int, int] | None:
    canonical = canonical_methodology_repo()
    code, stdout, _stderr = run_command(
        ["git", "-C", str(canonical), "rev-list", "--left-right", "--count", f"refs/heads/{branch_name}...{upstream_ref}"]
    )
    if code != 0:
        return None
    parts = stdout.split()
    if len(parts) != 2:
        return None
    try:
        return int(parts[0]), int(parts[1])
    except ValueError:
        return None


def repair_methodology_release_main_checkout(channel: str = "stable") -> tuple[bool, str]:
    canonical = canonical_methodology_repo()
    release_branch = framework_channel_branch(channel)
    upstream = methodology_release_upstream(channel)
    if upstream is None:
        return False, f"cannot repair methodology {release_branch} because release origin/{release_branch} is not configured"
    remote, branch, upstream_ref = upstream
    code, stdout, stderr = run_command(["git", "-C", str(canonical), "fetch", remote, branch])
    if code != 0:
        return False, f"cannot repair methodology {release_branch} because release fetch failed: {stderr or stdout or 'command failed'}"
    if run_git(canonical, ["rev-parse", upstream_ref]) == "unavailable":
        return False, f"cannot repair methodology {release_branch} because release ref is unavailable: {upstream_ref}"
    dirty = run_git(canonical, ["status", "--porcelain"])
    if dirty == "unavailable":
        return False, f"cannot repair methodology {release_branch} because git status is unavailable"
    if dirty:
        rescued, detail, _rescue_branch = rescue_methodology_local_changes(upstream)
        return rescued, detail
    branch_name = run_git(canonical, ["branch", "--show-current"])
    if branch_name not in (release_branch, "unavailable"):
        rescued, detail, _rescue_branch = rescue_methodology_non_main_checkout(branch_name or "detached HEAD", channel)
        return rescued, detail
    divergence = methodology_main_divergence(upstream_ref, release_branch)
    if divergence is None:
        return False, f"cannot repair methodology {release_branch} because local-vs-origin divergence could not be measured"
    ahead, behind = divergence
    if ahead == 0 and behind == 0:
        guard = install_methodology_release_guards()
        return True, f"release main already matches {upstream_ref}; {guard}"
    old_head = run_git(canonical, ["rev-parse", "refs/heads/main"])
    # Verify-before-advance (sec-trust-exec-1): refuse before the switch/reset so a denied upstream
    # never advances the release main to unverified code.
    refusal = gate_methodology_upstream_advance(run_git(canonical, ["rev-parse", upstream_ref]))
    if refusal is not None:
        append_methodology_write_journal(
            "repair-methodology-main", old_head, old_head, "held", detail=refusal
        )
        return False, refusal
    switched, switch_detail = switch_release_branch(upstream_ref, release_branch, "divergent-main", preserve_existing_main=ahead > 0)
    if not switched:
        append_methodology_write_journal(
            "repair-methodology-main", old_head, old_head, "failed", detail=switch_detail
        )
        return False, switch_detail
    new_head = run_git(canonical, ["rev-parse", "HEAD"])
    guard = install_methodology_release_guards()
    if ahead > 0:
        detail = (
            f"rescued divergent methodology main ahead={ahead} behind={behind}{switch_detail}; "
            f"reset {old_head[:12]} -> {new_head[:12]}; {guard}"
        )
    else:
        detail = (
            f"fast-forwarded methodology main behind={behind}; "
            f"reset {old_head[:12]} -> {new_head[:12]}; {guard}"
        )
    append_methodology_write_journal(
        "repair-methodology-main", old_head, new_head, "ok", detail=detail
    )
    return True, detail


def rescue_methodology_local_changes(upstream: tuple[str, str, str] | None = None) -> tuple[bool, str, str]:
    canonical = canonical_methodology_repo()
    upstream = upstream or methodology_upstream()
    if upstream is None:
        return False, "cannot auto-rescue local changes because no supported upstream is configured", ""
    remote, branch, upstream_ref = upstream
    code, stdout, stderr = run_command(["git", "-C", str(canonical), "fetch", remote, branch])
    if code != 0:
        return False, f"cannot auto-rescue local changes because upstream fetch failed: {stderr or stdout or 'command failed'}", ""
    upstream_sha = run_git(canonical, ["rev-parse", upstream_ref])
    if upstream_sha == "unavailable":
        return False, f"cannot auto-rescue local changes because upstream ref is unavailable: {upstream_ref}", ""
    # Verify-before-advance (sec-trust-exec-1): the fetch above did not move the checkout; refuse now,
    # before any rescue branch / commit / reset, so a denied upstream never advances the working tree.
    refusal = gate_methodology_upstream_advance(upstream_sha)
    if refusal is not None:
        return False, refusal, ""
    original_branch = run_git(canonical, ["branch", "--show-current"])
    old_head = run_git(canonical, ["rev-parse", "HEAD"])
    short_head = run_git(canonical, ["rev-parse", "--short", "HEAD"])
    stamp = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%SZ")
    rescue_branch = f"tautline-local-rescue/{stamp}-{os.getpid()}-{short_head}"

    def _failed(detail: str) -> tuple[bool, str, str]:
        append_methodology_write_journal(
            "rescue-methodology-local-changes", old_head, old_head, "failed", detail=detail
        )
        return False, detail, rescue_branch

    code, stdout, stderr = run_command(["git", "-C", str(canonical), "switch", "-c", rescue_branch])
    if code != 0:
        return _failed(f"auto-rescue failed during create rescue branch: {stderr or stdout or 'command failed'}")
    code, stdout, stderr = run_command(["git", "-C", str(canonical), "add", "-u"])
    if code != 0:
        return _failed(f"auto-rescue failed during stage tracked methodology changes: {stderr or stdout or 'command failed'}")
    staged_code, _staged_stdout, staged_stderr = run_command(["git", "-C", str(canonical), "diff", "--cached", "--quiet"])
    if staged_code not in (0, 1):
        return _failed(f"auto-rescue failed during staged change check: {staged_stderr or 'command failed'}")
    if staged_code == 1:
        commit_command = [
            "git",
            "-C",
            str(canonical),
            "-c",
            "user.name=Minervit Methodology",
            "-c",
            "user.email=methodology@minervit.local",
            "commit",
            "-m",
            "chore: preserve local methodology changes before auto-sync",
        ]
        code, stdout, stderr = run_command(commit_command)
        if code != 0:
            run_command(["git", "-C", str(canonical), "reset"])
            return _failed(f"auto-rescue failed during commit rescue branch: {stderr or stdout or 'command failed'}")
    untracked_dir, untracked_error = move_untracked_methodology_files(rescue_branch)
    if untracked_error:
        return _failed(f"auto-rescue failed while preserving untracked files: {untracked_error}")
    switched, switch_detail = switch_release_main(upstream_ref, "local-changes", preserve_existing_main=original_branch != "main")
    if not switched:
        return _failed(switch_detail)
    new_head = run_git(canonical, ["rev-parse", "HEAD"])
    untracked_detail = f"; untracked files moved to {untracked_dir}" if untracked_dir else ""
    if old_head != "unavailable" and new_head != "unavailable":
        detail = f"rescued local changes to {rescue_branch}{untracked_detail}{switch_detail}; updated {old_head[:12]} -> {new_head[:12]}"
    else:
        detail = f"rescued local changes to {rescue_branch}{untracked_detail}{switch_detail}; reset main to {upstream_ref}"
    append_methodology_write_journal(
        "rescue-methodology-local-changes", old_head, new_head, "ok", detail=detail
    )
    return True, detail, rescue_branch


def rescue_methodology_non_main_checkout(branch_display: str, channel: str = "stable") -> tuple[bool, str, str]:
    canonical = canonical_methodology_repo()
    release_branch = framework_channel_branch(channel)
    upstream = methodology_release_upstream(channel)
    if upstream is None:
        return False, f"cannot auto-rescue non-main methodology checkout because release origin/{release_branch} is not configured", ""
    remote, branch, upstream_ref = upstream
    code, stdout, stderr = run_command(["git", "-C", str(canonical), "fetch", remote, branch])
    if code != 0:
        return False, f"cannot auto-rescue non-main methodology checkout because release fetch failed: {stderr or stdout or 'command failed'}", ""
    upstream_sha = run_git(canonical, ["rev-parse", upstream_ref])
    if upstream_sha == "unavailable":
        return False, f"cannot auto-rescue non-main methodology checkout because release ref is unavailable: {upstream_ref}", ""
    dirty = run_git(canonical, ["status", "--porcelain"])
    if dirty == "unavailable":
        return False, "cannot auto-rescue non-main methodology checkout because status is unavailable", ""
    if dirty:
        rescued, detail, rescue_branch = rescue_methodology_local_changes(upstream)
        if not rescued:
            return False, detail, rescue_branch
        return True, f"non-main checkout {branch_display}; {detail}", rescue_branch
    old_head = run_git(canonical, ["rev-parse", "HEAD"])
    # Verify-before-advance (sec-trust-exec-1): refuse before the switch/reset so a denied upstream
    # never advances a clean non-release checkout to unverified code.
    refusal = gate_methodology_upstream_advance(upstream_sha)
    if refusal is not None:
        return False, refusal, ""
    switched, switch_detail = switch_release_branch(upstream_ref, release_branch, "non-main")
    if not switched:
        append_methodology_write_journal(
            "rescue-methodology-non-main", old_head, old_head, "failed", detail=switch_detail
        )
        return False, switch_detail, ""
    new_head = run_git(canonical, ["rev-parse", "HEAD"])
    if old_head != "unavailable" and new_head != "unavailable":
        detail = (
            f"switched clean methodology checkout from non-release branch {branch_display} ({old_head[:12]}) "
            f"to release {release_branch} {new_head[:12]}; branch preserved{switch_detail}"
        )
    else:
        detail = (
            f"switched clean methodology checkout from non-release branch {branch_display} "
            f"to release {release_branch}{switch_detail}"
        )
    append_methodology_write_journal(
        "rescue-methodology-non-main", old_head, new_head, "ok", detail=detail
    )
    return True, detail, ""


def invoked_from_methodology_repo() -> bool:
    """True when the cwd is inside EITHER methodology root (containment must cover both).

    This suppresses project-startup auto-rescue when a lane is already standing in the framework
    itself. Post-migration those are two directories -- the snapshot we execute and the canonical
    checkout sync mutates -- and missing either one would let an operator working inside one of
    them get their own checkout auto-rescued out from under them.
    """
    try:
        cwd = Path.cwd().resolve(strict=False)
    except OSError:
        return False
    return path_is_under(cwd, REPO_ROOT) or path_is_under(cwd, canonical_methodology_repo())


def methodology_repo_slugs() -> set[str]:
    return {METHODOLOGY_REPO_SLUG.lower(), *(slug.lower() for slug in LEGACY_METHODOLOGY_REPO_SLUGS)}


def adapter_is_methodology_repo(data: dict) -> bool:
    slug = str(data.get("repo", "")).strip().lower()
    if slug not in methodology_repo_slugs():
        return False
    _warn_legacy_methodology_slug(slug)
    return True


def should_auto_rescue_methodology_for_project_startup() -> bool:
    if util_module().resolve_env("MINERVIT_METHODOLOGY_DISABLE_AUTO_RESCUE") == "1":
        return False
    return not invoked_from_methodology_repo()


def framework_checkout_standdown_reason() -> str:
    """The sanctioned "this checkout is intentional, do not ask me to reconcile it" signals.

    ONE ENUMERATED SET, on purpose. Two review rounds each surfaced a different population this
    control locked out -- package-mode runtimes, then operator-launcher sessions -- and patching
    them one at a time invites a third. Every sanctioned way to say "I own this upstream" belongs
    here, so the question "who is exempt?" has one answer that a test can read.

    A control that refuses the wrong people does not get adopted; it gets bypassed, and the bypass
    is a machine-wide standdown that disables far more than this check.
    """
    if running_from_installed_package():
        # The canonical checkout is IRRELEVANT here: pip/pipx updates the running code, so a
        # leftover clone on another channel's branch says nothing about what this runtime executes.
        # `sync-methodology` already stands down for exactly this reason.
        return "standing down - package mode; the canonical checkout does not drive this runtime"
    if maintainer_mode_armed():
        # The ARMED predicate, not `maintainer_mode_configured`: a machine that developed the
        # framework and then disarmed is not standing down.
        return "standing down - maintainer mode manages this checkout"
    operator_channel = util_module().resolve_env("MINERVIT_METHODOLOGY_OPERATOR_CHANNEL")
    if operator_channel:
        # The operator launcher exports this when started with `--operator-channel`, which is the
        # explicit "I own this upstream" declaration. That session deliberately runs a non-release
        # checkout and its whole contract is that it never blocks.
        #
        # A DEDICATED signal, and Codex R3 P1 is why: an earlier version keyed on
        # DISABLE_AUTO_RESCUE, which any managed session may set to suppress destructive rescue
        # WITHOUT claiming ownership of the checkout. That turned a generic safety setting into a
        # blanket bypass of the exact contradiction this control exists to catch -- an
        # over-correction for R2's finding that was worse than the finding.
        return (
            f"standing down - operator-managed checkout (session declares channel "
            f"{operator_channel})"
        )
    return ""


def framework_checkout_reconciliation(
    channel: str,
    release_branch: str,
    allow_non_main: bool = False,
    target: Path | None = None,
) -> tuple[str, str]:
    """Returns ``("ok"|"deferred"|"advisory"|"required", line)``.

    RCA 2026-07-22 control 5: a channel/branch CONTRADICTION demands a resolution and is never
    carried forward as a bare warning again.

    THE ARMING CONDITION IS NARROW ON PURPOSE, and the narrowing is the whole design. ``required``
    fires ONLY when the checkout sits on ANOTHER CHANNEL's release branch -- the actual 2026-07-22
    state (checkout on `experimental`, channel `stable`), where every enumerated resolution is real.

    An any-non-release-branch rule was written first and rejected against measurement: this repo's
    own adapter carries no framework pin, so the channel resolves to `stable` -> release branch
    `main`, while every lane on the machine lives on `experimental` and on feature branches. That
    rule turned every framework session on any feature branch into exit-2 debt, and of its three
    enumerated exits two are impossible for a feature branch (you cannot check out a feature branch
    as a release branch, and channels are only `stable|experimental`), leaving a machine-wide
    `maintainer-mode on` as the only durable escape. **A fail-closed control whose cheapest exit is
    a global gate standdown teaches the bypass this cluster exists to delete.** So any other
    non-release branch -- feature branch, detached HEAD -- is ``advisory``: it prints the same
    enumerated line and exits 0.

    Every path this returns is executed by a test, so the function is bound by the composition rule
    it exists to serve.
    """
    standdown = framework_checkout_standdown_reason()
    if standdown:
        return "ok", standdown
    canonical = canonical_methodology_repo()
    if run_git(canonical, ["rev-parse", "--is-inside-work-tree"]) != "true":
        return "ok", ""
    branch = run_git(canonical, ["branch", "--show-current"])
    if branch in (release_branch, "unavailable"):
        return "ok", ""
    if allow_non_main or util_module().resolve_env("MINERVIT_METHODOLOGY_ALLOW_NON_MAIN") == "1":
        return "deferred", "MINERVIT_METHODOLOGY_ALLOW_NON_MAIN=1 (single intentional deviation)"
    display = branch or "detached HEAD"
    contradiction = bool(branch) and branch in set(FRAMEWORK_CHANNEL_BRANCHES.values())
    other_channel = next(
        (name for name, value in FRAMEWORK_CHANNEL_BRANCHES.items() if value == branch), ""
    )
    # Codex R1 P1 and P2: the remedy must name the RESOLVED target and be shell-safe. A remedy
    # that repins `.` when the operator ran `--target /path/to/lane` from elsewhere modifies the
    # wrong worktree and leaves the gate uncleared, and an unquoted path with a space is split by
    # the shell. This cluster shipped four wrong remedy lists; a remedy that runs somewhere else is
    # the same defect wearing a different hat.
    target_argument = guard_target_argument(target if target is not None else Path("."))
    canonical_argument = shlex.quote(str(canonical))
    third_path = (
        f"(3) the channel is wrong -> `{CLI_NAME} set-framework-channel {other_channel} "
        f"--target {target_argument}` (its release branch is the branch you are on); "
        if contradiction and other_channel
        else f"(3) you are on a working branch -> finish or park it and return to "
        f"{release_branch}, or arm maintainer mode if this machine develops the framework; "
    )
    paths = (
        f"Resolve one: (1) you develop the framework and track {display} on purpose -> "
        f"`{CLI_NAME} maintainer-mode on`; "
        f"(2) this machine should follow the channel -> `git -C {canonical_argument} checkout "
        f"{release_branch}` then `{CLI_NAME} sync-methodology --target {target_argument}`; "
        + third_path
        + "One-shot deviation: MINERVIT_METHODOLOGY_ALLOW_NON_MAIN=1."
    )
    return ("required" if contradiction else "advisory"), (
        f"methodology checkout tracks {display} but channel '{channel}' releases from "
        f"{release_branch}. {paths}"
    )


def framework_checkout_reconciliation_lines(
    channel: str,
    release_branch: str,
    allow_non_main: bool = False,
    target: Path | None = None,
) -> tuple[str, list[str]]:
    """The printable form, so both surfaces emit byte-identical text from one place."""
    state, line = framework_checkout_reconciliation(
        channel, release_branch, allow_non_main, target
    )
    if not line:
        return state, []
    return state, [f"framework_checkout_reconciliation: {state} - {line}"]


def methodology_checkout_hygiene_warning(allow_non_main: bool = False) -> str:
    canonical = canonical_methodology_repo()
    if run_git(canonical, ["rev-parse", "--is-inside-work-tree"]) != "true":
        return ""
    # The BRANCH condition moved to `framework_checkout_reconciliation`, which resolves the release
    # branch from the CHANNEL instead of hardcoding `main`. Hardcoding it meant a lane on channel
    # `experimental` sitting on `experimental` -- correct -- was warned, while the same lane sitting
    # on `main` -- the actual contradiction -- was silent. This arm keeps only the dirty-checkout
    # condition, which has a different owner and a different remedy.
    dirty = run_git(canonical, ["status", "--porcelain"])
    if dirty not in ("", "unavailable"):
        return (
            "methodology checkout has local changes; "
            "manual or pinned framework updates will not auto-rescue this checkout"
        )
    return ""


# --- The immutable snapshot store ----------------------------------------------------------
# Lanes must not execute a tree that `sync-methodology` is concurrently rewriting. So sync mutates
# only the canonical checkout, and each trust-verified commit is EXPORTED into
# <store>/<short12-sha>/ -- a tree with no .git, made physically read-only -- behind an atomically
# swapped `current` symlink. Three invariants hold the design up:
#
#   immutable   a published snapshot is 0444/0555 files and 0555 dirs. Immutability is enforced by
#               the filesystem, not by discipline: any write path we failed to retarget at the
#               canonical checkout fails LOUDLY here instead of silently corrupting the tree that
#               other lanes are mid-execution on.
#   atomic      a snapshot is visible complete or not at all (stage in .tmp/, publish by rename),
#               and every failure path leaves the store exactly as it found it.
#   safe prune  retention never deletes a tree something is still executing: the current target,
#               a live pin, a recently-current snapshot, or the newest `keep`.
#
# PERMISSIONS AND rename(2) -- the trap that shapes the code below. Once a tree is 0555 you can
# neither move it to a new parent (rename must update its `..` entry, which needs write permission
# on the directory being moved: EACCES) nor delete it (unlinking a child needs write permission on
# its 0555 parent). shutil.rmtree(..., ignore_errors=True) fails at that SILENTLY. So: the
# read-only pass deliberately leaves the tree's ROOT writable and the caller locks it after the
# publish rename; prune restores the root's write bit before its rename; and every removal of a
# tree that may already be read-only goes through _rmtree_force. Nothing here may use bare rmtree.

SNAPSHOT_KEEP_ENV = "MINERVIT_METHODOLOGY_SNAPSHOT_KEEP"
SNAPSHOT_PIN_TTL_HOURS_ENV = "MINERVIT_METHODOLOGY_SNAPSHOT_PIN_TTL_HOURS"
_SNAPSHOT_DIR_PATTERN = re.compile(r"[0-9a-f]{12}")










_SNAPSHOT_STORE_WARNINGS: set[str] = set()

# Errno-sensitive fault naming: "store unreadable" on a full disk sends the operator chasing
# permissions instead of freeing space. These five cover the write faults prune can hit
# (ENOSPC/EDQUOT), the read-only-mount and stale-mount cases the helper's docstring names, and
# raw device errors. EACCES/EPERM stay on the default -- the exec integration tests pin it.
# Deliberately a leading-underscore dict, not an UPPER_CASE list[str]: policy_phrase_constants()
# would otherwise sweep these phrases into the policy-phrases SSOT.
# getattr-guarded: EDQUOT/ESTALE are POSIX-only and absent from errno on native
# Windows -- direct attribute access would crash the CLI at IMPORT, before any
# command could run (Codex R2 on the 0.10.3 train).
_SNAPSHOT_STORE_FAULT_PHRASES: dict[int, str] = {
    code: phrase
    for name, phrase in (
        ("ENOSPC", "store out of space"),
        ("EDQUOT", "store quota exhausted"),
        ("EROFS", "store on a read-only filesystem"),
        ("ESTALE", "store on a stale mount"),
        ("EIO", "store I/O error"),
    )
    if (code := getattr(errno, name, None)) is not None
}


def warn_snapshot_store_unreadable(operation: str, exc: OSError) -> None:
    """Announce a store read that could not complete -- once per distinct failure per process.

    Reading the store must NEVER raise past its helper. The store is an optimization, never a
    dependency: "I cannot even look at it" has to answer the same as "there is nothing there" --
    no usable current, run the canonical checkout -- because a launch that dies on a chmod, an ACL,
    a stale mount or a full disk is the one failure mode the store was built to be incapable of.
    (A raise here does not merely fail a command: under the launcher's no-dead-ends policy a failed
    sync gate escalates to a repair session, so an unreadable store would drive the whole fleet into
    repair instead of quietly degrading.)

    But it must not degrade SILENTLY either, or a store that has been broken for weeks looks exactly
    like a machine that never enabled one. Deduplicated because a single sync reads the store
    several times over (gate skip, heal, stamp, pin refresh) and four copies of one line say nothing
    the first does not. The wording is errno-sensitive (_SNAPSHOT_STORE_FAULT_PHRASES) so the one
    line the operator gets names the actual fault, not a blanket "unreadable".

    The warning rides stderr: `snapshot-status` stdout is its machine-readable key:value report,
    and a degrade line dropped into the middle of it corrupts what a script is parsing.
    """
    phrase = _SNAPSHOT_STORE_FAULT_PHRASES.get(exc.errno, "store unreadable")
    detail = f"methodology_snapshot: {phrase} - {operation}: {exc}"
    if detail in _SNAPSHOT_STORE_WARNINGS:
        return
    _SNAPSHOT_STORE_WARNINGS.add(detail)
    print(detail, file=sys.stderr, flush=True)


def _snapshot_dir_manifest(dest: Path) -> dict | None:
    """The manifest of a snapshot directory in the store (vs. snapshot_manifest(), which reads the
    one we are EXECUTING). A dir with no readable, schema-matching manifest is not a snapshot: it
    is a partial publish or a foreign directory, and must never be reused or trusted."""
    try:
        data = json.loads((dest / SNAPSHOT_MANIFEST_NAME).read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return None
    if not isinstance(data, dict) or data.get("schema") != SNAPSHOT_MANIFEST_SCHEMA:
        return None
    return data


def _snapshot_is_executable(snapshot_dir: Path) -> bool:
    """Can anything actually RUN this snapshot?

    The one predicate that decides whether a snapshot is usable, and it is not the manifest. The
    shim asks `[ -x "$SNAPSHOT_CURRENT/bin/tautline" ]`, the launcher asks the same of
    `$SNAPSHOT_STORE/current/bin/tautline`, and both fall through to the canonical checkout when the
    answer is no. Python has to ask exactly that question, of exactly that path, or the two halves
    of one machine disagree about whether the store works: a manifest is an INDEX ENTRY, and a
    `current` whose .snapshot-meta.json is pristine while its CLI has been deleted is not a healthy
    snapshot, it is a trap that every shim on the machine execs into and every shim falls out of.
    """
    try:
        cli_path = snapshot_dir / "bin" / CLI_NAME
        return cli_path.is_file() and os.access(cli_path, os.X_OK)
    except OSError:
        return False




def _store_snapshot_dirs(store: Path) -> list[Path]:
    """Published snapshots, oldest -> newest.

    materializedAt is second-granularity, so mtime breaks ties and the (stable, arbitrary) name
    breaks the rest. Anything without a valid manifest is not listed -- it is not a snapshot.

    An unreadable store lists as EMPTY, never as an exception: same contract as
    methodology_snapshot_current_dir(). The guard has to span the stat()s as well as the iterdir(),
    and not just the iterdir() it once covered -- listing a directory needs only READ permission
    while stat-ing what is in it needs SEARCH, so a store with one but not the other enumerated
    happily and then raised EACCES on the first sort key. But a SINGLE entry vanishing under the
    stat (ENOENT/ENOTDIR: a concurrent prune retired it, snapshot-status lists locklessly) is not
    store-level unreadability: that entry is skipped, never escalated to "store unreadable".
    """
    keyed: list[tuple[str, float, str, Path]] = []
    try:
        if not store.is_dir():
            return []
        for path in store.iterdir():
            if not _SNAPSHOT_DIR_PATTERN.fullmatch(path.name):
                continue
            manifest = _snapshot_dir_manifest(path)
            if manifest is None:
                continue
            try:
                mtime = path.stat().st_mtime
            except (FileNotFoundError, NotADirectoryError):
                # A concurrent _retire_store_snapshot_dir rename landed between the manifest
                # read and the stat. A retired entry is not a store fault -- any correct
                # listing would have excluded it -- so skip it, never escalate.
                continue
            # str(): a hand-corrupted manifest with a non-string materializedAt would otherwise
            # take out the whole sort with a TypeError -- another store read crashing the CLI.
            keyed.append((str(manifest.get("materializedAt", "")), mtime, path.name, path))
    except OSError as exc:
        warn_snapshot_store_unreadable("cannot list snapshots", exc)
        return []
    keyed.sort(key=lambda item: item[:3])
    return [item[3] for item in keyed]


def materialize_methodology_snapshot(
    repo: Path, commit: str, channel: str
) -> tuple[Path | None, str]:
    """Export <commit> of <repo> into an immutable store directory. Atomic publish, idempotent.

    Returns (snapshot_dir, detail) or (None, why). NEVER raises: a broken/unwritable store must
    degrade to "keep running the code we already have", never fail an operator's session start.
    """
    store = methodology_snapshot_store_root()
    # --verify ... ^{commit}, not a bare rev-parse: a bare `rev-parse <40-hex>` happily echoes back
    # a sha that names no object in this repo, and we would go on to name a store directory after a
    # commit that does not exist and only discover it when `git archive` failed.
    full_sha = run_git(repo, ["rev-parse", "--verify", "--quiet", f"{commit}^{{commit}}"])
    if full_sha in ("", "unavailable") or not re.fullmatch(r"[0-9a-f]{40}", full_sha):
        return None, f"could not resolve {commit} in {repo}"
    dest = store / full_sha[:12]
    staging = store / ".tmp" / f"mat-{full_sha[:12]}-{os.getpid()}"
    tar_path = store / ".tmp" / f"mat-{full_sha[:12]}-{os.getpid()}.tar"
    try:
        (store / ".tmp").mkdir(parents=True, exist_ok=True)
        lock_path = store / ".store-lock"
        with lock_path.open("a", encoding="utf-8") as lock_file, advisory_flock(lock_file):
            existing = _snapshot_dir_manifest(dest)
            if existing and existing.get("commit") == full_sha:
                if _snapshot_is_executable(dest):
                    return dest, f"reused existing snapshot {full_sha[:12]}"
                # The manifest matches but the tree cannot be run. Reusing it would hand the caller
                # back the very trap it asked us to repair -- heal would swap `current` onto a
                # snapshot with no CLI and report success. Retire it and publish a whole one.
                if not _retire_store_snapshot_dir(dest):
                    return None, (
                        f"snapshot {full_sha[:12]} is missing bin/{CLI_NAME} and could not be "
                        "replaced"
                    )
            if staging.exists():
                # A crash between the read-only pass and the publish rename leaves a 0555 tree
                # under this exact name (same sha, and pids recycle). Plain rmtree cannot remove
                # it, so materialization would be wedged for as long as the leak survives.
                _rmtree_force(staging)
            staging.mkdir(parents=True)
            # The unlink has to cover the ARCHIVE too, not just the extraction: `git archive -o`
            # creates its output file before it writes, so a failure partway (disk-full is the
            # realistic one) leaves a partial tar behind. prune never walks .tmp -- it only visits
            # manifest-bearing snapshot dirs, pins and history -- so a tar orphaned here is orphaned
            # permanently, and the disk-full case would leak another one on every retry.
            try:
                code, _stdout, stderr = run_command(
                    [
                        "git", "-C", str(repo), "archive", "--format=tar",
                        "-o", str(tar_path), full_sha,
                    ]
                )
                if code != 0:
                    _rmtree_force(staging)
                    return None, f"git archive failed: {stderr or 'unknown error'}"
                try:
                    _safe_extract_methodology_tar(tar_path, staging)
                except (OSError, tarfile.TarError) as exc:
                    _rmtree_force(staging)
                    return None, f"snapshot extraction failed: {exc}"
            finally:
                tar_path.unlink(missing_ok=True)
            if not (staging / "bin" / CLI_NAME).is_file() or not (staging / "VERSION").is_file():
                _rmtree_force(staging)
                return None, (
                    f"exported tree is missing bin/{CLI_NAME} or VERSION; refusing to publish"
                )
            (staging / "bin" / CLI_NAME).chmod(0o755)
            manifest = {
                "schema": SNAPSHOT_MANIFEST_SCHEMA,
                "commit": full_sha,
                "shortCommit": full_sha[:12],
                "version": (staging / "VERSION").read_text(encoding="utf-8").strip(),
                "channel": channel,
                "materializedAt": datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ"),
                "canonicalRepo": str(repo.resolve()),
                "materializedBy": {"pid": os.getpid(), "pluginVersion": methodology_version()},
            }
            util_module().write_text_atomic(
                staging / SNAPSHOT_MANIFEST_NAME, json.dumps(manifest, indent=2) + "\n"
            )
            _make_snapshot_read_only(staging)
            try:
                os.rename(staging, dest)
            except OSError as exc:
                # The staging tree is READ-ONLY by now -- _rmtree_force, never rmtree, or this
                # leaks a 0555 tree per attempt and no one ever finds out.
                _rmtree_force(staging)
                winner = _snapshot_dir_manifest(dest)
                if winner and winner.get("commit") == full_sha:
                    return dest, (
                        f"reused snapshot {full_sha[:12]} published by a concurrent process"
                    )
                return None, f"could not publish snapshot {full_sha[:12]}: {exc}"
            try:
                dest.chmod(0o555)  # the last write bit: the tree is in place, seal its root
            except OSError:
                pass
    except OSError as exc:
        _rmtree_force(staging)
        return None, f"snapshot store unavailable: {exc}"
    append_methodology_write_journal(
        "snapshot.materialize", full_sha, full_sha, "ok", detail=str(dest)
    )
    return dest, f"materialized {full_sha[:12]}"


def swap_methodology_snapshot_current(snapshot_dir: Path) -> tuple[bool, str]:
    """Point <store>/current at a snapshot atomically (symlink + os.replace).

    os.replace on a symlink swaps the LINK, never its target, so no lane ever observes a missing
    or half-written `current`: it sees the old snapshot, then the new one.
    """
    store = snapshot_dir.parent
    tmp_link = store / f".current-tmp-{os.getpid()}"
    try:
        if tmp_link.is_symlink() or tmp_link.exists():
            tmp_link.unlink()
        os.symlink(snapshot_dir.name, tmp_link)  # relative: the store stays relocatable
        os.replace(tmp_link, store / "current")
    except OSError as exc:
        try:
            tmp_link.unlink(missing_ok=True)
        except OSError:
            pass
        return False, f"could not swap current symlink: {exc}"
    # The swap history is what protects a snapshot that is no longer current but is still being
    # executed by a session that adopted it while it was (see prune's TTL window).
    history_path = store / "history.jsonl"
    try:
        with history_path.open("a", encoding="utf-8") as handle, advisory_flock(handle):
            handle.write(
                json.dumps(
                    {
                        "ts": datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ"),
                        "snapshot": snapshot_dir.name,
                    }
                )
                + "\n"
            )
    except OSError:
        pass
    append_methodology_write_journal("snapshot.swap-current", "", snapshot_dir.name, "ok")
    return True, f"current -> {snapshot_dir.name}"


def methodology_snapshot_pin_path(lane_path: Path) -> Path:
    return methodology_snapshot_store_root() / "pins" / f"{instrumentation_lane_id(lane_path)}.pin"


def write_methodology_snapshot_pin(lane_path: Path, snapshot_dir: Path) -> Path:
    """Declare "this lane is executing this snapshot; do not delete it".

    The pin's MTIME is its heartbeat -- prune ages pins out past the TTL, so a lane that dies
    without cleaning up cannot protect a snapshot forever.
    """
    pin_path = methodology_snapshot_pin_path(lane_path)
    pin_path.parent.mkdir(parents=True, exist_ok=True)
    util_module().write_text_atomic(
        pin_path,
        json.dumps(
            {
                "schema": SNAPSHOT_PIN_SCHEMA,
                "snapshot": snapshot_dir.name,
                "lanePath": str(lane_path),
                "pid": os.getpid(),
                "createdAt": datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ"),
            },
            indent=2,
        )
        + "\n",
    )
    return pin_path


def snapshot_pin_ttl_seconds() -> int:
    raw = util_module().resolve_env(SNAPSHOT_PIN_TTL_HOURS_ENV)
    hours = int(raw) if raw.isdigit() else SNAPSHOT_DEFAULT_PIN_TTL_HOURS
    return hours * 3600


def prune_methodology_snapshots(keep: int | None = None) -> list[str]:
    """Delete superseded snapshots. Returns the names actually removed.

    A snapshot is protected when ANY of these hold, because each means something may still be
    executing it: it is among the newest `keep`; it is the current target; a lane holds a pin on it
    younger than the TTL; or it was current within the TTL window (a session that adopted it is
    bounded by the same TTL). Everything else is garbage.
    """
    store = methodology_snapshot_store_root()
    if keep is None:
        raw_keep = util_module().resolve_env(SNAPSHOT_KEEP_ENV)
        keep = int(raw_keep) if raw_keep.isdigit() else SNAPSHOT_DEFAULT_KEEP
    ttl_seconds = snapshot_pin_ttl_seconds()
    pruned: list[str] = []
    lock_path = store / ".store-lock"
    try:
        # Inside the guard: is_dir() stats the store, and on an unreadable one that raises rather
        # than answering False. Prune is called from the heal/advance paths, so an escape here
        # fails a launch just as surely as one out of methodology_snapshot_current_dir().
        if not store.is_dir():
            return []
        with lock_path.open("a", encoding="utf-8") as lock_file, advisory_flock(lock_file):
            snaps = _store_snapshot_dirs(store)
            protected = {path.name for path in snaps[-keep:]} if keep > 0 else set()
            current = store / "current"
            if current.is_symlink():
                protected.add(current.resolve(strict=False).name)
            pins_dir = store / "pins"
            now = time.time()
            if pins_dir.is_dir():
                for pin in pins_dir.glob("*.pin"):
                    try:
                        if now - pin.stat().st_mtime > ttl_seconds:
                            pin.unlink()
                            continue
                        pin_data = json.loads(pin.read_text(encoding="utf-8"))
                        protected.add(str(pin_data.get("snapshot", "")))
                    except (OSError, json.JSONDecodeError):
                        continue
            history = store / "history.jsonl"
            if history.is_file():
                cutoff = datetime.now(timezone.utc) - timedelta(seconds=ttl_seconds)
                try:
                    lines = history.read_text(encoding="utf-8").splitlines()
                except OSError:
                    lines = []
                for line in lines:
                    try:
                        entry = json.loads(line)
                        when = datetime.strptime(entry["ts"], "%Y-%m-%dT%H:%M:%SZ").replace(
                            tzinfo=timezone.utc
                        )
                    except (json.JSONDecodeError, KeyError, TypeError, ValueError):
                        continue
                    if when >= cutoff:
                        protected.add(str(entry.get("snapshot", "")))
            (store / ".tmp").mkdir(exist_ok=True)
            for snap in snaps:
                if snap.name in protected:
                    continue
                if _retire_store_snapshot_dir(snap):
                    pruned.append(snap.name)
    except OSError as exc:
        warn_snapshot_store_unreadable("prune incomplete", exc)
        return pruned
    if pruned:
        append_methodology_write_journal("snapshot.prune", "", "", "ok", detail=",".join(pruned))
    return pruned


def methodology_snapshot_current_dir() -> Path | None:
    """The snapshot <store>/current points at, or None when absent/dangling/not a snapshot.

    An UNREADABLE store answers None too, loudly. `is_symlink()` stats the path, and a store
    directory that cannot be opened at all (chmod, ACL, dead mount) makes that stat fail with
    EACCES -- which pathlib propagates on some interpreter/platform combinations and swallows on
    others. Every caller here treats None as "no usable snapshot, run the canonical checkout", so
    letting the error escape on the platforms that raise turned the store's one safety promise
    inside out: instead of degrading, an unreadable store BLOCKED the launch.
    """
    current = methodology_snapshot_store_root() / "current"
    try:
        if not current.is_symlink():
            return None
        resolved = current.resolve(strict=False)
    except OSError as exc:
        warn_snapshot_store_unreadable("no usable current, using canonical checkout", exc)
        return None
    return resolved if _snapshot_dir_manifest(resolved) else None


def _published_store_snapshot(candidate: Path) -> Path | None:
    """`candidate` as a snapshot PUBLISHED IN THIS STORE, or None.

    A pin records a snapshot by NAME and prune protects store entries by name, so a pin is only
    protection when the name it carries is one this store can actually collect. A path that is not
    a manifest-bearing <sha12> directory directly under the store root -- a pruned exec root, a
    checkout, a foreign or stale export -- must therefore never reach a pin: it would write a pin
    that guards nothing, which is strictly worse than falling back to `current`.
    """
    store = methodology_snapshot_store_root()
    try:
        resolved = candidate.expanduser().resolve(strict=False)
        if resolved.parent != store.resolve(strict=False):
            return None
        if not _SNAPSHOT_DIR_PATTERN.fullmatch(resolved.name):
            return None
    except OSError as exc:
        warn_snapshot_store_unreadable("cannot resolve the session exec root", exc)
        return None
    return resolved if _snapshot_dir_manifest(resolved) else None


def session_snapshot_exec_root() -> Path | None:
    """The snapshot THIS SESSION is executing, or None when it is not executing one.

    NOT `current`. Session-stickiness is the store's whole point: a session resolves one exec root
    (the launcher does it with `pwd -P` and exports it; the shim re-execs into it) and runs that
    tree for its entire life, precisely so another lane's swap cannot hop it between versions
    mid-flight. `current` is the opposite of that -- a symlink any lane may move at any instant.

    Two sources, in the order they are authoritative:

    1. The running tree itself. When this process IS a snapshot, its own manifest is not an
       assertion about the session, it is the session: no env, no symlink, nothing to race.
    2. The exported exec root. This covers the one case (1) cannot see: an operator-preset
       MINERVIT_METHODOLOGY_CLI keeps the launcher's own CLI on the canonical checkout while every
       hook in the session still execs the exported snapshot -- so the session runs a snapshot that
       this process is not.

    Both are validated against the store, so a stale or pruned root degrades to `current` rather
    than writing a pin that protects nothing.
    """
    if running_from_snapshot():
        own = _published_store_snapshot(REPO_ROOT)
        if own is not None:
            return own
    # Read exactly as the shim and the launcher read it -- the MINERVIT_ spelling, no alias. This
    # is not an operator setting but the session's own inherited exec state, and resolve_env would
    # let a stale TAUTLINE_-spelled shell variable outrank it: Python would then pin one snapshot
    # while the shell half of the same session execs another, which is the very split this
    # function exists to close. tests/test_env_reads_use_resolver.py holds the exemption.
    exported = os.environ.get(METHODOLOGY_EXEC_ROOT_ENV, "").strip()
    if exported:
        return _published_store_snapshot(Path(exported))
    return None


def snapshot_status(args: argparse.Namespace) -> int:
    store = methodology_snapshot_store_root()
    print(f"snapshot_store_root: {store}")
    print(f"snapshot_store_enabled: {'true' if methodology_snapshot_store_enabled() else 'false'}")
    if methodology_snapshot_exec_disabled():
        # Otherwise `enabled: false` on a machine whose store key IS configured reads as a bug.
        # Name the lever that turned it off, so the way back is obvious.
        print(f"snapshot_exec_disabled: true ({METHODOLOGY_DISABLE_SNAPSHOT_EXEC_ENV}=1)")
    elif running_from_installed_package() and _managed_config_value(METHODOLOGY_SNAPSHOT_STORE_ENV):
        # Same truthfulness rule for the package standdown: a leftover store key on a pip/pipx
        # install reads `enabled: false` above -- name the cause so it does not read as a bug.
        print("snapshot_store_standdown: installed package runtime - leftover store key is inert")
    current = methodology_snapshot_current_dir()
    print(f"snapshot_store_current: {current.name if current else 'none'}")
    snaps = _store_snapshot_dirs(store)
    print(f"snapshot_store_count: {len(snaps)}")
    for snap in snaps:
        manifest = _snapshot_dir_manifest(snap) or {}
        print(
            f"snapshot: {snap.name} version={manifest.get('version', 'unknown')} "
            f"channel={manifest.get('channel', 'unknown')} "
            f"materialized={manifest.get('materializedAt', 'unknown')}"
        )
    pins_dir = store / "pins"
    ttl_seconds = snapshot_pin_ttl_seconds()
    now = time.time()
    try:
        # is_dir() and glob() both stat, so both raise on an unreadable store. `snapshot-status` is
        # the command an operator reaches for BECAUSE the store looks wrong; it has to survive a
        # store that is wrong and report it, not traceback on the way to saying so.
        pins = sorted(pins_dir.glob("*.pin")) if pins_dir.is_dir() else []
    except OSError as exc:
        warn_snapshot_store_unreadable("cannot list pins", exc)
        pins = []
    for pin in pins:
        try:
            data = json.loads(pin.read_text(encoding="utf-8"))
            age = int(now - pin.stat().st_mtime)
        except (OSError, json.JSONDecodeError):
            continue
        state = "stale" if age > ttl_seconds else "live"
        print(
            f"snapshot_pin: {pin.stem} -> {data.get('snapshot', 'unknown')} "
            f"age={age // 3600}h state={state} lane={data.get('lanePath', 'unknown')}"
        )
    return 0


def snapshot_prune(args: argparse.Namespace) -> int:
    keep = getattr(args, "keep", None)
    pruned = prune_methodology_snapshots(keep=keep)
    print(f"snapshot_store_root: {methodology_snapshot_store_root()}")
    print(f"snapshot_pruned: {', '.join(pruned) if pruned else 'none'}")
    return 0


def snapshot_pin_target() -> Path | None:
    """The snapshot a pin for THIS session must name.

    The session's own exec root when it has one, and only then `current`. Pinning `current`
    unconditionally is a race against the very stickiness the store provides: the launcher resolves
    the exec root and calls `snapshot-pin` a few lines later, and any lane that swaps `current` in
    that window makes this lane declare a snapshot it is not running -- leaving prune free to
    collect the one it IS running, which is the single deletion the pin exists to prevent.

    `current` remains the fallback, not the rule: a pre-cutover launcher, a bare `tautline
    snapshot-pin` on a machine whose store is only just enabled, and any session executing the
    canonical checkout all legitimately have no exec root, and the snapshot they would adopt on
    their next launch is exactly `current`.
    """
    return session_snapshot_exec_root() or methodology_snapshot_current_dir()


def snapshot_pin(args: argparse.Namespace) -> int:
    """Pin the lane to the snapshot it is executing.

    Called by the launcher on EVERY start, so it exits 0 no matter what: a disabled store, an empty
    store, or a store mid-bootstrap is a note, never a failed session start.
    """
    lane = Path(getattr(args, "target", None) or ".").expanduser().resolve(strict=False)
    if not methodology_snapshot_store_enabled():
        print("snapshot_pin: skipped - snapshot store not enabled")
        return 0
    target = snapshot_pin_target()
    if target is None:
        print(f"snapshot_pin: skipped - no current snapshot in {methodology_snapshot_store_root()}")
        return 0
    try:
        pin_path = write_methodology_snapshot_pin(lane, target)
    except OSError as exc:
        print(f"snapshot_pin: skipped - could not write pin: {exc}")
        return 0
    print(f"snapshot_pin: {pin_path}")
    print(f"snapshot_pin_target: {target.name}")
    print(f"snapshot_pin_lane: {lane}")
    return 0


def heal_methodology_snapshot_current(channel: str = "stable") -> None:
    """Make `<store>/current` name the canonical HEAD: rebuild it when missing or dangling, and
    republish it when it is STALE.

    Without this the store would only ever gain a `current` on a trust-gated ADVANCE, which may be
    days away: a freshly-enabled store (or one whose current target was deleted) would leave every
    session falling back to the canonical checkout while the store sat there empty. Best-effort by
    construction -- the store is an optimization, never a dependency, so a failure prints and the
    sync carries on.

    Staleness is reconciled here because this is the ONLY publisher that runs when no advance
    fires, and every way the store gets left behind ends in exactly that state: a publish that
    failed mid-advance, an operator taking the rollback lever in one shell (that lane fast-forwards
    the canonical checkout and, executing the canonical tree, publishes nothing), or a manual git
    advance. In all three the checkout moves and `current` does not -- and because the next lane's
    sync then finds the checkout already up to date, no advance fires and _reexec_updated_methodology
    (the only other publisher) is never re-entered. Returning early on a `current` that merely
    EXISTS therefore froze the store one head behind for good, and every session on the machine kept
    executing the stale snapshot while sync reported ok.

    Trust is NOT re-litigated here: the canonical checkout only reaches a new head through the
    trust-gated advance path (or the operator's own hands), so its HEAD is already the machine's
    decision about what to run. This mirrors what heal has always done for a missing `current`.
    """
    if not methodology_snapshot_store_enabled():
        return
    canonical = canonical_methodology_repo()
    head = run_git(canonical, ["rev-parse", "HEAD"])
    if head == "unavailable":
        print(f"methodology_snapshot: heal skipped - HEAD unavailable in {canonical}")
        return
    current = methodology_snapshot_current_dir()
    at_head = current is not None and (
        (_snapshot_dir_manifest(current) or {}).get("commit") == head
    )
    # Healthy means RUNNABLE, not merely manifest-consistent. A `current` whose manifest names the
    # canonical head while its bin/tautline has been deleted passes every commit comparison in this
    # file and fails the only test that decides anything: the `-x` the shim and the launcher apply
    # before they exec it. Judged healthy, it is never repaired -- so every session on the machine
    # silently falls back to the canonical checkout, forever, while sync reports ok.
    if at_head and _snapshot_is_executable(current):
        return  # already the canonical head, and runnable: no republish, no swap, no prune churn
    # A `current` that is present but stale (or present but gutted) is republished, not left alone.
    # Distinguish that from an empty store in the report: "healed" is a store that had nothing to
    # run, "republished" is one that was quietly serving a head nobody can execute.
    action = "republished current" if current is not None else "healed current"
    snapshot_dir, snap_detail = materialize_methodology_snapshot(canonical, head, channel)
    if snapshot_dir is None:
        print(f"methodology_snapshot: failed - {snap_detail}")
        return
    swapped, swap_detail = swap_methodology_snapshot_current(snapshot_dir)
    if not swapped:
        # Report what actually happened. This function IS the recovery mechanism for a store whose
        # `current` is missing, dangling or stale, so announcing success over a failed swap would
        # leave the operator's only signal that the store is still broken reading as a repair -- a
        # silent failure in the very machinery that exists to make store failures loud.
        print(f"methodology_snapshot: heal failed - {snap_detail}; {swap_detail}")
        return
    print(f"methodology_snapshot: {action} - {snap_detail}; {swap_detail}")
    prune_methodology_snapshots()


# --- Launcher sync gate -------------------------------------------------------------------
# Every lane start runs sync-methodology. Ungated, N lanes launching together all fetch, all
# advance the one canonical checkout, and all race to publish the same snapshot into the same
# store. The gate makes the first lane do the work and the rest observe its result: a flock
# serializes them, and a freshness stamp lets the ones that wake up behind it skip a sync that
# demonstrably just happened.
METHODOLOGY_SYNC_FRESHNESS_ENV = "MINERVIT_METHODOLOGY_SYNC_FRESHNESS_MINUTES"
# Exec-handoff pair, read with os.environ.get and NEVER through resolve_env: a TAUTLINE_ alias for
# either would let a stale shell variable outrank what this process exported into its own
# environment microseconds earlier -- and for the lock fd, "outrank" means flocking a foreign file
# descriptor number. tests/test_env_reads_use_resolver.py holds the exemption and the prohibition.
METHODOLOGY_SYNC_LOCK_FD_ENV = "MINERVIT_METHODOLOGY_SYNC_LOCK_FD"
METHODOLOGY_SYNC_GATE_ENV = "MINERVIT_METHODOLOGY_SYNC_GATE"


def methodology_sync_lock_path() -> Path:
    return methodology_state_dir() / "methodology-sync.lock"


def methodology_sync_stamp_path() -> Path:
    return methodology_state_dir() / "methodology-sync.stamp"


def methodology_sync_freshness_seconds() -> int:
    """The window in which another lane's sync counts as this lane's sync. 0 disables the skip."""
    raw = util_module().resolve_env(METHODOLOGY_SYNC_FRESHNESS_ENV).strip()
    minutes = int(raw) if raw.isdigit() else METHODOLOGY_SYNC_DEFAULT_FRESHNESS_MINUTES
    return max(minutes, 0) * 60


def write_methodology_sync_stamp(head: str, snapshot: str, status: str) -> None:
    """Record that the methodology is synced as of NOW, to this head and this snapshot.

    Best-effort by construction: the stamp is an optimization, never a correctness input. A lane
    that cannot write it costs the next lane one redundant fetch, which is the pre-gate behavior.
    """
    try:
        path = methodology_sync_stamp_path()
        path.parent.mkdir(parents=True, exist_ok=True)  # fresh HOME: the state dir may not exist
        util_module().write_text_atomic(
            path,
            json.dumps(
                {
                    "schema": METHODOLOGY_SYNC_STAMP_SCHEMA,
                    "syncedAt": datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ"),
                    "head": head,
                    "snapshot": snapshot,
                    "status": status,
                    "pid": os.getpid(),
                },
                indent=2,
            )
            + "\n",
        )
    except OSError:
        pass


def read_methodology_sync_stamp() -> tuple[dict, float] | None:
    """The stamp plus its age in seconds, or None when absent, unreadable, or foreign.

    Age comes from the file's mtime, not from `syncedAt`: write_text_atomic renames a fresh temp
    file into place, so the mtime IS the write instant, and it cannot be faked by a stale clock in
    the JSON the way a hand-edited timestamp could.
    """
    path = methodology_sync_stamp_path()
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
        age = time.time() - path.stat().st_mtime
    except (OSError, json.JSONDecodeError):
        return None
    if not isinstance(data, dict) or data.get("schema") != METHODOLOGY_SYNC_STAMP_SCHEMA:
        return None
    return data, max(age, 0.0)


def launcher_gate_skip_reason() -> str | None:
    """Why this gated sync may trust a sibling lane's recent sync, or None to do the work.

    Every condition below is a bug that was worth a test:
      * a re-exec token VETOES the skip. A post-advance process arrives holding a stamp its own
        predecessor wrote seconds ago, and its entire purpose is the post-sync body the predecessor
        could not run (token consumption, release guards, heal, pin refresh, version reporting).
        Skipping there would silently drop all of it;
      * a fresh stamp over a store whose `current` is missing, dangling, or gutted must NOT skip,
        or the heal that would rebuild it is starved for a whole freshness window and every session
        launched in that window quietly falls back to the canonical checkout;
      * the stamp must name the snapshot `current` actually points at -- otherwise it describes a
        store state that no longer exists;
      * a stamp whose recorded head is NOT the snapshot it names records a sync whose publish
        FAILED (the checkout advanced, the store was left behind). Honoring it would starve the
        heal republish retry for a whole freshness window, and every launch inside that window
        would quietly pin outdated code;
      * an installed package VETOES the skip. Its gated sync stands down and prints the
        pipx/pip update hint -- that hint IS the work -- and the only stamp such a machine can
        hold was inherited from its checkout era, describing a runtime this wheel never
        executes.
    """
    window = methodology_sync_freshness_seconds()
    if window <= 0:
        return None
    if os.environ.get(METHODOLOGY_REEXEC_TOKEN_ENV):
        return None
    if running_from_installed_package():
        return None
    stamp = read_methodology_sync_stamp()
    if stamp is None:
        return None
    data, age = stamp
    if age >= window or str(data.get("status", "")) == "failed":
        return None
    if methodology_snapshot_store_enabled():
        current = methodology_snapshot_current_dir()
        if current is None:
            return None
        if str(data.get("snapshot", "")) != current.name:
            return None
        # The same runnability predicate heal now judges health by. Declining to skip is only half
        # the remedy: it exists to HAND a gutted `current` to heal, which must then rebuild it.
        if not _snapshot_is_executable(current):
            return None
        # Materialize names snapshot dirs <full_sha[:12]>, so name-vs-head compares commits. A
        # head run_git could not resolve never matches a sha12 name and fails open toward syncing.
        if str(data.get("head", ""))[:12] != current.name:
            return None
    return f"synced {int(age)}s ago by another lane"


@contextmanager
def launcher_sync_gate():
    """Hold one lock across the WHOLE gated body -- including across os.execve.

    CPython opens descriptors close-on-exec, so a gate that flocked a plain file handle would
    silently RELEASE its lock at the exact moment a trust-gated advance re-execs: the successor
    would do its checkout surgery with the gate wide open and a lane launching right then would
    walk straight in. os.set_inheritable keeps the open file description -- and therefore the flock
    on it -- alive across the exec, and the fd NUMBER travels in the environment so the successor
    ADOPTS that same lock. It must not reopen: the inherited fd still holds the lock, so a second
    open + flock would deadlock the successor against itself, forever.
    """
    lock_file = None
    inherited = os.environ.get(METHODOLOGY_SYNC_LOCK_FD_ENV, "").strip()
    if inherited.isdigit():
        lock_file = _adopt_launcher_gate_lock(int(inherited))
    if lock_file is None:
        path = methodology_sync_lock_path()
        path.parent.mkdir(parents=True, exist_ok=True)  # fresh HOME: the state dir may not exist
        lock_file = path.open("a", encoding="utf-8")
    os.set_inheritable(lock_file.fileno(), True)
    os.environ[METHODOLOGY_SYNC_LOCK_FD_ENV] = str(lock_file.fileno())
    os.environ[METHODOLOGY_SYNC_GATE_ENV] = "1"
    try:
        with advisory_flock(lock_file):
            yield
    finally:
        # Not reached on the re-exec path: os.execve replaces this process mid-body and the lock
        # deliberately rides the inherited fd into the successor, which closes the gate for us.
        os.environ.pop(METHODOLOGY_SYNC_LOCK_FD_ENV, None)
        os.environ.pop(METHODOLOGY_SYNC_GATE_ENV, None)
        try:
            lock_file.close()
        except OSError:
            pass


def _adopt_launcher_gate_lock(fd: int):
    """Wrap the inherited gate fd, or None when that number is not our lock file.

    The number alone proves nothing -- a foreign environment (or a stale export) could name a
    descriptor this process opened for something else entirely, and flocking THAT would lock a file
    nobody meant to lock. os.fstat identifies what actually sits on the number, and the (dev, ino)
    comparison confirms it is the very lock file we would otherwise have opened.
    """
    try:
        fd_stat = os.fstat(fd)
        lock_stat = methodology_sync_lock_path().stat()
    except OSError:
        return None
    if (fd_stat.st_dev, fd_stat.st_ino) != (lock_stat.st_dev, lock_stat.st_ino):
        return None
    try:
        return os.fdopen(fd, "a", encoding="utf-8")
    except OSError:
        return None


def refresh_methodology_snapshot_pin(lane: Path) -> None:
    """Re-stamp an EXISTING pin for this lane. Never creates one.

    Pins are created by the launcher's `snapshot-pin`; this keeps a long-lived lane that relaunches
    from having its pin aged out by prune's TTL while it is still executing the snapshot. Creating
    one here instead would let any incidental gated sync (a hook, a status check) claim a pin for a
    directory that is not really a lane, and pin-protected snapshots would never be collectable.

    Re-stamps snapshot_pin_target(), not `current`, for the same reason `snapshot-pin` does -- and
    it matters MORE here. This is the heartbeat that keeps a session's pin alive past the TTL, so a
    version that re-stamped `current` would, on the first sync after another lane advanced the
    store, quietly move the lane's only protection off the snapshot it is executing and onto one it
    is not. That is worse than never refreshing: the free protection a once-current snapshot enjoys
    inside the TTL window then expires with nothing behind it, and prune deletes the running tree.
    """
    if not methodology_snapshot_store_enabled():
        return
    target = snapshot_pin_target()
    if target is None:
        return
    try:
        if not methodology_snapshot_pin_path(lane).is_file():
            return
        write_methodology_snapshot_pin(lane, target)
    except OSError as exc:
        warn_snapshot_store_unreadable("cannot refresh pin", exc)


def _reexec_updated_methodology(old_head: str, new_head: str, detail: str, channel: str) -> str:
    """Journal the advance, publish it as a snapshot, and re-exec the NEW code. Trust is already
    verified by the caller -- every call site sits behind verify_upstream_trust(new_head).

    Returns ONLY on exec failure, with the detail the caller should report as `failed`.

    `old_head` is the CANONICAL checkout's pre-advance head, supplied by the caller -- never the
    running snapshot's commit, which may be many advances behind and would make the journal lie
    about what this run actually mutated.
    """
    canonical = canonical_methodology_repo()
    # Journal BEFORE the exec: os.execve replaces this process, so nothing after it ever runs.
    # (The rescue/repair helpers separately journal their own git surgery; this entry records the
    # ADOPTION -- which head this lane is about to start executing.)
    append_methodology_write_journal(
        "sync-methodology.advance", old_head, new_head, "ok", detail=detail
    )
    own_root = REPO_ROOT
    exec_root = own_root
    if methodology_snapshot_store_enabled():
        adopted: Path | None = None
        snapshot_dir, snap_detail = materialize_methodology_snapshot(canonical, new_head, channel)
        if snapshot_dir is None:
            print(f"methodology_snapshot: failed - {snap_detail}", flush=True)
        else:
            swapped, swap_detail = swap_methodology_snapshot_current(snapshot_dir)
            print(f"methodology_snapshot: {snap_detail}; {swap_detail}", flush=True)
            if swapped:
                adopted = snapshot_dir
        if adopted is not None:
            exec_root = adopted
            prune_methodology_snapshots()
        elif running_from_snapshot():
            # We are executing a snapshot of the OLD head and the store could not publish the new
            # one. Re-execing ourselves would hand this tree a token bound to new_head while its
            # manifest still says old_head -- consume_methodology_reexec_token() would reject it and
            # the launch would die with "invalid or expired". The canonical checkout is at new_head,
            # clean, and trust-verified: exec that instead and keep the session alive.
            exec_root = canonical
            print(
                f"methodology_snapshot: falling back to canonical checkout {canonical} "
                "for this session",
                flush=True,
            )
    elif running_from_snapshot():
        # Snapshot mode is OFF (the rollback lever, or the store key removed) while THIS process is
        # itself executing a snapshot -- an operator pulling the lever mid-session, or a direct call
        # to <store>/current/bin/tautline. Re-execing own_root walks into the same stale-token trap
        # as above: our manifest says old_head and the token is bound to new_head. Take the same
        # exit, which is also what the lever asks for -- execute the canonical checkout.
        exec_root = canonical
        print(
            f"methodology_snapshot: snapshot execution disabled; executing canonical checkout "
            f"{canonical} for this session",
            flush=True,
        )
    if os.environ.get(METHODOLOGY_SYNC_GATE_ENV) == "1":
        # Inside a launcher gate, os.execve is the ONLY exit from the gated body -- nothing after
        # it runs. Stamp here or the gate window re-execs stampless, and every sibling lane queued
        # on the flock repeats the fetch this run just finished. The snapshot recorded is whatever
        # `current` resolves to now: the one just swapped in on the happy path, the unchanged
        # previous one when the store could not publish (a truthful stamp the next lane can match).
        current = methodology_snapshot_current_dir()
        write_methodology_sync_stamp(new_head, current.name if current else "", "ok")
    # The exec target is the bin/tautline SHIM beside the chosen root (own_root == REPO_ROOT on the
    # unchanged path, else the adopted snapshot / canonical checkout). Post package-split the engine
    # lives in the package, so re-exec must always go through the shim, never this module.
    exec_cli = exec_root / "bin" / CLI_NAME
    print(f"methodology_update: updated - {detail}; re-running current command", flush=True)
    env = os.environ.copy()
    env[METHODOLOGY_REEXEC_TOKEN_ENV] = create_methodology_reexec_token(new_head)
    if exec_root != own_root:
        env[METHODOLOGY_EXEC_ROOT_ENV] = str(exec_root)
    try:
        os.execve(sys.executable, [sys.executable, str(exec_cli), *sys.argv[1:]], env)
    except OSError as exc:
        return f"{detail}; could not re-run after update: {exc}"
    raise AssertionError("unreachable after execve")  # pragma: no cover


def _held_candidate_take_it_offer(canonical: Path, candidate_sha: str, channel: str) -> str | None:
    """The resolved take-it remedy for a trust-`held` candidate, or None to keep the generic one.

    The generic gate remedy names no version and leaves `<stable|experimental>` for the operator to
    guess -- the lockout reported in the FR-2 RCA, where following it in a loop never took the
    update. This resolves both from the candidate actually being held, reusing the same offer copy
    the skip-path surfaces already print (`_framework_update_version_offer`).

    Two deliberate limits:

    - Only a `pinned` hold is rewritten. A `signed` hold's remedy is signature repair, which
      repinning cannot fix, so its own remedy is left exactly as the gate wrote it.
    - The HELD CANDIDATE is authoritative. Its version is read from the fetched commit itself, never
      from the display probe (which resolves independently and may name a different sha), so the
      remedy either names the real held version or names none at all -- never a wrong one.

    Display-only: nothing here feeds framework_update_decision or the trust gate.
    """
    if methodology_update_policy() != "pinned":
        return None
    version = _update_probe_version_at(canonical, candidate_sha)
    if version is None:
        # Sha-only degrade: VERSION is unreadable at the candidate (shallow object, malformed file).
        # Name the commit rather than borrow a version that may belong to a different candidate.
        version = f"the upstream release at {candidate_sha[:12]}"
    offer = _framework_update_version_offer(
        {}, {"availableSha": candidate_sha}, {"channel": channel}, version
    )
    return offer.removeprefix("framework_update_offer: ")


def _resolve_held_refusal(refusal: str, canonical: Path, candidate_sha: str, channel: str) -> str:
    """Swap the trust gate's generic pin remedy for the resolved take-it offer, leaving exactly one.

    Fail-safe both ways: no resolved offer (a signed hold), or a refusal that does not carry the
    generic remedy, returns the gate's own text untouched.
    """
    offer = _held_candidate_take_it_offer(canonical, candidate_sha, channel)
    if offer is None:
        return refusal
    generic = _generic_pinned_advance_remedy()
    if generic not in refusal:
        return refusal
    return refusal.replace(generic, f"take it -- {offer}")


def update_methodology_repo(
    skip_update: bool,
    allow_non_main: bool = False,
    auto_rescue_local_changes: bool = False,
    auto_rescue_stale_only: bool = False,
    channel: str = "stable",
) -> tuple[str, str]:
    """Sync the canonical checkout to its trusted release upstream.

    Journaling note: entries are appended by the code paths that actually WRITE to the canonical
    repo (the fast-forward below, the rescue/repair helpers, the release guards, update-repin) --
    never by the read-only refusals. The journal must stay a pure observer of mutations: it lives
    under $HOME, and an unconditional write here would leave a file behind on paths that touched
    nothing, which is both misleading forensics and a real side effect (it dirties any checkout
    that happens to contain $HOME, sending the very next sync down the local-changes rescue path).
    """
    if running_from_installed_package():
        # Package standdown (PP-R1-P1-1), evaluated BEFORE canonical-repo resolution so a
        # still-configured valid checkout can never reintroduce checkout mutation: pip updates
        # the RUNNING code; fetching/ff-merging a leftover checkout would change nothing this
        # wheel executes and would violate the auto-update non-goal. Read-only refusal: the
        # journal stays silent (see the docstring rule above). NOTE this "skipped" status is
        # deliberately non-failed, so it is NOT what keeps the sync tail from healing/stamping:
        # the store half of the standdown lives in methodology_snapshot_store_enabled() and the
        # freshness-stamp half in sync_methodology's gated tail.
        return "skipped", (
            "this Tautline runs from an installed package; checkout sync stands down - "
            f"update with {PACKAGE_INSTALL_UPDATE_HINT}"
        )
    canonical = canonical_methodology_repo()
    if skip_update:
        return "skipped", "--skip-update requested"
    reexec_token = consume_methodology_reexec_token()
    if reexec_token is True:
        return "skipped", "already updated in this lane-start process"
    if reexec_token is False:
        return "failed", f"invalid or expired {METHODOLOGY_REEXEC_TOKEN_ENV}; refusing to guess whether methodology sync already ran"
    if maintainer_mode_armed():
        # Maintainer standdown, placed AFTER --skip-update and the re-exec token (their contracts
        # keep existing precedence) and BEFORE any branch check, fetch, rescue, or ff-merge. This
        # is the single choke point every caller funnels through -- launcher-gate sync, manual
        # sync, lane-target sync -- so returning here is what makes the mode total. The non-failed
        # status is load-bearing: heal_methodology_snapshot_current still republishes canonical
        # HEAD into <store>/current (committed maintainer work reaches the very next launch) and
        # the freshness stamp is still written. Read-only refusal: the journal stays silent (see
        # the docstring rule above).
        return "skipped", (
            "maintainer mode - update gates stand down; checkout left untouched "
            "(disable with `tautline maintainer-mode off`)"
        )
    if run_git(canonical, ["rev-parse", "--is-inside-work-tree"]) != "true":
        return "skipped", "methodology checkout is not a Git worktree"
    release_branch = framework_channel_branch(channel)
    branch = run_git(canonical, ["branch", "--show-current"])
    if branch not in (release_branch, "unavailable") and not allow_non_main and util_module().resolve_env("MINERVIT_METHODOLOGY_ALLOW_NON_MAIN") != "1":
        branch_display = branch or "detached HEAD"
        if auto_rescue_local_changes:
            # Capture the pre-rescue canonical head BEFORE the rescue mutates the checkout: the
            # journal must record what this run actually moved, and after the reset it is gone.
            pre_rescue_head = run_git(canonical, ["rev-parse", "HEAD"])
            if channel == "stable":
                rescued, detail, _rescue_branch = rescue_methodology_non_main_checkout(branch_display)
            else:
                rescued, detail, _rescue_branch = rescue_methodology_non_main_checkout(branch_display, channel)
            if not rescued:
                return "failed", detail
            # The rescue reset HEAD to freshly-fetched upstream; verify trust BEFORE re-exec'ing it,
            # exactly as the pull/repair paths below do. Without this the default auto-rescue path is
            # an ungated RCE (one compromised upstream = fleet-wide code execution on adopter startup).
            rescued_head = run_git(canonical, ["rev-parse", "HEAD"])
            allowed, trust_msg = verify_upstream_trust(rescued_head)
            if trust_msg:
                print(f"methodology_update_trust: {trust_msg}", file=sys.stderr, flush=True)
            if not allowed:
                return "failed", f"{detail}; refusing to re-exec rescued methodology {rescued_head[:12]}: {trust_msg}"
            return "failed", _reexec_updated_methodology(pre_rescue_head, rescued_head, detail, channel)
        return (
            "failed",
            f"methodology checkout is on {branch_display}, not {release_branch}; refusing to sync from a non-release branch. "
            # RCA 2026-07-22 control 1: this message used to name ONLY the allow-non-main env
            # var, and never named maintainer mode -- the supported control for an operator who
            # intentionally tracks a non-release branch. Two consecutive sessions read it and
            # built a launcher bypass instead, and the second one hand-rewrote the config env and
            # silently disarmed the standdown. A refusal that omits its own control teaches
            # bypasses; the supported fix goes FIRST.
            f"If you develop the framework and track {branch_display} on purpose, arm the "
            f"machine-wide standdown: `{CLI_NAME} maintainer-mode on`. "
            f"Otherwise switch the methodology checkout to {release_branch}, or set "
            "MINERVIT_METHODOLOGY_ALLOW_NON_MAIN=1 for a single intentional deviation.",
        )
    dirty = run_git(canonical, ["status", "--porcelain"])
    if dirty == "unavailable":
        return "skipped", "methodology checkout status unavailable"
    if dirty:
        remote_status = ""
        if auto_rescue_local_changes:
            if auto_rescue_stale_only:
                remote_status = remote_methodology_status(False)
                if remote_status == "up to date":
                    return "skipped", "methodology checkout has local changes but remote is up to date"
                if not remote_status.startswith("remote differs "):
                    return (
                        "failed",
                        "methodology checkout has local changes and "
                        f"{remote_status}; refusing to auto-rescue without confirmed newer remote methodology. "
                        f"Resolve local changes in {canonical}, then rerun `tautline sync-methodology`.",
                    )
            # Pre-rescue canonical head, captured before the rescue branch/reset moves it.
            pre_rescue_head = run_git(canonical, ["rev-parse", "HEAD"])
            rescued, detail, _rescue_branch = rescue_methodology_local_changes(methodology_release_upstream(channel))
            if not rescued:
                return "failed", detail
            # The rescue reset HEAD to freshly-fetched upstream; verify trust BEFORE re-exec'ing it,
            # exactly as the pull/repair paths below do. Without this the default auto-rescue path is
            # an ungated RCE (one compromised upstream = fleet-wide code execution on adopter startup).
            rescued_head = run_git(canonical, ["rev-parse", "HEAD"])
            allowed, trust_msg = verify_upstream_trust(rescued_head)
            if trust_msg:
                print(f"methodology_update_trust: {trust_msg}", file=sys.stderr, flush=True)
            if not allowed:
                return "failed", f"{detail}; refusing to re-exec rescued methodology {rescued_head[:12]}: {trust_msg}"
            return "failed", _reexec_updated_methodology(pre_rescue_head, rescued_head, detail, channel)
        if not remote_status:
            remote_status = remote_methodology_status(False)
        if remote_status == "up to date":
            return "skipped", "methodology checkout has local changes but remote is up to date"
        return (
            "failed",
            "methodology checkout has local changes and "
            f"{remote_status}; refusing to start with stale methodology. "
            f"Resolve local changes in {canonical}, then rerun `tautline sync-methodology`.",
        )

    old_head = run_git(canonical, ["rev-parse", "HEAD"])
    # Verify-before-advance (sec-trust-exec-1): fetch the release upstream WITHOUT moving the checkout,
    # verify the FETCHED commit against the trust policy, and only then fast-forward. A bare
    # `git pull --ff-only` advances the on-disk bin/minervit-methodology BEFORE verification, so a denied
    # upstream would still be executed by the next shim invocation. On a denied upstream we return failed
    # with the checkout untouched.
    upstream = methodology_release_upstream(channel)
    if upstream is not None:
        remote, upstream_branch, upstream_ref = upstream
        code, stdout, stderr = run_command(["git", "-C", str(canonical), "fetch", remote, upstream_branch])
        if code == 0:
            upstream_sha = run_git(canonical, ["rev-parse", upstream_ref])
            if upstream_sha == "unavailable":
                code, stdout, stderr = 1, "", f"could not resolve fetched upstream ref {upstream_ref}"
            else:
                if upstream_sha != old_head:
                    refusal = gate_methodology_upstream_advance(upstream_sha)
                    if refusal is not None:
                        # HELD, not failed: the checkout never advanced, so it still runs code the
                        # active trust policy accepts -- a safe launch state. Blocking startup here
                        # left operators dead in the water with no remedy (operator directive
                        # 2026-07-11: the remedy must always ship alongside the error). Held is
                        # only safe when the RETAINED head itself passes the trust policy (Codex
                        # 0.9.1 R1 P1): an empty/replaced allowlist or an unsigned local commit
                        # must stay fail-closed, not launch under a "trusted" label.
                        retained_allowed, _retained_msg = verify_upstream_trust(old_head)
                        if retained_allowed:
                            # The held detail is the ONLY place the resolved remedy is formatted:
                            # the candidate's sha, version, and channel are all in hand here, and
                            # the lane-start / sync-methodology emitters just print what they get.
                            resolved = _resolve_held_refusal(
                                refusal, canonical, upstream_sha, channel
                            )
                            return "held", (
                                f"update available but held by the trust policy; continuing on the "
                                f"trusted retained checkout {old_head[:12]}. {resolved}"
                            )
                        return "failed", (
                            f"update refused and the retained checkout {old_head[:12]} does not pass "
                            f"the active trust policy either; {refusal}"
                        )
                code, stdout, stderr = run_command(["git", "-C", str(canonical), "merge", "--ff-only", upstream_sha])
    else:
        # No resolvable release upstream (e.g. no origin remote): fall back to the tracking-
        # configured pull. The post-advance re-exec gate below still refuses to re-exec an
        # unverified HEAD.
        code, stdout, stderr = run_command(["git", "-C", str(canonical), "pull", "--ff-only"])
    if code != 0:
        if auto_rescue_local_changes:
            repaired, detail = repair_methodology_release_main_checkout(channel)
            if repaired:
                repaired_head = run_git(canonical, ["rev-parse", "HEAD"])
                allowed, trust_msg = verify_upstream_trust(repaired_head)
                if trust_msg:
                    print(f"methodology_update_trust: {trust_msg}", file=sys.stderr, flush=True)
                if not allowed:
                    return "failed", f"{detail}; refusing to re-exec repaired methodology {repaired_head[:12]}: {trust_msg}"
                # old_head predates the failed ff (which never moves HEAD), so it IS the pre-repair
                # canonical head the repair then reset away from.
                return "failed", _reexec_updated_methodology(old_head, repaired_head, detail, channel)
        return "failed", stderr or stdout or "git pull --ff-only failed"
    new_head = run_git(canonical, ["rev-parse", "HEAD"])
    if old_head != "unavailable" and new_head != "unavailable" and old_head != new_head:
        allowed, trust_msg = verify_upstream_trust(new_head)
        if trust_msg:
            print(f"methodology_update_trust: {trust_msg}", file=sys.stderr, flush=True)
        if not allowed:
            return "failed", f"refusing to re-exec updated methodology {new_head[:12]}: {trust_msg}"
        return "failed", _reexec_updated_methodology(
            old_head,
            new_head,
            f"fast-forwarded {old_head[:12]} -> {new_head[:12]}",
            channel,
        )
    return "ok", stdout or "already up to date"


_lane_start_hook_write = _lane_mod._lane_start_hook_write


def lane_start(args: argparse.Namespace) -> int:
    # getattr, not args.defer_debt_preflights: internal callers build synthetic Namespaces
    # (init_methodology_project's onboarding lane-start) that predate the flag; absent means the
    # unflagged, byte-for-byte-baseline behavior.
    defer_debt_preflights = getattr(args, "defer_debt_preflights", False)
    # The standing directive is the FIRST output; loader diagnostics are captured and replayed
    # after (see _replay_loader_streams). A loader error replays then propagates -- no directive.
    buf_out, buf_err = io.StringIO(), io.StringIO()
    try:
        with redirect_stdout(buf_out), redirect_stderr(buf_err):
            data, project_path, target = lane_project(args)
    except SystemExit:
        _replay_loader_streams(buf_out.getvalue(), buf_err.getvalue())
        raise
    print_autonomy_directive(data, target)
    sys.stdout.flush()
    _replay_loader_streams(buf_out.getvalue(), buf_err.getvalue())
    ensure_lane_state(data, target)
    # BEFORE any generated-file write, lane-env write, or debt preflight. A refusal that fires
    # after this lane has already written into a checkout another session is using has not
    # prevented the collision -- it has recorded that it happened.
    occupancy_rc = occupancy_gate(data, target)
    if occupancy_rc:
        return occupancy_rc
    if getattr(args, "profile", None):
        profile_lock = write_work_profile_lock(data, target, args.profile)
        print(f"work_profile_lock: wrote {profile_lock}")
    print(work_profile_status_line(data, target))
    _profile, _profile_cfg, _profile_source, profile_issues = effective_work_profile(data, target)
    for issue in profile_issues:
        print(f"work_profile_issue: {issue}")
    framework_pin, framework_pin_source = effective_framework_pin(data, target)
    framework_decision = framework_update_decision(framework_pin, data, target, args.skip_update)
    # Display-only discovery: launches never fetch (allow_fetch=False) and always query the remote
    # (this line replaces the framework_remote_status probe below, so a launch runs one ls-remote).
    framework_probe = framework_update_probe(
        target, data, framework_pin, allow_fetch=False, no_remote=False
    )
    print(framework_pin_status_line(framework_pin, framework_pin_source))
    print(framework_update_available_line(framework_decision, framework_probe))
    # OUTSIDE the update skip, deliberately. The 2026-07-22 incident state HAD a pending update --
    # that is what made the sync refuse the non-release branch in the first place -- so a
    # reconciliation evaluated only when no update is pending would go silent in exactly the
    # situation it exists for. This is the case v1 of the control omitted entirely.
    _startup_checkout_state, startup_checkout_lines = framework_checkout_reconciliation_lines(
        framework_pin.get("channel", "stable"),
        framework_channel_branch(framework_pin.get("channel", "stable")),
        getattr(args, "allow_non_main", False),
        target,
    )
    for line in startup_checkout_lines:
        print(line)
    if framework_decision["action"] != "update":
        remote_line = framework_remote_status_from_probe(framework_probe)
        if remote_line is None:
            remote_line = remote_methodology_status(False)
        print(f"framework_remote_status: {remote_line}")
        hygiene_warning = methodology_checkout_hygiene_warning(getattr(args, "allow_non_main", False))
        if hygiene_warning:
            print(f"framework_checkout_warning: {hygiene_warning}")
    for reason in framework_decision.get("wipReasons", []):
        print(f"framework_wip: {reason}")
    locked = read_lock(data, target)
    if locked and locked.get("invalid"):
        print(f"methodology_update: locked by invalid lock file; run unlock-methodology to archive it - {locked.get('path')}")
    elif locked:
        print(f"methodology_update: locked at {locked.get('commit', 'unknown')} ({locked.get('reason', 'no reason')})")
    else:
        if framework_decision["action"] == "update":
            auto_rescue = should_auto_rescue_methodology_for_project_startup()
            status, detail = update_methodology_repo(
                args.skip_update,
                getattr(args, "allow_non_main", False),
                auto_rescue,
                auto_rescue_stale_only=auto_rescue,
                channel=framework_pin["channel"],
            )
        else:
            status, detail = "skipped", framework_decision["reason"]
        print(f"methodology_update: {status} - {detail}")
        for offer_line in framework_update_offer_lines(
            framework_decision, framework_probe, framework_pin
        ):
            print(offer_line)
        if status == "failed":
            print("startup: methodology update must be resolved before lane startup can continue")
            return 1
        if status == "held":
            # The hold detail printed above carries the ACTIVE policy's remedy (pinned -> update-
            # repin, signed -> signature repair); do not restate a policy-specific command here
            # (Codex R2 P2).
            print(
                "methodology_update_held: startup continues on the trusted retained checkout; "
                "to advance, follow the remedy in the hold message above"
            )
        print(f"methodology_release_guard: {install_methodology_release_guards()}")
    print(f"plugin_version: {plugin_version()}")
    print(f"methodology_commit: {running_methodology_commit(short=True)}")
    development_environment_issues = print_development_environment_status(data)
    if development_environment_issues:
        print("startup: development environment must be resolved before lane gates run")
        return 1
    session_version, session_drift = record_lane_session_plugin_version(data, target)
    print(f"lane_session_plugin_version_at_start: {session_version}")
    if session_drift:
        print(
            f"plugin_version_drift: methodology plugin advanced {session_drift} -> {session_version} "
            "since the prior lane start; re-render the adapter (`render-adapters --json-only --write`) and "
            "document any review-evidence contract change before relying on pre-advance manifests"
        )
    rescue_findings = print_methodology_rescue_ref_warnings()
    if not rescue_findings:
        print("methodology_rescue_ref_adapter_drift: clean")

    validate_bootstrap_evidence_for_target(data, project_path, target)
    ensure_lane_state(data, target)
    written, skipped, downgraded = write_generated_files(
        data, project_path, target, trigger="lane-start"
    )
    for path in written:
        print(f"wrote {path}")
    for path in skipped:
        print(
            f"generated_markdown_protected: skipped {path} "
            "(non-generated; use `render-adapters --write --json-only` for config-only updates or migrate before full render)"
        )
    for path in downgraded:
        # Narrate and continue. A stale-pinned machine must still be able to start a lane, because
        # starting one is how it runs the repin that is the actual remedy.
        refusal = generated_downgrade_refusal(
            path, on_disk_template_stamp(path), plugin_version()
        )
        print(f"generated_downgrade_refused: {refusal}")
    env_path = write_lane_env(data, target)
    print(f"lane_env: wrote {env_path}")
    env_values = lane_env_values(data, target)
    port_summary = ", ".join(
        f"{key}={value}" for key, value in env_values.items() if key.endswith("_PORT")
    )
    if port_summary:
        print(f"lane_env_ports: {port_summary}")
    print(f"lane_env_compose_project: {env_values['COMPOSE_PROJECT_NAME']}")

    migrated, migration_errors = migrate_relevant_scratch_plans(data, target)
    for source, dest in migrated:
        print(f"planning_migration: moved {source} -> {dest}")
    for source, dest, error in migration_errors:
        print(f"planning_migration_error: could not move {source} -> {dest}: {error}")

    continuity_path = target / data["continuity"]["path"]
    packet_path = target / data["laneState"]["executionPacket"]
    goal_path = goal_run_path(data, target)
    milestone_path = milestone_run_path(data, target)
    goal_source_path = configured_path(target, data["goalArtifacts"]["sourceOfTruth"])
    goal_template_path = configured_path(target, data["goalArtifacts"]["template"])
    template_path = configured_path(target, data["planningArtifacts"]["template"])
    source_path = configured_path(target, data["planningArtifacts"]["sourceOfTruth"])
    scratch_candidates = scratch_plan_candidates(data, target)
    relevant_scratch = relevant_scratch_plan_candidates(data, scratch_candidates)
    print(f"continuity: {'present' if continuity_path.exists() else 'missing'} {continuity_path}")
    print(f"goal_run: {'present' if goal_path.exists() else 'missing'} {goal_path}")
    print(f"goal_source_of_truth: {'present' if goal_source_path.exists() else 'missing'} {goal_source_path}")
    print(f"goal_template: {'present' if goal_template_path.exists() else 'missing'} {goal_template_path}")
    print(backlog_provider_status_summary(data))
    print(goal_tracker_status_summary(data))
    print(stakeholder_questions_status_summary(data))
    try:
        latest_baseline, _latest_warnings = latest_code_baseline(data, target, write=True)
        print_latest_code_baseline(data, target, latest_baseline, state=f"wrote {latest_code_status_path(data, target)}")
    except SystemExit as exc:
        if defer_debt_preflights:
            print(f"lane_start_warn: latest_code - {exc}")
        else:
            print(f"latest_code: failed - {exc}")
            print("startup: latest-code baseline should be resolved before status, deep analysis, planning, implementation, review, or subagent work; read-only diagnosis remains allowed")
            return 1
    except OSError as exc:
        # Codex T7 R1 P2: a statusFile create/write failure (read-only .ai-work, path collision)
        # is the same latest_code debt family as a SystemExit resolve failure. Unflagged behavior
        # stays byte-for-byte baseline: the OSError propagates exactly as pre-0.8.9.
        if not defer_debt_preflights:
            raise
        print(f"lane_start_warn: latest_code - {exc}")
    if goal_path.exists():
        try:
            goal_run = load_goal_run(data, target)
            print(f"goal_status: {goal_run.get('status')} percent_complete={goal_run.get('percentComplete', goal_percent_complete(goal_run))}")
            print(f"goal_next_action: {goal_next_action_record(goal_run)['instruction']}")
            if goal_run.get("status") == "complete":
                source_goal_path = goal_run_source_path(data, target, goal_run)
                excluded = {source_goal_path} if source_goal_path else set()
                print_next_goal_candidate(data, target, exclude_paths=excluded)
        except SystemExit as exc:
            print(f"goal_status: invalid - {exc}")
    else:
        print_next_goal_candidate(data, target)
    print(f"execution_packet: {'present' if packet_path.exists() else 'missing'} {packet_path}")
    print(f"milestone_run: {'present' if milestone_path.exists() else 'missing'} {milestone_path}")
    print(f"planning_source_of_truth: {'present' if source_path.exists() else 'missing'} {source_path}")
    print(f"planning_template: {'present' if template_path.exists() else 'missing'} {template_path}")
    # Codex R1 P2: the coverage report had no caller, so `planning.templateCoverage` had no
    # observable effect at all -- a knob that changes nothing is worse than an absent one, because
    # it advertises a control that is not there. Reported beside the template it is about.
    print(plan_template_coverage_status_line(data, template_path))
    print(scratch_status_line("planning_scratch_candidates", scratch_candidates))
    print(scratch_status_line("planning_relevant_scratch_plans", relevant_scratch))
    if relevant_scratch:
        print("startup: migrate relevant scratch plans into the source-of-truth path before any new planning work")
    for path in ensure_lane_coordination_artifacts(data, target):
        print(f"lane_coordination_bootstrap: created {path}")
    print_lane_coordination_status(data, target)
    print_document_context_status(data, target)
    print_graphify_status(data, target)
    print_behavior_spec_status(data, target)
    ci_test_gate_startup_issues = print_ci_test_gate_status(data, target)
    if ci_test_gate_startup_issues and ci_test_gate_config(data)["enforcement"] == "block":
        print(
            "startup: this repo has tests but CI does not run them on every PR/push; wire a CI test gate "
            "(see ci-health-check) before relying on local/agent-invoked gates — methodology-status --fail-on-drift and the pre-push hook will block until it exists"
        )
    pending_journals = pending_session_journals(data, target)
    session_journal = data["sessionJournal"]
    milestone_continuation = data["milestoneContinuation"]
    print(f"session_journal: enabled={str(session_journal['enabled']).lower()} cadence={session_journal['cadence']} branch={session_journal['branch']}")
    optin_hint = session_journal_optin_hint(data, project_path, target)
    if optin_hint:
        print(optin_hint)
    print(f"session_journal_local: {session_journal_local_dir(data, target)}")
    print(f"session_journal_pending: {compact_path_list(pending_journals, target)}")
    print_event_log_status(data, target)
    print_instrumentation_status(data)
    print_usage_accounting_status(data, target)
    print_iteration_review_status(data, target)
    print_milestone_update_status(data, target)
    print_product_chat_status(data)
    print_deployment_notification_status(data, target)
    # A journal in a NON-git-ignored path (an upgraded lane whose runs dir was never ignored, or a copy
    # left by the pre-0.9.0 publication path) can still ride a broad `git add` to a product remote
    # despite narrative publication being disabled. This scan runs INDEPENDENTLY of pending_journals
    # (see session_journal_leak_warning): a marked copy is just as committable.
    leak_warning = session_journal_leak_warning(data, target)
    if leak_warning:
        print(leak_warning)
    if pending_journals:
        print(
            "startup: pending local session journals are evidence only and stay on this machine "
            "(narrative publication is disabled as of 0.9.0). To contribute sanitized upstream "
            "signal, enable instrumentation and run `tautline publish-instrumentation-record --target .`."
        )
    print_context_rotation_status(data)
    print_claude_autocompact_status()
    _lane_start_hook_write(
        defer_debt_preflights,
        "autocompact",
        "claude_autocompact_settings",
        "ok",
        write_claude_autocompact_settings,
        Path.home() / ".claude" / "settings.json",
    )
    print(
        "milestone_watchdog: "
        f"enabled={str(milestone_continuation['watchdogEnabled']).lower()} cadence={milestone_continuation['watchdogCadenceMinutes']}m"
    )
    print("plan_finalization_gate: required before approval, execution packet, ready-for-development marking, plan-only PR, ExitPlanMode, or implementation start")
    print(f"plan_review_manifests: {planning_source_root(data, target) / '.plan-reviews'}")
    _lane_start_hook_write(
        defer_debt_preflights,
        "hook",
        "claude_plan_finalization_hook",
        "present",
        write_claude_plan_finalization_hook,
        Path.home() / ".claude" / "settings.json",
        "tautline plan-finalization-hook",
    )
    _lane_start_hook_write(
        defer_debt_preflights,
        "hook",
        "claude_branch_liveness_hook",
        "present",
        write_claude_branch_liveness_hook,
        Path.home() / ".claude" / "settings.json",
        "tautline branch-liveness-hook",
    )
    _lane_start_hook_write(
        defer_debt_preflights,
        "hook",
        "claude_response_guard_hook",
        "present",
        write_claude_response_guard_hook,
        Path.home() / ".claude" / "settings.json",
        "tautline response-guard-hook",
    )
    _lane_start_hook_write(
        defer_debt_preflights,
        "hook",
        "claude_tool_rejection_hook",
        "present",
        write_claude_tool_rejection_hook,
        Path.home() / ".claude" / "settings.json",
        "tautline tool-rejection-hook",
    )
    _lane_start_hook_write(
        defer_debt_preflights,
        "hook",
        "claude_background_command_hook",
        "present",
        write_claude_background_command_hook,
        Path.home() / ".claude" / "settings.json",
        "tautline background-command-hook",
    )
    _lane_start_hook_write(
        defer_debt_preflights,
        "hook",
        "claude_latest_code_hook",
        "present",
        write_claude_latest_code_hook,
        Path.home() / ".claude" / "settings.json",
        "tautline latest-code-hook",
    )
    _lane_start_hook_write(
        defer_debt_preflights,
        "hook",
        "claude_context_rotation_heartbeat_hook",
        "present",
        write_claude_context_rotation_heartbeat_hook,
        Path.home() / ".claude" / "settings.json",
        "tautline context-rotation-heartbeat-hook",
    )
    _lane_start_hook_write(
        defer_debt_preflights,
        "hook",
        "claude_plan_review_pending_hook",
        "present",
        write_claude_plan_review_pending_hook,
        Path.home() / ".claude" / "settings.json",
        "tautline plan-review-pending-hook",
    )
    _lane_start_hook_write(
        defer_debt_preflights,
        "hook",
        "claude_question_guard_hook",
        "present",
        write_claude_question_guard_hook,
        Path.home() / ".claude" / "settings.json",
        "tautline question-guard-hook",
    )
    _lane_start_hook_write(
        defer_debt_preflights,
        "hook",
        "claude_fleet_guard_hook",
        "present",
        write_claude_fleet_guard_hook,
        Path.home() / ".claude" / "settings.json",
        "tautline fleet-guard-hook",
    )
    _lane_start_hook_write(
        defer_debt_preflights,
        "hook",
        "claude_session_start_directive_hook",
        "present",
        write_claude_session_start_directive_hook,
        Path.home() / ".claude" / "settings.json",
        SESSION_START_DIRECTIVE_HOOK_COMMAND,
    )
    # Settings-managed installs migrate through lane-start, not the plugin manifest and not a
    # separately invoked install-hooks. Wiring only install_hooks would leave supported users
    # without the hook -- and because C6 keeps its absence out of hook_failures, nothing would
    # ever force the repair, so the feature would silently never arrive.
    _lane_start_hook_write(
        defer_debt_preflights,
        "hook",
        "claude_session_start_lane_status_hook",
        "present",
        write_claude_session_start_lane_status_hook,
        Path.home() / ".claude" / "settings.json",
        SESSION_START_LANE_STATUS_HOOK_COMMAND,
    )
    git_hook_results, git_hook_errors = write_git_branch_liveness_hooks(target)
    for item in git_hook_results:
        print(f"git_branch_liveness_hook: {item}")
    for error in git_hook_errors:
        print(f"git_branch_liveness_hook: {error}")
    # Report-only, and never able to change lane-start's exit code (see test_run_evidence_lines).
    for line in test_run_evidence_lines(target, data):
        print(line)
    print("startup: run required project gates, publish pending journals, then use goal-next before milestone-next/execution-packet work")
    try_write_event(
        data,
        target,
        event="startup",
        severity="ok",
        plain="Lane startup refreshed the lane adapter config, generated Markdown when safe, lane environment, hooks, and visible process state.",
        next_action="Run methodology-status --fail-on-drift, publish pending journals if listed, then continue through goal-next or milestone-next.",
    )
    return 0


def context_bootstrap(args: argparse.Namespace) -> int:
    # Standing directive is the FIRST output; loader diagnostics captured and replayed after.
    buf_out, buf_err = io.StringIO(), io.StringIO()
    try:
        with redirect_stdout(buf_out), redirect_stderr(buf_err):
            data, _, target = lane_project(args)
    except SystemExit:
        _replay_loader_streams(buf_out.getvalue(), buf_err.getvalue())
        raise
    print_autonomy_directive(data, target)
    sys.stdout.flush()
    _replay_loader_streams(buf_out.getvalue(), buf_err.getvalue())
    ensure_lane_state(data, target)
    status = document_context_status_data(data, target)
    wrote = False
    for index_path in status["index_paths"]:
        if index_path.exists():
            print(f"context_index: present {index_path}")
            continue
        print(f"context_index: missing {index_path}")
        if args.write:
            index_path.parent.mkdir(parents=True, exist_ok=True)
            index_path.write_text(document_context_index_template(data, target, index_path), encoding="utf-8")
            print(f"wrote {index_path}")
            wrote = True
    for historical_path in status["historical_roots"]:
        if historical_path.exists():
            print(f"context_archive: present {historical_path}")
            continue
        print(f"context_archive: missing {historical_path}")
        if args.write:
            historical_path.mkdir(parents=True, exist_ok=True)
            print(f"created {historical_path}")
            wrote = True

    if args.classify:
        status = document_context_status_data(data, target)
        candidate_entries = [
            f"- [ ] `{path_display(target, path)}` - classify as Active Work, Ready Next, or Historical Evidence Only."
            for path in status["unclassified"]
        ]
        if candidate_entries:
            print(f"context_classify: {len(candidate_entries)} candidate(s)")
        for index_path in status["index_paths"]:
            if not index_path.exists() or not candidate_entries:
                continue
            if args.write:
                text = index_path.read_text(encoding="utf-8", errors="replace")
                index_path.write_text(upsert_section_entries(text, "Needs Classification", candidate_entries), encoding="utf-8")
                print(f"updated {index_path}")
                wrote = True

    if args.add_archive_headers:
        status = document_context_status_data(data, target)
        header_count = 0
        missing_count = len(status["archive_header_gaps"])
        index_ref = path_display(target, status["index_paths"][0]) if status["index_paths"] else "the context index"
        for path in status["archive_header_gaps"]:
            print(f"context_archive_header: missing {path}")
            if args.write and insert_archive_header(path, index_ref):
                print(f"updated {path}")
                header_count += 1
                wrote = True
        print(f"context_archive_headers_missing: {missing_count}")
        if args.write:
            print(f"context_archive_headers_written: {header_count}")

    if not args.write:
        print("context_bootstrap: dry-run; pass --write to create or update files")
    elif not wrote:
        print("context_bootstrap: no changes")
    return 0


def context_status(args: argparse.Namespace) -> int:
    data, project_path, target = lane_project(args)
    drift = adapter_drift(data, project_path, target)
    issues = print_document_context_status(data, target)
    if drift:
        print(f"document_context_adapter_drift: {', '.join(drift)}")
    else:
        print("document_context_adapter_drift: clean")
    effective_strict = args.strict or data["documentContext"]["enforcement"] == "strict"
    if issues:
        for issue in issues:
            print(f"document_context_issue: {issue}")
    print(f"document_context_effective_enforcement: {'strict' if effective_strict else 'warn'}")
    if effective_strict and (issues or drift):
        return 1
    if args.fail_on_drift and drift:
        return 1
    return 0




def claude_autocompact_env_status() -> tuple[str, str, str, bool]:
    desired = util_module().resolve_env("MINERVIT_CLAUDE_AUTOCOMPACT_PCT", str(DEFAULT_CLAUDE_AUTOCOMPACT_PERCENT)).strip()
    actual = os.environ.get("CLAUDE_AUTOCOMPACT_PCT_OVERRIDE", "").strip()
    status = "ok" if actual == desired and actual else "missing" if not actual else "drift"
    required = util_module().resolve_env("MINERVIT_CLAUDE_AUTOCOMPACT_REQUIRED", "").strip().lower() in {"1", "true", "yes", "on"} or os.environ.get("CLAUDECODE") == "1"
    return desired, actual, status, required


def claude_autocompact_failure_messages(
    *,
    autocompact_required: bool,
    autocompact_status: str,
    autocompact_actual: str,
    autocompact_settings_ok: bool,
    autocompact_settings_status: str,
) -> list[str]:
    """The autocompact_failures debt-gate issue text. Its own pure function (rather than inline
    literals in methodology_status) so the startup-remediation recovery-action coverage test can
    scan exactly this string instead of methodology_status's entire body."""
    messages: list[str] = []
    if autocompact_required and autocompact_status != "ok":
        messages.append(
            "claude auto-compact env is "
            f"{autocompact_status}: desired={DEFAULT_CLAUDE_AUTOCOMPACT_PERCENT} actual={autocompact_actual or 'missing'}; "
            "start through the managed launcher or reinstall it with `tautline install-claude-launcher --force`"
        )
    if autocompact_required and not autocompact_settings_ok:
        messages.append(
            "claude auto-compact durable settings are not installed: "
            f"{autocompact_settings_status}; run `tautline lane-start --target .` or "
            "`tautline install-claude-launcher --force`"
        )
    return messages


def print_claude_autocompact_status() -> str:
    desired, actual, status, required = claude_autocompact_env_status()
    print(f"claude_autocompact_pct_override: desired={desired} actual={actual or 'missing'} status={status}")
    print(f"claude_autocompact_required: {str(required).lower()}")
    if status != "ok":
        print(
            "claude_autocompact_instruction: managed launchers set "
            f"CLAUDE_AUTOCOMPACT_PCT_OVERRIDE={DEFAULT_CLAUDE_AUTOCOMPACT_PERCENT}; reinstall with "
            "`tautline install-claude-launcher --force` or start through the managed launcher."
        )
    return status


context_rotation_decision = _context_mod.context_rotation_decision


def context_rotation_check(args: argparse.Namespace) -> int:
    data, _, target = lane_project(args)
    ensure_lane_state(data, target)
    rotation = data["contextRotation"]
    boundary = str(args.boundary).strip()
    percent = args.context_percent
    source_raw = args.context_percent_source
    if percent is not None and (percent < 0 or percent > 100):
        print("context_rotation_error: --context-percent must be between 0 and 100", file=sys.stderr)
        return 1
    safe_boundary = boundary in set(rotation["safeBoundaries"])
    decision = context_rotation_decision(rotation, percent, safe_boundary, source_raw)
    action = decision["action"]
    urgency = decision["urgency"]
    reason = decision["reason"]
    print_context_rotation_status(data)
    print(f"context_rotation_boundary: {boundary}")
    print(f"context_rotation_safe_boundary: {str(safe_boundary).lower()}")
    print(f"context_rotation_percent: {percent if percent is not None else 'unknown'}")
    print(f"context_rotation_percent_source: {decision['source']}")
    print(f"context_rotation_action: {action}")
    print(f"context_rotation_urgency: {urgency}")
    print(f"context_rotation_reason: {reason}")
    print(f"context_rotation_capped: {str(decision['capped']).lower()}")
    if action.startswith("rotate"):
        print(f"context_rotation_required_handoff: {target / data['continuity']['path']}")
        print(f"context_rotation_required_goal_ledger: {goal_run_path(data, target)}")
        print(
            "context_rotation_steps: refresh continuity; write/publish or pend session journal; update goal/milestone ledgers; "
            "compact or restart through the host when available; for Claude, invoke `/compact` or the strongest supported "
            "compact/restart path instead of yielding; resume with lane-start, methodology-status, pending journals, "
            "goal-condition or goal-next, then milestone-next"
        )
        if urgency == "mandatory":
            print(
                "context_rotation_host_fallback: if this agent turn cannot invoke `/compact` directly, this is a mandatory "
                "context rotation boundary: write the handoff/journal evidence and state the exact fresh-session startup action; "
                "do not ask the human operator whether to compact or continue"
            )
        else:
            print(
                "context_rotation_host_fallback: this is an advisory rotation, not a mandatory boundary; rotate at the "
                "safe boundary when convenient and continue authorized work — do not stop on an advisory or estimated signal"
            )
        print("context_rotation_stop_policy: context pressure is not goal completion and not a terminal blocker when compact/restart is available")
    elif action == "continue":
        print("context_rotation_steps: continue authorized work; rotate at a later safe boundary if threshold is reached")
    else:
        print("context_rotation_steps: inspect the visible context percentage; if threshold is reached, rotate at the safe boundary without asking")
    return 0




def plan_review_evidence_section_matches(evidence_section: str, expected_evidence: str) -> bool:
    """Compare a plan's committed evidence block against the regenerated expectation.

    Pre-0.8.0 evidence blocks embed the legacy CLI name in the template-generated
    Precheck line (every other line is manifest-derived and self-consistent), so a
    byte-exact comparison rejected every legitimately-reviewed legacy plan after
    the rename. Normalize exactly that command prefix; all other drift still fails.
    """
    normalized = evidence_section.strip().replace(
        f"`{LEGACY_CLI_NAME} plan-finalization-precheck ",
        f"`{CLI_NAME} plan-finalization-precheck ",
    )
    # The section-end marker bounds the block; generic markdown extraction
    # runs to the next `## ` heading, which for preamble-style plans pulls
    # trailing non-evidence content into the section — truncate at the
    # marker so only the manifest-derived body is compared.
    normalized = normalized.split(PLAN_REVIEW_EVIDENCE_END_MARKER, 1)[0].strip()
    return normalized == expected_evidence






def codex_plan_review_adapter_for(target: Path, plan_arg: object) -> dict:
    """The adapter, but only when the plan argument needs one to be resolved.

    A lane-relative plan resolves without any adapter, and this verb historically had none in
    scope. Reading one unconditionally would make every existing call depend on a file it never
    needed -- measured: twelve tests broke on fixtures that have no adapter at all. The root token
    is what decides.
    """
    reference = paths_module().plan_reference.parse_plan_reference(str(plan_arg or ""))
    if reference.root == paths_module().plan_reference.LANE_ROOT:
        return {}
    try:
        return load_project(adapter_marker_path(target))
    except (SystemExit, OSError, KeyError):
        # Unreadable adapter: fall back to the lane-only resolver, which is what this verb did
        # before the root form existed. The containment check downstream still refuses honestly.
        return {}


def codex_plan_review_command(args: argparse.Namespace) -> int:
    target = args.target.resolve()
    extra_args = list(args.review_args or [])
    if extra_args and extra_args[0] == "--":
        extra_args = extra_args[1:]
    plan_arg = getattr(args, "plan", None)
    cleaned_extra_args: list[str] = []
    index = 0
    while index < len(extra_args):
        token = extra_args[index]
        if token == "--plan":
            if index + 1 >= len(extra_args):
                print("codex_plan_review_error: --plan requires a value", file=sys.stderr)
                return 1
            if plan_arg is not None:
                print("codex_plan_review_error: --plan was provided more than once", file=sys.stderr)
                return 1
            plan_arg = Path(extra_args[index + 1])
            index += 2
            continue
        if token.startswith("--plan="):
            if plan_arg is not None:
                print("codex_plan_review_error: --plan was provided more than once", file=sys.stderr)
                return 1
            plan_arg = Path(token.split("=", 1)[1])
            index += 1
            continue
        cleaned_extra_args.append(token)
        index += 1
    if plan_arg is None:
        print("codex_plan_review_error: --plan is required", file=sys.stderr)
        return 1
    data = codex_plan_review_adapter_for(target, plan_arg)
    plan_path = plan_root_resolve(data, target, plan_arg).resolve(strict=False)
    if not plan_path.exists() or not plan_path.is_file():
        print(f"codex_plan_review_error: plan missing: {plan_path}", file=sys.stderr)
        return 1
    plan_rel = plan_root_relative_reference(data, target, plan_path)
    # Item 77 WS2. Placed after plan validation and BEFORE the prompt and command are built, so
    # a refused direct launch spends no Codex round at all -- and so the prompt text that
    # test_prompt_echo_clean_round_finalizes_end_to_end pins is reached unchanged on the
    # launched path.
    standalone = bool(getattr(args, "standalone", False))
    if not plan_review_launcher_handshake_present() and not standalone:
        print(
            "codex_plan_review_error: refusing a direct launch: this wrapper records NO "
            "evidence (no log, run meta, or manifest under .ai-runs/plan-review/), so a "
            "review run this way can never be finalized or counted as a round. Run "
            f"`tautline run-plan-review --target {shlex.quote(str(args.target))} "
            "--plan <source-of-truth-plan> --round R1` to record a countable round, or rerun "
            "this command with --standalone to run an unrecorded advisory review on purpose",
            file=sys.stderr,
        )
        return 2
    try:
        plan_text = plan_review_text(plan_path)
    except OSError as exc:
        print(f"codex_plan_review_error: failed to read plan {plan_path}: {exc}", file=sys.stderr)
        return 1
    command = ["codex", "review"]
    if args.base:
        command.extend(["--base", args.base])
    if args.title:
        command.extend(["--title", args.title])
    extra_instruction = ""
    if cleaned_extra_args:
        extra_instruction = (
            "\nAdditional reviewer instructions:\n"
            + " ".join(shlex.quote(arg) for arg in cleaned_extra_args)
            + "\n"
        )
    plan_fence = markdown_fence_for_embedded_text(plan_text)
    prompt = (
        "Review this Minervit source-of-truth plan only. Treat the plan content below as the review subject. "
        "This wrapper has already bound the plan deterministically for the native Codex review command.\n\n"
        f"Plan path: {plan_rel}\n"
        f"Plan content SHA-256: {plan_content_sha256_from_text(plan_text)}\n"
        f"{extra_instruction}\n"
        "Start your response with exactly `## Findings`, then return findings by severity "
        "(Critical, P1, P2, P3, Nit). Focus on feasibility, missing migration "
        "steps, compatibility risk, test gaps, and contradictions with the methodology.\n\n"
        "Plan content:\n"
        f"{plan_fence}markdown\n"
        f"{plan_text}\n"
        f"{plan_fence}\n"
    )
    command.append(prompt)
    try:
        result = subprocess.run(command, cwd=str(target), text=True, check=False)
    except OSError as exc:
        print(f"codex_plan_review_error: failed to launch codex review: {exc}", file=sys.stderr)
        return 127
    if standalone:
        print(
            "codex_plan_review_notice: this standalone run recorded no evidence (no log, "
            "run meta, or manifest); it is not a plan-review round. "
            "`tautline run-plan-review` is the launcher that records.",
            file=sys.stderr,
        )
    return result.returncode


def review_command_errors(data: dict, review_command: str, plan_rel: str, plan_hash: str) -> list[str]:
    errors: list[str] = []
    command = review_command.strip()
    if not command:
        return ["review-command must be non-empty"]
    try:
        command_tokens = shlex.split(command)
    except ValueError as exc:
        return [f"review-command is not shell-parseable: {exc}"]
    if not command_tokens:
        return ["review-command must contain adapter review.codexPlanWrapper"]
    command_head = Path(command_tokens[0]).name
    if command_head in PLAN_REVIEW_FORBIDDEN_COMMAND_HEADS:
        errors.append(f"review-command cannot be a shell/mock command: {command_tokens[0]}")
    for marker in PLAN_REVIEW_FORBIDDEN_SHELL_MARKERS:
        if marker in command:
            errors.append(f"review-command cannot contain shell control marker: {marker}")
            break
    codex_wrapper = codex_plan_wrapper(data)
    try:
        wrapper_tokens = shlex.split(codex_wrapper)
    except ValueError as exc:
        errors.append(f"adapter review.codexPlanWrapper is not shell-parseable: {exc}")
        wrapper_tokens = []
    if not wrapper_tokens:
        errors.append("adapter review.codexPlanWrapper is empty")
    elif command_tokens[: len(wrapper_tokens)] != wrapper_tokens:
        errors.append("review-command must start with adapter review.codexPlanWrapper")
    if not review_tokens_bind_plan(command_tokens, plan_rel, plan_hash):
        errors.append("review-command must include a structured --plan binding to the reviewed plan path or plan content hash")
    return errors




class PlanReviewFrameMark(NamedTuple):
    """One frame sentinel found in a log: where it sits and which run it claims."""

    start: int
    end: int
    nonce: str


def _plan_review_frame_marks(log_text: str, marker: str) -> list[PlanReviewFrameMark]:
    """Line-anchored sentinel matches, with the optional `run:<nonce>` suffix parsed off."""
    pattern = re.compile(rf"(?m)^{re.escape(marker)}(?:[ \t]+run:(?P<nonce>\S+))?[ \t]*\r?$")
    return [
        PlanReviewFrameMark(match.start(), match.end(), match.group("nonce") or "")
        for match in pattern.finditer(log_text)
    ]


def _plan_review_followed_by_finished_at(log_text: str, mark: PlanReviewFrameMark) -> bool:
    """True when the next non-empty line after a sentinel is this run's `finished_at:` footer."""
    for line in log_text[mark.end :].splitlines():
        if not line.strip():
            continue
        return line.strip().startswith("finished_at:")
    return False


def plan_review_log_frame(
    log_text: str, *, expected_nonce: str | None = None
) -> tuple[int, int] | None:
    """Span of the reviewer output in this log, or None when the log carries no frame.

    `expected_nonce` is the ONLY source of nonce authority. A nonce found in the text is content:
    an import, or a reviewer quoting another round's log, can carry any nonce at all, and adopting
    one would let quoted evidence define this run's boundary (item 25: plan-review log verbatim
    replay).
    """
    starts = _plan_review_frame_marks(log_text, PLAN_REVIEW_OUTPUT_START)
    ends = _plan_review_frame_marks(log_text, PLAN_REVIEW_OUTPUT_END)
    if not starts:
        return None
    if expected_nonce:
        start = next((mark for mark in starts if mark.nonce == expected_nonce), None)
        if start is not None:
            end = next(
                (
                    mark
                    for mark in ends
                    if mark.nonce == expected_nonce and mark.start > start.end
                ),
                None,
            )
            if end is not None:
                return (start.end, end.start)
        # A supplied nonce that does not appear is stale metadata, not a reason to return
        # nothing; fall through to the positional rules below.
    begin = starts[0].end  # run_plan_review writes the header before it spawns the reviewer
    footed = [
        mark
        for mark in ends
        if mark.start > begin and _plan_review_followed_by_finished_at(log_text, mark)
    ]
    if footed:
        # Position heuristic, and honest about being one: the genuine footer is the LAST thing
        # run_plan_review writes and is always immediately followed by `finished_at:`. An echoed
        # copy of some other run's footer can satisfy the shape, so ties resolve toward the file
        # end, where this run's own footer necessarily sits.
        return (begin, footed[-1].start)
    if ends and ends[-1].start > begin:
        return (begin, ends[-1].start)
    return (begin, len(log_text))  # watchdog-killed run: no footer was ever written


def _plan_review_quoted_frame_spans(
    scope_text: str, *, min_depth: int
) -> list[tuple[int, int, int]]:
    """Complete frames inside `scope_text` at nesting depth >= `min_depth`, as
    `(outer_start, content_end, outer_end)`.

    Pairing is STACK-based, not greedy. A greedy first-end-after-this-start match pairs an OUTER
    frame with an INNER footer, which makes the whole file look like one span and every heading
    look quoted -- that mis-pairing let an imported framed log fall back to a quoted clean block
    and grade a real blocker as clean (0.23.0 implementation review R1 P2).

    `min_depth` is what distinguishes the two scopes. When the scope is already a frame's CONTENT
    (an authoritative log), every complete pair inside it is quoted material: min_depth 0. When the
    scope is a whole file (an import), the OUTERMOST pair is the file's own content and only pairs
    strictly inside it are quotes: min_depth 1.

    `content_end` is the start of the closing sentinel, so a section truncated at a frame boundary
    never swallows the run-log footer; `outer_end` is past it, which is what containment needs.
    """
    marks = sorted(
        [(mark, True) for mark in _plan_review_frame_marks(scope_text, PLAN_REVIEW_OUTPUT_START)]
        + [(mark, False) for mark in _plan_review_frame_marks(scope_text, PLAN_REVIEW_OUTPUT_END)],
        key=lambda item: item[0].start,
    )
    stack: list[PlanReviewFrameMark] = []
    spans: list[tuple[int, int, int]] = []
    for mark, is_start in marks:
        if is_start:
            stack.append(mark)
            continue
        if not stack:
            continue
        opened = stack.pop()
        if len(stack) >= min_depth:
            spans.append((opened.start, mark.start, mark.end))
    # Popping a stack yields INNER frames before the outer ones that contain them. Callers walk
    # these in order to excise quoted text, and an out-of-order walk keeps an enclosing quote's
    # prefix -- so a quoted blocker in that prefix could still refuse a clean round (item 31:
    # label trust in the remaining plan-review call sites).
    return sorted(spans)


def plan_review_findings_offset(scope_text: str) -> int | None:
    """Offset just past the reviewer's own `## Findings` heading, or None if there is none.

    Prefer the LAST heading that is not inside a complete frame nested in this scope -- a nested
    frame is quoted material whichever side of the reviewer's answer it falls on. If every
    candidate is nested (an import whose whole content is one framed log), take the last candidate
    anyway: narrowing to nothing would read as CLEAN, which is the same failure inverted.
    """
    span = plan_review_findings_span(scope_text)
    return None if span is None else span[0]


def plan_review_findings_span(
    scope_text: str, *, scope_is_framed_content: bool = True
) -> tuple[int, int] | None:
    """The span of the reviewer's own findings section, or None when there is no heading.

    Selection walks preference tiers and takes the last candidate in the first non-empty one:

    1. Headings outside EVERY complete frame in scope. On an authoritative log that is the
       reviewer's own answer with all quoted material excluded, whichever side of it the quotes
       fall on. On an import it is text the reviewer wrote outside any framed log it pasted.
    2. Whole-file scopes only: headings outside every frame nested INSIDE another. This is the
       single-framed-import case -- the file's own outer frame is its content, not a quote, so its
       heading is eligible once tier 1 is empty.
    3. Every candidate. The fallback is load-bearing: narrowing to nothing would read as CLEAN,
       which is the original failure inverted.

    The END matters as much as the start. When the chosen heading sits inside a frame, its section
    stops at that frame's content end, so the run-log footer never trails in and makes a trailing
    empty severity header look like a non-empty section.
    """
    candidates = list(re.finditer(r"(?im)^##[ \t]+Findings[ \t]*\r?$", scope_text))
    if not candidates:
        return None
    all_frames = _plan_review_quoted_frame_spans(scope_text, min_depth=0)
    nested_frames = _plan_review_quoted_frame_spans(scope_text, min_depth=1)

    def outside(spans):
        return [
            match
            for match in candidates
            if not any(low <= match.start() < outer for low, _content, outer in spans)
        ]

    tiers = [outside(all_frames)]
    if not scope_is_framed_content:
        tiers.append(outside(nested_frames))
    tiers.append(candidates)
    chosen = next(tier for tier in tiers if tier)[-1]

    end = len(scope_text)
    for low, content_end, outer in all_frames:
        if low <= chosen.start() < outer:
            end = min(end, content_end)  # stop before this frame's own closing sentinel
    return (chosen.end(), end)




def _plan_review_without_quoted_frames(
    scope_text: str, span: tuple[int, int], *, min_depth: int
) -> str:
    """`scope_text[span]` with any quoted frames inside it REMOVED, not truncated at.

    Truncating at the first quoted frame was wrong in the dangerous direction: a reviewer that
    writes findings, pastes a prior log, then continues with a real blocker would have that
    blocker hidden, turning a false refusal into a false PASS (0.24.0 implementation review R1
    P1). Removing the quoted spans keeps everything the reviewer actually wrote, on both sides of
    the quote, and drops only what it copied.
    """
    start, end = span
    kept: list[str] = []
    cursor = start
    for low, _content_end, outer in _plan_review_quoted_frame_spans(scope_text, min_depth=min_depth):
        if outer <= start or low >= end:
            continue
        if low > cursor:
            kept.append(scope_text[cursor:max(cursor, min(low, end))])
        cursor = max(cursor, min(outer, end))
    if cursor < end:
        kept.append(scope_text[cursor:end])
    return "".join(kept)


# Item 73 WS2, Codex R1 P1. An IMPLEMENTATION review log is not a plan-review log: it is the whole
# `codex review` CLI transcript -- prompt echo, every tool invocation, and the full source diff --
# and it carries no `## Findings` heading, because that heading is a contract of the builtin
# plan-review wrapper's prompt, not of `codex review`.
#
# Measured, not assumed: on a real 751,076-byte implementation log from this very branch,
# `review_findings_section` returns 0 characters and `review_output_text` returns all 751,076. The
# transcript quotes source code containing the word "Critical" and test fixtures containing
# "Verdict: changes requested", so the verdict scan fired and a genuinely CLEAN review could not be
# finalized. Wiring the plan-review call shape unchanged would have made every implementation review
# in the fleet unfinalizable -- a false refusal on the push boundary, which is the highest-cost
# defect class there is and the same one this item's W1.1 half hit at its round cap.
#
# The codex CLI marks its own final response with a bare `codex` speaker line. Scoping to the text
# after the LAST one yields the reviewer's answer and nothing else.
CODEX_TRANSCRIPT_SPEAKER_MARKER = "codex"


def codex_transcript_final_response(log_text: str) -> str:
    """The reviewer's final response from a `codex review` CLI transcript, or "" if unlocatable."""
    lines = log_text.splitlines()
    marker_indexes = [
        index
        for index, line in enumerate(lines)
        if line.strip() == CODEX_TRANSCRIPT_SPEAKER_MARKER
    ]
    if not marker_indexes:
        return ""
    return "\n".join(lines[marker_indexes[-1] + 1 :])


def implementation_review_scan_text(log_text: str) -> tuple[str, str]:
    """Scope an implementation-review log to the reviewer's answer.

    Returns `(scan_text, source)`. `source` is `"findings-section"`, `"codex-final-response"`, or
    `"unlocatable"`.

    When the answer cannot be located this returns `("", "unlocatable")` and the caller SKIPS the
    cross-check with a printed line rather than scanning the raw transcript. That is a deliberate
    fail-open, and it is the direction that keeps the control real: scanning the transcript refuses
    100% of genuine logs (measured), so "fail closed" here means closed to everyone, which is not a
    gate but a fleet-wide wedge on a boundary whose input format this repo does not control. The
    skip is PRINTED, never silent -- a quiet skip is indistinguishable from a clean reconciliation,
    which is the exact defect class this cluster exists to close.
    """
    # ORDER MATTERS, and Codex R1-B P1 is why: a transcript that inspected a file containing a
    # `## Findings` heading -- this repo's own plan-review code and test fixtures do -- would have
    # that ECHOED heading chosen over the reviewer's actual answer, reproducing the very false
    # refusal this scoping exists to fix. So the final-response marker wins whenever it exists; the
    # findings section is the fallback for logs that are not codex transcripts at all.
    final_response = codex_transcript_final_response(log_text)
    if final_response.strip():
        return final_response, "codex-final-response"
    findings = review_findings_section(log_text, expected_nonce=None, authoritative=False)
    if findings.strip():
        return findings, "findings-section"
    return "", "unlocatable"


def review_output_text(
    log_text: str, *, expected_nonce: str | None = None, authoritative: bool = False
) -> str:
    """The reviewer output to scan.

    `authoritative` says whether the sentinels in this file may be trusted to bound a run at all;
    `expected_nonce` says which run. They are not redundant: a run meta written before the nonce
    existed is authoritative without one, and an import is neither. A file this tool did not write
    is scoped WHOLE, which is the fail-closed direction -- the verdict scan then sees more text,
    so it flags more, never less.
    """
    if not authoritative:
        return log_text
    frame = plan_review_log_frame(log_text, expected_nonce=expected_nonce)
    if frame is None:
        return log_text
    return log_text[frame[0] : frame[1]]


def review_findings_section(
    log_text: str, *, expected_nonce: str | None = None, authoritative: bool = False
) -> str:
    # The codex CLI echoes the user prompt into stdout inside the
    # --- review output --- block, so review_output_text returns both the
    # prompt-template echo and the assistant response. The prompt template
    # legitimately uses "Critical / P1 / Important" in its instructional
    # prose (and in its example output), which trips the verdict scan
    # below. Per the prompt-template contract every clean codex review
    # response uses a `## Findings` heading, so the validator scopes to the
    # last one -- but "last" alone is wrong when the reviewer QUOTES another
    # round's log after its own answer, which it does routinely because
    # reading prior evidence is legitimate review behavior. Selection
    # therefore skips headings inside a complete quoted frame, with a
    # fallback so it can never narrow to nothing (item 25: plan-review log
    # verbatim replay). Empty string is returned when no `## Findings`
    # heading is present at all, letting callers fall back.
    output = review_output_text(
        log_text, expected_nonce=expected_nonce, authoritative=authoritative
    )
    # `output` is a frame's CONTENT only when authority let review_output_text resolve one; on an
    # import it is the whole file, whose outermost frame is its own content rather than a quote.
    framed_content = authoritative and (
        plan_review_log_frame(log_text, expected_nonce=expected_nonce) is not None
    )
    span = plan_review_findings_span(output, scope_is_framed_content=framed_content)
    if span is None:
        return ""
    return _plan_review_without_quoted_frames(
        output, span, min_depth=0 if framed_content else 1
    )


def review_log_errors(
    log_text: str,
    review_command: str,
    plan_rel: str,
    plan_hash: str,
    *,
    expected_nonce: str | None = None,
    authoritative: bool = False,
) -> list[str]:
    """Identity check: the reviewer OUTPUT must reference the reviewed plan.

    This reader deliberately scopes differently from the verdict scan. Widening it to the whole
    log on an unauthoritative file would let the run-log header, the metadata footer, or the
    echoed review_command satisfy an identity requirement the reviewer's own text never met -- so
    identity keeps framed scoping whenever a frame exists at all, and falls back to whole text
    only when there is none. The verdict scan widens instead, because seeing more text can only
    make it flag more. That asymmetry is the one place these two readers disagree, on purpose.
    """
    errors: list[str] = []
    frame = plan_review_log_frame(log_text, expected_nonce=expected_nonce)
    if frame is None:
        output_text = log_text
    else:
        output_text = log_text[frame[0] : frame[1]]
    del authoritative  # identity scoping is decided by the presence of a frame, not by authority
    if plan_rel not in output_text and plan_hash not in output_text:
        errors.append("review output must reference the reviewed plan path or plan content hash")
    if review_command not in log_text:
        errors.append("review log must contain the exact review-command that produced it")
    return errors


def review_log_verdict_errors(
    log_text: str,
    verdict: str,
    unresolved_critical_count: int,
    unresolved_p1_count: int,
    classified_findings: list[dict] | None = None,
    *,
    expected_nonce: str | None = None,
    authoritative: bool = False,
    require_findings_section: bool = False,
    rerun_command: str = "",
    blocker_evidence: str = "any",
) -> list[str]:
    errors: list[str] = []
    # Scope to the assistant's `## Findings` section so we do not flag
    # the prompt-template's instructional wording (which the codex CLI
    # echoes into stdout). If the response does not include that heading,
    # fall back to the captured review-output block — still narrower than
    # the raw log so we skip the run-log header and metadata noise.
    findings_text = review_findings_section(
        log_text, expected_nonce=expected_nonce, authoritative=authoritative
    )
    if require_findings_section and not findings_text:
        # RCA rca-verdict-validator-prompt-echo: absence of the contracted heading is a
        # reviewer-FORMAT error, never license to scan the raw block -- that block contains the
        # codex CLI's prompt echo, which names the severities. Scanning it is how a clean round
        # reads as findings and a real one reads as clean.
        #
        # The heading is emitted by the BUILTIN wrapper's prompt only. A lane whose adapter
        # points review.codexPlanWrapper at its own script may have a prompt that never asks for
        # it, and for that lane a bare re-run reproduces this same log forever. So the
        # wrapper-side remedy is named FIRST and the re-run second.
        rerun = rerun_command or "tautline run-plan-review with the same --plan and --round"
        return [
            "reviewer response contains no `## Findings` section; this is a "
            "reviewer-format error, not a verdict -- the round is not classifiable "
            "(a raw-log severity scan is never a fallback for missing reviewer "
            "structure). Fix the reviewer contract first: the review wrapper's prompt "
            "must require the response to start with `## Findings` -- point the adapter's "
            "`review.codexPlanWrapper` at the builtin `tautline codex-plan-review`, or add "
            "that requirement to the lane-owned wrapper's prompt. Then re-run the round "
            f"with `{rerun}` and classify the new log. If the wrapper already requires "
            "`## Findings`, the reviewer drifted -- the re-run alone is the fix"
        ]
    scope_text = findings_text or review_output_text(
        log_text, expected_nonce=expected_nonce, authoritative=authoritative
    )
    lower = scope_text.lower()
    if verdict == "clean" and re.search(r"\bverdict\s*:\s*(?:blocked|failed?|needs changes|changes requested)\b", lower):
        errors.append("review log verdict conflicts with recorded clean verdict")
    if unresolved_critical_count == 0 and unresolved_p1_count == 0:
        suspicious_lines = []
        observed_blocker_classes: set[str] = set()
        # RESIDUAL, named rather than smuggled in. `finding_counts` and `BLOCKER_SEVERITIES` both
        # classify `p0` as Critical and `high` as P1, but THIS scan recognizes neither, so a blocker
        # reported only as `[P0]` or `High` is invisible here.
        #
        # A widened alias set was written for exactly that gap and then REMOVED, because it produced
        # false refusals on the push boundary from ordinary reviewer prose: "the tests provide high
        # confidence" reads as a P1 finding under a bare-word match, and the no/zero suppressions
        # below recognize only the original four, so a response saying "No P0 findings" would refuse
        # too. Positive and negative detection have to move together, and matching `High` safely
        # needs severity POSITIONS rather than word presence -- design work this item's round budget
        # cannot confirm. Closing the gap is a filed successor; shipping a scan that refuses
        # "high confidence" would be strictly worse than the gap it closes.
        severity_alias_pattern = r"\b(?:critical|c1|p1|important)\b"
        scope_lines = scope_text.splitlines()
        for index, line in enumerate(scope_lines):
            line_lower = line.lower()
            if not re.search(severity_alias_pattern, line_lower):
                continue
            # A bare severity section HEADER is structure ONLY when its section is EMPTY --
            # rendered as '### P1' + '- None.' (or equivalent) on the NEXT line, immediately
            # followed by another heading, or trailing with no body. A NON-EMPTY section is
            # blocker evidence even when its bullets do not repeat the severity word
            # (Codex T7 R4 P1: the unconditional skip let '### P1' + an unlabeled finding
            # bullet finalize clean).
            if re.match(r"^#{1,6}\s*(?:critical|c1|p0|p1|important|high)\s*$", line_lower.strip()):
                next_content = next((item.strip() for item in scope_lines[index + 1:] if item.strip()), "")
                if (
                    not next_content
                    or next_content.startswith("#")
                    or re.match(r"^[-*+]?\s*(?:none|n/?a|no findings|0)\s*[.!]?$", next_content.lower())
                ):
                    continue
                suspicious_lines.append(line.strip())
                observed_blocker_classes.update(re.findall(severity_alias_pattern, line_lower))
                continue
            if re.search(r"\b(?:no|zero|0)\b.*\b(?:critical|c1|p1|important)\b", line_lower):
                continue
            if re.search(r"\b(?:critical|c1|p1|important)\b.*\b(?:none|zero|0)\b", line_lower):
                continue
            suspicious_lines.append(line.strip())
            observed_blocker_classes.update(re.findall(severity_alias_pattern, line_lower))
        if suspicious_lines:
            if blocker_evidence == "all":
                # Codex R2-B P1, and it is the same hole one level up. The helper below only ever
                # inspected findings the classification file SUPPLIED, so a log carrying three
                # Criticals alongside a JSON carrying one routed Important returned "all resolved"
                # -- one routed finding masking omitted blockers, exactly the divergence this
                # workstream exists to close. The escape now also requires the classification to
                # ACCOUNT FOR every blocker class the log shows.
                #
                # Class-level, not count-level, on purpose: the log formats carry no per-finding
                # identity to count against, so exact reconciliation remains the named residual and
                # its successor's trigger. Class coverage is strictly stronger than what shipped
                # and needs nothing the log does not already state.
                has_evidence = classified_findings_all_blockers_resolved(
                    classified_findings or []
                ) and classified_findings_cover_blocker_classes(
                    classified_findings or [], observed_blocker_classes
                )
            else:
                has_evidence = classified_findings_have_resolved_blocker_evidence(
                    classified_findings or []
                )
            if not has_evidence:
                errors.append("review log mentions Critical/P1/Important findings while recorded unresolved counts are zero")
    return errors


def plan_review_exemption_errors(data: dict, plan_path: Path) -> list[str] | None:
    text = plan_path.read_text(encoding="utf-8", errors="replace")
    section = markdown_section(text, PLAN_REVIEW_EXEMPTION_HEADING)
    if not section:
        return None
    lower = section.lower()
    configured_exemptions = [str(item).strip() for item in data["planningArtifacts"].get("reviewExemptions", [])]
    if not configured_exemptions:
        return ["Plan Review Exemption section is present, but the adapter declares no review exemptions"]
    labels = [item.split(":", 1)[0].strip().lower() for item in configured_exemptions]
    errors: list[str] = []
    if not any(label and label in lower for label in labels):
        errors.append("Plan Review Exemption must name an adapter-declared exemption label")
    required_claims = [
        ("no product/runtime behavior change", r"\b(no|not|without)\b.*\b(product|runtime|behavior|code|schema|route|ui|infra|deployment|security|data|test harness)\b"),
        ("implementation review still required", r"\b(implementation|diff|stage)\b.*\b(review|gate|validation|test)\b"),
    ]
    for label, pattern in required_claims:
        if not re.search(pattern, lower, re.S):
            errors.append(f"Plan Review Exemption must state {label}")
    return errors








def critical_journey_pending_issues(data: dict, target: Path) -> list[str]:
    """A scenario whose feature maps to a declared critical journey must never be @pending (RC5).
    Returns a blocking issue per such inactive scenario."""
    journeys = data.get("criticalJourneys") or []
    if not isinstance(journeys, list) or not journeys:
        return []
    behavior = data.get("behaviorSpecs") or {}
    pending_tags = [str(t).strip() for t in behavior.get("pendingTags", DEFAULT_BEHAVIOR_PENDING_TAGS) if str(t).strip()] or list(DEFAULT_BEHAVIOR_PENDING_TAGS)
    issues: list[str] = []
    for journey in journeys:
        if not isinstance(journey, dict):
            continue
        name = str(journey.get("name") or "unnamed").strip() or "unnamed"
        features = critical_journey_feature_files(journey, target)
        if not features:
            issues.append(
                f"critical journey `{name}` resolves to zero feature files (featurePaths is empty or "
                "matches nothing): a declared critical journey must have live scenario coverage, so an "
                "absent feature is a coverage gap -- write the feature or remove the journey"
            )
            continue
        for feature in features:
            try:
                pending = behavior_pending_scenarios(feature, pending_tags)
            except OSError:
                continue
            for scenario in pending:
                issues.append(
                    f"critical journey `{name}` has an inactive (@pending) scenario "
                    f"'{scenario.get('name')}' at {feature.relative_to(target)}:{scenario.get('line')}: a "
                    "declared critical-journey scenario must have live coverage, never @pending"
                )
    return issues


def print_critical_journey_status(data: dict, target: Path) -> list[str]:
    journeys = data.get("criticalJourneys") or []
    issues = critical_journey_pending_issues(data, target)
    print(f"critical_journeys: count={len(journeys)} status={'drift' if issues else 'ok'}")
    for issue in issues:
        print(f"critical_journey_issue: {issue}")
    return issues




def behavior_harness_script_text(target: Path, command: str) -> str:
    try:
        parts = shlex.split(command)
    except ValueError:
        parts = command.split()
    if not parts:
        return ""
    candidates: list[Path] = []
    for part in parts:
        if part.startswith("-") or "=" in part:
            continue
        try:
            candidate = configured_path(target, part).resolve(strict=False)
        except ValueError:
            # The harness `command` is command TEXT, not an adapter path field: a token that
            # escapes the project root (e.g. the `/bin/sh` in `/bin/sh scripts/acceptance.sh`)
            # is simply not a project script to read for proof. Skip it and keep probing the
            # remaining tokens; sec-config-path-1 containment stays strict for real path fields.
            continue
        if candidate.exists() and candidate.is_file():
            candidates.append(candidate)
            break
    text_parts: list[str] = [command]
    for candidate in candidates:
        try:
            text_parts.append(candidate.read_text(encoding="utf-8", errors="replace"))
        except OSError:
            pass
    return "\n".join(text_parts)


def behavior_spec_status_record(data: dict, target: Path) -> dict:
    behavior = data.get("behaviorSpecs", {})
    feature_files = behavior_feature_files(data, target)
    pending_tags = [str(tag).strip() for tag in behavior.get("pendingTags", DEFAULT_BEHAVIOR_PENDING_TAGS) if str(tag).strip()]
    pending_scenarios: list[dict] = []
    for feature_file in feature_files:
        pending_scenarios.extend(behavior_pending_scenarios(feature_file, pending_tags))

    issues: list[str] = []
    max_pending = int(behavior.get("maxPendingScenarios", 0))
    if len(pending_scenarios) > max_pending:
        issues.append(
            f"inactive acceptance scenarios exceed limit: {len(pending_scenarios)} > {max_pending}; "
            "remove pending tags or record owner, reason, and un-pend trigger"
        )
    if behavior.get("pendingRequiresOwnerAndTrigger", True):
        for scenario in pending_scenarios:
            missing = behavior_pending_missing_metadata(scenario["context"])
            if missing:
                rel = path_relative_to_target(target, scenario["path"])
                issues.append(
                    f"inactive scenario missing {', '.join(missing)}: {rel}:{scenario['line']} {scenario['name']}"
                )

    harnesses = behavior.get("acceptanceHarnesses", [])
    harness_records: list[dict] = []
    if behavior.get("required") and feature_files and not harnesses:
        issues.append("behaviorSpecs.acceptanceHarnesses missing while behavior specs are required and feature files exist")
    for index, harness in enumerate(harnesses, start=1):
        name = str(harness.get("name", f"harness-{index}")).strip()
        command = str(harness.get("command", "")).strip()
        app_path_text = str(harness.get("appPath", "")).strip()
        app_path = configured_path(target, app_path_text).resolve(strict=False)
        feature_patterns = [str(value).strip() for value in harness.get("featurePaths", []) if str(value).strip()]
        target_proof = [str(value).strip() for value in harness.get("targetProof", []) if str(value).strip()]
        proof_needles = target_proof or [app_path_text]
        haystack = behavior_harness_script_text(target, command)
        harness_feature_files: set[Path] = set()
        for pattern in feature_patterns:
            for candidate in target.glob(pattern):
                if candidate.is_file() and candidate.suffix == ".feature":
                    harness_feature_files.add(candidate)
                elif candidate.is_dir():
                    harness_feature_files.update(path for path in candidate.rglob("*.feature") if path.is_file())
        if app_path_text and not app_path.exists():
            issues.append(f"acceptance harness `{name}` appPath missing: {app_path_text}")
        if command and not behavior_harness_script_text(target, command):
            issues.append(f"acceptance harness `{name}` command has no readable proof surface: {command}")
        missing_proofs = [needle for needle in proof_needles if needle and needle not in haystack]
        if missing_proofs:
            issues.append(
                f"acceptance harness `{name}` does not prove target app alignment; missing proof: {', '.join(missing_proofs)}"
            )
        if feature_patterns and not harness_feature_files:
            issues.append(f"acceptance harness `{name}` featurePaths matched no .feature files")
        harness_records.append(
            {
                "name": name,
                "command": command,
                "appPath": app_path,
                "featureFiles": sorted(harness_feature_files),
                "proofOk": not missing_proofs,
            }
        )

    return {
        "required": bool(behavior.get("required")),
        "enforcement": str(behavior.get("inactiveAcceptanceEnforcement", "strict" if behavior.get("required") else "warn")),
        "pendingTags": pending_tags,
        "featureFiles": feature_files,
        "pendingScenarios": pending_scenarios,
        "harnesses": harness_records,
        "issues": issues,
    }


def print_behavior_spec_status(data: dict, target: Path, status: dict | None = None) -> list[str]:
    """Print the repo-wide behavior-spec report; `status` lets a caller supply the record it has.

    `behavior_spec_status_record` walks and parses every in-scope feature file, and BOTH verbs that
    print it needed the record again afterwards for their strictness decision -- so each was paying
    for that walk twice per invocation. `methodology-status` is required by policy 15 before every
    plan finalization, merge, and delivery, which makes it the hot path where the second scan is
    least affordable. The parameter is optional so the startup caller stays behavior-identical.
    """
    status = behavior_spec_status_record(data, target) if status is None else status
    print(
        "behavior_specs: "
        f"required={str(status['required']).lower()} "
        f"enforcement={status['enforcement']} "
        f"feature_files={len(status['featureFiles'])} "
        f"inactive_scenarios={len(status['pendingScenarios'])} "
        f"harnesses={len(status['harnesses'])}"
    )
    print(f"behavior_specs_pending_tags: {','.join(status['pendingTags']) if status['pendingTags'] else 'none'}")
    print(f"behavior_specs_feature_files: {compact_path_list(status['featureFiles'], target)}")
    if status["pendingScenarios"]:
        sample = [
            Path(f"{path_relative_to_target(target, item['path'])}:{item['line']}")
            for item in status["pendingScenarios"][:5]
        ]
        print(f"behavior_specs_inactive_sample: {', '.join(str(item) for item in sample)}")
    for harness in status["harnesses"]:
        print(
            "behavior_specs_harness: "
            f"{harness['name']} app={path_relative_to_target(target, harness['appPath'])} "
            f"features={len(harness['featureFiles'])} proof={'ok' if harness['proofOk'] else 'missing'} "
            f"command={harness['command']}"
        )
    # The canonical form is CITED here, on the one line every author already reads, and
    # interpolated from the constant so it cannot drift from the refusals that enforce it (it
    # grew a `@reason:` field in 0.47.0). It deliberately does not go on the
    # `behavior_specs_issue:` lines: consumers and tests parse those, and RCA control #2's second
    # clause is satisfied by an author being shown the shape, not by reshaping parsed output.
    print(
        "behavior_specs_instruction: Executable behavior specs must run against the app package being changed; "
        "inactive acceptance scenarios require owner, reason, and un-pend trigger and cannot be normalized as covered."
        f" Canonical form: `{BEHAVIOR_PENDING_CANONICAL_FORM}`."
    )
    for issue in status["issues"]:
        print(f"behavior_specs_issue: {issue}")
    return list(status["issues"])


def print_behavior_spec_added_delta(data: dict, target: Path, base_ref: str) -> None:
    """Report the inactive scenarios this branch added since `base_ref`. REPORTING ONLY.

    RCA `20260615T135932Z` clause (c): the repo-wide counts above answer "how much debt is there",
    which a repo carrying long-standing debt answers identically whether a change added to it or
    not. Growth per change was invisible at the surface policy 15 requires before every
    finalization -- this answers it.

    Two whole TREES are compared, never the worktree (plan amendments A7/A10). Scenario text comes
    from HEAD's blobs and the merge base's blobs, so an uncommitted edit above a scenario cannot
    shift its span into looking introduced, and an added scenario deleted from disk but not from
    HEAD cannot hide. That is invariant I1 satisfied by construction rather than by care.

    The base is the MERGE BASE of `base_ref` and HEAD, so scenarios that only ever existed on a
    diverged base branch are never attributed to this one.

    Two qualifications a reader would otherwise get wrong:

    * **the offender list is deliberately NOT a subset of the count.** `behavior_delta_findings`
      also reports a scenario whose metadata this branch REMOVED -- debt introduced without a
      scenario being introduced -- so `behavior_specs_added_inactive: 0` printed alongside a
      `behavior_specs_added_issue:` line is a correct answer, not a contradiction.
    * **the scenarios come from two git trees; the POLICY comes from the worktree adapter** that
      `lane_project` resolved (`behaviorSpecs.paths`, `pendingTags`,
      `pendingRequiresOwnerAndTrigger`). `behavior-spec-delta-check` guards that seam because it
      REFUSES commits, so a dirty adapter there is a bypass. Here the same adapter is applied to
      both revisions symmetrically and gates nothing, so a dirty adapter changes what is reported
      and never what is allowed. Revision-aware adapter resolution is A3's work.

    Never changes the exit code (decision D5) -- including when it fails. Every failure, expected
    or not, lands on the same `unknown` floor.
    """
    behavior = data.get("behaviorSpecs", {})
    metadata_required = bool(behavior.get("pendingRequiresOwnerAndTrigger", True))

    def _blind(reason: str) -> None:
        # `unknown`, never `0` -- and on BOTH halves. Flooring the count while simply omitting the
        # issue lines leaves the ACTIONABLE surface reading exactly like a clean branch, because
        # zero `behavior_specs_added_issue:` lines is precisely what a branch that added nothing
        # prints. A blind check indistinguishable from a clean one is the defect class this whole
        # item exists to close, so both halves say "I could not look".
        print(f"behavior_specs_added_warning: {reason}")
        print(f"behavior_specs_added_inactive: unknown (vs {base_ref})")
        print(f"behavior_specs_added_issues: unknown (vs {base_ref})")

    def _names(rels: list[str]) -> str:
        # An unreadable-file list is unbounded. A blobless clone of a monorepo produces hundreds of
        # kilobytes on one line, and the log shipper that truncates it takes the REASON with it,
        # leaving a warning that explains nothing.
        head = ", ".join(rels[:5])
        return head if len(rels) <= 5 else f"{head} and {len(rels) - 5} more"

    def _report() -> None:
        if not base_ref.strip():
            # An unset CI variable expands to the empty string, and `--base ""` is falsy. Treating
            # it as "no --base given" would print nothing at all: the caller asked for a delta and
            # got silence that reads exactly like a branch with no growth.
            _blind(
                "--base was given a blank ref, so there is nothing to compare against. Pass a ref "
                "such as `--base origin/main`, or drop --base to report repo-wide counts only"
            )
            return
        # Four distinct failures, four distinct remedies. Collapsing them behind one merge-base
        # call tells a lane in a fresh clone to fetch a ref that is already present, and tells a
        # lane comparing unrelated histories the same thing.
        if run_git(target, ["rev-parse", "--git-dir"]) == "unavailable":
            _blind(
                f"{target} is not a git repository this checkout can read, so no revision "
                "can be compared"
            )
            return
        if run_git(target, ["rev-parse", "--verify", "--quiet", "HEAD"]) in ("", "unavailable"):
            _blind("HEAD has no commit yet, so this branch has introduced nothing to compare")
            return
        base_commit = run_git(
            target, ["rev-parse", "--verify", "--quiet", f"{base_ref}^{{commit}}"]
        )
        if base_commit in ("", "unavailable"):
            _blind(
                f"{base_ref} does not name a commit this checkout can see; fetch it "
                f"(`git fetch origin {base_ref}`) or pass a --base that is present locally"
            )
            return
        base_sha = run_git(target, ["merge-base", base_ref, "HEAD"])
        if base_sha in ("", "unavailable"):
            _blind(
                f"{base_ref} and HEAD share no common ancestor, so nothing here can be attributed "
                "to this branch; compare against a ref on the same history"
            )
            return
        try:
            tip_rels = behavior_feature_paths_at_revision(data, target, "HEAD")
            base_rels = behavior_feature_paths_at_revision(data, target, base_sha)
        except BehaviorRevisionUnavailable as exc:
            _blind(f"could not list the feature files in scope ({exc})")
            return
        if not tip_rels and not base_rels:
            # A work set derived from a pattern needs a non-vacuity floor. A mistyped or stale
            # `behaviorSpecs.paths` selects nothing, and nothing yields `0 added` -- which reads
            # identically to a branch that genuinely added none. This program has now paid for
            # that shape three times; an emptied scope is `unknown`, never zero.
            _blind(
                f"no .feature file is in behaviorSpecs.paths scope at HEAD or at {base_ref}, so a "
                "count would be measured over an empty set; check behaviorSpecs.paths"
            )
            return
        tip_scenarios, tip_unreadable = behavior_pending_scenarios_at_revision(data, target, "HEAD")
        if tip_unreadable:
            # A PARTIAL read is a blind read: the count computed from the files that did load is
            # one this report cannot stand behind, and it is usually the same number a clean tree
            # prints.
            _blind(
                "could not read " + _names(tip_unreadable) + " at HEAD; the count would come from "
                "a partial tree"
            )
            return
        base_scenarios, base_unreadable = behavior_pending_scenarios_at_revision(
            data, target, base_sha
        )
        if base_unreadable:
            _blind(
                "could not read " + _names(base_unreadable) + f" at {base_ref}; pre-existing debt "
                "cannot be told apart from debt this branch introduces"
            )
            return
        try:
            diff_text = git_diff_text_at(target, base_sha, "HEAD")
        except BehaviorRevisionUnavailable:
            _blind(
                f"could not diff {base_ref}...HEAD, so a rename cannot be followed to its source "
                "and a moved file's pre-existing scenarios would read as introduced"
            )
            return
        rename_sources = behavior_rename_sources(data, diff_text)
        added_inactive, offending = behavior_delta_findings(
            tip_scenarios, base_scenarios, target, rename_sources
        )
        # The suffixed form is deliberate: `behavior-spec-delta-check` prints the same key bare,
        # about the STAGED revision. Two answers to two different questions must stay
        # distinguishable in a mixed log, so they are never unified.
        print(f"behavior_specs_added_inactive: {len(added_inactive)} (vs {base_ref})")
        if not metadata_required:
            # The adapter turned the owner/un-pend rule off deliberately, and both
            # `behavior_spec_status_record` and `behavior-spec-delta-check` honour that. Listing
            # offenders anyway would invent debt the project has decided it does not have -- a
            # false report is the reporting surface's version of a false refusal. The COUNT above
            # is unaffected: it measures growth in inactive scenarios, which this flag says
            # nothing about, and which the adapter's ceiling still governs.
            print(
                "behavior_specs_added_issues: disabled by adapter "
                "(pendingRequiresOwnerAndTrigger)"
            )
            return
        print(f"behavior_specs_added_issues: {len(offending)} (vs {base_ref})")
        for scenario in offending:
            rel = path_relative_to_target(target, scenario["path"])
            fields = ", ".join(behavior_pending_missing_metadata(scenario.get("context", "")))
            print(
                f"behavior_specs_added_issue: inactive scenario missing {fields}: "
                f"{rel}:{scenario['line']} {scenario['name']} "
                f"— annotate as `{BEHAVIOR_PENDING_CANONICAL_FORM}`"
            )

    try:
        _report()
    except Exception as exc:
        # A REPORT may never change the exit code (decision D5), and that has to hold when the
        # REPORT ITSELF breaks: git absent from PATH raises FileNotFoundError, a feature path that
        # escapes the target raises ValueError out of path_relative_to_target, a subprocess can
        # raise OSError. Without this the verb dies before printing
        # `behavior_specs_effective_enforcement:`, the shell sees a traceback exit, and a flag
        # documented as reporting-only has silently become a gate -- the exact inversion D5 forbids.
        _blind(f"the delta report failed unexpectedly ({exc!r}), so the added count is unknown")


def behavior_spec_status(args: argparse.Namespace) -> int:
    data, _project_path, target = lane_project(args)
    status = behavior_spec_status_record(data, target)
    issues = print_behavior_spec_status(data, target, status)
    # `is not None`, not truthiness: an unset CI variable expands to `--base ""`, and a falsy test
    # would silently answer a delta question with no delta and no warning. `args.base` is read
    # directly rather than through getattr so deleting the parser wiring fails loudly here.
    if args.base is not None:
        print_behavior_spec_added_delta(data, target, str(args.base))
    effective_strict = bool(args.strict) or status["enforcement"] == "strict"
    print(f"behavior_specs_effective_enforcement: {'strict' if effective_strict else 'warn'}")
    return 1 if effective_strict and issues else 0


def behavior_spec_delta_check(args: argparse.Namespace) -> int:
    """`behavior-spec-delta-check`: refuse inactive scenarios THIS change introduces without
    owner/un-pend metadata.

    The RCA gap this closes: 0.47.0 gave the owner+un-pend rule one definition and published its
    form, but left the rule reachable only from `codex-run`'s evidence-recording path and the
    repo-wide status report. A commit that crossed neither landed metadata-less pending debt
    silently -- the mechanism that let one adopter's debt reach 268 scenarios before a repo-wide
    gate detonated on an unrelated PR. Naming a rule does not enforce it; this is the same rule at
    the source boundary, where the debt is actually created.

    Scoping obeys the plan's load-bearing invariants:
      I1  the scenarios compared come from two whole tree objects (`HEAD` and the index), never
          from the worktree, so an uncommitted edit cannot make a scenario look introduced;
      I3  only scenarios the change actually introduces can block -- pre-existing debt never
          blocks, at any boundary, in any mode;
      I4  discovery uses the adapter's own path predicate, never a looser one;
      I5  FAIL-OPEN with a visible warning. This is built to run in a generated hook in every
          consumer repo, including fresh clones with no remote, so an unreadable tree or a git
          failure warns and exits 0. `codex-run` remains the strict backstop.
    """
    data, project_path, target = lane_project(args)

    def _blind(reason: str) -> int:
        # Fail-open, but SAY so, and report the count as `unknown` rather than `0`. Printing 0
        # would make a blind check indistinguishable from a clean one -- in the logs and to
        # anything parsing them -- which is the whole class of defect this verb exists to close.
        print(f"behavior_spec_delta_warning: {reason}")
        print("behavior_specs_added_inactive: unknown")
        return 0

    # The POLICY and the SCENARIOS must come from the same revision. `lane_project` resolves the
    # adapter from the worktree while everything below reads the index, so an adapter edited but
    # not staged sets the rules for a tree it is not part of. Both directions are wrong, and one
    # is a bypass: flipping `pendingRequiresOwnerAndTrigger` to false in the worktree alone would
    # silence an otherwise enforcing staged adapter, without that change ever being committed.
    #
    # Reading policy from the index instead would be the fuller fix; it needs the whole adapter
    # resolution and validation path to become revision-aware, which is A3's work. Until then this
    # refuses to answer rather than answer from the wrong revision.
    if project_path:
        try:
            rel_adapter = str(Path(project_path).resolve().relative_to(Path(target).resolve()))
        except (ValueError, OSError):
            rel_adapter = ""
        if rel_adapter:
            staged = git_object_bytes(target, f":./{rel_adapter}")
            try:
                on_disk: bytes | None = Path(project_path).read_bytes()
            except OSError:
                on_disk = None
            if staged is None or on_disk is None:
                # `None` is ABSENT-OR-UNREADABLE, not "same as the worktree". An adapter that is
                # untracked, staged for deletion, or unreadable is policy the staged revision does
                # not carry -- so an unstaged `pendingRequiresOwnerAndTrigger: false` would make
                # the check print `disabled` and exit 0, which is the bypass this guard exists to
                # stop, just entering through the missing-file door instead of the edited-file one.
                return _blind(
                    f"the adapter at {rel_adapter} could not be read from the index; policy for "
                    "the staged revision is unknown. Stage the adapter and re-run"
                )
            if staged != on_disk:
                return _blind(
                    f"the adapter at {rel_adapter} differs between the worktree and the index; "
                    "policy and scenarios would come from different revisions. Stage the adapter, "
                    "or revert it, and re-run"
                )

    behavior = data.get("behaviorSpecs", {})
    if not behavior.get("pendingRequiresOwnerAndTrigger", True):
        print("behavior_spec_delta_check: disabled by adapter (pendingRequiresOwnerAndTrigger)")
        return 0

    revision = BEHAVIOR_REVISION_INDEX
    tip_scenarios, unreadable = behavior_pending_scenarios_at_revision(data, target, revision)
    if unreadable:
        # A PARTIAL read is a blind read. Warning and then printing a number computed from the
        # files that did load reports a count the check cannot stand behind, and that count is
        # usually 0 -- exactly what a clean tree prints.
        return _blind(
            "could not read "
            + ", ".join(unreadable)
            + " at the staged revision; the count below is not trustworthy"
        )
    # An unborn HEAD is an EMPTY base, not an unreadable one. On the very first commit of a repo
    # there is no prior revision to compare against and no pre-existing debt to protect, so
    # treating it as a failed read would make the gate fail open on exactly the commit that
    # establishes a repo's baseline.
    #
    # `--verify --quiet HEAD` exits non-zero for an unborn HEAD, and `run_git` reports every
    # non-zero exit as "unavailable" -- so "unavailable" alone cannot tell an unborn repository
    # from a broken git. Reading it as unborn would empty the base set, and every pre-existing
    # unannotated scenario would then look newly introduced and REFUSE the commit: failing closed
    # on a blind read, the most expensive direction available. So an unborn HEAD has to be
    # confirmed positively, by asking a question that succeeds in a working repository.
    # `rev-parse --git-dir` answers for any repo, born or not.
    head_sha = run_git(target, ["rev-parse", "--verify", "--quiet", "HEAD"])
    if head_sha not in ("", "unavailable"):
        has_head, unborn_confirmed = True, False
    else:
        has_head = False
        # An UNBORN HEAD is a symbolic ref pointing at a branch that has no commit yet. Both parts
        # have to be established POSITIVELY, and neither `rev-list --all` nor `symbolic-ref` alone
        # can do it:
        #
        #   * `rev-list --all` is non-empty on an ORPHAN branch (`git checkout --orphan`) in a repo
        #     with commits on other refs -- HEAD is unborn but history exists, so reading `--all`
        #     as "there are commits" reports `unknown` and waves the orphan branch's first commit
        #     straight through; and
        #   * `symbolic-ref` succeeding proves only that HEAD names a branch, born or not.
        #
        # `for-each-ref` is the probe that distinguishes all three states, because it exits 0
        # whether or not the ref exists: a refname means the branch is born, empty means it is not,
        # and "unavailable" means git failed. A detached HEAD fails `symbolic-ref`, which is the
        # broken case this must never read as unborn.
        head_ref = run_git(target, ["symbolic-ref", "--quiet", "HEAD"])
        unborn_confirmed = bool(head_ref) and head_ref != "unavailable" and (
            run_git(target, ["for-each-ref", "--format=%(refname)", head_ref]) == ""
        )
    if not has_head and not unborn_confirmed:
        return _blind(
            "could not determine whether HEAD exists; pre-existing debt cannot be distinguished "
            "from debt this change introduces"
        )
    try:
        diff_text = git_diff_text_at(target, "HEAD", revision)
    except BehaviorRevisionUnavailable as exc:
        if has_head:
            return _blind(f"could not diff the staged revision ({exc})")
        diff_text = ""
    rename_sources = behavior_rename_sources(data, diff_text)
    if has_head:
        base_scenarios, base_unreadable = behavior_pending_scenarios_at_revision(
            data, target, "HEAD"
        )
    else:
        base_scenarios, base_unreadable = [], []
    if base_unreadable:
        # Treating an unreadable BASE as "no pre-existing debt" would make every scenario in that
        # file look introduced and refuse the commit -- failing CLOSED on debt the change never
        # touched, which is the worst available outcome.
        return _blind(
            "could not read " + ", ".join(base_unreadable) + " at HEAD; "
            "pre-existing debt cannot be distinguished from debt this change introduces"
        )
    added_inactive, offending = behavior_delta_findings(
        tip_scenarios, base_scenarios, target, rename_sources
    )

    print(f"behavior_specs_added_inactive: {len(added_inactive)}")
    if not offending:
        return 0

    for scenario in offending:
        rel = path_relative_to_target(target, scenario["path"])
        fields = ", ".join(behavior_pending_missing_metadata(scenario.get("context", "")))
        print(
            f"behavior_spec_delta_error: inactive scenario missing {fields}: "
            f"{rel}:{scenario['line']} {scenario['name']}",
            file=sys.stderr,
        )
    print(
        "behavior_spec_delta_instruction: annotate each scenario above as "
        f"`{BEHAVIOR_PENDING_CANONICAL_FORM}`, or remove its pending tag and implement it, then "
        "re-stage. To record the debt deliberately instead, set "
        "`behaviorSpecs.pendingRequiresOwnerAndTrigger: false` in the SOURCE adapter with a "
        "decision record and re-render.",
        file=sys.stderr,
    )
    return 1


def behavior_source_material_citation_errors(data: dict, plan_text: str) -> list[str]:
    behavior = data.get("behaviorSpecs", {})
    source_materials = [
        str(value).strip()
        for value in behavior.get("sourceMaterials", [])
        if str(value).strip()
    ]
    if not source_materials:
        return []

    errors: list[str] = []
    section = markdown_section(plan_text, "## Behavior Source Materials")
    if not section:
        if BEHAVIOR_SOURCE_EXEMPTION_MARKER in plan_text:
            errors.append(
                f"behavior source material exemption `{BEHAVIOR_SOURCE_EXEMPTION_MARKER}` must appear inside "
                "`## Behavior Source Materials`"
            )
        errors.append(
            "behavior source material section missing: add `## Behavior Source Materials` and account for every "
            "behaviorSpecs.sourceMaterials entry as reviewed/adapted or not applicable with a reason"
        )
        return errors

    if plan_text.count(BEHAVIOR_SOURCE_EXEMPTION_MARKER) > section.count(BEHAVIOR_SOURCE_EXEMPTION_MARKER):
        errors.append(
            f"behavior source material exemption `{BEHAVIOR_SOURCE_EXEMPTION_MARKER}` must appear only inside "
            "`## Behavior Source Materials`"
        )

    exempted, exemption_error = behavior_source_material_exemption_state(section, BEHAVIOR_SOURCE_EXEMPTION_MARKER)
    if exempted:
        normalized_section = section.replace("\\", "/")
        cited_sources = [
            source
            for source in source_materials
            if source.replace("\\", "/") in normalized_section
        ]
        if cited_sources:
            errors.append(
                "behavior source material exemption conflicts with cited source entries: "
                + ", ".join(cited_sources)
            )
        return errors
    if exemption_error:
        errors.append(exemption_error)

    normalized_lines = [(line, line.replace("\\", "/")) for line in section.splitlines()]
    adaptation_pattern = re.compile(
        r"\b(?:reviewed|adapted|imported|normalized|split|preserved|source-derived)\b",
        re.IGNORECASE,
    )
    source_recreation_pattern = re.compile(
        r"\b(?:from scratch|recreated?|ignored|did not use|not used|without using|not reviewed)\b",
        re.IGNORECASE,
    )
    not_applicable_terms = ["not applicable", "does not apply", "not relevant", "out of scope"]
    for source in source_materials:
        normalized_source = source.replace("\\", "/")
        matching_lines = [line for line, normalized in normalized_lines if normalized_source in normalized]
        if not matching_lines:
            errors.append(f"behavior source material not accounted for: {source}")
            continue
        line = matching_lines[0].strip()
        lower_line = line.lower()
        if any(term in lower_line for term in not_applicable_terms):
            if not behavior_not_applicable_line_has_reason(line, source, not_applicable_terms):
                errors.append(f"behavior source material not-applicable entry lacks a reason: {source}")
            continue
        if source_recreation_pattern.search(line):
            errors.append(f"behavior source material entry says source was not used: {source}")
            continue
        if not adaptation_pattern.search(line):
            errors.append(
                "behavior source material entry must state reviewed/adapted/imported/normalized/split/preserved "
                f"or not applicable with a reason: {source}"
            )
    return errors












def validate_plan_review_run_meta(
    meta: dict,
    target: Path,
    plan_rel: str,
    plan_hash: str,
    review_command: str,
    log_path: Path,
    wrapper_exit_code: int,
) -> list[str]:
    errors: list[str] = []
    required_fields = [
        "schema",
        "plan_path",
        "plan_content_sha256",
        "review_scope",
        "code_diff_review",
        "review_command",
        "log_path",
        "log_sha256",
        "wrapper_exit_code",
        "started_at",
        "finished_at",
    ]
    for field in required_fields:
        if field not in meta:
            errors.append(f"plan review run metadata missing field: {field}")
    if errors:
        return errors
    if meta["schema"] != PLAN_REVIEW_RUN_SCHEMA:
        errors.append(f"plan review run metadata schema mismatch: {meta['schema']}")
    if meta["plan_path"] != plan_rel:
        errors.append(f"plan review run metadata plan_path mismatch: {meta['plan_path']} != {plan_rel}")
    if meta["plan_content_sha256"] != plan_hash:
        errors.append("plan review run metadata is stale: plan_content_sha256 does not match current plan content")
    if meta["review_scope"] != "plan-only":
        errors.append("plan review run metadata review_scope must be plan-only")
    if meta["code_diff_review"] is not False:
        errors.append("plan review run metadata code_diff_review must be false")
    if meta["review_command"] != review_command:
        errors.append("plan review run metadata review_command mismatch")
    try:
        meta_exit_code = int(meta["wrapper_exit_code"])
    except (TypeError, ValueError):
        meta_exit_code = -999999
        errors.append("plan review run metadata wrapper_exit_code must be an integer")
    if meta_exit_code != wrapper_exit_code:
        errors.append("plan review run metadata wrapper_exit_code mismatch")
    meta_log_path = cli_path(target, str(meta["log_path"])).resolve(strict=False)
    if meta_log_path != log_path.resolve(strict=False):
        errors.append(f"plan review run metadata log_path mismatch: {meta['log_path']}")
    elif not log_path.exists() or not log_path.is_file():
        errors.append(f"plan review run metadata log missing: {log_path}")
    else:
        log_hash = file_sha256(log_path)
        if meta["log_sha256"] != log_hash:
            errors.append("plan review run metadata log_sha256 mismatch")
    return errors






def plan_review_successful_run_meta_records(data: dict, target: Path, plan_rel: str) -> list[tuple[Path, dict]]:
    runs_dir = configured_path(target, data["laneState"]["runsDir"]) / "plan-review"
    records: list[tuple[Path, dict]] = []
    if not runs_dir.exists() or not runs_dir.is_dir():
        return records
    for meta_path in sorted(runs_dir.glob("*.meta.json")):
        try:
            meta = json.loads(meta_path.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError):
            continue
        if not isinstance(meta, dict):
            continue
        if meta.get("schema") != PLAN_REVIEW_RUN_SCHEMA:
            continue
        if not plan_references_match(data, target, str(meta.get("plan_path") or ""), plan_rel):
            continue
        try:
            wrapper_exit_code = int(meta.get("wrapper_exit_code"))
        except (TypeError, ValueError):
            continue
        if wrapper_exit_code != 0:
            continue
        records.append((meta_path, meta))
    return records


def plan_review_observed_run_count(data: dict, target: Path, plan_rel: str) -> int:
    """How many reviewer invocations this source plan has actually spent.

    Thin wrapper over the one reader that already filters to wrapper_exit_code == 0, so a failed
    or watchdog-killed run -- which produced no review -- never costs a round.
    """
    return len(plan_review_successful_run_meta_records(data, target, plan_rel))


def plan_review_manifest_path_for_rel(data: dict, target: Path, plan_rel: str) -> Path:
    """The manifest a chain member's relative plan path resolves to.

    The walk carries members as recorded relative paths -- that is what evidence records store --
    so it needs the same slug derivation the Path-keyed helper does, without pretending the plan
    file still exists on disk. A superseded predecessor may have been deleted; its manifest is the
    record that outlives it.
    """
    # Item 59 W3: resolve through the recorded reference's ROOT rather than rebuilding
    # `target / plan_rel`, which reinstated the lane assumption for exactly the records that outlive
    # their plan. A bare legacy string still reads as the lane, so nothing already recorded moves.
    return plan_review_manifest_path(
        data, target, paths_module().resolve_plan_reference(data, target, plan_rel)
    )


def plan_review_recorded_predecessor(data: dict, target: Path, plan_rel: str) -> str | None:
    """The plan this one succeeds, per its own records, or None when it is standalone.

    Resolution order is finalized-first: the manifest is the bound record, and a run meta is only
    a launch-time declaration. Among run metas the EARLIEST wins -- lineage is append-once, so the
    first declaration is the one that stands. Absent everywhere means standalone, never guessed.
    """
    manifest = load_plan_review_manifest(plan_review_manifest_path_for_rel(data, target, plan_rel))
    if manifest:
        recorded = str(manifest.get("predecessor_plan_path") or "").strip()
        if recorded:
            return recorded
    for _meta_path, meta in plan_review_successful_run_meta_records(data, target, plan_rel):
        recorded = str(meta.get("predecessor_plan_path") or "").strip()
        if recorded:
            return recorded
    # Codex R4 P2 (item 108 WS3): the durable round record is the third place a declaration
    # survives -- after .ai-runs is pruned it is the ONLY place. Reading it here keeps the
    # conflict branch honest: one plan cannot append a contradictory --predecessor while the
    # resolver still counts the original record-backed edge. Earliest record wins, matching
    # the append-once rule the metas already follow.
    try:
        for _record_path, record in plan_review_round_records_for_rel(data, target, plan_rel):
            # Codex R1 P2 (post-rebase lineage): CHARGED only, matching the meta reader above,
            # which counts successful runs alone. A failed wrapper still writes its invocation
            # record, so an uncharged one would let a run that produced no review become the
            # recorded lineage -- conflicting with a later correct --predecessor and pulling an
            # ancestor's spend into the budget on the strength of an attempt that never happened.
            if not plan_review_record_is_charged_invocation(record):
                continue
            recorded = str(record.get("declared_predecessor") or "").strip()
            if recorded:
                return recorded
    except ValueError:
        pass
    return None


def plan_review_rounds_dir_for_rel(data: dict, target: Path, plan_rel: str) -> Path:
    """A member's record directory from its recorded reference (item 108 WS2).

    Resolves through the reference's ROOT exactly like `plan_review_manifest_path_for_rel`: the
    records outlive the plan file, so this never requires the plan to still exist on disk.
    """
    return plan_review_rounds_dir(
        data, target, paths_module().resolve_plan_reference(data, target, plan_rel)
    )


def plan_review_recorded_member_spend(
    data: dict, target: Path, plan_rel: str
) -> tuple[int, str] | None:
    """Cumulative member spend from the durable record, or None for a pre-record member.

    Item 108 WS2 T2.1, the Design-section arithmetic: ADDITIVE across the cutover, never a
    max() -- `spend = baseline pre-record floor (corrections applied raise-only) + |charged
    invocation records, run and imported alike|`. Cardinality of an append-only set is
    order-free, so fresh worktrees and out-of-order finalization cannot decrement it. A member
    with no baseline has no records by construction (every record-appending verb writes the
    baseline first), so this returns None and the caller reads the pre-record floor instead.

    A successful lane meta whose digest is in NEITHER the records NOR the baseline's enumerated
    set is counted exactly once -- and surfaced loudly as a record write-path bug, never
    silently absorbed. This reader is PURE: it never writes a baseline or any other record.
    """
    module = plan_round_record_module()
    try:
        rounds = plan_review_rounds_dir_for_rel(data, target, plan_rel)
    except ValueError:
        # An unresolvable recorded reference names no record directory; the floor is the truth.
        return None
    baseline = module.load_baseline(rounds)
    if baseline is None:
        return None
    records = module.load_round_records(rounds)
    recorded_digests = module.reviewer_invocation_log_sha256s(records)
    baseline_set = {str(digest) for digest in (baseline.get("prerecord_log_sha256s") or [])}
    unrecorded: set[str] = set()
    for _meta_path, meta in plan_review_successful_run_meta_records(data, target, plan_rel):
        digest = str(meta.get("log_sha256") or "")
        if digest and digest not in recorded_digests and digest not in baseline_set:
            unrecorded.add(digest)
    if unrecorded:
        print(
            f"plan_review_round_spend_warning: {len(unrecorded)} successful run meta(s) for "
            f"{plan_rel} match no round record and no baseline digest "
            f"({', '.join(sorted(unrecorded))}); each is counted once in spend, but a spent "
            "round without its record is a record write-path bug -- bind each log with "
            "`tautline record-plan-review` so the durable record catches up",
            file=sys.stderr,
        )
    spend = (
        module.effective_prerecord_count(baseline, records)
        + module.charged_invocation_count(records)
        + len(unrecorded)
    )
    return spend, ("round_records" if records or unrecorded else "baseline")


def plan_review_member_spend(data: dict, target: Path, plan_rel: str) -> tuple[int | None, str]:
    """THE budget surface (item 108 WS2): cumulative member spend, and its honest source.

    Every BUDGET decision reads through here; the manifest's lane-local
    `observed_successful_runs` copy is display, the baseline input, and the no-baseline floor --
    never the budget. Sources: `round_records` (the durable record, additively),
    `baseline` (a cutover member with no invocations yet), `run_metas` / `manifest-floor` (a
    pre-record member reading at today's floor -- relabelled from the chain display's
    `manifest` so a floor never masquerades as the durable truth), or `unknown`.
    """
    recorded = plan_review_recorded_member_spend(data, target, plan_rel)
    if recorded is not None:
        return recorded
    count, source = plan_review_prerecord_member_floor(data, target, plan_rel)
    return count, ("manifest-floor" if source == "manifest" else source)


def plan_review_member_recorded_rounds(
    data: dict, target: Path, plan_rel: str
) -> tuple[int | None, str]:
    """How many review rounds one chain member spent, and where that number came from.

    The durable record first (item 108 WS2): a member with a baseline reads its additive
    record-backed spend, which survives fresh worktrees and out-of-order finalization. Only a
    pre-record member (no baseline, hence no records) falls to the evidence ladder below, under
    the ladder's own recorded source vocabulary.

    A member's own `chain_recorded_rounds` is deliberately NOT consulted: it already covers that
    member's ancestors, and summing chain totals double-counts every shared ancestor.
    """
    recorded = plan_review_recorded_member_spend(data, target, plan_rel)
    if recorded is not None:
        return recorded
    return plan_review_prerecord_member_floor(data, target, plan_rel)


def plan_review_prerecord_member_floor(
    data: dict, target: Path, plan_rel: str
) -> tuple[int | None, str]:
    """The pre-record evidence ladder, honest at every rung (K3).

    Successful run metas when the lane still holds them; else the member's finalized manifest,
    whose carried `observed_successful_runs` counts the runs BEFORE the bound one, plus that
    bound run only when it actually succeeded -- a failed bind never becomes a successful round.
    Past that the answer is `unknown`, which the summary reports as an unknown and folds into a
    floor rather than inventing a number.
    """
    records = plan_review_successful_run_meta_records(data, target, plan_rel)
    manifest = load_plan_review_manifest(plan_review_manifest_path_for_rel(data, target, plan_rel))
    manifest_count = None
    if manifest:
        try:
            observed = int(manifest["observed_successful_runs"])
        except (KeyError, TypeError, ValueError):
            observed = None
        if observed is not None:
            try:
                bound_exit = int(manifest.get("wrapper_exit_code"))
            except (TypeError, ValueError):
                bound_exit = None
            manifest_count = observed + (1 if bound_exit == 0 else 0)
    # Codex R1 P2: retained run metas being NONEMPTY does not mean COMPLETE. A lane that pruned
    # its .ai-runs/plan-review history keeps a partial set of metas alongside a manifest whose
    # observed_successful_runs still remembers the full spend -- returning len(records) alone then
    # UNDERCOUNTS and the caller reports it "exact". The manifest count is never lower than what
    # actually happened (it is written once, at bind time, from the ledger this member itself
    # walked), so whichever source is larger is closer to the truth; only when they genuinely
    # disagree does the source label read "manifest" instead of "run_metas", which is honest either
    # way since "run_metas" already means "this is the trusted rung of the ladder".
    if records and (manifest_count is None or len(records) >= manifest_count):
        return len(records), "run_metas"
    if manifest_count is not None:
        return manifest_count, "manifest"
    return None, "unknown"


def plan_review_lineage_identity(data: dict, target: Path, plan_rel: str) -> str:
    """A dedupe key that survives spelling. Two references naming one plan must count ONCE.

    An unresolvable reference (a plan-root token this lane no longer configures) falls back to
    its raw string: it stays inert and distinct rather than raising out of a ceremony.
    """
    try:
        return str(paths_module().resolve_plan_reference(data, target, plan_rel).resolve())
    except (ValueError, OSError):
        return plan_rel


def plan_review_manifest_for_rel(data: dict, target: Path, plan_rel: str) -> dict | None:
    """A recorded reference's manifest, or None when the reference cannot even be resolved.

    RESOLUTION-SAFE on purpose: the lineage resolver walks EVERY recorded reference in the lane,
    and one stale root token (`backlog` vs `tautline-backlog`) must never raise out of a run or
    -- worse -- out of a finalize before its manifest write.
    """
    try:
        manifest_path = plan_review_manifest_path_for_rel(data, target, plan_rel)
    except (ValueError, OSError):
        return None
    return load_plan_review_manifest(manifest_path)


def plan_review_round_records_for_rel(
    data: dict, target: Path, plan_rel: str
) -> list[tuple[Path, dict]]:
    """The member's durable round records (item 108 WS1), or [] when the reference is inert."""
    try:
        plan_path = paths_module().resolve_plan_reference(data, target, plan_rel)
    except (ValueError, OSError):
        return []
    return plan_round_record_module().load_round_records(
        plan_review_rounds_dir(data, target, plan_path)
    )


def plan_review_reviewed_plan_references(data: dict, target: Path) -> list[str]:
    """Every plan this lane holds review evidence for: manifests, run metas AND round records.

    Read from each record's own `plan_path`, never from a manifest FILENAME: the filename is a
    slug, and the recorded reference is the thing every other surface keys on. Run metas and
    round-record directories count alongside manifests because a plan that took a round and was
    never bound still has real spend -- enumerating manifests alone made it invisible, which is
    a budget refill through a door a lane can open by accident.
    """
    references: list[str] = []
    seen: set[str] = set()

    def add(reference: object) -> None:
        text = str(reference or "").strip()
        if not text:
            return
        key = plan_review_lineage_identity(data, target, text)
        if key in seen:
            return
        seen.add(key)
        references.append(text)

    reviews_root = plan_review_root(data, target) / ".plan-reviews"
    if reviews_root.is_dir():
        for manifest_path in sorted(reviews_root.glob("*.json")):
            if manifest_path.name.endswith(".imported.json"):
                continue
            manifest = load_plan_review_manifest(manifest_path)
            if manifest:
                add(manifest.get("plan_path"))
    runs_dir = configured_path(target, data["laneState"]["runsDir"]) / "plan-review"
    if runs_dir.is_dir():
        for meta_path in sorted(runs_dir.glob("*.meta.json")):
            try:
                meta = json.loads(meta_path.read_text(encoding="utf-8"))
            except (OSError, json.JSONDecodeError):
                continue
            if not isinstance(meta, dict) or meta.get("schema") != PLAN_REVIEW_RUN_SCHEMA:
                continue
            try:
                if int(meta.get("wrapper_exit_code")) != 0:
                    continue
            except (TypeError, ValueError):
                continue
            add(meta.get("plan_path"))
    rounds_root = reviews_root / "rounds"
    if rounds_root.is_dir():
        module = plan_round_record_module()
        for member_dir in sorted(path for path in rounds_root.iterdir() if path.is_dir()):
            baseline = module.load_baseline(member_dir)
            if baseline:
                add(baseline.get("plan_path"))
                continue
            records = module.load_round_records(member_dir)
            if records:
                add(records[0][1].get("plan_path"))
    return references


def plan_review_name_shape_predecessor(
    data: dict, target: Path, plan_rel: str, universe: list[str] | None = None
) -> str:
    """The `-vN` ancestor among EXISTING entries -- enumeration, never candidate-name generation.

    Item 108 P1 #2 (DD). The prior descent GENERATED names downward from N and stopped at the
    32-name bound, so `admin-v34` never found `admin-v1` -- and a date-like `-v20260815` suffix
    would have materialised twenty million strings first. This lists what actually exists --
    sibling plan files, reviewed references (manifests, run metas, round records) -- matches each
    stem against `^<base>(-v\\d+)?$`, and picks the highest version below N (the bare base counts
    as version 0). Cost is bounded by directory and evidence size, never by N.

    Only entries WITH review evidence bind: a bare file that never spent a round has no budget to
    draw on, and binding it would put an invented lineage into the advisory output. Ties on one
    version resolve to the lexicographically smallest reference, so the answer is deterministic
    whichever enumeration order found it.
    """
    try:
        plan_path = paths_module().resolve_plan_reference(data, target, plan_rel)
    except (ValueError, OSError):
        return ""
    match = PLAN_REVIEW_SUCCESSOR_STEM_PATTERN.match(plan_path.stem)
    if not match:
        return ""
    number = int(match.group("number"))
    stem_pattern = re.compile(rf"^{re.escape(match.group('base'))}(?:-v(?P<n>\d+))?$")
    try:
        plan_dir = plan_path.parent.resolve()
    except OSError:
        return ""
    best: tuple[int, str] | None = None

    def consider(candidate_path: Path, reference: str, *, evidenced: bool) -> None:
        nonlocal best
        if candidate_path.suffix != plan_path.suffix:
            return
        shape = stem_pattern.match(candidate_path.stem)
        if not shape:
            return
        version = int(shape.group("n")) if shape.group("n") else 0
        if version >= number:
            return
        try:
            if candidate_path.parent.resolve() != plan_dir:
                return
        except OSError:
            return
        if not evidenced and not plan_review_reference_has_review_evidence(
            data, target, reference
        ):
            return
        if best is None or version > best[0] or (version == best[0] and reference < best[1]):
            best = (version, reference)

    try:
        siblings = sorted(entry for entry in plan_path.parent.iterdir() if entry.is_file())
    except OSError:
        siblings = []
    for sibling in siblings:
        try:
            reference = plan_root_relative_reference(data, target, sibling)
        except (ValueError, SystemExit):
            continue
        consider(sibling, reference, evidenced=False)
    # Reviewed entries outlive their files: a deleted predecessor's manifest, run meta or round
    # record is still an existing entry, so `rm` never buys the budget back.
    if universe is None:
        universe = plan_review_reviewed_plan_references(data, target)
    for reference in universe:
        try:
            candidate = paths_module().resolve_plan_reference(data, target, reference)
        except (ValueError, OSError):
            continue
        consider(candidate, reference, evidenced=True)
    return best[1] if best else ""


def plan_review_reference_has_review_evidence(data: dict, target: Path, plan_rel: str) -> bool:
    """Whether this reference has spent anything reviewable: manifest, run meta or round record."""
    if plan_review_manifest_for_rel(data, target, plan_rel):
        return True
    if plan_review_successful_run_meta_records(data, target, plan_rel):
        return True
    # Codex R5 P2 (item 108 WS3): only a CHARGED invocation is evidence -- a failed wrapper's
    # uncharged record matches the meta path's wrapper_exit_code == 0 filter, or a predecessor
    # with zero successful reviews binds lineage it never earned.
    return any(
        record.get("kind") == "reviewer-invocation" and record.get("charged")
        for _path, record in plan_review_round_records_for_rel(data, target, plan_rel)
    )


def plan_review_record_is_charged_invocation(record: object) -> bool:
    """Whether a round record is a reviewer invocation that actually spent a review.

    ONE predicate for every lineage reader. A failed wrapper still writes its invocation record
    -- deliberately, it is the audit trail -- but it produced no review, so it must never supply
    a lineage edge: not a declared predecessor, not a work item. Two rounds of review found this
    class at two different sites (Codex R1 P2 and R2 P2 on this lineage), which is the signature
    of a rule expressed per-site instead of once. The meta readers beside these call sites have
    always been success-only; this is that same rule, named.
    """
    if not isinstance(record, dict):
        return False
    return record.get("kind") == "reviewer-invocation" and bool(record.get("charged"))


def plan_review_predecessor_edges(
    data: dict,
    target: Path,
    plan_rel: str,
    *,
    seed: str = "",
    universe: list[str] | None = None,
) -> list[tuple[str, str]]:
    """Every predecessor edge this plan asserts, as (reference, source) -- THE UNION.

    Item 108 P1 #3 (T3.1). The prior first hop consulted the explicit `--predecessor` seed only
    when name-shape inference found nothing, so one launch recorded two different lineages. Here
    every edge is admitted: the caller's seed, the manifest's recorded predecessor, every run
    meta's declaration, every durable round record's `declared_predecessor` (item 108 WS1), and
    the name-shape inference -- deduped on resolved identity, declared edges first, so the order
    is deterministic and a declared fact is never shadowed by an inference.
    """
    edges: list[tuple[str, str]] = []
    seen: set[str] = set()

    def admit(reference: object, source: str) -> None:
        text = str(reference or "").strip()
        if not text:
            return
        key = plan_review_lineage_identity(data, target, text)
        if key in seen:
            return
        seen.add(key)
        edges.append((text, source))

    admit(seed, "declared")
    manifest = plan_review_manifest_for_rel(data, target, plan_rel)
    if manifest:
        admit(manifest.get("predecessor_plan_path"), "declared")
    for _meta_path, meta in plan_review_successful_run_meta_records(data, target, plan_rel):
        admit(meta.get("predecessor_plan_path"), "declared")
    for _record_path, record in plan_review_round_records_for_rel(data, target, plan_rel):
        # CHARGED only -- see plan_review_charged_invocation_records: every recorded lineage
        # edge must rest on a review that actually happened.
        if plan_review_record_is_charged_invocation(record):
            admit(record.get("declared_predecessor"), "declared")
    admit(
        plan_review_name_shape_predecessor(data, target, plan_rel, universe=universe),
        "name-shape",
    )
    return edges


def plan_review_work_items_for_rel(data: dict, target: Path, plan_rel: str) -> set[str]:
    """EVERY work item this plan has declared -- recorded and live -- as a set.

    A UNION, not a preference: recorded values (manifest, run metas, round records) survive the
    deletion of the plan file, and the live declaration survives a between-rounds correction of
    the field. Membership is an intersection test at the call site, so a plan belongs to every
    lineage it has ever claimed.
    """
    items: set[str] = set()

    def add(value: object) -> None:
        text = str(value or "").strip()
        if text:
            items.add(text)

    manifest = plan_review_manifest_for_rel(data, target, plan_rel)
    if manifest:
        add(manifest.get("work_item_reference"))
    for _meta_path, meta in plan_review_successful_run_meta_records(data, target, plan_rel):
        add(meta.get("work_item_reference"))
    for _record_path, record in plan_review_round_records_for_rel(data, target, plan_rel):
        # CHARGED only, same rule as the declared-predecessor edge above (Codex R2 P2): a failed
        # wrapper records its work_items too, and harvesting them let an attempt that produced no
        # review bind this plan to same-item siblings and their ancestors after the plan text
        # changed. Live plan text still covers every legitimate current declaration.
        if not plan_review_record_is_charged_invocation(record):
            continue
        recorded_items = record.get("work_items")
        if isinstance(recorded_items, list):
            for item in recorded_items:
                add(item)
    try:
        plan_path = paths_module().resolve_plan_reference(data, target, plan_rel)
        for item in plan_round_record_module().declared_work_items(plan_review_text(plan_path)):
            add(item)
    except (ValueError, OSError):
        pass
    return items


def plan_review_lineage_members(
    data: dict,
    target: Path,
    plan_rel: str,
    *,
    current_rounds: int | None = None,
    declared_predecessor: str = "",
) -> tuple[list[dict], bool, list[str]]:
    """THE lineage resolver (item 108 WS3): one member set every consumer reads.

    The lineage is the CONNECTED CLOSURE over three edge kinds -- declared predecessors (flag,
    manifest, run metas, round records), `-vN` name shape against existing entries, and shared
    declared work items -- walked backward from `plan_rel` and forward across every reviewed
    reference in the lane, deduped on resolved identity. Advisory chain lines and the (future)
    authoritative budget consume this one output, so a single launch can never record two
    different lineages.

    Truncation is LOUD and the result is a FLOOR (T3.3): a walk cut by a recorded cycle, the
    chain-depth cap or the component cap prints `plan_review_lineage_walk_truncated` and returns
    `truncated=True`, which `plan_review_chain_summary` labels `evidence=floor`. A cut lineage is
    never silently a standalone plan on a fresh budget.

    `current_rounds` merges the caller's known count for the current plan (launch: the same
    `observed_successful_runs` the round ledger prints) with the durable ladder -- whichever
    knows about MORE spend wins, so a fresh worktree's zero cannot mask recorded history.
    `declared_predecessor` seeds the first hop for a successor's first round, when the validated
    flag is not recorded anywhere yet.
    """
    identities: dict[str, str] = {}

    def identity(reference: str) -> str:
        if reference not in identities:
            identities[reference] = plan_review_lineage_identity(data, target, reference)
        return identities[reference]

    start_id = identity(plan_rel)
    universe = plan_review_reviewed_plan_references(data, target)
    if all(identity(reference) != start_id for reference in universe):
        universe.append(plan_rel)

    truncation_reasons: list[str] = []
    binding_sources: list[str] = []

    def note_truncation(reason: str) -> None:
        if reason not in truncation_reasons:
            truncation_reasons.append(reason)

    def note_source(source: str) -> None:
        if source not in binding_sources:
            binding_sources.append(source)

    edges_cache: dict[str, list[tuple[str, str]]] = {}

    def edges_of(reference: str) -> list[tuple[str, str]]:
        key = identity(reference)
        if key not in edges_cache:
            seed = declared_predecessor if key == start_id else ""
            edges_cache[key] = plan_review_predecessor_edges(
                data, target, reference, seed=seed, universe=universe
            )
        return edges_cache[key]

    def walk_back(start: str) -> tuple[list[str], list[str], bool, bool]:
        """Backward closure via union edges: (preorder line, edge kinds used, cyclic, capped).

        DFS with an explicit path stack so a BACK-EDGE is distinguishable from a DIAMOND: two
        routes to one ancestor count it once and cut nothing, while a DECLARED edge pointing
        back into the path is a recorded cycle and flags truncation. A name-shape back-edge is
        skipped silently instead -- it is an inference restating connectivity the walk already
        has (a `-v1`/base pair points at itself in both directions by shape alone), and calling
        that a cycle would label an honest, complete walk a floor.
        """
        order: list[str] = []
        used_sources: list[str] = []
        seen_ids: set[str] = set()
        cyclic = False
        capped = False

        def visit(reference: str, stack_ids: frozenset[str]) -> None:
            nonlocal cyclic, capped
            order.append(reference)
            seen_ids.add(identity(reference))
            if len(stack_ids) >= PLAN_REVIEW_CHAIN_WALK_MAX_DEPTH:
                # Codex R1 P2 (item 108 WS3): a chain of EXACTLY cap depth whose last member
                # has no further unvisited edge is complete, not a floor -- capped only says
                # "there was more beyond the cap". Codex R2 P2: the boundary member's edges
                # still get the CYCLE reading the loop below would have given them -- a
                # declared edge closing back onto the stack at exactly the cap is a recorded
                # cycle, and calling that walk exact would hide it.
                for edge_reference, source in edges_of(reference):
                    edge_id = identity(edge_reference)
                    if edge_id in stack_ids:
                        if source == "declared":
                            cyclic = True
                        continue
                    if edge_id not in seen_ids:
                        capped = True
                return
            for edge_reference, source in edges_of(reference):
                edge_id = identity(edge_reference)
                if edge_id in stack_ids:
                    if source == "declared":
                        cyclic = True
                    continue
                if edge_id in seen_ids:
                    continue
                if source not in used_sources:
                    used_sources.append(source)
                visit(edge_reference, stack_ids | {edge_id})

        visit(start, frozenset({identity(start)}))
        return order, used_sources, cyclic, capped

    chain_line, chain_sources, chain_cyclic, chain_capped = walk_back(plan_rel)
    for source in chain_sources:
        note_source(source)
    if chain_cyclic:
        note_truncation("cycle")
    if chain_capped:
        note_truncation("chain-depth-cap")

    component: dict[str, str] = {}

    def admit_member(reference: str) -> bool:
        key = identity(reference)
        if key in component:
            return True
        if len(component) >= PLAN_REVIEW_CHAIN_WALK_MAX_DEPTH:
            note_truncation("component-cap")
            return False
        component[key] = reference
        return True

    for reference in chain_line:
        admit_member(reference)

    work_items_cache: dict[str, set[str]] = {}

    def work_items_of(reference: str) -> set[str]:
        key = identity(reference)
        if key not in work_items_cache:
            work_items_cache[key] = plan_review_work_items_for_rel(data, target, reference)
        return work_items_cache[key]

    ancestry_cache: dict[str, tuple[list[str], list[str], bool, bool]] = {}

    def ancestry_of(reference: str) -> tuple[list[str], list[str], bool, bool]:
        key = identity(reference)
        if key not in ancestry_cache:
            ancestry_cache[key] = walk_back(reference)
        return ancestry_cache[key]

    # Forward and sideways closure: every reviewed plan whose own ancestry passes through the
    # component, and every reviewed plan sharing a declared work item with a member, joins --
    # and brings its own ancestors with it. Iterated to a fixpoint because each admission can
    # make further candidates reachable. Speculative walks of candidates that never join do NOT
    # taint the result: their cycles and caps describe lineages this plan is not in.
    changed = True
    while changed and "component-cap" not in truncation_reasons:
        changed = False
        for candidate in universe:
            if identity(candidate) in component:
                continue
            line, line_sources, line_cyclic, line_capped = ancestry_of(candidate)
            joined_via = ""
            if any(identity(node) in component for node in line):
                joined_via = "forward"
            else:
                candidate_items = work_items_of(candidate)
                if candidate_items and any(
                    candidate_items & work_items_of(member)
                    for member in list(component.values())
                ):
                    joined_via = "work-item"
            if not joined_via:
                continue
            if joined_via == "work-item":
                note_source("work-item")
            for source in line_sources:
                note_source(source)
            if line_cyclic:
                note_truncation("cycle")
            if line_capped:
                note_truncation("chain-depth-cap")
            for node in line:
                if not admit_member(node):
                    break
            changed = True
            if "component-cap" in truncation_reasons:
                break

    truncated = bool(truncation_reasons)
    if truncated:
        # LOUD, at the resolver itself, so no consumer -- advisory or authoritative -- can
        # inherit a silently cut lineage (T3.3). The summary carries the same fact as
        # `evidence=floor`, so the printed signal and the recorded label cannot disagree.
        print(
            "plan_review_lineage_walk_truncated: "
            f"plan={plan_rel} reason={','.join(truncation_reasons)} "
            f"cap={PLAN_REVIEW_CHAIN_WALK_MAX_DEPTH}; the resolved member set and its counted "
            "rounds are a FLOOR -- deeper members were cut, never granted a fresh budget and "
            "never reported as a standalone plan",
            file=sys.stderr,
        )

    chain_ids = {identity(reference) for reference in chain_line}
    siblings = [
        reference
        for member_id, reference in sorted(component.items())
        if member_id not in chain_ids
    ]
    members: list[dict] = []
    for reference in [*siblings, *reversed(chain_line)]:
        # Codex R3 P2 (item 108 WS3): an admitted reference can still be unresolvable here --
        # a stale plan-root token after a rename or checkout config change. That member is
        # reported as unknown and the walk stays a floor; a crash would take run/finalize
        # down with it.
        try:
            recorded_rounds, rounds_source = plan_review_member_recorded_rounds(
                data, target, reference
            )
        except ValueError:
            recorded_rounds, rounds_source = None, "unresolved"
        if identity(reference) == start_id and current_rounds is not None:
            # MERGE, never REPLACE: the caller's count is authoritative about what THIS
            # invocation knows, but it is derived from lane-local run metas and a fresh worktree
            # has none. Whichever source knows about MORE spend is telling the truth.
            durable = recorded_rounds if recorded_rounds is not None else 0
            if int(current_rounds) >= durable:
                recorded_rounds, rounds_source = int(current_rounds), "launch"
        members.append(
            {
                "plan_path": reference,
                "recorded_rounds": recorded_rounds,
                "rounds_source": rounds_source,
            }
        )
    return members, truncated, binding_sources


def plan_review_chain_members(data: dict, target: Path, plan_rel: str) -> tuple[list[dict], bool]:
    """Every plan in this plan's lineage, current plan last, plus a truncation flag.

    A delegate over THE resolver (item 108 WS3): the members this returns are the members every
    other consumer counts, so the finalize refresh, the merge-time report and any future budget
    can never disagree about what the lineage is.
    """
    members, truncated, _sources = plan_review_lineage_members(data, target, plan_rel)
    return members, truncated


def plan_review_member_round_proof(
    data: dict,
    target: Path,
    plan_rel: str,
    counted: int,
) -> tuple[int, list[str]]:
    """How many of ONE member's counted rounds carry a classification record, and the gaps.

    Proof is per INVOCATION, and only an OBSERVED invocation can be proven: a charged
    `reviewer-invocation` record with `source: run` -- a round this CLI itself launched and
    watched exit -- is proven when some `round-classification` record references it by nonce or
    by log digest. Two exclusions carry the whole property, and each closed a live hole:

    - a classification carrying an `origin` (`pre-record`, `imported-unverified`) proves nothing:
      neither knows the round it names was ever counted by a record of its own;
    - a `source: imported` invocation can never be proven AT ALL, whatever classification points
      at it (WS5 remediation P2). `plan_review_append_import_records` MINTS that invocation on a
      first import, so a second identical `tautline record-plan-review` bound to it and wrote an
      origin-free classification -- and one re-import flipped the basis to verified for a round
      the CLI never observed. Proof that a lane can manufacture by re-running an import is not
      proof.

    The round being finalized right now proves itself the same way every other round does: its
    classification record is appended BEFORE the basis is derived (WS5 remediation P1), so this
    reads it off disk rather than trusting a digest handed in by the writer that has not yet
    persisted anything.

    Every counted round the invocation records cannot account for -- the baseline's pre-record
    floor, a member with no baseline reading at the manifest floor, a successful run meta the
    record never caught -- is reported as a residual GAP, never silently proven.
    """
    module = plan_round_record_module()
    try:
        rounds = plan_review_rounds_dir_for_rel(data, target, plan_rel)
    except ValueError:
        return 0, [
            f"{plan_rel}: unresolvable plan reference, so its {counted} counted round(s) name no "
            "record directory"
        ]
    baseline = module.load_baseline(rounds)
    if baseline is None:
        return 0, [
            f"{plan_rel}: {counted} counted round(s) predate the durable record (no baseline; "
            "this member reads at the manifest floor, which can never be verified)"
        ]
    records = module.load_round_records(rounds)
    # A RETRACTION NAMES A RECORD, NOT A ROUND -- so ordering never has to be trusted.
    #
    # Three rounds walked this seam and each fix opened the next hole. R1 P1: an orphan
    # classification, left by a finalize whose manifest write failed, was read as proof of a
    # round whose blockers were never carried. R2 P2: retracting the round's TARGET poisoned it,
    # so a legitimate retry could never re-prove it. R3 P2: folding by `recorded_at` (second
    # precision) then a random filename suffix does not preserve append order, and in the very
    # failure path this exists for -- classification and correction written back-to-back inside
    # one second -- the correction could sort FIRST and be overwritten, silently reinstating the
    # R1 defect.
    #
    # Ordering was the wrong foundation. A correction now names the RECORD it retracts, by that
    # record's own file identity, which is unique by construction (O_EXCL on a fresh name). A
    # retracted classification is skipped no matter what order it is read in, and a retry's new
    # classification is a DIFFERENT record that nothing retracts, so it proves its round with no
    # ordering rule at all.
    retracted_records: set[str] = set()
    for _path, record in records:
        if record.get("kind") != "correction":
            continue
        corrects = str(record.get("corrects") or "").strip()
        if corrects and corrects != module.CORRECTION_BASELINE_TARGET:
            retracted_records.add(corrects)
    classified_nonces: set[str] = set()
    classified_digests: set[str] = set()
    for path, record in records:
        if record.get("kind") != "round-classification" or record.get("origin"):
            continue
        if Path(path).stem in retracted_records:
            continue
        if record.get("nonce"):
            classified_nonces.add(str(record["nonce"]))
        if record.get("log_sha256"):
            classified_digests.add(str(record["log_sha256"]))
    proven = 0
    gaps: list[str] = []
    for _path, record in records:
        if record.get("kind") != "reviewer-invocation" or record.get("charged") is not True:
            continue
        nonce = str(record.get("nonce") or "")
        digest = str(record.get("log_sha256") or "")
        named = (
            f"{plan_rel} round {str(record.get('declared_round') or '?')} "
            f"(nonce={nonce or 'none'}, log={digest[:12] or 'none'})"
        )
        # Fails CLOSED on an unrecognised source: a record that cannot say it was observed is
        # exactly the record that must not certify anything.
        if str(record.get("source") or "") != "run":
            gaps.append(
                f"{named} is counted and was never observed by this CLI (imported evidence), so "
                "no classification record can prove it"
            )
            continue
        if (nonce and nonce in classified_nonces) or (digest and digest in classified_digests):
            proven += 1
            continue
        gaps.append(f"{named} is counted and never classified")
    proven = min(proven, counted)
    residual = counted - proven - len(gaps)
    if residual > 0:
        gaps.append(
            f"{plan_rel}: {residual} further counted round(s) have no invocation record to "
            "classify (pre-record baseline floor, or a successful run the record missed)"
        )
    return proven, gaps


def plan_review_carried_findings_basis(
    data: dict, target: Path, plan_rel: str
) -> tuple[str, int, int, int, list[str], list[str]]:
    """The capped manifest's carried-findings basis, PROVEN or disclosed unproven (WS5, DF).

    Returns `(basis, counted, proven, member_count, gaps, floors)`. The rounds counted here are
    the rounds THE AUTHORITATIVE RESOLVER counts -- `plan_review_lineage_members`, the one member
    set every budget decision reads -- never a local re-walk (R1 P1 on the plan): a narrower view
    could certify fewer rounds than the cap later counts, and a verified token over a lineage
    nobody else agrees with is worse than the honest `caller-asserted` it would replace.

    Two kinds of unproven, deliberately separate, because they disclose different things:

    - a GAP is a counted round that is named and unproven -- a lane can go and bind it;
    - a FLOOR is a reason `counted` and `proven` are themselves understatements: a truncated walk,
      or a member whose spend cannot be read at all. Its rounds are in NEITHER total, so a
      disclosure that only printed the totals would report the smallest number exactly when the
      lineage is least knowable (WS5 remediation P3). Floors are printed and they block the
      upgrade: an unknown member's rounds can never be shown classified.

    The basis upgrades ONLY when every counted round in the lineage carries a classification
    record and nothing is a floor. Pre-record history and a member reading at the manifest floor
    can never verify either -- neither has an invocation record to classify.
    """
    gaps: list[str] = []
    floors: list[str] = []
    try:
        members, truncated, _sources = plan_review_lineage_members(data, target, plan_rel)
    except (ValueError, OSError):
        return (
            PLAN_REVIEW_CARRIED_FINDINGS_BASIS,
            0,
            0,
            0,
            [f"{plan_rel}: the lineage could not be resolved, so no counted round can be proven"],
            [],
        )
    if truncated:
        floors.append(
            "the lineage walk was truncated, so members beyond the cut are in neither total"
        )
    counted_total = 0
    proven_total = 0
    for member in members:
        reference = str(member.get("plan_path") or "")
        try:
            counted = max(int(member["recorded_rounds"]), 0)
        except (KeyError, TypeError, ValueError):
            floors.append(
                f"{reference}: spend reads "
                f"{str(member.get('rounds_source') or 'unknown')}, so its rounds are in neither "
                "total and none of them can be proven"
            )
            continue
        counted_total += counted
        if not counted:
            continue
        proven, member_gaps = plan_review_member_round_proof(data, target, reference, counted)
        proven_total += proven
        gaps.extend(member_gaps)
    verified = counted_total > 0 and proven_total >= counted_total and not gaps and not floors
    basis = (
        PLAN_REVIEW_CARRIED_FINDINGS_BASIS_VERIFIED
        if verified
        else PLAN_REVIEW_CARRIED_FINDINGS_BASIS
    )
    return basis, counted_total, proven_total, len(members), gaps, floors


def plan_review_basis_detail(reasons: list[str]) -> str:
    """The named reasons, capped at what a lane can actually read, then summarised."""
    named = reasons[:PLAN_REVIEW_BASIS_GAPS_NAMED]
    more = len(reasons) - len(named)
    return "; ".join(named) + (f"; and {more} more" if more > 0 else "")


def plan_review_capped_disclosure_line(
    basis: str,
    counted: int,
    proven: int,
    member_count: int,
    gaps: list[str],
    floors: list[str],
) -> str:
    """What the capped finalize discloses about its carried list -- verified, or the named gap.

    Unproven is NOT merely announced (T5.1): the counted rounds without a classification record
    are named, because a lane can act on `round R2 of <plan>` and can do nothing at all with
    "completeness is not verified". And when the totals themselves are understatements -- an
    unknown member, a cut walk, a classification record that failed to persist -- the line says
    so where it prints them, rather than letting "0 of 0 are NOT verified" read as reassurance.
    """
    if basis == PLAN_REVIEW_CARRIED_FINDINGS_BASIS_VERIFIED:
        return (
            f"plan_review_capped_disclosure: carried_findings_basis={basis} -- all {counted} "
            f"counted round(s) across {member_count} lineage member(s) carry a round-"
            "classification record, so the carried list is complete against every counted round"
        )
    floor_clause = (
        f" (both totals are a FLOOR: {plan_review_basis_detail(floors)})" if floors else ""
    )
    gap_clause = f": {plan_review_basis_detail(gaps)}" if gaps else ""
    return (
        f"plan_review_capped_disclosure: carried_findings_basis={basis} -- the carried list is "
        f"this round's caller classification; {counted - proven} of {counted} counted round(s) "
        f"across {member_count} lineage member(s) are NOT verified"
        f"{floor_clause}{gap_clause}. Bind each named "
        "round with `tautline record-plan-review` (append only) before reading the carried list "
        "as complete"
    )


def plan_review_launch_chain(
    data: dict, target: Path, plan_rel: str, predecessor_rel: str, observed_runs: int
) -> tuple[list[dict], bool]:
    """The lineage as it stands at a launch, with the current plan's spend from the caller.

    At launch the current plan's count is KNOWN -- it is the same `observed_runs` the round
    ledger prints -- so it must never fall through the evidence ladder to `unknown`. The declared
    predecessor may not be recorded anywhere yet, so it seeds the resolver's first hop. Same
    resolver, same members: this wrapper only carries the launch-time knowns.
    """
    members, truncated, _sources = plan_review_lineage_members(
        data,
        target,
        plan_rel,
        current_rounds=int(observed_runs),
        declared_predecessor=predecessor_rel or "",
    )
    return members, truncated










def plan_review_chain_advisory_line(summary: dict, surface: str = "run") -> str:
    """One printed advisory past either line, or '' below both. NEVER a refusal.

    The successor path is the sanctioned exit the round cap names, so chain accounting observes
    it and nothing more: the line states the numbers, states plainly that nothing is blocked, and
    names only the two remedies that genuinely work from here -- the same split the round cap
    names, and the implementation-review focus list.
    """
    over_rounds = summary["cumulative_recorded_rounds"] > PLAN_REVIEW_CHAIN_ADVISORY_ROUNDS
    over_depth = summary["depth"] >= PLAN_REVIEW_CHAIN_ADVISORY_DEPTH
    if not over_rounds and not over_depth:
        return ""
    # Name the line that actually fired. Printing both thresholds and leaving the reader to work
    # out which one this chain crossed is the shape of message people stop reading.
    crossed = []
    if over_rounds:
        crossed.append(
            "cumulative rounds have passed the advisory line of "
            f"{PLAN_REVIEW_CHAIN_ADVISORY_ROUNDS}"
        )
    if over_depth:
        crossed.append(
            f"chain depth has reached the advisory line of {PLAN_REVIEW_CHAIN_ADVISORY_DEPTH}"
        )
    proceeds = "this finalize proceeds" if surface == "finalize" else "this run proceeds"
    return (
        "plan_review_chain_advisory: this succession chain has spent "
        f"{plan_review_chain_total_display(summary)} recorded review round(s) across "
        f"{summary['depth']} chained plan(s); {', and '.join(crossed)}. Nothing is blocked and "
        f"{proceeds}. Remedies that work: decompose the scope into smaller independent "
        "source-of-truth plans and review each one, or carry non-blocking findings into the "
        "implementation review focus list."
    )


def plan_review_lineage_rounds_for_merge(data: dict, target: Path, plan_rel: str) -> dict:
    """Cumulative LINEAGE review rounds for one plan's succession chain, at PR-merge time.

    T4.2 (item 106 WS4). Reuses the existing chain walk (`plan_review_chain_members`) and its
    honesty-marked summary (`plan_review_chain_summary`) -- the same machinery
    `run-plan-review`/`finalize-plan-review` already use for the chain advisory. No new counting
    logic and no new telemetry vocabulary: the approved v1 event codes `plan_review_round` /
    `plan_review_clean` / `plan_review_blocked` already cover round spend and verdict, so
    surfacing their cumulative total per merged PR needs no enum change and no T0 vocabulary
    re-approval gate.
    """
    members, truncated = plan_review_chain_members(data, target, plan_rel)
    summary = plan_review_chain_summary(members, truncated)
    return {
        "plan_rel": plan_rel,
        "depth": summary["depth"],
        "cumulative_recorded_rounds": summary["cumulative_recorded_rounds"],
        "evidence": summary["evidence"],
        "members": members,
    }


def plan_review_lineage_rounds_merge_line(pr_number: str, report: dict) -> str:
    """The one printed line a merged PR owes: how many lineage rounds it cost, honestly marked."""
    total_display = (
        f">={report['cumulative_recorded_rounds']}"
        if report["evidence"] == "floor"
        else str(report["cumulative_recorded_rounds"])
    )
    return (
        "plan_review_lineage_rounds_at_merge: "
        f"pr={pr_number} plan={report['plan_rel']} depth={report['depth']} "
        f"cumulative_recorded_rounds={total_display} evidence={report['evidence']} "
        "(vocabulary: plan_review_round/plan_review_clean/plan_review_blocked)"
    )






# A successor plan named by shape rather than by prose (item 36: no English parsing). Anchored and
# strict: `admin-v2` matches, `admin-v`, `admin-v2b` and `adminv2` do not.
PLAN_REVIEW_SUCCESSOR_STEM_PATTERN = re.compile(r"^(?P<base>.+)-v(?P<number>\d+)$")


def plan_review_lineage_shape_hint(data: dict, target: Path, plan_path: Path) -> str:
    """One advisory line when a `-vN`-shaped plan has a reviewed predecessor but no lineage.

    Adoption pressure, not inference: the hint names the flag and never records anything. Auto-
    recording a guessed predecessor would put an invented fact into an evidence record.
    """
    try:
        plan_rel = plan_root_relative_reference(data, target, plan_path)
    except ValueError:
        return ""
    if plan_review_recorded_predecessor(data, target, plan_rel):
        return ""
    match = PLAN_REVIEW_SUCCESSOR_STEM_PATTERN.match(plan_path.stem)
    if not match:
        return ""
    # Codex R1 P3 (item 108 WS3): the hint names the SAME predecessor the resolver's
    # enumerated inference binds advisorily -- the old v(N-1)/bare-base probe went silent on
    # exactly the lineages the enumeration now finds (admin-v34 -> admin-v1).
    inferred = plan_review_name_shape_predecessor(data, target, plan_rel)
    for candidate_rel in ([inferred] if inferred else []):
        return (
            f"plan_review_lineage_hint: this plan's name has the `-vN` successor shape and "
            f"{candidate_rel} already has recorded review evidence, but no lineage is recorded "
            f"for {plan_rel}; declare it on this plan's next review run with "
            f"`--predecessor {shlex.quote(candidate_rel)}` so the chain's cumulative review spend "
            "is accounted. Nothing is blocked and no lineage was recorded."
        )
    return ""


def plan_review_lineage_errors(
    data: dict, target: Path, plan_path: Path, plan_rel: str, predecessor_arg: Path | None
) -> tuple[list[str], str]:
    """Resolve this plan's lineage, or refuse an explicitly-passed value that cannot be right.

    Succession is NEVER hard-blocked: omitting `--predecessor` behaves exactly as it did before
    chain accounting existed, and every error below fires only on a value the caller passed. The
    recorded lineage is append-once -- a matching flag is a no-op, a conflicting one is refused,
    and nothing here ever edits or retires an evidence record.
    """
    recorded = plan_review_recorded_predecessor(data, target, plan_rel) or ""
    if predecessor_arg is None:
        return [], recorded

    predecessor_path = plan_root_resolve(data, target, predecessor_arg)
    source_root = planning_source_root(data, target)
    if not plan_is_under_a_configured_root(data, target, predecessor_path):
        return (
            [
                f"predecessor plan outside source-of-truth path: {predecessor_path} not under "
                f"{source_root}"
            ],
            "",
        )
    predecessor_rel = plan_root_relative_reference(data, target, predecessor_path)
    if plan_references_match(data, target, predecessor_rel, plan_rel):
        return (
            [f"--predecessor must name a different plan than --plan ('{plan_rel}')"],
            "",
        )
    if recorded and recorded != predecessor_rel:
        return (
            [
                f"--predecessor '{predecessor_rel}' conflicts with the lineage already recorded "
                f"for this plan ('{recorded}'); review evidence is never edited or retired, so "
                "the recorded lineage stands: rerun without --predecessor"
            ],
            "",
        )
    if not recorded:
        manifest_rel = path_relative_to_target(
            target, plan_review_manifest_path(data, target, predecessor_path)
        )
        runs_rel = path_relative_to_target(
            target, configured_path(target, data["laneState"]["runsDir"]) / "plan-review"
        )
        # Codex R3 P2 (item 108 WS3): the validator accepts the SAME evidence set the
        # resolver counts -- manifest, run metas, or the durable round record. A lane whose
        # .ai-runs was pruned before finalization still holds record-backed spend, and
        # refusing its explicit flag while the resolver would count that spend is a
        # contradiction between two readers of one truth.
        if not plan_review_reference_has_review_evidence(data, target, predecessor_rel):
            return (
                [
                    f"--predecessor '{predecessor_rel}' has no recorded plan-review evidence; "
                    f"checked for a manifest at '{manifest_rel}', for successful run metas "
                    f"keyed on '{predecessor_rel}' under '{runs_rel}', and for durable round "
                    "records. Remedies: correct the path, "
                    "or omit --predecessor when the predecessor genuinely has no recorded reviews "
                    "(then there is no chain spend to account for)"
                ],
                "",
            )
    return [], predecessor_rel


def plan_review_finalizable_run_meta(
    data: dict, target: Path, plan_path: Path, plan_rel: str, plan_hash: str
) -> Path | None:
    """An unbound successful run whose content hash matches the CURRENT plan, if one exists.

    This is the state where the hard-cap refusal must NOT say "split": finalize-plan-review binds
    this run today, so telling the lane to decompose sends it away from the working exit.
    """
    manifest = load_plan_review_manifest(plan_review_manifest_path(data, target, plan_path))
    for meta_path, meta in plan_review_successful_run_meta_records(data, target, plan_rel):
        if str(meta.get("plan_content_sha256") or "") != plan_hash:
            continue
        if plan_review_run_meta_matches_manifest(target, meta_path, manifest):
            continue
        # A run the manifest already accounts for is orphaned; pointing the lane at it would send
        # it backwards to re-bind superseded evidence. Order by TIME, never by the declared label
        # (0.22.0 implementation review R2 P2): this release exists because labels do not track
        # reality, and in a relabelled lane a current-hash run recorded after an R3 manifest can
        # still be called `R1`. Discarding it on label order would print "split" while
        # finalize-plan-review would happily bind it. Unparseable timestamps fail CLOSED to the
        # pre-existing split/finalize wording rather than to a possibly stale candidate.
        if manifest:
            finished_at = plan_review_parse_timestamp(meta.get("finished_at"))
            recorded_at = plan_review_parse_timestamp(manifest.get("timestamp"))
            # `now_iso()` has SECOND resolution, so a run finishing either side of a finalize can
            # share the manifest's stamp, and a tie cannot be ordered from the evidence. Both
            # readings fail somewhere: calling a tie PENDING can surface an already-superseded run,
            # and the edit guard then refuses the normal follow-up edit that addresses a blocked
            # manifest's findings; calling it SUPERSEDED can send an operator toward a split when
            # finalize would have worked. The blocking failure is worse, so ties stay superseded.
            # A tie-break, not a fix -- sub-second stamps are the real answer, filed as item 35.
            if finished_at is None or recorded_at is None or finished_at <= recorded_at:
                continue
        return meta_path
    return None




def plan_review_finalize_command(target: Path, plan_rel: str, meta_path: Path) -> str:
    """The runnable finalize invocation for an unbound run -- a path alone is not an action.

    Past the convergence target, finalize itself requires a recorded exception note, so a command
    printed without the flag would fail before binding anything -- an "actionable" remedy that is
    not runnable is the failure class this ladder exists to remove (0.22.0 implementation review
    R1 P2). The round the exception is attached to is the run's OWN round, read from its meta.
    """
    meta = {}
    try:
        loaded = json.loads(meta_path.read_text(encoding="utf-8"))
        if isinstance(loaded, dict):
            meta = loaded
    except (OSError, json.JSONDecodeError):
        meta = {}
    log_rel = str(meta.get("log_path") or "")
    if not log_rel:
        log_rel = path_relative_to_target(target, meta_path).removesuffix(".meta.json")
    review_round = str(meta.get("round") or "")
    round_number = plan_review_round_number(review_round)
    exception_flag = ""
    if round_number is not None and round_number > PLAN_REVIEW_TARGET_ROUNDS:
        recorded = str(meta.get("exception_reason") or "").strip()
        note_hint = shlex.quote(recorded or "<reason this round was needed>")
        exception_flag = f" --exception-note {note_hint}"
    return (
        f"tautline finalize-plan-review --target {guard_target_argument(target)} "
        f"--plan {shlex.quote(plan_rel)} --log {shlex.quote(log_rel)} "
        f"--round {shlex.quote(review_round)} --verdict <clean|clean-with-deferrals|blocked> "
        f"--unresolved-critical-count <n> --unresolved-p1-count <n>{exception_flag}"
    )


def plan_review_manifest_is_clean_for_hash(manifest: dict | None, plan_hash: str) -> bool:
    if not manifest:
        return False
    verdict = str(manifest.get("verdict") or "").strip().lower()
    if verdict not in PLAN_REVIEW_ALLOWED_VERDICTS:
        return False
    if str(manifest.get("plan_content_sha256") or "") != plan_hash:
        return False
    try:
        critical = int(manifest.get("unresolved_critical_count", 0))
        p1 = int(manifest.get("unresolved_p1_count", 0))
    except (TypeError, ValueError):
        return False
    return critical == 0 and p1 == 0


def plan_review_carried_findings(manifest: dict | None) -> list[dict]:
    """The Critical/P1 findings a capped manifest carried into implementation review.

    Reads the record rather than re-deriving severity from prose: `finalize-plan-review` stamped
    `status: carried` on exactly the findings it carried, at the severity the classification
    recorded. An empty list from a capped manifest is a defect the precheck refuses, not a quiet
    "nothing to do" -- see `plan_review_capped_manifest_errors`.
    """
    if not manifest:
        return []
    findings = manifest.get("classified_findings")
    if not isinstance(findings, list):
        return []
    return [
        item
        for item in findings
        if isinstance(item, dict)
        and str(item.get("status") or "").strip().lower() == PLAN_REVIEW_CARRIED_STATUS
    ]


def plan_review_capped_manifest_errors(manifest: dict) -> list[str]:
    """What a `capped-with-open-findings` manifest must prove before finalization accepts it.

    The release valve is only safe because the findings it releases past are RECORDED as binding
    obligations. Without this check the new verdict would be strictly weaker than the refusal it
    replaces: a lane could write `capped-with-open-findings` over any blocked round and walk. The
    predicate is mechanical -- every unresolved Critical/P1 in the record must carry the carried
    marker -- so it needs no judgment and cannot be argued with.
    """
    errors: list[str] = []
    findings = manifest.get("classified_findings")
    if not isinstance(findings, list):
        return [
            f"plan review manifest verdict {PLAN_REVIEW_CAPPED_VERDICT} requires "
            "classified_findings evidence"
        ]
    # The reviewer's own word must survive, and must still be a REFUSAL (Codex remediation-round
    # P2). `asserted_verdict` is the entire reason the record keeps two verdicts: the derived one
    # says the budget ran out, the asserted one says what the reviewer actually concluded, and the
    # pair is what lets a capped record be reconciled against the log that produced it. Nothing
    # required the field or constrained its value, so deleting it or rewriting it to `clean` left a
    # record claiming the final review found nothing while carrying binding Criticals -- the audit
    # trail testifying against itself. A capped finalize is only ever derived from a round that
    # asserted blockers, so `clean`/`clean-with-deferrals` there is provably false rather than
    # merely unverified.
    asserted = str(manifest.get("asserted_verdict") or "").strip().lower()
    if not asserted:
        errors.append(
            f"plan review manifest verdict {PLAN_REVIEW_CAPPED_VERDICT} requires "
            '"asserted_verdict" -- the reviewer\'s own verdict is what makes a capped record '
            "reconcilable against its log, so a capped manifest without it cannot be audited"
        )
    elif asserted != PLAN_REVIEW_BLOCKED_VERDICT:
        # EQUALS `blocked`, not merely "is not clean" (Codex round 4 P2). Both clean verdicts are
        # refused before the manifest is written, so `blocked` is the ONLY value a legitimate
        # capped finalize can have asserted -- which makes an allowlist of one the honest check.
        # Rejecting just the clean values left every other string passing, so a hand-edited
        # `"banana"` satisfied the guard while destroying exactly the reconcilability the field
        # exists to provide. A validator that enumerates what it forbids is only as good as that
        # enumeration; this one now enumerates what it permits.
        errors.append(
            f"plan review manifest verdict {PLAN_REVIEW_CAPPED_VERDICT} records "
            f'"asserted_verdict": {asserted!r}, but a capped finalize is derived only from a '
            f"round that asserted {PLAN_REVIEW_BLOCKED_VERDICT!r}; any other value cannot be "
            "reconciled against the log that produced it"
        )
    records = [item for item in findings if isinstance(item, dict)]
    unresolved_blockers = [
        item
        for item in records
        if str(item.get("severity", item.get("priority", ""))).lower() in BLOCKER_SEVERITIES
        and str(item.get("status") or "").lower() not in plan_review_resolved_statuses()
    ]
    if not unresolved_blockers:
        errors.append(
            f"plan review manifest verdict {PLAN_REVIEW_CAPPED_VERDICT} records no unresolved "
            "Critical/P1 finding; a capped finalize exists to CARRY open blockers, so a record "
            "with none belongs at verdict clean or clean-with-deferrals"
        )
    for item in unresolved_blockers:
        label = str(item.get("id") or item.get("title") or item.get("summary") or "finding")[:80]
        if str(item.get("status") or "").lower() != PLAN_REVIEW_CARRIED_STATUS:
            errors.append(
                f"unresolved {str(item.get('severity', item.get('priority', ''))).lower()} finding "
                f"{label!r} in a {PLAN_REVIEW_CAPPED_VERDICT} manifest must carry "
                f'"status": "{PLAN_REVIEW_CARRIED_STATUS}"'
            )
        if item.get("binding") is not True:
            errors.append(
                f"carried finding {label!r} must carry \"binding\": true -- a carried Critical/P1 "
                "is a binding implementation-review focus item, never an advisory note"
            )
        # A carried finding with no identity is INVISIBLE, not merely untidy (Codex
        # remediation-round P2). `plan_review_carried_focus_items` keys on
        # `focus_id or id` and skips anything with neither, so stripping the generated
        # `focus_id` from an id-less blocker leaves a record that still satisfies the
        # status and binding checks above while every downstream report -- the finalize
        # print, the push gate, the implementation-review focus list -- omits it. The
        # obligation would be recorded and unreportable at the same time, which is worse
        # than an obligation that was never carried, because the manifest testifies that
        # it was.
        if not str(item.get("focus_id") or item.get("id") or "").strip():
            errors.append(
                f"carried finding {label!r} must carry a non-empty \"focus_id\" (or \"id\") -- "
                "carried findings are reported by that key, so one without it is recorded as "
                "binding and then omitted from every downstream report"
            )
    return errors


def plan_review_finalize_event_severity(
    *, capped: bool, convergence_errors: bool, blockers: int, wrapper_exit_code: int
) -> str:
    """The severity the `plan_review_finalized` event carries.

    `warn` on the capped path, and the distinction is the whole release valve in one word. The
    command exits 0 and the lane is released into implementation, so recording `block` beside a
    successful exit would make every status surface say the lane is stuck at the exact moment the
    gate let it out. It is not `ok` either: real Critical/P1 findings are open and binding on
    implementation review, and calling that clean would be the ledger lying in the cheaper
    direction.

    Extracted rather than inlined so the choice is testable without writing an event: the event
    file resolves against a lane-relative state dir, which no test can assert on without
    contaminating every other lane sharing it.

    The wrapper exit code is checked BEFORE the capped branch (Codex R1 P2). A wrapper that exited
    nonzero can still produce enough output to reach finalization; the command then returns that
    nonzero code and the precheck rejects the manifest, so the lane is NOT released and an event
    saying `warn` would be describing a release that did not happen.
    """
    if capped and wrapper_exit_code == 0:
        return "warn"
    if not convergence_errors and not blockers and wrapper_exit_code == 0:
        return "ok"
    return "block"


def plan_review_focus_key(plan_rel: str, focus_id: str) -> str:
    """The identity a carried finding is REPORTED under. Plan-qualified on purpose: two plans in
    one lane can both carry a finding called `carried-1`.

    REPORT-ONLY, and this key is currently only ever printed. An earlier draft of this release
    also shipped a disposition flag (`<focus-key>=<what review found>`) that discharged an
    obligation, and this docstring used to describe percent-encoding `=` in both halves so a plan
    path or finding id containing `=` could not truncate the key. That gate was removed before
    release (see `plan_review_carried_focus_items`), and the encoding it justified was removed with
    it -- so the paragraph was describing behaviour this function does not have. It is restated
    here as history rather than deleted, because the encoding becomes REQUIRED again the moment a
    disposition flag returns: reinstate it in the same commit as the flag, not after.
    """
    return f"{plan_rel}::{focus_id}"


def plan_review_carried_focus_items(data: dict, target: Path) -> list[dict]:
    """The BINDING implementation-review focus items this lane owes, oldest manifest first.

    Sourced from capped plan-review manifests recorded by a trusted writer. An untrusted import
    can neither create this verdict (it is absent from every `--verdict` choice list) nor be
    believed about it here.

    NOT SCOPED TO A BRANCH LINEAGE, and that is a KNOWN OPEN GAP, not a solved problem. This
    docstring previously claimed the glob was scoped to the branch's lineage and credited a Codex
    confirming-round P1 for it. No such filter exists here or in any caller -- the claim was
    written against a draft that was removed, and it survived the removal. Restating it honestly:

    Every capped manifest in the lane is listed on every call, on every branch, indefinitely. The
    hazard the old text described is real -- a repo accumulates capped manifests for unrelated
    plans -- but the reason it is not a DEFECT today is that this list is REPORT-ONLY: nothing
    refuses on it, so plan A's implementation is never blocked by plan B's findings, and there is
    no disposition mechanism that could discharge plan B's binding Critical early. The cost is
    that the report degrades toward unconditional noise as manifests accumulate, which is how a
    report gets ignored.

    Scoping needs a durable plan-to-implementation lineage this codebase does not have yet; that
    lineage is the follow-up work. Whichever change first makes this list GATE anything must add
    the scope in the same commit -- an unscoped glob behind a refusal is the failure the removed
    draft actually had.
    """
    items: list[dict] = []
    reviews_root = planning_source_root(data, target) / ".plan-reviews"
    if not reviews_root.is_dir():
        return items
    for manifest_path in sorted(reviews_root.glob("*.json")):
        manifest = load_plan_review_manifest(manifest_path)
        if not manifest:
            continue
        if str(manifest.get("verdict") or "").strip().lower() != PLAN_REVIEW_CAPPED_VERDICT:
            continue
        if str(manifest.get("recorded_by") or "") not in PLAN_REVIEW_TRUSTED_RECORDERS:
            continue
        plan_rel = str(manifest.get("plan_path") or manifest_path.stem)
        for finding in plan_review_carried_findings(manifest):
            if finding.get("binding") is not True:
                continue
            focus_id = str(finding.get("focus_id") or finding.get("id") or "").strip()
            if not focus_id:
                continue
            key = plan_review_focus_key(plan_rel, focus_id)
            items.append(
                {
                    "focus_key": key,
                    "focus_id": focus_id,
                    "plan": plan_rel,
                    "severity": str(
                        finding.get("severity", finding.get("priority", "unknown"))
                    ).lower(),
                    "summary": " ".join(str(finding.get("summary") or "").split())[:240],
                    "acceptance_criterion": str(finding.get("acceptance_criterion") or ""),
                    "manifest": path_relative_to_target(target, manifest_path),
                    "binding": True,
                }
            )
    return items


def plan_review_carried_focus_lines(items: list[dict]) -> list[str]:
    """One printable line per binding focus item, in the machine-greppable house shape."""
    return [
        f"implementation_review_focus: [{item['severity'].upper()}] {item['focus_key']} -- "
        f"{item['summary'] or 'no summary recorded'} (BINDING; re-test against the code)"
        for item in items
    ]


def plan_review_carry_blockers(findings: list[dict], effective_round: int) -> list[dict]:
    """Stamp every still-unresolved Critical/P1 as CARRIED into implementation review.

    Severity is untouched, deliberately. The temptation at a cap is to relabel blockers down until
    the gate is satisfied -- `status: deferred` was already the cheapest escape on this record --
    and a valve that quietly downgrades findings buys convergence with the honesty of the ledger.
    Carrying changes the MEDIUM a finding gets settled in (prose -> code), never its severity.

    `binding: True` is what distinguishes these from the advisory transfer the round-3 message has
    always offered. `plan_review_carried_focus_items` reads that flag and REPORTS them at
    `plan-finalization-precheck`, `review-evidence-check` and `finalize-implementation-review`.
    Recorded here, enforced by the follow-up: recording it is what makes the obligation exist.

    Findings already carrying a resolving status pass through untouched: `finding_counts` does not
    count them, so carrying them would invent obligations the round did not record.
    """
    carried: list[dict] = []
    sequence = 0
    # Codex R1 P2: `id` is not unique in the classified-findings contract, and the implementation
    # finalizer keys outstanding obligations by focus key in a SET. Two Critical findings sharing
    # an id would collapse into one obligation, so one disposition would discharge both -- the
    # exact "one routed finding masks the rest" shape the contract already refuses elsewhere.
    used_focus_ids: set[str] = set()
    for item in findings:
        if not isinstance(item, dict):
            carried.append(item)
            continue
        severity = str(item.get("severity", item.get("priority", ""))).lower()
        status = str(item.get("status") or "").lower()
        if severity not in BLOCKER_SEVERITIES or status in plan_review_resolved_statuses():
            carried.append(item)
            continue
        sequence += 1
        record = dict(item)
        record["status"] = PLAN_REVIEW_CARRIED_STATUS
        record["carried_at_round"] = int(effective_round)
        record["carried_to"] = PLAN_REVIEW_CARRY_TARGET
        record["binding"] = True
        # A finding that never carried an id still has to be dispositionable, and the disposition
        # is typed by a human at a shell. Positional ids are stable for a manifest that is written
        # once and never rewritten, which is what this one is.
        focus_id = str(item.get("id") or "").strip() or f"carried-{sequence}"
        if focus_id in used_focus_ids:
            # THE DISAMBIGUATOR MUST ITSELF BE CHECKED. The suffixed form was previously trusted
            # without re-testing it, so it could collide with an id a finding already SUPPLIED:
            # ids `R1#3`, `R1`, `R1` gave `R1#3`, `R1`, and then `R1#3` again -- two carried
            # blockers sharing one focus key. Downstream keys obligations by that key in a set, so
            # the pair collapses into a single obligation and one disposition discharges both.
            # That is the binding-ness of carried findings failing quietly, which is the single
            # property the release valve rests on, so the uniquifier cannot be the thing that
            # takes it away. Bounded: `attempt` strictly increases and the set is finite.
            attempt = sequence
            candidate = f"{focus_id}#{attempt}"
            while candidate in used_focus_ids:
                attempt += 1
                candidate = f"{focus_id}#{attempt}"
            focus_id = candidate
        used_focus_ids.add(focus_id)
        record["focus_id"] = focus_id
        carried.append(record)
    return carried


def plan_review_manifest_is_capped_for_hash(manifest: dict | None, plan_hash: str) -> bool:
    """True when the bound evidence is a capped finalize for the CURRENT plan content.

    Capped evidence is finalizable evidence: `plan_finalization_precheck_errors` accepts it, so
    every gate that asks "can this lane still get out of here?" must answer yes for it. Answering
    no would leave the lane holding a successful finalize that the next gate calls unusable, which
    is the deadlock shape one step downstream.
    """
    if not manifest:
        return False
    if str(manifest.get("verdict") or "").strip().lower() != PLAN_REVIEW_CAPPED_VERDICT:
        return False
    if str(manifest.get("plan_content_sha256") or "") != plan_hash:
        return False
    return bool(plan_review_carried_findings(manifest))


def plan_review_bound_evidence_is_unfinalizable(manifest: dict | None, plan_hash: str) -> bool:
    """True when the bound evidence cannot be finalized against the CURRENT plan.

    This is the predicate the hard-cap REMEDY must be chosen by. Blocker counts alone are not
    enough: plan-finalization-precheck rejects a manifest whose plan_content_sha256 has moved, so
    evidence that is clean but STALE cannot be finalized either. Choosing on counts alone would
    tell the operator to "finalize the existing review evidence" in a state where finalization
    provably fails and the cap forbids another round -- a dead end, which is exactly what this
    ladder exists to remove. Stale-clean evidence therefore takes the mandatory split, like any
    other state with no usable evidence for the plan in hand.

    Capped-for-hash evidence counts as finalizable (D2). It IS finalized -- the whole point of the
    release valve -- so a refusal that told this lane to split would be prescribing a fresh budget
    to a lane that already has its exit in hand.
    """
    if plan_review_manifest_is_capped_for_hash(manifest, plan_hash):
        return False
    return not plan_review_manifest_is_clean_for_hash(manifest, plan_hash)


def plan_review_run_meta_matches_manifest(target: Path, meta_path: Path, manifest: dict | None) -> bool:
    if not manifest:
        return False
    recorded = str(manifest.get("review_run_meta_path") or "").strip()
    if not recorded:
        return False
    try:
        recorded_path = cli_path(target, recorded).resolve(strict=False)
    except (OSError, RuntimeError):
        return False
    return recorded_path == meta_path.resolve(strict=False)






def plan_review_manifest_has_unresolved_blockers(manifest: dict | None) -> bool:
    """True when the bound evidence is missing, blocked, or still carries Critical/P1 findings."""
    if not manifest:
        return True
    if str(manifest.get("verdict") or "").strip().lower() not in PLAN_REVIEW_ALLOWED_VERDICTS:
        return True
    try:
        critical = int(manifest.get("unresolved_critical_count", 0))
        p1 = int(manifest.get("unresolved_p1_count", 0))
    except (TypeError, ValueError):
        return True
    return plan_review_blocker_total(critical, p1) > 0


def plan_review_self_authorized_reason(
    data: dict,
    target: Path,
    plan_path: Path,
    plan_rel: str,
    plan_hash: str,
) -> str:
    """Reason a past-target round self-authorizes without an explicit note, else ''.

    (a) convergence round: the bound manifest is blocked and the plan has changed since it was
        bound -- the fixes landed, so the evidence must be rebound against the fixed plan.
    (b) rebinding round: a successful run was voided by a plan edit before it could be finalized,
        so it can never be finalized and refusing here would be a dead end.

    A run that was finalized and later SUPERSEDED by another round is neither: the manifest binds
    one round at a time, so earlier rounds' metas are orphaned by design. Counting those as voided
    runs would make (b) self-satisfying -- after any clean convergence, one plan edit would
    self-authorize rounds 3-4 with a reason no human ever gave. When neither state is proven this
    returns '', and the round requires an explicit --exception-note.
    """
    manifest = load_plan_review_manifest(plan_review_manifest_path(data, target, plan_path))
    if manifest:
        bound_hash = str(manifest.get("plan_content_sha256") or "")
        moved = bool(bound_hash) and bound_hash != plan_hash
        if moved and plan_review_manifest_has_unresolved_blockers(manifest):
            return "blockers addressed after final bound round"
    for meta_path, meta in plan_review_successful_run_meta_records(data, target, plan_rel):
        if str(meta.get("plan_content_sha256") or "") == plan_hash:
            continue
        if plan_review_run_meta_matches_manifest(target, meta_path, manifest):
            continue
        if plan_review_run_meta_superseded_by_manifest(meta, manifest):
            continue
        return "rebinding round after a voided run"
    return ""


def plan_review_sha_stale_at_cap(
    data: dict, target: Path, plan_path: Path, plan_rel: str, plan_hash: str
) -> bool:
    """True when the capped review evidence can never be finalized against the CURRENT plan.

    All successful runs at/past the convergence target recorded a different content hash and no
    clean manifest binds the current hash: run-again is refused by the cap and finalize is refused
    by the hash check, so the only sanctioned exit is the successor-plan path.
    """
    records = plan_review_successful_run_meta_records(data, target, plan_rel)
    # Codex R1 P2 (item 108 WS2): a fresh worktree has no lane metas, but the durable record
    # still knows the spend -- this routing must follow the same count the record-backed cap
    # enforces, or a lane at a record-spent cap is told to carry findings into implementation
    # while every recorded review is stale and the next run is refused.
    recorded_spend, _spend_source = plan_review_member_spend(data, target, plan_rel)
    spent = max(len(records), recorded_spend or 0)
    if spent < PLAN_REVIEW_TARGET_ROUNDS:
        return False
    manifest = load_plan_review_manifest(plan_review_manifest_path(data, target, plan_path))
    if plan_review_manifest_is_clean_for_hash(manifest, plan_hash):
        return False
    # Successor is the sanctioned exit ONLY when run-plan-review would refuse the NEXT round --
    # so mirror plan_review_round_cap_errors exactly rather than approximate it.
    #
    # The next round is `len(records) + 1`, the CHEAPEST legal one. This supersedes the 0.10.6
    # Codex R2 rule that used the highest declared round instead of the record count, because the
    # budget is now counted in INVOCATIONS (item 24: plan-review round advance gap): the gate
    # takes max(declared, observed + 1), and a caller may declare any label it likes, so the
    # smallest round it can attempt is bounded only by what it has already spent. Keeping the
    # declared term would call a lane holding one successful run labelled `R4` a successor-only
    # dead end while three invocations remain. Same-round reruns DO count now -- each one consumed
    # a reviewer -- which is the point of the change, not an oversight.
    #
    # That round is accepted iff it is within the hard cap AND (within the target budget, or
    # self-authorized -- a blocked bound round the fixes moved past, or a voided run to rebind,
    # which run_plan_review passes as the exception_reason that clears the target cap). If a round
    # is accepted, telling the operator to split the plan would contradict the gate; only when none
    # is left is it a genuine dead end (a clean bound round the plan then edited, or the hard cap
    # truly spent).
    next_round = spent + 1
    # run_plan_review runs BOTH cap gates and a run needs both to pass. Past this point we are
    # already past the runtime cap's COUNT-based target (len(records) >= TARGET) and not clean,
    # and that gate clears only on self-authorization -- so a within-target round NUMBER does not
    # help; the run is accepted iff it is within the hard cap AND self-authorized (0.10.7 Codex
    # R1). Same-round reruns can't spoof the hard cap because next_round is the record count plus
    # one, so relabelling buys nothing.
    next_round_accepted = (
        next_round <= PLAN_REVIEW_HARD_CAP_ROUNDS
        and bool(plan_review_self_authorized_reason(data, target, plan_path, plan_rel, plan_hash))
    )
    if next_round_accepted:
        return False
    # Codex R2 P2 (item 108 WS2): the staleness scan must see the DURABLE invocation hashes
    # too. With record-backed spend and an empty lane (fresh worktree), a metas-only scan calls
    # evidence for the CURRENT hash stale and routes to a successor plan the cap does not
    # require. Union both sources; charged invocation records carry plan_content_sha256.
    observed_hashes = {str(meta.get("plan_content_sha256") or "") for _, meta in records}
    try:
        rounds = plan_review_rounds_dir_for_rel(data, target, plan_rel)
        module = plan_round_record_module()
        for _record_path, record in module.load_round_records(rounds):
            if record.get("kind") != "reviewer-invocation" or not record.get("charged"):
                continue
            observed_hashes.add(str(record.get("plan_content_sha256") or ""))
    except ValueError:
        pass
    # Codex R3 P2 (item 108 WS2): the manifest is the THIRD and last evidence surface. A
    # baselineless member at the manifest-floor cap in a fresh checkout has neither metas nor
    # records -- but a manifest bound to the CURRENT hash (any verdict: the valve finalizes
    # capped over a blocked one) is not stale evidence, and routing it to a successor plan is
    # the budget-refill exit this program retires. Metas, records, manifest: the enumeration
    # is complete, there is no fourth surface.
    if manifest:
        observed_hashes.add(str(manifest.get("plan_content_sha256") or ""))
    observed_hashes.discard("")
    return plan_hash not in observed_hashes




def plan_review_pending_block_reason(data: dict, target: Path, plan_path: Path) -> str | None:
    """Reason to block an edit of a reviewed plan, or None when the edit is safe.

    Fires only in the window between a successful plan-review run and its finalize: the run
    recorded exactly the current content hash and no manifest binds it yet. Editing the plan in
    that window permanently voids the run against the two-round cap (the sha-deadlock incident),
    so the guard demands finalize-first. Finalized plans, fresh plans, and already-voided runs
    (recorded hash differs from current content) never block.
    """
    if not plan_path.exists() or plan_path.suffix.lower() != ".md":
        return None
    resolved = plan_path.resolve(strict=False)
    # Item 59 W3: converge the spelling. This site used `not in resolved.parents` where the other
    # twelve used `path_is_under`, so it answered a subtly different question (a plan sitting AT the
    # root would fail here and pass there) on top of asking only about the lane.
    if not plan_is_under_a_configured_root(data, target, resolved):
        return None
    if ".plan-reviews" in resolved.parts:
        return None
    try:
        plan_rel = plan_root_relative_reference(data, target, plan_path)
    except ValueError:
        return None
    plan_hash = plan_content_sha256(plan_path)
    manifest = load_plan_review_manifest(plan_review_manifest_path(data, target, plan_path))
    # A plan whose CURRENT content is already bound by a clean manifest is finalized: an extra
    # later run for that same hash cannot create the deadlock this guard prevents (finalize
    # already succeeded), so ordinary edits must not block on it (0.10.5 Codex R2).
    if plan_review_manifest_is_clean_for_hash(manifest, plan_hash):
        return None
    # ONE predicate answers "is a successful run for the current content still unbound?", shared
    # with the hard-cap refusal so the two can never disagree. It orders by time, not by declared
    # round label: in a relabelled lane -- the lane 0.22.0 exists for -- a run recorded after a
    # later manifest can still be called `R1`, and the old label comparison discarded it here, so
    # an edit was allowed to void the only run the operator could still finalize (item 31: label
    # trust in the remaining plan-review call sites). A run the manifest genuinely superseded is
    # still exempt: blocking on one would be a false block on a finalized plan.
    pending_meta = plan_review_finalizable_run_meta(data, target, plan_path, plan_rel, plan_hash)
    if pending_meta is None:
        return None
    pending = [pending_meta]
    return (
        "Edit blocked by Minervit plan-review guard. A successful plan-review run for "
        f"{plan_rel} is awaiting finalize-plan-review "
        f"({path_relative_to_target(target, pending[0])}). "
        "Inspect/classify that run's log and bind it with `tautline finalize-plan-review` "
        "first; editing the reviewed plan now would permanently void the run against the "
        "two-round cap."
    )


def plan_review_launcher_handshake_present() -> bool:
    """True when this wrapper was spawned BY `run-plan-review` rather than invoked directly.

    Read through `resolve_env` rather than `os.environ`: it already prefers the TAUTLINE_ alias
    over the MINERVIT_ name and treats a blank value as unset, so a stale `TAUTLINE_...=` in a
    shell cannot blank out a working marker. A hand-rolled alias check here would be a second,
    drifting copy of that rule -- which is what `test_no_shipped_source_bypasses_the_resolver`
    exists to prevent, and it caught this exact line.
    """
    return bool(util_module().resolve_env(PLAN_REVIEW_LAUNCHER_HANDSHAKE_ENV).strip())


def plan_review_inflight_lease_path(runs_dir: Path, plan_hash: str) -> Path:
    return runs_dir / f"inflight-{plan_hash}.lease.json"


# How long after creation an unparseable lease body is still assumed to be a write in progress
# rather than garbage. Generous on purpose: the cost of waiting is one retry, and the cost of
# guessing wrong is two reviewers on one plan -- the exact failure the lease exists to prevent.
PLAN_REVIEW_LEASE_WRITE_WINDOW_SECONDS = 10.0


def plan_review_unlink_if_inode(lease_path: Path, expected_ino: int | None) -> bool:
    """Unlink `lease_path` only while it is still the SAME FILE we decided about. True if removed.

    `os.stat()` then `unlink()` is two operations on a NAME, and between them another launcher can
    delete that inode and create its own fresh lease at the same path -- so the unlink removes the
    new holder's lease and both rounds proceed unprotected. Codex R4 P2. Re-opening and comparing
    st_ino narrows that to the interval between fstat and unlink, and the open pins the inode we
    checked so a replacement cannot be mistaken for it.

    This is a narrowing, not an elimination: POSIX has no unlink-by-descriptor. A fully race-free
    release needs an advisory lock held across the round, which is a larger change than this one.
    """
    if expected_ino is None:
        return False
    try:
        fd = os.open(lease_path, os.O_RDONLY)
    except OSError:
        return False
    try:
        if os.fstat(fd).st_ino != expected_ino:
            return False
        try:
            lease_path.unlink()
        except (FileNotFoundError, OSError):
            return False
        return True
    finally:
        os.close(fd)


def plan_review_release_inflight_lease(lease_path: Path) -> bool:
    """Unlink `lease_path` only while it still names THIS process's lease. True when released.

    Ownership is decided by the recorded pid and hostname, which is what the acquire path writes
    and what the reclaim path reads -- one notion of "mine", not two. A lease we cannot read is
    not ours to delete either: something rewrote it.
    """
    try:
        observed = os.stat(lease_path)
        lease = json.loads(lease_path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return False
    if not isinstance(lease, dict):
        return False
    if lease.get("pid") != os.getpid() or str(lease.get("hostname") or "") != socket.gethostname():
        return False
    return plan_review_unlink_if_inode(lease_path, observed.st_ino)


def plan_review_inflight_lease_is_live(lease: dict) -> bool:
    """True when the recorded launcher is still running.

    Same-host: pid liveness. Cross-host the pid is unverifiable, so fall back to a TTL on
    started_at -- failing open there would re-create the double-launch this lease stops.
    """
    if not isinstance(lease, dict):
        return False
    try:
        pid = int(lease.get("pid"))
    except (TypeError, ValueError):
        return False
    # Codex R2 P2. `os.kill(0, 0)` signals the caller's whole PROCESS GROUP and negative pids
    # address a group too, so a malformed lease recording pid 0 or -1 would probe something that
    # always exists and read as live FOREVER -- a permanent lockout of that plan hash, with no
    # process that could ever die to clear it. A pid that cannot identify a launcher is not
    # evidence of one.
    if pid <= 0:
        return False
    if str(lease.get("hostname") or "") == socket.gethostname():
        try:
            os.kill(pid, 0)
        except ProcessLookupError:
            return False
        except PermissionError:
            # Someone else's process holds that pid. We cannot signal it, so fall through to the
            # TTL below rather than trusting it forever.
            return plan_review_inflight_lease_within_ttl(lease)
        # A PID THAT EXISTS IS NOT NECESSARILY THE ONE THAT WROTE THIS. If a launcher crashes and
        # the OS later reuses its pid for something unrelated, `kill(pid, 0)` succeeds and this
        # lease would read live until that stranger exits -- refusing every round on this plan
        # hash in the meantime. Codex R3 P2. The TTL is the backstop: a same-host lease is live
        # only while its pid exists AND it is younger than the window a real round can occupy.
        return plan_review_inflight_lease_within_ttl(lease)
    return plan_review_inflight_lease_within_ttl(lease)


def plan_review_inflight_lease_within_ttl(lease: dict) -> bool:
    """True while the lease's own `started_at` is inside the in-flight TTL.

    Shared by the same-host and cross-host paths so there is ONE answer to "is this round still
    plausibly running", not two that can drift apart.
    """
    try:
        started = datetime.fromisoformat(str(lease.get("started_at") or ""))
    except (TypeError, ValueError):
        return False
    # now_iso() is tz-aware, so our own leases carry an offset. A lease written by a foreign
    # writer, or hand-edited, may not -- and subtracting a NAIVE datetime from an aware one
    # raises TypeError, which would kill run-plan-review at launch instead of refusing or
    # reclaiming. Read a naive stamp as UTC rather than dying on someone else's clock format.
    if started.tzinfo is None:
        started = started.replace(tzinfo=timezone.utc)
    age = (datetime.now(timezone.utc) - started).total_seconds()
    # Codex R3 P2. A NEGATIVE age means the writing host's clock is ahead of ours, which is
    # ordinary skew between two machines sharing a lane -- not evidence the round ended. The old
    # lower bound turned that into "stale", so the second launcher reclaimed a still-running
    # foreign lease and started the duplicate round this lease exists to prevent.
    #
    # Fail toward LIVE, which is the asymmetry this function is built on: a false "live" costs
    # one refusal carrying a tail command, a false "stale" costs the incident.
    return age < PLAN_REVIEW_INFLIGHT_TTL_SECONDS


def plan_review_acquire_inflight_lease(
    target: Path,
    runs_dir: Path,
    plan_rel: str,
    plan_hash: str,
    review_round: str,
    log_path: Path,
) -> tuple[Path | None, str | None]:
    """(lease_path, None) on acquisition; (None, refusal) when a live round holds the lease.

    O_CREAT|O_EXCL makes the create atomic so two racing launches cannot both win; a dead
    holder (a crashed launcher) is reclaimed in place with a printed note, never silently.
    """
    lease_path = plan_review_inflight_lease_path(runs_dir, plan_hash)
    body = json.dumps(
        {
            "schema": PLAN_REVIEW_INFLIGHT_SCHEMA,
            "pid": os.getpid(),
            "hostname": socket.gethostname(),
            "plan_path": plan_rel,
            "plan_content_sha256": plan_hash,
            "round": str(review_round),
            "log_path": path_relative_to_target(target, log_path),
            "started_at": now_iso(),
        },
        indent=2,
        sort_keys=True,
    ) + "\n"
    for _attempt in range(2):
        try:
            fd = os.open(lease_path, os.O_CREAT | os.O_EXCL | os.O_WRONLY)
        except FileExistsError:
            # Stat and parse are SEPARATE reads on purpose: an unreadable or corrupt body must
            # still be reclaimable, and bundling them left a garbage lease with no inode to
            # compare against, so the reclaim never fired and the launcher spun to its fallback.
            try:
                observed = os.stat(lease_path)
            except OSError:
                observed = None
            unparseable = False
            try:
                lease = json.loads(lease_path.read_text(encoding="utf-8"))
            except (OSError, json.JSONDecodeError):
                lease = {}
                unparseable = True
            # Codex R2 P2: valid JSON that is not an object -- `[]`, `null`, a bare string --
            # parses fine and then crashes the reclaim print on `.get`. A lease that is not an
            # object carries no launcher identity, so it is stale by definition, not an error.
            if not isinstance(lease, dict):
                lease = {}
            # AN UNPARSEABLE **FRESH** LEASE IS A WRITE IN PROGRESS, NOT A DEAD ONE. The winner
            # creates this file with O_EXCL and only then writes the JSON body; a loser arriving
            # inside that window reads an empty file, and every path above turns that into `{}` --
            # which reads as stale, unlinks the winner's inode, and lets BOTH launchers proceed.
            # That is precisely the racing-launch case the lease exists to serialize, so it cannot
            # be the one case it fails. Codex R2 P2. Only a body that is both unreadable AND older
            # than the write window is treated as garbage; anything younger is assumed live and
            # the loser backs off, which costs a retry and never a duplicate round.
            # Only a body that FAILED TO PARSE can be a half-written one. Valid JSON that is not
            # an object -- `"a string"`, `42`, `null` -- was written completely by something; it
            # carries no launcher identity and stays stale by definition, as the round before this
            # one established.
            if unparseable and observed is not None:
                age = time.time() - observed.st_mtime
                if age < PLAN_REVIEW_LEASE_WRITE_WINDOW_SECONDS:
                    return None, (
                        "another launcher is mid-write on this plan's in-flight lease "
                        f"({age:.1f}s old, body not yet readable), which means a round for this "
                        "exact plan content is starting right now. Backing off rather than "
                        "reclaiming it: the alternative is two reviewers on one plan, which is "
                        "what this lease exists to prevent. Re-run in a few seconds -- by then "
                        "the lease is either readable, and names the round to re-attach to, or "
                        "old enough to be reclaimed as garbage."
                    )
            if isinstance(lease, dict) and plan_review_inflight_lease_is_live(lease):
                # Codex R1 P3: the lease records a TARGET-RELATIVE log path, but a second
                # launcher may be invoked from anywhere with --target. Resolve it against the
                # target so the tail command is runnable from the caller's cwd -- a re-attach
                # command that only works if you already cd'd into the lane is not a re-attach.
                held_rel = str(lease.get("log_path") or "").strip()
                held_log = str(cli_path(target, held_rel)) if held_rel else "<unknown log>"
                return None, (
                    "a plan-review round for this exact plan content is already in flight "
                    f"(pid {lease.get('pid')}, started {lease.get('started_at')}); launching "
                    "another would silently spend a second Codex round on the same plan hash. "
                    "Re-attach to the running round instead: run "
                    # `-F`, not `-f`: a second launcher can arrive after the lease is written
                    # but before the first process opens the log, and `tail -f` on a missing
                    # file exits immediately on common implementations -- a re-attach command
                    # that quits the moment you run it reads as the tool being broken.
                    f"`tail -F {shlex.quote(held_log)}`, then classify that log and bind it "
                    "with the finalize-plan-review verb when it finishes"
                )
            print(
                "plan_review_inflight_note: reclaiming stale in-flight lease "
                f"{path_relative_to_target(target, lease_path)} "
                f"(recorded launcher pid {lease.get('pid')} is not running)"
            )
            # Codex R1 P2: reclaiming must not delete somebody ELSE'S live lease. Two launchers
            # can read the same stale body; if the first reclaims it and acquires, an
            # unconditional unlink here would delete that fresh, LIVE lease and hand both
            # processes a round -- the exact double-launch this whole mechanism exists to stop,
            # reintroduced by its own recovery path.
            #
            # Only unlink the inode we actually inspected. If it changed underneath us, someone
            # else won the reclaim: leave their lease alone and loop, where the liveness check
            # now sees a live holder and refuses.
            # Codex R4 P2: stat-then-unlink is still two operations on a NAME. The open inside
            # plan_review_unlink_if_inode pins the inode we checked, so a replacement arriving in
            # between cannot be mistaken for it -- the same guard the release path uses, so there
            # is one answer to "is this still the file I decided about".
            try:
                if observed is not None:
                    plan_review_unlink_if_inode(lease_path, observed.st_ino)
            except FileNotFoundError:
                pass
            except OSError:
                pass
            continue
        with os.fdopen(fd, "w", encoding="utf-8") as handle:
            handle.write(body)
        return lease_path, None
    return None, (
        "could not acquire the plan-review in-flight lease after reclaiming a stale one; "
        f"inspect and remove {path_relative_to_target(target, lease_path)} if no round is "
        "running, then rerun "
        f"`tautline run-plan-review --target {guard_target_argument(target)} "
        f"--plan {shlex.quote(plan_rel)} --round {shlex.quote(str(review_round))}`"
    )


def plan_review_runtime_cap_errors(
    data: dict,
    target: Path,
    plan_path: Path,
    plan_rel: str,
    plan_hash: str,
    review_round: str,
    round_number: int,
    allow_r3_structural_critical: bool = False,
    exception_reason: str = "",
) -> list[str]:
    errors: list[str] = []
    manifest = load_plan_review_manifest(plan_review_manifest_path(data, target, plan_path))
    successful_records = plan_review_successful_run_meta_records(data, target, plan_rel)
    # Record-backed like every other budget decision (item 108 WS2): the lane-local meta count
    # can only undercount a member whose spend lives in committed records.
    member_spend, _member_spend_source = plan_review_member_spend(data, target, plan_rel)
    spent_rounds = member_spend or 0
    effective_round = plan_review_effective_round(round_number, spent_rounds)
    if effective_round > PLAN_REVIEW_HARD_CAP_ROUNDS:
        # Belt and braces: the round-cap gate already refused, but no caller may reach a launch
        # past the hard cap through this path either. Keyed on the effective round for the same
        # reason the other gate is -- a relabelled round is still a spent invocation.
        finalizable = plan_review_finalizable_run_meta(data, target, plan_path, plan_rel, plan_hash)
        return [
            plan_review_hard_cap_refusal(
                effective_round,
                unresolved_blockers=plan_review_bound_evidence_is_unfinalizable(manifest, plan_hash),
                observed_runs=spent_rounds,
                declared_label=str(review_round),
                finalizable_command=(
                    plan_review_finalize_command(target, plan_rel, finalizable)
                    if finalizable
                    else ""
                ),
                capped_evidence_bound=plan_review_manifest_is_capped_for_hash(manifest, plan_hash),
            )
        ]
    self_authorized = bool(exception_reason) or allow_r3_structural_critical
    if (
        spent_rounds >= PLAN_REVIEW_TARGET_ROUNDS
        and not self_authorized
        and not plan_review_manifest_is_clean_for_hash(manifest, plan_hash)
    ):
        cap_preamble = (
            f"plan review has already launched {spent_rounds} successful Codex round(s) "
            f"for this source plan; the {PLAN_REVIEW_TARGET_ROUNDS}-round convergence target is "
            "exhausted and no convergence exception applies (no blockers were fixed since the "
            "bound round and there is no voided run to rebind), so "
        )
        if plan_review_sha_stale_at_cap(data, target, plan_path, plan_rel, plan_hash):
            # Every capped run reviewed different content: finalize would refuse the stale hash
            # and the cap refuses another run, so the focus-transfer remedy is unreachable.
            errors.append(cap_preamble + plan_review_successor_instruction(plan_rel))
        else:
            errors.append(
                cap_preamble + "carry unresolved findings into the implementation review focus "
                "list instead of spawning another plan-review loop"
            )
    for meta_path, meta in successful_records:
        if str(meta.get("round") or "") != str(review_round):
            continue
        if str(meta.get("plan_content_sha256") or "") != plan_hash:
            # The plan moved after this run, so the run is voided: it can never be finalized and
            # must not be held up as the reason to refuse a rebinding round.
            continue
        if not plan_review_run_meta_matches_manifest(target, meta_path, manifest):
            errors.append(
                f"existing successful Codex run for {review_round} is not finalized: {path_relative_to_target(target, meta_path)}; "
                "finalize that run instead of launching another one"
            )
    return errors


def write_plan_review_manifest(
    data: dict,
    target: Path,
    plan_path: Path,
    plan_rel: str,
    plan_hash: str,
    log_path: Path,
    review_command: str,
    reviewer: str,
    model: str,
    review_round: str,
    wrapper_exit_code: int,
    verdict: str,
    unresolved_critical_count: int,
    unresolved_p1_count: int,
    findings: list[dict],
    recorded_by: str,
    run_meta_path: Path | None = None,
    exception_note: str = "",
    asserted_verdict: str = "",
    carried_findings_basis: str = "",
) -> tuple[Path, dict]:
    manifest_path = plan_review_manifest_path(data, target, plan_path)
    manifest_path.parent.mkdir(parents=True, exist_ok=True)
    manifest = {
        "schema": PLAN_REVIEW_SCHEMA,
        "classifier_version": PLAN_REVIEW_CLASSIFIER_VERSION,
        # Opt-in marker: manifests written from this release onward are re-validated
        # strictly by precheck. Read with .get elsewhere and deliberately NOT added to the
        # required-fields list, so legacy manifests still validate.
        "verdict_scan": PLAN_REVIEW_VERDICT_SCAN_CONTRACT,
        "recorded_by": recorded_by,
        "project": data["project"],
        "plan_path": plan_rel,
        "plan_content_sha256": plan_hash,
        "review_command": review_command,
        "log_path": path_relative_to_target(target, log_path),
        "log_sha256": file_sha256(log_path),
        "reviewer": reviewer,
        "reviewer_model": model,
        "round": review_round,
        "wrapper_exit_code": wrapper_exit_code,
        "verdict": verdict,
        "unresolved_critical_count": unresolved_critical_count,
        "unresolved_p1_count": unresolved_p1_count,
        "classified_findings": findings,
        "timestamp": now_iso(),
    }
    if run_meta_path is not None:
        manifest["review_run_meta_path"] = path_relative_to_target(target, run_meta_path)
        manifest["review_run_meta_sha256"] = file_sha256(run_meta_path)
        # Carry the round ledger THROUGH from the bound run meta -- never recount here. By the
        # time a run is finalized it is itself on disk as a successful record, so a recount would
        # read one higher than the launch this manifest describes. A run meta written before this
        # release (every one now on disk) and the record-plan-review import path carry nothing, so
        # the manifest simply omits the keys rather than inventing numbers.
        #
        # Since item 108 WS2 these carried keys are DISPLAY: every budget decision reads the
        # durable round records through plan_review_member_spend, so a smaller lane-local ledger
        # landing here can no longer shrink any member's cumulative spend.
        for key in ("observed_successful_runs", "effective_round"):
            value = plan_review_run_meta_ledger_value(run_meta_path, key)
            if value is not None:
                manifest[key] = value
        # Succession lineage rides the same carry-through (item 32): a standalone plan's run meta
        # carries none of it and this contributes nothing, so its manifest stays byte-identical.
        manifest.update(plan_review_manifest_chain_fields(run_meta_path, wrapper_exit_code))
    # Only past-target rounds carry a recorded exception, so a plan that converges within the
    # target rounds keeps a byte-identical manifest.
    if exception_note:
        manifest["exception_note"] = exception_note
    # Written ONLY on the capped path, so every other manifest stays byte-identical. `verdict` on a
    # capped record is derived by the gate, not attested by the lane, and the ledger has to keep
    # both: the reviewer's own word is the thing the log can be checked against, and losing it
    # would leave a record nobody could reconcile with the log that produced it.
    if asserted_verdict and asserted_verdict != verdict:
        manifest["asserted_verdict"] = asserted_verdict
    # Same capped-only rule. The basis token is the record's own honesty about what its carried
    # list rests on -- see PLAN_REVIEW_CARRIED_FINDINGS_BASIS.
    if carried_findings_basis:
        manifest["carried_findings_basis"] = carried_findings_basis

    manifest_rel = path_relative_to_target(target, manifest_path)
    body = plan_review_evidence_body(manifest, manifest_rel)
    plan_text = plan_path.read_text(encoding="utf-8")
    updated = upsert_plan_review_evidence(plan_text, body)
    final_plan_hash = plan_content_sha256_from_text(updated)
    if final_plan_hash != plan_hash:
        raise SystemExit(
            "plan_review_write_error: Cross-Model Review Evidence update would change normalized plan content hash; "
            "no manifest or plan evidence was written. Restore the plan from git if needed and rerun review against a stable plan."
        )
    if updated != plan_text:
        plan_path.write_text(updated, encoding="utf-8")
    manifest_path.write_text(json.dumps(manifest, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    return manifest_path, manifest


def plan_review_rounds_dir(data: dict, target: Path, plan_path: Path) -> Path:
    """Where a member's durable per-round records live (item 108 WS1, decision DA).

    Under the COMMITTED reviews root beside the manifests -- never `.ai-runs/` -- keyed by the
    collision-aware manifest identity, so 38 `plan.md`s cannot share a record directory.
    """
    return plan_round_record_module().rounds_dir(
        plan_review_root(data, target) / ".plan-reviews",
        plan_review_manifest_identity(data, target, plan_path),
    )


def plan_review_round_prerecord_inputs(
    data: dict, target: Path, plan_rel: str
) -> tuple[int, list[str]]:
    """The baseline's inputs: the manifest spend floor plus every successful lane meta digest.

    The floor is the manifest ladder `observed_successful_runs + bound-run-success` -- the same
    arithmetic `plan_review_member_recorded_rounds` trusts -- DUPLICATED here deliberately rather
    than refactored out of it: WS1 is dual-write only, so the existing accounting reader stays
    byte-for-byte untouched while the record writer grows its own leaf.
    """
    records = plan_review_successful_run_meta_records(data, target, plan_rel)
    digests = sorted({str(meta.get("log_sha256") or "") for _path, meta in records} - {""})
    manifest = load_plan_review_manifest(plan_review_manifest_path_for_rel(data, target, plan_rel))
    floor = 0
    if manifest:
        try:
            observed = int(manifest["observed_successful_runs"])
        except (KeyError, TypeError, ValueError):
            observed = None
        if observed is not None:
            try:
                bound_exit = int(manifest.get("wrapper_exit_code"))
            except (TypeError, ValueError):
                bound_exit = None
            floor = observed + (1 if bound_exit == 0 else 0)
    return max(floor, len(records)), digests


def plan_review_ensure_round_baseline(
    data: dict,
    target: Path,
    plan_path: Path,
    plan_rel: str,
    baseline_inputs: tuple[int, list[str]],
) -> tuple[dict, Path, bool]:
    """Write the member's one-time baseline, or re-read the one that already exists."""
    module = plan_round_record_module()
    rounds = plan_review_rounds_dir(data, target, plan_path)
    prerecord_count, digests = baseline_inputs
    baseline = module.render_baseline(
        plan_identity=plan_review_manifest_identity(data, target, plan_path),
        plan_path=plan_rel,
        prerecord_count=prerecord_count,
        prerecord_log_sha256s=digests,
    )
    record, created = module.write_baseline_once(rounds, baseline)
    return record, module.baseline_path(rounds), created


def plan_review_declared_work_items(plan_path: Path) -> list[str]:
    try:
        return plan_round_record_module().declared_work_items(plan_review_text(plan_path))
    except OSError:
        return []


def plan_review_round_record_failure(exc: OSError) -> None:
    # Dual-write: the lane-local ledger still counted this round, so a failed record write is a
    # LOUD stderr line, never a refusal of a run or of a finalize exit. The remedy is the
    # sanctioned append, not a rerun and not an overwrite.
    print(
        f"plan_review_round_record_error: could not append the durable round record: {exc}; "
        "the lane-local ledger still counted this round -- fix the reviews root, then append a "
        "correction record with `tautline record-plan-review --target <lane> --plan <plan> "
        "--correct <nonce|baseline> --correction-note '<why>'`; never overwrite or regenerate "
        "a record or manifest",
        file=sys.stderr,
    )


def plan_review_append_run_round_records(
    *,
    data: dict,
    target: Path,
    plan_path: Path,
    plan_rel: str,
    plan_hash: str,
    baseline_inputs: tuple[int, list[str]],
    declared_round: str,
    wrapper_exit_code: int,
    reviewer_model: str,
    started_at: str,
    finished_at: str,
    frame_nonce: str,
    log_sha256: str,
    predecessor_rel: str | None,
) -> None:
    """Dual-write the durable per-round record for a launch (item 108 WS1 T1.1).

    `baseline_inputs` is the PRE-RUN snapshot (108-R4-P1-1): it was measured before this run's
    meta existed, so a first-post-cutover baseline can never absorb the run the invocation
    record beneath it is counting -- the run is counted exactly once, by its own record.
    """
    module = plan_round_record_module()
    try:
        _baseline, baseline_file, created = plan_review_ensure_round_baseline(
            data, target, plan_path, plan_rel, baseline_inputs
        )
        record = module.render_reviewer_invocation(
            plan_identity=plan_review_manifest_identity(data, target, plan_path),
            plan_path=plan_rel,
            plan_content_sha256=plan_hash,
            declared_round=declared_round,
            wrapper_exit_code=wrapper_exit_code,
            reviewer="codex",
            reviewer_model=reviewer_model,
            started_at=started_at,
            finished_at=finished_at,
            nonce=frame_nonce,
            log_sha256=log_sha256,
            declared_predecessor=predecessor_rel or "",
            work_items=plan_review_declared_work_items(plan_path),
            source="run",
        )
        record_path = module.append_record(
            plan_review_rounds_dir(data, target, plan_path), record
        )
    except OSError as exc:
        plan_review_round_record_failure(exc)
        return
    if created:
        print(f"plan_review_round_baseline: {baseline_file}")
    print(f"plan_review_round_record: {record_path}")


def plan_review_retract_classification_record(
    *,
    data: dict,
    target: Path,
    plan_path: Path,
    plan_rel: str,
    classification_record_id: str,
    declared_round: str,
    recorded_by: str,
) -> bool:
    """Append a `correction` retracting the classification whose finalize did not complete.

    Codex R1 P1 (WS5): the classification is appended BEFORE the manifest so a failed append can
    never leave a manifest certifying a record that does not exist. That ordering opens the
    mirror case -- manifest write fails AFTER the append -- and an orphan classification is read
    as proof by the NEXT capped finalize, certifying a round whose blockers were never carried.
    A classification proves a round only if its finalize completed, and in an append-only design
    the way to say "that did not happen" is another record, never an edit or an unlink.

    Best-effort by construction: it runs on a failure path, and a retraction that itself raised
    would replace the caller's real error with its own.
    """
    module = plan_round_record_module()
    try:
        rounds = plan_review_rounds_dir(data, target, plan_path)
        target_ref = classification_record_id
        module.append_record(
            rounds,
            module.render_correction(
                plan_identity=plan_review_manifest_identity(data, target, plan_path),
                plan_path=plan_rel,
                corrects=target_ref,
                note=(
                    f"round {declared_round}: the finalize that appended this classification did "
                    "not complete -- its manifest was never written, so the classification "
                    "proves nothing and must not certify the round"
                ),
                raise_prerecord_count_to=None,
                recorded_by=recorded_by,
                recorded_at=now_iso(),
            ),
        )
        return True
    except (OSError, ValueError) as exc:  # pragma: no cover - failure path of a failure path
        print(
            f"plan_review_round_record_error: could not retract the classification for "
            f"{plan_rel} round {declared_round}: {exc}",
            file=sys.stderr,
        )
        return False


def plan_review_append_classification_record(
    *,
    data: dict,
    target: Path,
    plan_path: Path,
    plan_rel: str,
    plan_hash: str,
    log_path: Path,
    run_meta_path: Path | None,
    declared_round: str,
    verdict: str,
    unresolved_critical_count: int,
    unresolved_p1_count: int,
    findings_count: int,
    recorded_by: str,
) -> str:
    """Append the bind-time classification record (item 108 WS1 T1.2). Appends; never mutates.

    Returns the appended record's IDENTITY (its unique file stem), or "" when the append failed.
    A compensating correction names that identity, so a retraction never depends on record order
    and never poisons a later retry (Codex R2 P2 and R3 P2).

    Binding is deterministic: a recorded invocation (matched on the bound log's digest) binds by
    nonce + log_sha256; a digest in the baseline's enumerated set is a PRE-CUTOVER round and
    binds by digest alone with `origin: pre-record`; anything else binds by the meta's own nonce
    and is WS2's write-path bug to surface -- a finalize never refuses its exit over record
    bookkeeping.

    Returns whether the record is ON DISK (WS5 remediation P1). A finalize still exits 0 when the
    append fails -- the lane-local ledger counted the round either way -- but the caller must be
    able to tell, because a manifest that certifies its carried list against a record that was
    never written is the exact failure this whole item exists to remove.
    """
    module = plan_round_record_module()
    try:
        rounds = plan_review_rounds_dir(data, target, plan_path)
        log_digest = file_sha256(log_path)
        baseline, baseline_file, created = plan_review_ensure_round_baseline(
            data,
            target,
            plan_path,
            plan_rel,
            plan_review_round_prerecord_inputs(data, target, plan_rel),
        )
        recorded = module.find_reviewer_invocation(rounds, log_sha256=log_digest)
        origin = ""
        nonce = ""
        if recorded is not None:
            nonce = str(recorded.get("nonce") or "")
        elif log_digest in (baseline.get("prerecord_log_sha256s") or []):
            origin = "pre-record"
        elif run_meta_path is not None:
            nonce = plan_review_run_meta_frame_nonce(run_meta_path) or ""
        record = module.render_round_classification(
            plan_identity=plan_review_manifest_identity(data, target, plan_path),
            plan_path=plan_rel,
            plan_content_sha256=plan_hash,
            declared_round=declared_round,
            verdict=verdict,
            unresolved_critical_count=unresolved_critical_count,
            unresolved_p1_count=unresolved_p1_count,
            classified_findings_count=findings_count,
            nonce=nonce,
            log_sha256=log_digest,
            origin=origin,
            recorded_by=recorded_by,
            recorded_at=now_iso(),
        )
        record_path = module.append_record(rounds, record)
    except OSError as exc:
        plan_review_round_record_failure(exc)
        return ""
    if created:
        print(f"plan_review_round_baseline: {baseline_file}")
    print(f"plan_review_round_record: {record_path}")
    # The record's own identity, so a compensating correction can name THIS record rather than
    # the round it describes -- see plan_review_member_round_proof (Codex R3 P2).
    return Path(record_path).stem


def plan_review_append_import_records(
    *,
    data: dict,
    target: Path,
    plan_path: Path,
    plan_rel: str,
    plan_hash: str,
    log_path: Path,
    run_meta: dict,
    declared_round: str,
    verdict: str,
    unresolved_critical_count: int,
    unresolved_p1_count: int,
    findings_count: int,
    reviewer: str,
    reviewer_model: str,
    wrapper_exit_code: int,
) -> None:
    """One deterministic rule for record-plan-review imports (item 108, 108-R4-P1-2).

    In order: a digest matching a recorded invocation binds to that record (a re-import never
    charges twice); a digest in the baseline's enumerated set is a pre-cutover round and gets a
    classification with `origin: pre-record` and NO spend record; anything else -- including
    every import against a digestless floor, where the baseline count came from
    `observed_successful_runs` with nothing enumerable -- first appends a CHARGED
    `reviewer-invocation` record with `source: imported` (nonce minted here) and references it
    from an `origin: imported-unverified` classification. Never an uncharged classification for
    an unknown digest: manifest evidence can never outrun the budget that produced it.

    A RE-IMPORT inherits the origin of the invocation it binds to (WS5 remediation P2). The first
    import MINTS its own `source: imported` invocation, so re-running the same
    `tautline record-plan-review` used to bind to that minted record and write an origin-free
    classification -- and an origin-free classification is what the carried-findings basis reads
    as proof. Two identical imports therefore certified a round nobody ever observed. An import
    that binds a `source: run` invocation is the opposite case and still classifies cleanly: that
    is the sanctioned remedy the capped disclosure names for a round that ran but was never bound.
    """
    module = plan_round_record_module()
    try:
        rounds = plan_review_rounds_dir(data, target, plan_path)
        log_digest = file_sha256(log_path)
        baseline, baseline_file, created = plan_review_ensure_round_baseline(
            data,
            target,
            plan_path,
            plan_rel,
            plan_review_round_prerecord_inputs(data, target, plan_rel),
        )
        recorded = module.find_reviewer_invocation(rounds, log_sha256=log_digest)
        origin = ""
        nonce = ""
        invocation_path: Path | None = None
        if recorded is not None:
            nonce = str(recorded.get("nonce") or "")
            if str(recorded.get("source") or "") != "run":
                origin = "imported-unverified"
        elif log_digest in (baseline.get("prerecord_log_sha256s") or []):
            origin = "pre-record"
        else:
            nonce = secrets.token_hex(8)
            invocation = module.render_reviewer_invocation(
                plan_identity=plan_review_manifest_identity(data, target, plan_path),
                plan_path=plan_rel,
                plan_content_sha256=plan_hash,
                declared_round=declared_round,
                wrapper_exit_code=wrapper_exit_code,
                reviewer=reviewer,
                reviewer_model=reviewer_model,
                started_at=str(run_meta.get("started_at") or ""),
                finished_at=str(run_meta.get("finished_at") or ""),
                nonce=nonce,
                log_sha256=log_digest,
                declared_predecessor=str(run_meta.get("predecessor_plan_path") or ""),
                work_items=plan_review_declared_work_items(plan_path),
                source="imported",
            )
            invocation_path = module.append_record(rounds, invocation)
            origin = "imported-unverified"
        record = module.render_round_classification(
            plan_identity=plan_review_manifest_identity(data, target, plan_path),
            plan_path=plan_rel,
            plan_content_sha256=plan_hash,
            declared_round=declared_round,
            verdict=verdict,
            unresolved_critical_count=unresolved_critical_count,
            unresolved_p1_count=unresolved_p1_count,
            classified_findings_count=findings_count,
            nonce=nonce,
            log_sha256=log_digest,
            origin=origin,
            recorded_by="tautline record-plan-review",
            recorded_at=now_iso(),
        )
        record_path = module.append_record(rounds, record)
    except OSError as exc:
        plan_review_round_record_failure(exc)
        return
    if created:
        print(f"plan_review_round_baseline: {baseline_file}")
    if invocation_path is not None:
        print(f"plan_review_round_record: {invocation_path}")
    print(f"plan_review_round_record: {record_path}")


def plan_review_append_correction_record(
    data: dict,
    target: Path,
    plan_path: Path,
    plan_rel: str,
    *,
    corrects: str,
    note: str,
    raise_prerecord_count_to: int | None,
) -> int:
    """The sanctioned amendment writer (item 108 WS1 T1.2, 108-R4-P2-2).

    Appends a `correction` record referencing the original -- an invocation nonce, or the
    literal `baseline`. Corrections RAISE; nothing lowers anything, and nothing here rewrites,
    renames, or deletes an existing record. WS2's reader consumes the raise-only semantics; WS1
    only writes.
    """
    module = plan_round_record_module()
    try:
        rounds = plan_review_rounds_dir(data, target, plan_path)
        if corrects == module.CORRECTION_BASELINE_TARGET:
            baseline, _baseline_file, _created = plan_review_ensure_round_baseline(
                data,
                target,
                plan_path,
                plan_rel,
                plan_review_round_prerecord_inputs(data, target, plan_rel),
            )
            # Codex R2 P2: the floor includes every PRIOR baseline correction, or a later,
            # lower raise slips under an earlier one and the durable record turns ambiguous.
            current = module.current_prerecord_floor(rounds, baseline)
            if raise_prerecord_count_to is not None and raise_prerecord_count_to <= current:
                print(
                    "plan_review_record_error: corrections raise and nothing lowers anything: "
                    f"--raise-prerecord-count-to {raise_prerecord_count_to} does not exceed the "
                    f"member's current pre-record floor of {current} (baseline plus prior "
                    "corrections)",
                    file=sys.stderr,
                )
                return 1
        else:
            if raise_prerecord_count_to is not None:
                print(
                    "plan_review_record_error: --raise-prerecord-count-to targets the member's "
                    "pre-record floor; pass `--correct baseline` to raise it",
                    file=sys.stderr,
                )
                return 1
            if module.find_reviewer_invocation(rounds, nonce=corrects) is None:
                print(
                    f"plan_review_record_error: no reviewer-invocation record with nonce "
                    f"{corrects} under {rounds}; a correction is an append that references an "
                    "existing record -- inspect the record files there for the nonce to pass to "
                    "--correct, or pass `--correct baseline` to amend the pre-record floor",
                    file=sys.stderr,
                )
                return 1
        record = module.render_correction(
            plan_identity=plan_review_manifest_identity(data, target, plan_path),
            plan_path=plan_rel,
            corrects=corrects,
            note=note,
            raise_prerecord_count_to=raise_prerecord_count_to,
            recorded_by="tautline record-plan-review --correct",
            recorded_at=now_iso(),
        )
        record_path = module.append_record(rounds, record)
    except OSError as exc:
        print(
            f"plan_review_record_error: could not append the correction record: {exc}; fix the "
            "reviews root named in the error and rerun the same `tautline record-plan-review "
            "--target <lane> --plan <plan> --correct <nonce|baseline> --correction-note '<why>'` "
            "invocation -- a refused append wrote nothing, so retrying is safe",
            file=sys.stderr,
        )
        return 1
    print(f"plan_review_round_record: {record_path}")
    print(
        "plan_review_correction: appended; a correction references its original and is applied "
        "raise-only by the spend reader -- no record or manifest was rewritten"
    )
    return 0


def plan_template_coverage_errors(data: dict, template_path: Path) -> list[str]:
    """What the shipped plan TEMPLATE fails to cover, as a report. Never refuses.

    The template is a fixture for the content contract: if a lane can fill it in completely and
    still fail `plan-substance-check`, the template is the defect, not the lane. This measures
    exactly that -- the same predicate the pre-gate uses, pointed at the template instead of at
    somebody's plan.

    F1 PARITY: this consumes the SAME issue list as the gate. A second implementation would drift,
    and the drift would be invisible precisely because the two are never compared.
    """
    authoring = plan_authoring_module()
    if authoring.normalize_planning_template_coverage(data)["enforcement"] == "off":
        return []
    if not template_path.is_file():
        return [f"plan template not found at {template_path}"]
    try:
        text = template_path.read_text(encoding="utf-8")
    except OSError as exc:
        return [f"plan template unreadable: {exc}"]
    return list(
        authoring.plan_authoring_standard_issues(strip_plan_review_evidence(text))
    ) + list(validate_plan_substance(template_path))


def plan_template_coverage_status_line(data: dict, template_path: Path) -> str:
    """One line for lane-start. Reports; never changes an exit code."""
    issues = plan_template_coverage_errors(data, template_path)
    if not issues:
        return "plan_template_coverage: ok - the shipped template covers the content contract"
    return (
        f"plan_template_coverage: {len(issues)} gap(s) in the shipped template "
        f"({issues[0]}) - report only; a lane filling this in completely would still be told "
        "something is missing, which makes the TEMPLATE the thing to fix"
    )


def plan_review_content_pregate(
    data: dict, plan_path: Path, observed_runs: int
) -> tuple[list[str], list[str]]:
    """Content issues at the R1 seam, split into `(refusals, warnings)`.

    THE POINT IS WHEN, NOT WHETHER. `plan-finalization-precheck` already refuses these, but only
    after the review budget is spent -- and fixing them then changes the plan, which unbinds the
    evidence. Item 57 lost one successor plan to that and item 62 lost two. Surfacing the same
    facts at round zero costs nothing: plan edits made before R1 void no evidence.

    At `observed_runs > 0` everything is advisory, always. Forcing an edit mid-loop is the
    ORIGINAL defect, not a stricter version of the fix.
    """
    authoring = plan_authoring_module()
    enforcement = authoring.normalize_planning_content_pregate(data)["enforcement"]
    if enforcement == "off":
        return [], []
    try:
        plan_text = plan_path.read_text(encoding="utf-8")
    except OSError:
        # Unreadable here is not a content verdict -- the gates above already decided the plan is
        # readable, and inventing a refusal from a transient read failure would refuse a plan
        # nobody can see is wrong.
        return [], []
    # STRIP THE REVIEW EVIDENCE FIRST. A previously-reviewed plan carries its own log under
    # `## Cross-Model Review Evidence`, and that log routinely contains `model-tier:`,
    # `best judgment` and `decision-record` -- so an unstripped read lets a plan satisfy authoring
    # markers it never authored, out of the words a REVIEWER wrote about it. The finalization path
    # already strips this for exactly this check; not doing so here made the gate weaker on the
    # plans most likely to reach it. Codex R2 P2.
    authored = strip_plan_review_evidence(plan_text)
    issues = list(authoring.plan_authoring_standard_issues(authored)) + list(
        validate_plan_substance(plan_path)
    )
    # Sizing rides along as a HINT and never as a refusal, in any mode, at any round count. It is
    # appended to the advisory side below rather than passed through the refusable/advisory split,
    # because that split answers "can a reviewer work around this" and sizing is not that kind of
    # question -- a large plan is reviewable, just expensively.
    sizing = list(authoring.plan_scope_advisory(authored))
    if not issues and not sizing:
        return [], []
    refusable, advisory = authoring.partition_pregate_errors(issues)
    if enforcement != "block" or observed_runs > 0:
        return [], refusable + advisory + sizing
    return refusable, advisory + sizing


def plan_review_content_pregate_next_action(plan_rel: str, target: Path) -> str:
    """The line that makes the warnings actionable while they are still free to act on."""
    return (
        "plan_review_run_warning: fix these BEFORE R1 -- plan edits made now cost no review "
        "budget and void no evidence; run `tautline plan-substance-check --target "
        f"{guard_target_argument(target)} --plan {shlex.quote(plan_rel)}` to re-check"
    )


def plan_root_resolve(data: dict, target: Path, spec: str) -> Path:
    """A `--plan` value to a filesystem path, honouring the `<root>:<path>` form.

    THE THREAD W3 IS NAMED FOR. `resolve_plan_path` treats its argument as a lane-relative path, so
    the advertised `tautline-backlog:ready/x/plan.md` reached the filesystem as a literal directory
    named `tautline-backlog:ready` -- which meant the configured-root check below never saw an
    external plan at all, and the feature could not be used the way its own release note describes
    it. Codex R1 P1.
    """
    reference = paths_module().plan_reference.parse_plan_reference(str(spec or ""))
    roots = paths_module().configured_plan_roots(data, target)
    root = roots.get(reference.root)
    if reference.root == paths_module().plan_reference.LANE_ROOT or root is None:
        # No root token, or a token this adapter does not configure. Unchanged behaviour: the lane
        # resolver decides, and an unconfigured token then fails the containment check below with
        # the path it actually tried -- which is the honest message.
        return resolve_plan_path(target, Path(spec)).resolve(strict=False)
    return (Path(root) / reference.relative).resolve(strict=False)


def plan_root_relative_reference(data: dict, target: Path, plan_path: Path) -> str:
    """How this plan is RECORDED: lane-relative as before, or `<root>:<relative>` when external.

    `path_relative_to_target` raises for anything outside the target, and every downstream surface
    keys on this string -- so without a root-aware rendering an external plan could be resolved and
    then not written down. Lane-local plans render exactly as they always did, which is what keeps
    the existing manifests and ledgers byte-identical.
    """
    try:
        return path_relative_to_target(target, plan_path)
    except (ValueError, SystemExit):
        pass
    resolved = plan_path.resolve()
    reference_mod = paths_module().plan_reference
    for token, root in paths_module().configured_plan_roots(data, target).items():
        if token == reference_mod.LANE_ROOT:
            continue
        try:
            relative = resolved.relative_to(Path(root).resolve())
        except ValueError:
            continue
        return reference_mod.render_plan_reference(token, relative.as_posix())
    # Under no configured root: let the original error stand rather than inventing a reference.
    return path_relative_to_target(target, plan_path)


def run_plan_review(args: argparse.Namespace) -> int:
    data, _project_path, target = lane_project(args)
    plan_path = plan_root_resolve(data, target, args.plan)
    source_root = planning_source_root(data, target)
    if not plan_path.exists() or not plan_path.is_file():
        print(f"plan_review_run_error: plan missing: {plan_path}", file=sys.stderr)
        return 1
    if not plan_is_under_a_configured_root(data, target, plan_path):
        print(f"plan_review_run_error: plan outside source-of-truth path: {plan_path} not under {source_root}", file=sys.stderr)
        return 1
    plan_rel = plan_root_relative_reference(data, target, plan_path)
    plan_hash = plan_content_sha256(plan_path)
    round_number = plan_review_round_number(args.review_round)
    exception_note = plan_review_exception_note(
        getattr(args, "exception_note", None),
        getattr(args, "structural_critical_evidence", None),
    )
    detected_reason = plan_review_self_authorized_reason(
        data, target, plan_path, plan_rel, plan_hash
    )
    # A run self-authorizes on a recorded note OR on a detected convergence/rebinding state; the
    # note only becomes mandatory when the round is finalized into the manifest.
    exception_reason = exception_note or detected_reason
    manifest_path = plan_review_manifest_path(data, target, plan_path)
    existing_manifest = load_plan_review_manifest(manifest_path)
    # Only the LAUNCH path spends budget, so only this caller passes the observed count -- and
    # the budget reads the DURABLE record (item 108 WS2 T2.1): a fresh worktree launches at its
    # committed cumulative spend, never at zero. The lane-local meta count and the manifest's
    # `observed_successful_runs` copy stay what they now are -- display, the baseline input, and
    # the pre-record floor for a member with no baseline.
    member_spend, _member_spend_source = plan_review_member_spend(data, target, plan_rel)
    observed_runs = member_spend or 0
    # Snapshot the durable baseline's inputs BEFORE this run can write a meta (item 108 WS1,
    # finding 108-R4-P1-1): the cutover marker written after the run below must never absorb the
    # very run its invocation record counts, or the first post-cutover round bills twice.
    round_baseline_inputs = plan_review_round_prerecord_inputs(data, target, plan_rel)
    effective_round = plan_review_effective_round(round_number, observed_runs)
    finalizable_meta = plan_review_finalizable_run_meta(
        data, target, plan_path, plan_rel, plan_hash
    )
    round_cap_errors = plan_review_round_cap_errors(
        round_number=round_number,
        structural_critical_evidence=getattr(args, "structural_critical_evidence", None),
        exception_reason=exception_reason,
        unresolved_blockers=plan_review_bound_evidence_is_unfinalizable(existing_manifest, plan_hash),
        observed_runs=observed_runs,
        declared_label=str(args.review_round),
        finalizable_command=(
            plan_review_finalize_command(target, plan_rel, finalizable_meta)
            if finalizable_meta
            else ""
        ),
        capped_evidence_bound=plan_review_manifest_is_capped_for_hash(existing_manifest, plan_hash),
    )
    if round_cap_errors:
        for error in round_cap_errors:
            print(f"plan_review_run_error: {error}", file=sys.stderr)
        return 1
    finalize_requested = any(
        value is not None
        for value in [args.verdict, args.unresolved_critical_count, args.unresolved_p1_count, args.classified_findings_json]
    )
    if finalize_requested and (
        args.verdict is None
        or args.unresolved_critical_count is None
        or args.unresolved_p1_count is None
    ):
        print(
            "plan_review_run_error: inline finalization requires --verdict, --unresolved-critical-count, and --unresolved-p1-count; "
            "otherwise run without those flags, inspect the log, then call finalize-plan-review",
            file=sys.stderr,
        )
        return 1
    if (
        finalize_requested
        and round_number is not None
        and round_number > PLAN_REVIEW_TARGET_ROUNDS
        and not exception_note
    ):
        # Refuse BEFORE spending a Codex round: inline finalization writes the manifest, so it is
        # bound by the same recorded-exception rule as finalize-plan-review.
        print(
            f"plan_review_run_error: inline finalization of round {round_number} is past the "
            f"{PLAN_REVIEW_TARGET_ROUNDS}-round convergence target, so it requires a recorded "
            "exception: pass --exception-note '<reason>' (at least "
            f"{PLAN_REVIEW_EXCEPTION_NOTE_MIN_CHARS} characters)",
            file=sys.stderr,
        )
        return 1
    try:
        command_tokens = shlex.split(codex_plan_wrapper(data))
    except ValueError as exc:
        print(f"plan_review_run_error: adapter review.codexPlanWrapper is not shell-parseable: {exc}", file=sys.stderr)
        return 1
    if not command_tokens:
        print("plan_review_run_error: adapter review.codexPlanWrapper is empty", file=sys.stderr)
        return 1
    review_args = list(args.review_args or [])
    if review_args and review_args[0] == "--":
        review_args = review_args[1:]
    for index, token in enumerate(review_args):
        if token == "--plan" or token.startswith("--plan="):
            print("plan_review_run_error: review args cannot supply --plan; run-plan-review binds the source-of-truth plan itself", file=sys.stderr)
            return 1
        if index > 0 and review_args[index - 1] == "--plan":
            print("plan_review_run_error: review args cannot supply --plan; run-plan-review binds the source-of-truth plan itself", file=sys.stderr)
            return 1
    review_args.extend(["--plan", plan_rel])
    full_command = [*command_tokens, *review_args]
    review_command = " ".join(shlex.quote(part) for part in full_command)
    # Item 76 T2.4. Advisory, not a refusal, and deliberately emitted HERE -- at wrapper
    # resolution, before the in-flight lease is acquired (packet S3), so it costs nothing and an
    # advisory printed on a lease-refused launch is harmless.
    #
    # The `## Findings` heading the trusted path now requires is produced by the BUILTIN
    # wrapper's prompt. A lane pointing review.codexPlanWrapper at its own script owns that
    # requirement itself, and the first it would otherwise hear of it is a finalize-time format
    # error on a round it has already paid for.
    if "codex-plan-review" not in full_command:
        print(
            "plan_review_reviewer_contract: this lane's review.codexPlanWrapper is not the "
            "builtin `tautline codex-plan-review`, so the reviewer contract is the wrapper's "
            "own responsibility: its prompt must require the response to start with "
            "`## Findings`, or finalizing this round will report a reviewer-format error. "
            "Pointing the adapter at the builtin wrapper satisfies the contract by construction."
        )
    command_errors = review_command_errors(data, review_command, plan_rel, plan_hash)
    if command_errors:
        for error in command_errors:
            print(f"plan_review_run_error: {error}", file=sys.stderr)
        return 1
    runtime_cap_errors = plan_review_runtime_cap_errors(
        data=data,
        target=target,
        plan_path=plan_path,
        plan_rel=plan_rel,
        plan_hash=plan_hash,
        review_round=args.review_round,
        round_number=round_number,
        exception_reason=exception_reason,
    )
    if runtime_cap_errors:
        for error in runtime_cap_errors:
            print(f"plan_review_run_error: {error}", file=sys.stderr)
        return 1
    # Succession-chain accounting (item 32). Resolved BEFORE the reviewer is launched so a
    # provably-wrong --predecessor costs no round; the flag is the ONLY thing that can error here,
    # so a run without it reaches the launch on exactly the path it did before this existed.
    lineage_errors, predecessor_rel = plan_review_lineage_errors(
        data, target, plan_path, plan_rel, getattr(args, "predecessor", None)
    )
    if lineage_errors:
        for error in lineage_errors:
            print(f"plan_review_run_error: {error}", file=sys.stderr)
        return 1
    chain_fields: dict = {}
    chain_summary: dict = {}
    # ONE resolver, one lineage (item 108 WS3): the declared flag, the `-vN` name shape and
    # shared work items bind as a UNION, so the advisory summary printed below and any
    # authoritative consumer read the same member set -- a launch can never record two different
    # lineages. Resolved on every run: an UNDECLARED lineage (name shape or work item, no flag)
    # still gets the advisory ledger line, while the recorded chain fields stay declared-only --
    # recording an inferred predecessor would put an invented fact into an evidence record.
    chain_members, chain_truncated = plan_review_launch_chain(
        data, target, plan_rel, predecessor_rel, observed_runs
    )
    if predecessor_rel or len(chain_members) > 1:
        chain_summary = plan_review_chain_summary(chain_members, chain_truncated)
    if predecessor_rel:
        chain_fields = {
            "predecessor_plan_path": predecessor_rel,
            "predecessor_manifest_path": path_relative_to_target(
                target, plan_review_manifest_path_for_rel(data, target, predecessor_rel)
            ),
            "chain_depth": chain_summary["depth"],
            # Before-this-run, exactly like observed_successful_runs beside it.
            "chain_prior_recorded_rounds": chain_summary["cumulative_recorded_rounds"],
            # PERSISTED, not print-time-only: a stored total must never look exact when the walk
            # could only establish a floor.
            "chain_evidence": chain_summary["evidence"],
            "chain_unknown_members": chain_summary["unknown_members"],
        }
    if round_number is not None and round_number > PLAN_REVIEW_TARGET_ROUNDS:
        print(
            f"plan_review_exception: convergence round {round_number} of "
            f"{PLAN_REVIEW_HARD_CAP_ROUNDS} - {exception_reason}"
        )
    codex_env = codex_fast_mode_env(data, target, os.environ.copy())
    codex_env[PLAN_REVIEW_LAUNCHER_HANDSHAKE_ENV] = "run-plan-review"
    # Codex R4 P2: dual-write through the house helper rather than setting the MINERVIT_ name
    # alone. The receiver reads via resolve_env, which PREFERS the TAUTLINE_ alias and emits a
    # sunset warning when it has to fall back -- so a single-name write would put a deprecation
    # warning into every builtin plan-review run's captured log, which is the artifact that then
    # gets classified as review evidence.
    codex_env = brand_env_pairs(codex_env)

    runs_dir = configured_path(target, data["laneState"]["runsDir"]) / "plan-review"
    runs_dir.mkdir(parents=True, exist_ok=True)
    stamp = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%SZ")
    log_path = runs_dir / f"{stamp}-{slugify(plan_path.stem, 'plan')}-{slugify(args.review_round, 'round')}.log"
    # Item 80 (N6), honouring the successor invariant W1.3 wrote below: the CONTENT pre-gate sits
    # ABOVE the lease acquisition. A content refusal below it would return while the lease is held,
    # stranding it for the whole TTL on a plan nobody is reviewing -- which is the C2 interlock,
    # and `test_content_refusal_never_holds_a_lease` is what proves it stayed above.
    pregate_refusals, pregate_warnings = plan_review_content_pregate(
        data, plan_path, observed_runs
    )
    for warning in pregate_warnings:
        print(f"plan_review_run_warning: {warning}", file=sys.stderr)
    if pregate_warnings or pregate_refusals:
        print(plan_review_content_pregate_next_action(plan_rel, target), file=sys.stderr)
    if pregate_refusals:
        for refusal in pregate_refusals:
            print(f"plan_review_run_error: {refusal}", file=sys.stderr)
        return 1

    # Item 77 WS1. Acquired HERE -- after every budget, precheck, command and adapter gate
    # above has already passed, and before the started event -- so a refused launch has spent
    # nothing. SUCCESSOR INVARIANT (packet W1.3 s1.3, and item 80 reads this): a new CONTENT
    # gate goes ABOVE this point -- item 80 placed it there; see the block immediately above.
    # A content refusal below it would return while the lease is
    # held, stranding it for the whole TTL on a plan nobody is reviewing.
    lease_path, lease_refusal = plan_review_acquire_inflight_lease(
        target, runs_dir, plan_rel, plan_hash, args.review_round, log_path
    )
    if lease_refusal:
        print(f"plan_review_run_error: {lease_refusal}", file=sys.stderr)
        return 1
    try:
        started_at = now_iso()
        # Frames this run's captured output so a reviewer quoting another round's log --
        # which it does
        # routinely, because reading prior evidence is legitimate -- cannot close this run's block
        # (item 25: plan-review log verbatim replay). A collision guard, not a secret.
        frame_nonce = secrets.token_hex(8)
        try_write_event(
            data,
            target,
            event="plan_review_started",
            severity="info",
            plain=f"Codex plan review {args.review_round} started for {plan_rel}.",
            next_action="Wait for this single review round to finish, then classify the log with finalize-plan-review.",
            refs={"plan": plan_rel, "log": path_display(target, log_path)},
        )
        with log_path.open("w", encoding="utf-8") as log:
            log.write("MINERVIT_PLAN_REVIEW_RUN_V1\n")
            log.write(f"plan_path: {plan_rel}\n")
            log.write(f"plan_content_sha256: {plan_hash}\n")
            log.write("review_scope: plan-only\n")
            log.write("code_diff_review: no\n")
            log.write("native_review_required: yes\n")
            log.write("native_review_requirement: authoring-model native/Superpowers review on current plan before R1 only\n")
            if round_number is not None and round_number > PLAN_REVIEW_TARGET_ROUNDS:
                log.write("plan_review_exception: yes\n")
                log.write(f"plan_review_exception_reason: {exception_reason}\n")
            log.write(f"codex_fast_mode: {codex_fast_mode_status(data)}\n")
            log.write(f"review_command: {review_command}\n")
            log.write(f"started_at: {started_at}\n")
            log.write(f"no_output_timeout_seconds: {args.no_output_timeout_seconds}\n")
            log.write(f"{PLAN_REVIEW_OUTPUT_START} run:{frame_nonce}\n")
            log.flush()
            wrapper_exit_code, stale_marker_path = run_process_with_no_output_watchdog(
                full_command,
                cwd=target,
                env=codex_env,
                log_handle=log,
                log_path=log_path,
                no_output_timeout_seconds=int(args.no_output_timeout_seconds),
            )
            finished_at = now_iso()
            log.write(f"\n{PLAN_REVIEW_OUTPUT_END} run:{frame_nonce}\n")
            log.write(f"finished_at: {finished_at}\n")
            log.write(f"wrapper_exit_code: {wrapper_exit_code}\n")
            if stale_marker_path:
                log.write(f"stale_marker: {stale_marker_path}\n")

        meta_path = plan_review_run_meta_path(log_path)
        meta = {
            "schema": PLAN_REVIEW_RUN_SCHEMA,
            "plan_path": plan_rel,
            "plan_content_sha256": plan_hash,
            "review_scope": "plan-only",
            "code_diff_review": False,
            "native_review_required": True,
            "native_review_requirement": "authoring-model native/Superpowers review on current plan before R1 only",
            "exception_round": (
                round_number is not None and round_number > PLAN_REVIEW_TARGET_ROUNDS
            ),
            "exception_reason": exception_reason,
            "codex_fast_mode": codex_fast_mode_enabled(data),
            "review_command": review_command,
            "log_path": path_relative_to_target(target, log_path),
            "log_sha256": file_sha256(log_path),
            "log_frame_nonce": frame_nonce,
            "wrapper_exit_code": wrapper_exit_code,
            "no_output_timeout_seconds": int(args.no_output_timeout_seconds),
            "stale_marker_path": path_relative_to_target(target, stale_marker_path) if stale_marker_path else "",
            "round": args.review_round,
            # The ledger: what the caller called this launch vs what the evidence says it is. Both
            # describe the state BEFORE this run, so a reader can reconstruct the budget without
            # recounting (item 24: plan-review round advance gap).
            "observed_successful_runs": observed_runs,
            "effective_round": effective_round,
            "reviewer": "codex",
            "reviewer_model": args.model,
            "started_at": started_at,
            "finished_at": finished_at,
        }
        # Empty for a standalone plan, so its run meta is byte-identical to a pre-item-32 record.
        meta.update(chain_fields)
        meta_path.write_text(json.dumps(meta, indent=2, sort_keys=True) + "\n", encoding="utf-8")
        # The durable per-round record (item 108 WS1): every invocation, success or failure,
        # appends exactly one committed record beside the manifests -- printed so the plan-review
        # evidence commit picks the new files up.
        plan_review_append_run_round_records(
            data=data,
            target=target,
            plan_path=plan_path,
            plan_rel=plan_rel,
            plan_hash=plan_hash,
            baseline_inputs=round_baseline_inputs,
            declared_round=str(args.review_round),
            wrapper_exit_code=wrapper_exit_code,
            reviewer_model=args.model,
            started_at=started_at,
            finished_at=finished_at,
            frame_nonce=frame_nonce,
            log_sha256=str(meta["log_sha256"]),
            predecessor_rel=predecessor_rel,
        )
        review_failed_stale = wrapper_exit_code == 124 and stale_marker_path is not None
        review_finish_next_action = (
            "Recover the stale review process and rerun this configured review round; do not classify the frozen log as review evidence."
            if review_failed_stale
            else "Inspect and classify the printed log once; do not rerun Codex just to bind the manifest."
        )
        try_write_event(
            data,
            target,
            event="plan_review_finished" if wrapper_exit_code == 0 else "plan_review_failed",
            severity="ok" if wrapper_exit_code == 0 else "fail",
            plain=f"Codex plan review {args.review_round} finished for {plan_rel} with exit code {wrapper_exit_code}.",
            next_action=review_finish_next_action,
            refs={"plan": plan_rel, "log": path_display(target, log_path), "meta": path_display(target, meta_path)},
        )
        # Printed on EVERY run, including the inline-finalization path below, so the ledger is never
        # silent about a divergence between the label and the evidence.
        print(
            f"plan_review_round_ledger: declared={args.review_round} "
            f"observed_successful_runs={observed_runs} effective_round={effective_round} "
            f"hard_cap={PLAN_REVIEW_HARD_CAP_ROUNDS}"
        )
        # Printed only when a lineage exists, so standalone output is unchanged. Since item 108
        # WS3 the resolver binds name-shape and work-item lineages too, so an UNDECLARED lineage
        # prints the same ledger -- the advisory surface and the resolver can never disagree.
        if chain_summary:
            print(plan_review_chain_ledger_line(chain_summary, chain_members))
            # Codex R1 P1: when this round inline-finalizes (finalize_requested), the finalize
            # call below prints its OWN chain advisory -- correctly suppressed there whenever the
            # round is capped/blocked, so the build-carry remedy is never contradicted. Printing
            # this run-time copy unconditionally reached that contradiction from an EARLIER site
            # in the same invocation, before the finalize call ever got a chance to suppress
            # anything. Print it here only on a bare run (finalize NOT requested this call), where
            # no later print gets a chance to say it.
            if not finalize_requested:
                advisory = plan_review_chain_advisory_line(chain_summary)
                if advisory:
                    print(advisory)
        if not predecessor_rel:
            # Adoption pressure stays: an undeclared `-vN` lineage now COUNTS advisorily, but it
            # is still unrecorded, and the flag is the only sanctioned way to record it.
            hint = plan_review_lineage_shape_hint(data, target, plan_path)
            if hint:
                print(hint)
        if not finalize_requested:
            print(f"plan_review_run_log: {log_path}")
            print(f"plan_review_run_meta: {meta_path}")
            print("plan_review_scope: plan-only")
            print("plan_review_code_diff_review: no")
            print("plan_review_native_review_required: one authoring-model native/Superpowers self-check before R1 only")
            print(f"plan_review_codex_fast_mode: {codex_fast_mode_status(data)}")
            print(f"plan_review_run_command: {review_command}")
            print(f"plan_review_run_exit_code: {wrapper_exit_code}")
            print(f"plan_review_no_output_timeout_seconds: {int(args.no_output_timeout_seconds)}")
            if stale_marker_path:
                print(f"plan_review_stale_marker: {stale_marker_path}")
            if review_failed_stale:
                print(
                    "plan_review_next_action: review produced no fresh output before the watchdog fired; recover or rerun "
                    "the configured review round and do not classify this frozen log as evidence"
                )
            else:
                # Past the target the finalize that follows REQUIRES a recorded note, so the printed
                # guidance must carry the flag: an agent following the tool must never
                # hit the error.
                note_hint = shlex.quote(exception_reason or "<reason this round was needed>")
                exception_flag = (
                    f" --exception-note {note_hint}"
                    if round_number is not None and round_number > PLAN_REVIEW_TARGET_ROUNDS
                    else ""
                )
                print(
                    "plan_review_next_action: inspect this log once, classify findings, then run "
                    f"`tautline finalize-plan-review --target {guard_target_argument(target)} "
                    f"--plan {shlex.quote(plan_rel)} "
                    f"--log {shlex.quote(path_relative_to_target(target, log_path))} --round {shlex.quote(args.review_round)} "
                    "--verdict <clean|clean-with-deferrals|blocked> "
                    "--unresolved-critical-count <n> "
                    f"--unresolved-p1-count <n>{exception_flag}`; "
                    "do not rerun Codex just to bind the manifest"
                )
            return wrapper_exit_code
        return finalize_trusted_plan_review(
            data=data,
            target=target,
            plan_path=plan_path,
            log_path=log_path,
            review_round=args.review_round,
            model=args.model,
            verdict=args.verdict,
            unresolved_critical_count=args.unresolved_critical_count,
            unresolved_p1_count=args.unresolved_p1_count,
            classified_findings_json=args.classified_findings_json,
            recorded_by="tautline run-plan-review",
            error_prefix="plan_review_run_error",
            structural_critical_evidence=getattr(args, "structural_critical_evidence", None),
            exception_note=getattr(args, "exception_note", None),
        )
    finally:
        # Released in a finally so a wedged, watchdog-killed or exception-ended round frees
        # the lease too -- the failure modes that most need a clean re-run are exactly the
        # ones that would otherwise leave it held. Wrapping THROUGH the meta write means
        # there is no window where the lease is gone but the evidence is not yet visible.
        # RELEASE ONLY WHAT THIS RUN STILL OWNS. A cross-host round that outlives the TTL can be
        # reclaimed while this process is still inside the try, and a new launcher then holds a
        # FRESH lease at the same path -- an unconditional unlink deleted that one, leaving the
        # second review unprotected and a third free to start on the same plan hash. Codex R3 P2.
        # The same ownership question the reclaim path already asks, asked once more on the way
        # out. Not owning it is normal here, not an error: it means someone else already decided
        # this round was gone.
        plan_review_release_inflight_lease(lease_path)


def finalize_trusted_plan_review(
    *,
    data: dict,
    target: Path,
    plan_path: Path,
    log_path: Path,
    review_round: str,
    model: str,
    verdict: str,
    unresolved_critical_count: int,
    unresolved_p1_count: int,
    classified_findings_json: str | None,
    recorded_by: str,
    error_prefix: str,
    structural_critical_evidence: str | None = None,
    exception_note: str | None = None,
) -> int:
    source_root = planning_source_root(data, target)
    errors: list[str] = []
    if not plan_path.exists() or not plan_path.is_file():
        errors.append(f"plan missing: {plan_path}")
    elif not plan_is_under_a_configured_root(data, target, plan_path):
        errors.append(f"plan outside source-of-truth path: {plan_path} not under {source_root}")
    if not log_path.exists() or not log_path.is_file():
        errors.append(f"plan review log missing: {log_path}")
    elif not path_is_under(log_path, target):
        errors.append(f"plan review log must live under the target lane: {log_path}")
    if errors:
        for error in errors:
            print(f"{error_prefix}: {error}", file=sys.stderr)
        return 1

    plan_rel = plan_root_relative_reference(data, target, plan_path)
    plan_hash = plan_content_sha256(plan_path)
    round_number = plan_review_round_number(review_round)
    # Finalizing WRITES the manifest, so a past-target round must carry a recorded note here: a
    # detected convergence state authorizes the run, but only an explicit reason is recordable.
    recorded_note = plan_review_exception_note(exception_note, structural_critical_evidence)
    # The past-cap REMEDY is a property of the BOUND manifest, never of the round being submitted:
    # the round the cap refuses is never written, so its counts say nothing about what the operator
    # can actually finalize. Choosing on the submitted counts would print "finalize the existing
    # review evidence" whenever THIS round happens to be clean -- even when the bound evidence is
    # stale and plan-finalization-precheck provably rejects it. Refusal itself stays unconditional.
    bound_manifest = load_plan_review_manifest(plan_review_manifest_path(data, target, plan_path))
    round_cap_errors = plan_review_round_cap_errors(
        round_number=round_number,
        exception_reason=recorded_note,
        unresolved_blockers=plan_review_bound_evidence_is_unfinalizable(bound_manifest, plan_hash),
        capped_evidence_bound=plan_review_manifest_is_capped_for_hash(bound_manifest, plan_hash),
    )
    if round_cap_errors:
        for error in round_cap_errors:
            print(f"{error_prefix}: {error}", file=sys.stderr)
        return 1

    findings = parse_classified_findings(classified_findings_json)
    derived_critical, derived_p1 = finding_counts(findings)
    if derived_critical != unresolved_critical_count or derived_p1 != unresolved_p1_count:
        print(f"{error_prefix}: unresolved Critical/P1 counts must match classified-findings-json", file=sys.stderr)
        return 1
    # Codex R1 P2 on this diff: the deferral contract was enforced only where the precheck READS
    # the manifest, so a writer would happily persist an invalid deferral and the lane would learn
    # about it one command later, from a file it had already written. Refuse at the producer, the
    # same shape item 74's T3.0 demands on the implementation path. Not version-gated: a writer
    # runs in the current CLI by definition.
    deferral_errors = critical_origin_deferral_errors(findings)
    if deferral_errors:
        for error in deferral_errors:
            print(f"{error_prefix}: {error}", file=sys.stderr)
        return 1

    run_meta, run_meta_path, run_meta_load_errors = load_plan_review_run_meta(log_path)
    if run_meta_load_errors:
        for error in run_meta_load_errors:
            print(f"{error_prefix}: {error}", file=sys.stderr)
        return 1
    assert run_meta is not None
    for required_field in ["review_command", "wrapper_exit_code", "review_scope", "code_diff_review"]:
        if required_field not in run_meta:
            print(f"{error_prefix}: plan review run metadata missing field: {required_field}", file=sys.stderr)
            return 1
    review_command = str(run_meta["review_command"])
    try:
        wrapper_exit_code = int(run_meta["wrapper_exit_code"])
    except (TypeError, ValueError):
        print(f"{error_prefix}: plan review run metadata wrapper_exit_code must be an integer", file=sys.stderr)
        return 1
    if run_meta.get("review_scope") != "plan-only" or run_meta.get("code_diff_review") is not False:
        print(f"{error_prefix}: plan review run metadata must prove plan-only scope and code_diff_review=false", file=sys.stderr)
        return 1
    run_meta_errors = validate_plan_review_run_meta(
        run_meta,
        target,
        plan_rel,
        plan_hash,
        review_command,
        log_path,
        wrapper_exit_code,
    )
    if run_meta_errors:
        for error in run_meta_errors:
            print(f"{error_prefix}: {error}", file=sys.stderr)
        return 1

    command_errors = review_command_errors(data, review_command, plan_rel, plan_hash)
    if command_errors:
        for error in command_errors:
            print(f"{error_prefix}: {error}", file=sys.stderr)
        return 1
    log_text = log_path.read_text(encoding="utf-8", errors="replace")
    # run_plan_review wrote this log, so its sentinels bound a real run: pass authority, plus the
    # nonce when the run meta carries one (absent on every run meta written before the frame
    # existed, which then resolves positionally).
    frame_nonce = plan_review_run_meta_frame_nonce(run_meta_path)
    log_errors = review_log_errors(
        log_text,
        review_command,
        plan_rel,
        plan_hash,
        expected_nonce=frame_nonce,
        authoritative=True,
    )
    log_errors.extend(
        review_log_verdict_errors(
            log_text,
            verdict,
            unresolved_critical_count,
            unresolved_p1_count,
            findings,
            expected_nonce=frame_nonce,
            authoritative=True,
            # Unconditional on the trusted path. This helper has TWO callers -- the
            # finalize-plan-review verb and run-plan-review's inline finalize -- so this makes
            # `run-plan-review --verdict ...` strict too. That is intended, not incidental: the
            # trusted classification boundary is this helper, and a verdict attested through
            # the run verb must meet the same contract as one attested through finalize. Do not
            # "fix" it by moving the kwarg into the verb.
            require_findings_section=True,
            # NAME A COMMAND THE GUARD WILL ACCEPT. The run meta for this round was already
            # written by `run-plan-review` before the log reached this check, so a bare re-run of
            # the SAME round is refused by the duplicate-run guard ("finalize that run instead") --
            # and finalizing is exactly what just failed. That is a closed loop, which is the
            # dead-end shape this framework refuses to ship. Codex R1 P1. The log carries no
            # recognisable verdict, so its meta attests nothing and removing it loses no evidence;
            # the recovery says so, and names the exact path rather than making the lane find it.
            rerun_command=(
                f"rm {shlex.quote(str(run_meta_path))} "
                "&& tautline run-plan-review --target "
                f"{guard_target_argument(target)} "
                f"--plan {shlex.quote(plan_rel)} "
                f"--round {shlex.quote(str(review_round))}"
                "   # the run recorded no verdict, so its meta attests nothing"
            )
            if run_meta_path
            else (
                "tautline run-plan-review --target "
                f"{guard_target_argument(target)} "
                f"--plan {shlex.quote(plan_rel)} "
                f"--round {shlex.quote(str(review_round))}"
            ),
        )
    )
    if log_errors:
        for error in log_errors:
            print(f"{error_prefix}: {error}", file=sys.stderr)
        return 1

    current_blockers = plan_review_blocker_total(unresolved_critical_count, unresolved_p1_count)
    existing_manifest_path = plan_review_manifest_path(data, target, plan_path)
    existing_manifest_present = existing_manifest_path.exists()
    previous_blockers = previous_plan_review_blocker_total(existing_manifest_path)
    # The convergence remedy must be chosen by what was SPENT, not by what this round was called.
    # A blocked round labelled `R1` in a lane that has already burned four reviewer invocations is
    # at the hard cap, and telling it to "rerun R2" sends it at a gate that will refuse (item 31:
    # label trust in the remaining plan-review call sites). The recorded ledger is authoritative
    # when the bound run meta carries it; a pre-release run meta has none, and then the declared
    # round is the only thing there is.
    recorded_effective = plan_review_run_meta_ledger_value(run_meta_path, "effective_round")
    effective_round = max(round_number or 0, recorded_effective or 0)
    convergence_errors: list[str] = []
    # THE RELEASE VALVE (D2). This branch used to be the refusal that made the whole loop possible:
    # it prescribed decomposing the plan into smaller source-of-truth plans as the remedy, and a
    # successor plan is a new file path, and a new file path is a fresh 4-round budget. The gate
    # refusing here was therefore not bounding the ceremony -- it was PRESCRIBING the refill.
    #
    # It now finalizes instead. The budget is still absolute (a fifth round is still refused at
    # launch); what changed is that spending it ends the planning, honestly, with the blockers
    # written down at their real severity and carried into the medium where they can be falsified
    # against an artifact. No state of this gate refuses every exit.
    asserted_verdict = verdict
    # SPENT INVOCATIONS, never the declared label (Codex R1 P1). `effective_round` is
    # max(declared, observed+1), so a plan whose FIRST round is labelled `--round R4` reads as
    # round 4 and would reach the valve after one Codex invocation -- buying the release with a
    # label while R1-R3 never happened. That is the same label-trust defect the round cap itself
    # was rebuilt to close (item 24), reintroduced through a new door.
    #
    # The bound run meta's own ledger is authoritative when it carries one; a pre-release run meta
    # carries nothing, and then the count of successful run metas on disk is the honest floor. This
    # finalize's own run is already recorded by the time it runs, so that count includes it.
    # Only a SUCCESSFUL current run counts toward the release (Codex confirming-round P2). A
    # wrapper that exits nonzero can still emit classifiable output; counting it would open the
    # valve on a run that produced no usable review, write `capped-with-open-findings`, and then
    # fail -- leaving a manifest that a later cap check could mistake for finalizable evidence and
    # act on by sending the lane to BUILD.
    recorded_spend = plan_review_run_meta_ledger_value(run_meta_path, "observed_successful_runs")
    meta_ledger_spend = (
        recorded_spend + (1 if wrapper_exit_code == 0 else 0)
        if recorded_spend is not None
        else plan_review_observed_run_count(data, target, plan_rel)
    )
    # ...AND the durable record reads THROUGH the finalize (item 108 WS2 T2.2): the bound run's
    # own invocation record is already on disk (charged only if the wrapper succeeded), so the
    # record-backed member spend covers it without the +1. Evidence can only read the spend UP,
    # never down -- a fresh worktree's bound meta carrying a smaller lane-local ledger no longer
    # walks the budget under the committed cumulative count, and the manifest this finalize
    # writes stays a display copy of the bound meta's ledger exactly as before.
    member_spend, _member_spend_source = plan_review_member_spend(data, target, plan_rel)
    spent_invocations = max(member_spend or 0, meta_ledger_spend)
    # `existing_manifest_present` is a REQUIREMENT, not a refinement (Codex remediation-round P1).
    # The valve counts successful reviewer INVOCATIONS; it said nothing about whether those
    # invocations were ever classified. Launch R1-R3 under distinct labels without finalizing any
    # of them and all three metas count, so finalizing R4 derives the capped verdict here -- ahead
    # of the `not existing_manifest_present` convergence check below, which exists precisely to
    # refuse a late round that cannot prove what the earlier ones found. `plan-finalization-
    # precheck` then passes on four metas whose first three logs were never classified, and every
    # Critical those rounds raised is gone: not carried, not deferred, just absent.
    #
    # That is the failure the valve exists to prevent, arriving through the valve. Requiring a
    # finalized predecessor costs the legitimate path nothing -- each round finalizes inline, so
    # by R4 a manifest is always present -- and a lane without one falls through to the
    # convergence branch that names the real problem.
    # WHAT THIS DOES NOT PROVE, stated because two earlier versions of this comment each claimed
    # more than the code delivered. `existing_manifest_present` shows that SOME round was
    # classified, not that every one was: finalize R1, leave R2/R3 unclassified, and R4 still
    # reaches the valve with their findings never carried.
    #
    # A continuity check was written for that and REMOVED again. It compared the current run
    # against the latest manifest, which proves only that this round immediately follows that one;
    # four successive rounds then found holes in it and in the recovery instruction it needed
    # (each fix defective in the next round, the last one prescribing a backfill that OVERWRITES
    # the single per-plan manifest and can erase the blocker it was recovering). Four rounds of
    # findings in one small area is a design being wrong, not prose.
    #
    # Closing it properly needs per-round evidence that survives out-of-order finalization -- a
    # durable record this codebase does not have, and a COUNTING concern belonging to the
    # workstream that owns round counting rather than the one that owns the cap's exit. Deferred
    # with a decision record and disclosed in the PR body rather than half-built here.
    capped_with_open_findings = (
        current_blockers > 0
        and spent_invocations >= PLAN_REVIEW_HARD_CAP_ROUNDS
        and existing_manifest_present
    )
    # A clean assertion cannot ride the valve (Codex round 3 P2). `--verdict clean` with nonzero
    # counts used to reach the derivation, get recorded as `asserted_verdict`, and return success
    # -- and then `plan-finalization-precheck` rejected the manifest, because the guard added last
    # round refuses a capped record asserting clean. A successful finalize whose evidence the very
    # next required gate calls unusable is the deadlock this release exists to remove, reintroduced
    # by my own fix. Caught here, before the manifest is written, where the message can still name
    # the contradiction the lane actually typed.
    if capped_with_open_findings and verdict in INSTRUMENTATION_FINALIZE_CLEAN_VERDICTS:
        print(
            f"{error_prefix}: --verdict {verdict} was submitted with "
            f"{current_blockers} unresolved Critical/P1 finding(s) at the round cap; a capped "
            "finalize carries open blockers forward, so the asserted verdict must be blocked",
            file=sys.stderr,
        )
        return 1
    if capped_with_open_findings:
        findings = plan_review_carry_blockers(findings, effective_round)
        verdict = PLAN_REVIEW_CAPPED_VERDICT
    elif current_blockers > 0:
        # The three convergence refusals below record `blocked`, which plan-finalization-precheck
        # correctly refuses -- the note keeps that from reading as a second blocker. The capped
        # path above no longer needs the note: precheck accepts `capped-with-open-findings`
        # directly. (This note predates the valve; item 106 WS4 threaded it through the ladder
        # when the hard-cap refusal still lived here.)
        precheck_note = (
            "plan-finalization-precheck correctly refuses this blocked verdict, so do not wait on "
            "it or treat its refusal as a blocker itself"
        )
        if (
            effective_round >= PLAN_REVIEW_DECOMPOSE_IF_STALLED_ROUND
            and not existing_manifest_present
        ):
            convergence_errors.append(
                "plan review round 3 or later has unresolved Critical/P1 blockers but no previous "
                f"manifest to prove convergence; restore the prior review manifest from its "
                f"original log if it was lost, else -- {precheck_note} -- carry every unresolved "
                "Critical/P1 into the implementation-review focus list yourself and proceed "
                "to the build straight away without it; do not ask for a path choice"
            )
        elif (
            effective_round >= PLAN_REVIEW_DECOMPOSE_IF_STALLED_ROUND
            and previous_blockers is None
        ):
            convergence_errors.append(
                "plan review round 3 or later cannot read previous blocker evidence; append a "
                "correction record (`tautline record-plan-review --target <lane> --plan <plan> "
                "--correct <nonce|baseline> --correction-note '<why>'`) -- never overwrite or "
                "regenerate review evidence -- "
                f"or -- {precheck_note} -- carry every unresolved Critical/P1 into the "
                "implementation-review focus list yourself and proceed to the build straight away "
                "without it; do not ask for a path choice"
            )
        elif (
            effective_round >= PLAN_REVIEW_DECOMPOSE_IF_STALLED_ROUND
            and current_blockers >= previous_blockers
        ):
            convergence_errors.append(
                "plan review has not reduced unresolved Critical/P1 blockers by round 3; do not "
                f"ask for a path choice; {precheck_note}: carry every unresolved Critical/P1 into "
                "the implementation-review focus list yourself and proceed to the build straight "
                "away without it, never a successor plan for budget"
            )

    std_cfg = plan_authoring_module().normalize_planning_authoring_standard(data)
    std_level = std_cfg["enforcement"]
    if std_level != "off":
        # Use plan_review_text (strips the appended Cross-Model Review Evidence) so an exception
        # note that happens to carry model-tier/autonomy terminology cannot satisfy markers the
        # authored tasks lack.
        shape_text = plan_review_text(plan_path)
        shape_issues = plan_authoring_module().plan_authoring_standard_issues(shape_text)
        if shape_issues:
            # Full text to stderr (the actionable-error contract); guard_log_event applies its
            # own telemetry length limit.
            detail = "; ".join(shape_issues)
            if std_level == "block":
                print(f"{error_prefix}: plan-authoring standard not met: {detail}", file=sys.stderr)
                guard_log_event(target, "plan.authoring_standard", True, "state", detail)
                return 1
            if std_level == "advise":
                for issue in shape_issues:
                    print(f"plan_authoring_standard_warning: {issue}", file=sys.stderr)
            guard_log_event(target, "plan.authoring_standard", True, "state", detail)
        else:
            guard_log_event(target, "plan.authoring_standard", False, "state", "compliant")

    # The durable per-round record (item 108 WS1 T1.2): the bind APPENDS a classification record
    # referencing the invocation; it never rewrites the invocation record the launch appended.
    #
    # BEFORE the manifest write, and before the basis is derived from it (WS5 remediation P1). The
    # first cut wrote the manifest -- carrying `round-record-verified` -- and appended this record
    # afterwards, inside a handler that turns an OSError into a stderr line and a return. Finalize
    # a capped round with the record directory unwritable and the run exited 0 with a manifest
    # certifying its carried list against a classification record that does not exist: a control
    # reporting success while the thing it counts is already lost, which is the named defect class
    # this item was opened to remove. Ordering it first makes the record the fact and the manifest
    # the report of it. If the manifest write then fails, an append-only classification record
    # exists for a round with no manifest -- evidence surviving its report, which is the safe
    # direction and the one the whole record design already takes.
    classification_recorded = plan_review_append_classification_record(
        data=data,
        target=target,
        plan_path=plan_path,
        plan_rel=plan_rel,
        plan_hash=plan_hash,
        log_path=log_path,
        run_meta_path=run_meta_path,
        declared_round=str(review_round),
        verdict=verdict,
        unresolved_critical_count=unresolved_critical_count,
        unresolved_p1_count=unresolved_p1_count,
        findings_count=len(findings),
        recorded_by=recorded_by,
    )

    # The valve's disclosed precondition, UPGRADED ON PROOF (item 108 WS5 T5.1, decision DF).
    # Read before the manifest write so the token the record carries and the line the lane reads
    # are one derivation -- and read from DISK, so the bound round proves itself through the
    # record appended above rather than through a digest the writer promises to persist later.
    carried_findings_basis = ""
    basis_counted = basis_proven = basis_members = 0
    basis_gaps: list[str] = []
    basis_floors: list[str] = []
    if capped_with_open_findings:
        (
            carried_findings_basis,
            basis_counted,
            basis_proven,
            basis_members,
            basis_gaps,
            basis_floors,
        ) = plan_review_carried_findings_basis(data, target, plan_rel)
        if not classification_recorded:
            # Belt AND braces. The disk read above already misses this round when its invocation
            # record exists; when the whole record tree is unwritable the invocation record is
            # missing too, the counted total silently drops by one, and what is left could still
            # read as complete. A round whose classification did not persist can never be part of
            # a verified basis, whatever the surviving records happen to say.
            carried_findings_basis = PLAN_REVIEW_CARRIED_FINDINGS_BASIS
            basis_floors = [
                f"{plan_rel} round {review_round}: this finalize's own classification record "
                "could not be appended (see plan_review_round_record_error above), so the round "
                "this manifest records is unproven and may be in neither total",
                *basis_floors,
            ]

    # Codex R1 P1 (WS5 fresh lineage): ORDERING ALONE CANNOT MAKE THIS SAFE, and the comment
    # above used to claim it could. Appending the classification first closed "manifest says
    # verified, record never landed" but opened its mirror image: if the manifest write fails
    # AFTER the append, an append-only classification record survives for a round whose manifest
    # and classified_findings were never written -- and a LATER capped finalize reads that orphan
    # as proof, certifying a round whose blockers were never carried into the binding focus list.
    # Same defect class, opposite direction.
    #
    # A classification proves a round only if the finalize that appended it COMPLETED, and the
    # append-only design already carries the tool for saying so: a compensating `correction`
    # record. If the manifest write raises, the classification just appended is invalidated by a
    # correction naming it, and the proof reader skips any classification a correction retracts.
    # Nothing is rewritten or deleted, and the failure is still raised to the caller.
    try:
        manifest_path, manifest = write_plan_review_manifest(
            data=data,
            target=target,
            plan_path=plan_path,
            plan_rel=plan_rel,
            plan_hash=plan_hash,
            log_path=log_path,
            review_command=review_command,
            reviewer="codex",
            model=model,
            review_round=review_round,
            wrapper_exit_code=wrapper_exit_code,
            verdict=verdict,
            unresolved_critical_count=unresolved_critical_count,
            unresolved_p1_count=unresolved_p1_count,
            findings=findings,
            recorded_by=recorded_by,
            run_meta_path=run_meta_path,
            exception_note=recorded_note,
            asserted_verdict=asserted_verdict,
            carried_findings_basis=carried_findings_basis,
        )
    except BaseException:
        # The manifest never landed, so the classification appended just above describes a round
        # with no report. Retract it with a correction rather than leaving an orphan that a later
        # finalize would read as proof. Append-only: nothing is rewritten or removed, and the
        # original failure is re-raised untouched.
        if classification_recorded:
            plan_review_retract_classification_record(
                data=data,
                target=target,
                plan_path=plan_path,
                plan_rel=plan_rel,
                classification_record_id=classification_recorded,
                declared_round=str(review_round),
                recorded_by=recorded_by,
            )
        raise
    print(f"plan_review_manifest: {manifest_path}")
    print(f"plan_review_run_log: {log_path}")
    print(f"plan_review_run_meta: {run_meta_path}")
    print(f"plan_review_run_command: {review_command}")
    next_round = (round_number or 0) + 1
    if capped_with_open_findings:
        carried = plan_review_carried_findings(manifest)
        # Enumerated, not counted. A lane handed "3 findings carried" has to open the JSON to
        # learn what it now owes; the obligation is binding, so it is printed where the lane is
        # already looking.
        for item in carried:
            print(
                "plan_review_carried_focus: "
                f"[{str(item.get('severity', item.get('priority', 'unknown'))).upper()}] "
                f"{str(item.get('id') or item.get('title') or 'finding')} -- "
                f"{' '.join(str(item.get('summary') or 'no summary recorded').split())[:160]} "
                "(BINDING)"
            )
        next_action = (
            f"the plan-review budget is spent -- {spent_invocations} of "
            f"{PLAN_REVIEW_HARD_CAP_ROUNDS} reviewer invocations against this plan: "
            f"{len(carried)} unresolved Critical/P1 finding(s) are "
            "recorded as carried and are BINDING implementation-review focus items, so run "
            "plan-finalization-precheck and start implementation. Do not spawn a successor plan "
            "and do not launch another round"
        )
        print(
            f"plan_review_capped: verdict={PLAN_REVIEW_CAPPED_VERDICT}; "
            f"asserted_verdict={asserted_verdict}; carried_binding_findings={len(carried)}; "
            f"spent_invocations={spent_invocations}; effective_round={effective_round}"
        )
        # What the carried list rests on, said out loud where the lane is already reading -- and
        # since item 108 WS5, PROVEN rather than merely disclosed whenever the durable record can
        # prove it. When it cannot, the line names the counted rounds that lack a classification
        # record: an unverified claim a lane can act on beats a warning it can only acknowledge.
        print(
            plan_review_capped_disclosure_line(
                carried_findings_basis,
                basis_counted,
                basis_proven,
                basis_members,
                basis_gaps,
                basis_floors,
            )
        )
    elif convergence_errors:
        next_action = (
            "plan-finalization-precheck correctly refuses this blocked verdict -- do not wait on "
            "it: carry every unresolved Critical/P1 into the implementation-review focus list "
            "yourself and proceed to the build straight away without it, never a successor plan "
            "for budget"
        )
    elif unresolved_critical_count or unresolved_p1_count:
        # UNCHANGED BY THIS RELEASE, DELIBERATELY. Three successive review rounds tried to make
        # this message smarter -- derive the round from the spend, then special-case the exhausted
        # budget, then prescribe backfilling the unclassified runs -- and each attempt was itself
        # found defective by the next round: the first dead-ended the recovery by leaving a run
        # meta unbound, the second still advertised a round the cap refuses, and the third
        # prescribed a backfill that OVERWRITES the single per-plan manifest and can erase the
        # very blocker it was recovering.
        #
        # That is four rounds of findings in one small area, which says the design is wrong rather
        # than the wording. A correct recovery needs per-round evidence that survives out-of-order
        # finalization -- the same durable per-round record the continuity proof needs -- and that
        # is the round-counting workstream's to build. So this release leaves the message exactly
        # as it shipped: the pre-existing "round 5 of 4" wording for a label-inflated lane is a
        # wart that predates this branch and is unchanged by it, routed as its own item rather
        # than half-fixed here. Reverting is the honest move; three of my own P1s came from
        # improving it.
        next_action = (
            f"fix the Critical/P1 blockers and self-authorize round {next_round} of "
            f"{PLAN_REVIEW_HARD_CAP_ROUNDS} with --exception-note (no operator authorization "
            "needed), or transfer non-blocking findings into implementation review focus"
            if next_round > PLAN_REVIEW_TARGET_ROUNDS
            else (
                f"fix the Critical/P1 blockers and rerun round {next_round} of "
                f"{PLAN_REVIEW_TARGET_ROUNDS}"
            )
        )
    else:
        next_action = "run plan-finalization-precheck and finalize only if it passes"
    # Round status renders against the TARGET on the normal path, so a plan that converges within
    # two rounds prints exactly what it printed before the ladder existed. The hard cap governs
    # refusal, not display.
    within_target = (round_number or 0) <= PLAN_REVIEW_TARGET_ROUNDS
    round_scale = PLAN_REVIEW_TARGET_ROUNDS if within_target else PLAN_REVIEW_HARD_CAP_ROUNDS
    print(
        "plan_review_round_status: "
        f"round {round_number} of {round_scale}"
        f"{' (recorded convergence exception)' if recorded_note else ''}; "
        f"verdict={verdict}; "
        f"unresolved_critical={unresolved_critical_count}; "
        f"unresolved_p1={unresolved_p1_count}; "
        f"next_action={next_action}"
    )
    # Succession-chain accounting (item 32). The STATUS counts come from the manifest just
    # written, never from a fresh walk: a run meta landing between the launch and this finalize
    # would make a recomputed status contradict the record it sits beside. The walk runs only to
    # refresh the members list and the advisory, both labelled as of now.
    chain_status = plan_review_chain_status_line(manifest)
    chain_refs = plan_review_chain_event_refs(manifest)
    if chain_status:
        print(chain_status)
        chain_members, chain_truncated = plan_review_chain_members(data, target, plan_rel)
        chain_summary = plan_review_chain_summary(chain_members, chain_truncated)
        print(
            "plan_review_chain_members: "
            f"{plan_review_chain_members_display(chain_members)} (refreshed at finalize)"
        )
        # Codex R1 P1: this advisory's own remedy text ("decompose the scope into smaller
        # independent source-of-truth plans") is the exact split instruction the convergence
        # ladder above just replaced with "carry into the build" -- printing both in the same
        # finalize call sends contradictory directions for the highest-spend chains, the ones a
        # cap-state message is already governing. Suppressed whenever convergence_errors fired;
        # the authoritative remedy already printed above is what a capped lane should read.
        # The capped finalize is the same contradiction one step later: the valve just told the
        # lane to build, so the advisory's split remedy is suppressed there too.
        if not convergence_errors and not capped_with_open_findings:
            advisory = plan_review_chain_advisory_line(chain_summary, surface="finalize")
            if advisory:
                print(advisory)
    severity = plan_review_finalize_event_severity(
        capped=capped_with_open_findings,
        convergence_errors=bool(convergence_errors),
        blockers=current_blockers,
        wrapper_exit_code=wrapper_exit_code,
    )
    try_write_event(
        data,
        target,
        event="plan_review_finalized",
        severity=severity,
        plain=f"Plan review evidence was finalized for {plan_rel}: {verdict}, Critical={unresolved_critical_count}, P1={unresolved_p1_count}.",
        next_action=next_action,
        refs={
            "plan": plan_rel,
            "manifest": path_display(target, manifest_path),
            "log": path_display(target, log_path),
            # T2: structured fields the T3 reducer will read to choose plan_review_clean vs.
            # plan_review_blocked -- never freeform text, always one of PLAN_REVIEW_ALL_VERDICTS.
            "verdict": verdict,
            "unresolved_critical_count": str(unresolved_critical_count),
            "unresolved_p1_count": str(unresolved_p1_count),
            **chain_refs,
        },
    )
    if convergence_errors:
        for error in convergence_errors:
            print(f"plan_review_convergence_error: {error}", file=sys.stderr)
        return 2
    return wrapper_exit_code


def finalize_plan_review(args: argparse.Namespace) -> int:
    data, _project_path, target = lane_project(args)
    plan_path = plan_root_resolve(data, target, args.plan).resolve(strict=False)
    log_path = (args.log.expanduser() if args.log.is_absolute() else target / args.log).resolve(strict=False)
    return finalize_trusted_plan_review(
        data=data,
        target=target,
        plan_path=plan_path,
        log_path=log_path,
        review_round=args.review_round,
        model=args.model,
        verdict=args.verdict,
        unresolved_critical_count=args.unresolved_critical_count,
        unresolved_p1_count=args.unresolved_p1_count,
        classified_findings_json=args.classified_findings_json,
        recorded_by="tautline finalize-plan-review",
        error_prefix="plan_review_finalize_error",
        structural_critical_evidence=getattr(args, "structural_critical_evidence", None),
        exception_note=getattr(args, "exception_note", None),
    )


def record_plan_review(args: argparse.Namespace) -> int:
    data, _project_path, target = lane_project(args)
    plan_path = plan_root_resolve(data, target, args.plan).resolve(strict=False)
    source_root = planning_source_root(data, target)
    errors: list[str] = []
    if not plan_path.exists() or not plan_path.is_file():
        errors.append(f"plan missing: {plan_path}")
    elif not plan_is_under_a_configured_root(data, target, plan_path):
        errors.append(f"plan outside source-of-truth path: {plan_path} not under {source_root}")
    if errors:
        for error in errors:
            print(f"plan_review_record_error: {error}", file=sys.stderr)
        return 1

    plan_rel_reference = plan_root_relative_reference(data, target, plan_path)
    # The correction writer (item 108 WS1 T1.2): the ONLY sanctioned amendment to the durable
    # per-round record is appending a new record that references the original. It takes no
    # import evidence -- a correction is not a review.
    if getattr(args, "correct", None):
        import_flags = [
            flag
            for flag, value in (
                ("--log", args.log),
                ("--reviewer", args.reviewer),
                ("--wrapper-exit-code", args.wrapper_exit_code),
                ("--verdict", args.verdict),
                ("--unresolved-critical-count", args.unresolved_critical_count),
                ("--unresolved-p1-count", args.unresolved_p1_count),
                ("--classified-findings-json", args.classified_findings_json),
            )
            if value is not None
        ]
        if import_flags:
            print(
                "plan_review_record_error: --correct appends a correction record and takes no "
                f"import evidence; drop {', '.join(import_flags)} or drop --correct",
                file=sys.stderr,
            )
            return 1
        note = str(getattr(args, "correction_note", None) or "").strip()
        if not note:
            print(
                "plan_review_record_error: a correction carries its reason on the record: pass "
                "--correction-note '<why this correction is needed>'",
                file=sys.stderr,
            )
            return 1
        return plan_review_append_correction_record(
            data,
            target,
            plan_path,
            plan_rel_reference,
            corrects=str(args.correct).strip(),
            note=note,
            raise_prerecord_count_to=getattr(args, "raise_prerecord_count_to", None),
        )
    missing_import_flags = [
        flag
        for flag, value in (
            ("--log", args.log),
            ("--reviewer", args.reviewer),
            ("--wrapper-exit-code", args.wrapper_exit_code),
            ("--verdict", args.verdict),
            ("--unresolved-critical-count", args.unresolved_critical_count),
            ("--unresolved-p1-count", args.unresolved_p1_count),
        )
        if value is None
    ]
    if missing_import_flags:
        print(
            "plan_review_record_error: a diagnostic import requires "
            f"{', '.join(missing_import_flags)} (a correction instead passes --correct "
            "<nonce|baseline> with --correction-note)",
            file=sys.stderr,
        )
        return 1

    log_path = (args.log.expanduser() if args.log.is_absolute() else target / args.log).resolve(strict=False)
    if not log_path.exists() or not log_path.is_file():
        print(f"plan_review_record_error: log missing: {log_path}", file=sys.stderr)
        return 1
    if not path_is_under(log_path, target):
        print(
            f"plan_review_record_error: log must live under the target lane so the manifest can use a portable relative path: {log_path}",
            file=sys.stderr,
        )
        return 1
    if log_path.stat().st_mtime_ns < plan_path.stat().st_mtime_ns:
        print("plan_review_record_error: review log is older than the current plan; rerun review against the current plan", file=sys.stderr)
        return 1

    plan_rel = plan_root_relative_reference(data, target, plan_path)
    plan_hash = plan_content_sha256(plan_path)

    # record-plan-review writes the plan-review manifest schema too, so the convergence ladder
    # binds it identically: a secondary writer must never be a way around the recorded exception.
    # The past-cap remedy is read off the BOUND manifest for the same reason it is in the other two
    # writers -- the refused round is never written, so its counts cannot say whether the operator
    # has finalizable evidence in hand. Refusal itself remains unconditional.
    recorded_note = plan_review_exception_note(getattr(args, "exception_note", None))
    bound_manifest = load_plan_review_manifest(plan_review_manifest_path(data, target, plan_path))
    round_cap_errors = plan_review_round_cap_errors(
        round_number=plan_review_round_number(args.review_round),
        exception_reason=recorded_note,
        unresolved_blockers=plan_review_bound_evidence_is_unfinalizable(bound_manifest, plan_hash),
        capped_evidence_bound=plan_review_manifest_is_capped_for_hash(bound_manifest, plan_hash),
    )
    if round_cap_errors:
        for error in round_cap_errors:
            print(f"plan_review_record_error: {error}", file=sys.stderr)
        return 1

    findings = parse_classified_findings(args.classified_findings_json)
    # Same producer-side refusal as the run/finalize writer above (Codex R1 P2).
    deferral_errors = critical_origin_deferral_errors(findings)
    if deferral_errors:
        for error in deferral_errors:
            print(f"plan_review_record_error: {error}", file=sys.stderr)
        return 1
    review_command = args.review_command or codex_plan_wrapper(data)
    if args.reviewer.lower() != "codex":
        print("plan_review_record_error: reviewer must be codex for cross-model plan finalization evidence", file=sys.stderr)
        return 1
    command_errors = review_command_errors(data, review_command, plan_rel, plan_hash)
    if command_errors:
        for error in command_errors:
            print(f"plan_review_record_error: {error}", file=sys.stderr)
        return 1
    derived_critical, derived_p1 = finding_counts(findings)
    if derived_critical != args.unresolved_critical_count or derived_p1 != args.unresolved_p1_count:
        # Item 48 / no-dead-ends: the refusal used to state the mismatch and stop, leaving the lane
        # to guess which side was wrong. Print BOTH sides and the exact re-invocation -- the counts
        # are derived from the file the lane already wrote, so the fix is always mechanical.
        print(
            "plan_review_record_error: unresolved Critical/P1 counts must match "
            "classified-findings-json: the file derives "
            f"{derived_critical} Critical and {derived_p1} P1 (excluding resolved/deferred "
            f"statuses), but --unresolved-critical-count {args.unresolved_critical_count} and "
            f"--unresolved-p1-count {args.unresolved_p1_count} were passed. Re-run with "
            f"--unresolved-critical-count {derived_critical} --unresolved-p1-count "
            f"{derived_p1}, or correct the severity/status fields in the findings file",
            file=sys.stderr,
        )
        return 1
    log_text = log_path.read_text(encoding="utf-8", errors="replace")
    log_errors = review_log_errors(log_text, review_command, plan_rel, plan_hash)
    log_errors.extend(
        review_log_verdict_errors(
            log_text,
            args.verdict,
            args.unresolved_critical_count,
            args.unresolved_p1_count,
            findings,
        )
    )
    if log_errors:
        for error in log_errors:
            print(f"plan_review_record_error: {error}", file=sys.stderr)
        return 1
    run_meta, run_meta_path, run_meta_load_errors = load_plan_review_run_meta(log_path)
    if run_meta_load_errors:
        for error in run_meta_load_errors:
            print(f"plan_review_record_error: {error}", file=sys.stderr)
        return 1
    assert run_meta is not None
    run_meta_errors = validate_plan_review_run_meta(
        run_meta,
        target,
        plan_rel,
        plan_hash,
        review_command,
        log_path,
        args.wrapper_exit_code,
    )
    if run_meta_errors:
        for error in run_meta_errors:
            print(f"plan_review_record_error: {error}", file=sys.stderr)
        return 1
    manifest_path = plan_review_import_manifest_path(data, target, plan_path)
    manifest_path.parent.mkdir(parents=True, exist_ok=True)
    manifest = {
        "schema": PLAN_REVIEW_SCHEMA,
        "classifier_version": PLAN_REVIEW_CLASSIFIER_VERSION,
        "recorded_by": "tautline record-plan-review",
        "project": data["project"],
        "plan_path": plan_rel,
        "plan_content_sha256": plan_hash,
        "review_command": review_command,
        "log_path": path_relative_to_target(target, log_path),
        "log_sha256": file_sha256(log_path),
        "review_run_meta_path": path_relative_to_target(target, run_meta_path),
        "review_run_meta_sha256": file_sha256(run_meta_path),
        "reviewer": args.reviewer,
        "reviewer_model": args.model,
        "round": args.review_round,
        "wrapper_exit_code": args.wrapper_exit_code,
        "verdict": args.verdict,
        "unresolved_critical_count": args.unresolved_critical_count,
        "unresolved_p1_count": args.unresolved_p1_count,
        "classified_findings": findings,
        "timestamp": now_iso(),
    }
    if recorded_note:
        manifest["exception_note"] = recorded_note
    manifest_path.write_text(json.dumps(manifest, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    # The durable per-round record (item 108 WS1, finding 108-R4-P1-2): one deterministic rule
    # for imports -- pre-cutover digests classify as pre-record, everything else spends.
    plan_review_append_import_records(
        data=data,
        target=target,
        plan_path=plan_path,
        plan_rel=plan_rel,
        plan_hash=plan_hash,
        log_path=log_path,
        run_meta=run_meta,
        declared_round=str(args.review_round),
        verdict=args.verdict,
        unresolved_critical_count=args.unresolved_critical_count,
        unresolved_p1_count=args.unresolved_p1_count,
        findings_count=len(findings),
        reviewer=args.reviewer,
        reviewer_model=args.model,
        wrapper_exit_code=args.wrapper_exit_code,
    )

    print(f"plan_review_manifest: {manifest_path}")
    print(f"plan_review_plan: {plan_path}")
    print(f"plan_review_verdict: {args.verdict}")
    print("plan_review_record_warning: diagnostic import only; wrote .imported.json and did not update source plan evidence")
    print("plan_review_record_warning: plan-finalization-precheck trusts only the canonical run-plan-review manifest")
    return 0


def plan_finalization_precheck_errors(data: dict, target: Path, plan_arg: Path) -> tuple[list[str], Path | None, Path | None]:
    errors: list[str] = []
    plan_path = plan_root_resolve(data, target, plan_arg).resolve(strict=False)
    source_root = planning_source_root(data, target)
    if not plan_path.exists() or not plan_path.is_file():
        return [f"plan missing: {plan_path}"], plan_path, None
    if not plan_is_under_a_configured_root(data, target, plan_path):
        errors.append(f"plan outside source-of-truth path: {plan_path} not under {source_root}")
    exemption_errors = plan_review_exemption_errors(data, plan_path)
    if exemption_errors is not None:
        errors.extend(exemption_errors)
        return errors, plan_path, None
    errors.extend(validate_plan_substance(plan_path))
    raw_plan_text = plan_path.read_text(encoding="utf-8", errors="replace")
    errors.extend(behavior_source_material_citation_errors(data, raw_plan_text))
    errors.extend(behavior_role_vocabulary_errors(data, raw_plan_text))
    ac_cfg = data.get("planAcceptance") or DEFAULT_PLAN_ACCEPTANCE
    if ac_cfg.get("enforcement") == "block":
        errors.extend(plan_acceptance_binding_issues(raw_plan_text, ac_cfg, _plan_pending_tags(data)))
    # Plan-authoring standard: enforce at the precheck/ExitPlanMode seam too (not only at the
    # review-manifest write), so a plan finalized under a laxer enforcement level cannot slip
    # through a later `block` by reusing its existing manifest.
    std_cfg = plan_authoring_module().normalize_planning_authoring_standard(data)
    if std_cfg["enforcement"] == "block":
        std_text = plan_review_text(plan_path)
        for issue in plan_authoring_module().plan_authoring_standard_issues(std_text):
            errors.append(f"plan-authoring standard not met: {issue}")

    manifest_path = plan_review_manifest_path(data, target, plan_path)
    if not manifest_path.exists():
        errors.append(f"plan review manifest missing: {manifest_path}")
        return errors, plan_path, manifest_path
    try:
        manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
    except json.JSONDecodeError as exc:
        errors.append(f"plan review manifest invalid JSON: {exc}")
        return errors, plan_path, manifest_path

    required_fields = [
        "schema",
        "classifier_version",
        "recorded_by",
        "plan_path",
        "plan_content_sha256",
        "review_command",
        "log_path",
        "log_sha256",
        "review_run_meta_path",
        "review_run_meta_sha256",
        "reviewer",
        "reviewer_model",
        "round",
        "wrapper_exit_code",
        "verdict",
        "unresolved_critical_count",
        "unresolved_p1_count",
        "classified_findings",
        "timestamp",
    ]
    for field in required_fields:
        if field not in manifest:
            errors.append(f"plan review manifest missing field: {field}")
    if errors:
        return errors, plan_path, manifest_path

    # ROOT-AWARE, like the run that WROTE the manifest. Deriving this with
    # path_relative_to_target compared a lane-relative string against a `<root>:<path>` reference,
    # so a reviewed external plan could never pass finalization -- the flow dead-ended one step
    # before the gate it exists to reach. Codex R2 P1: one notion of how a plan is named, used by
    # the writer and the reader alike.
    expected_plan_rel = plan_root_relative_reference(data, target, plan_path)
    if manifest["schema"] != PLAN_REVIEW_SCHEMA:
        errors.append(f"plan review manifest schema mismatch: {manifest['schema']}")
    if manifest["classifier_version"] != PLAN_REVIEW_CLASSIFIER_VERSION:
        errors.append(
            f"plan review manifest classifier_version is stale: {manifest['classifier_version']} != {PLAN_REVIEW_CLASSIFIER_VERSION}"
        )
    if manifest["plan_path"] != expected_plan_rel:
        errors.append(f"plan review manifest plan_path mismatch: {manifest['plan_path']} != {expected_plan_rel}")
    current_plan_hash = plan_content_sha256(plan_path)
    if manifest["plan_content_sha256"] != current_plan_hash:
        errors.append("plan review manifest is stale: plan_content_sha256 does not match current plan content")
    if manifest["recorded_by"] not in PLAN_REVIEW_TRUSTED_RECORDERS:
        errors.append(f"plan review manifest recorded_by is not trusted: {manifest['recorded_by']}")
    try:
        wrapper_exit_code = int(manifest["wrapper_exit_code"])
    except (TypeError, ValueError):
        wrapper_exit_code = -1
    if wrapper_exit_code != 0:
        errors.append(f"plan review wrapper_exit_code is not clean: {manifest['wrapper_exit_code']}")
    # D2. A capped finalize is a LEGITIMATE finalization state, and this is the gate that decides
    # whether the release valve actually releases anything. Refusing it here would leave the lane
    # holding a successful `finalize-plan-review` that the very next command calls unusable -- the
    # 2026-07-14 deadlock moved one gate downstream, which is not a fix. The capped record earns
    # that acceptance by carrying its blockers: `plan_review_capped_manifest_errors` refuses a
    # capped verdict whose findings were not actually stamped as binding carried items, so
    # "capped" cannot become a way to declare open blockers away.
    capped = str(manifest["verdict"]).strip().lower() == PLAN_REVIEW_CAPPED_VERDICT
    if capped:
        errors.extend(plan_review_capped_manifest_errors(manifest))
        # ...AND the spend is re-derived from the durable round records (or, pre-record, the run
        # metadata on disk), never read out of the manifest (Codex confirming-round P1).
        # Everything checked above this line lives INSIDE
        # the manifest -- verdict, recorded_by, wrapper_exit_code, the carried stamps -- so a lane
        # holding a trusted `blocked` R1 manifest could edit that one file into
        # `capped-with-open-findings`, stamp its blockers carried/binding, and walk through this
        # gate having spent one reviewer invocation instead of four. `PLAN_REVIEW_CAPPED_VERDICT`
        # being absent from every `--verdict` choice list stops the verb from ASSERTING it; it
        # does nothing about the file. The valve's whole claim is "the budget is spent", so the
        # budget is the thing that must be proved, against evidence the manifest does not own.
        #
        # SCOPE: this proves the INVOCATION COUNT, not that each invocation was classified (Codex
        # round 4 P1). A forged capped manifest sitting on four spent-but-unclassified runs still
        # satisfies it. Proving classification needs the persisted continuity provenance deferred
        # above; counting is the half that can be proved from evidence the manifest does not own,
        # and it is stated as that rather than as the whole guarantee.
        #
        # Item 108 WS2: the durable record is now the first-choice evidence, so a fresh worktree
        # holding the committed records passes without the lane-local metas. The `manifest-floor`
        # fallback of the budget reader is deliberately NOT consulted here: that floor is read
        # out of the manifest itself, and this gate exists to prove the manifest's claim against
        # evidence the manifest does not own.
        recorded_member_spend = plan_review_recorded_member_spend(data, target, expected_plan_rel)
        observed_runs = (
            recorded_member_spend[0]
            if recorded_member_spend is not None
            else plan_review_observed_run_count(data, target, expected_plan_rel)
        )
        if observed_runs < PLAN_REVIEW_HARD_CAP_ROUNDS:
            errors.append(
                f"plan review manifest verdict {PLAN_REVIEW_CAPPED_VERDICT} claims the round "
                f"budget is spent, but only {observed_runs} successful reviewer invocation(s) are "
                f"recorded on disk for this plan (the valve opens at {PLAN_REVIEW_HARD_CAP_ROUNDS})"
                "; the capped verdict is DERIVED by finalize-plan-review from real runs and cannot "
                "be written into the manifest by hand"
            )
    elif manifest["verdict"] not in PLAN_REVIEW_ALLOWED_VERDICTS:
        errors.append(f"plan review verdict does not allow finalization: {manifest['verdict']}")
    if str(manifest.get("reviewer", "")).lower() != "codex":
        errors.append("plan review manifest must be from the configured Codex cross-model reviewer")
    unresolved_counts: dict[str, int | None] = {}
    for key in ["unresolved_critical_count", "unresolved_p1_count"]:
        try:
            count = int(manifest[key])
        except (TypeError, ValueError):
            errors.append(f"plan review manifest {key} must be an integer")
            unresolved_counts[key] = None
            continue
        unresolved_counts[key] = count
        if count != 0 and not capped:
            errors.append(f"plan review manifest {key} must be 0 before finalization")
    if not isinstance(manifest["classified_findings"], list):
        errors.append("plan review manifest classified_findings must be an array")
    else:
        derived_critical, derived_p1 = finding_counts(manifest["classified_findings"])
        if unresolved_counts.get("unresolved_critical_count") != derived_critical:
            errors.append("plan review manifest unresolved_critical_count does not match classified_findings")
        if unresolved_counts.get("unresolved_p1_count") != derived_p1:
            errors.append("plan review manifest unresolved_p1_count does not match classified_findings")
        if manifest["verdict"] == "clean-with-deferrals" and not manifest["classified_findings"]:
            errors.append("clean-with-deferrals requires classified_findings evidence")
        # Item 74 WS3: `status: deferred` was the cheapest escape on this record, and nothing
        # asked why a Critical was non-blocking or what criterion it was judged against.
        errors.extend(
            critical_origin_deferral_errors(
                [item for item in manifest["classified_findings"] if isinstance(item, dict)]
            )
        )

    review_command = str(manifest["review_command"])
    errors.extend(review_command_errors(data, review_command, expected_plan_rel, current_plan_hash))

    log_path = cli_path(target, str(manifest["log_path"])).resolve(strict=False)
    if not path_is_under(log_path, target):
        errors.append(f"plan review log path is not target-relative: {manifest['log_path']}")
    elif not log_path.exists() or not log_path.is_file():
        errors.append(f"plan review log missing: {log_path}")
    else:
        log_hash = file_sha256(log_path)
        if log_hash != manifest["log_sha256"]:
            errors.append("plan review log hash mismatch")
        log_text = log_path.read_text(encoding="utf-8", errors="replace")
        # Authority follows the trust boundary the finalization gate already uses: a manifest
        # recorded by a run/finalize writer describes a log this tool wrote; a record-plan-review
        # import does not, and gets whole-log verdict scoping (item 25: plan-review log verbatim
        # replay). review_run_meta_path is a REQUIRED manifest field here, so the run meta always
        # exists by this point -- only its nonce may be absent.
        trusted_log = str(manifest.get("recorded_by") or "") in PLAN_REVIEW_TRUSTED_RECORDERS
        bound_meta = cli_path(target, str(manifest["review_run_meta_path"])).resolve(strict=False)
        frame_nonce = plan_review_run_meta_frame_nonce(bound_meta if trusted_log else None)
        errors.extend(
            review_log_errors(
                log_text,
                review_command,
                expected_plan_rel,
                current_plan_hash,
                expected_nonce=frame_nonce,
                authoritative=trusted_log,
            )
        )
        if unresolved_counts.get("unresolved_critical_count") is not None and unresolved_counts.get("unresolved_p1_count") is not None:
            errors.extend(
                review_log_verdict_errors(
                    log_text,
                    str(manifest["verdict"]),
                    int(unresolved_counts["unresolved_critical_count"]),
                    int(unresolved_counts["unresolved_p1_count"]),
                    manifest["classified_findings"] if isinstance(manifest.get("classified_findings"), list) else [],
                    expected_nonce=frame_nonce,
                    authoritative=trusted_log,
                    # Keyed on the MANIFEST, not the clock. Manifests finalized before this
                    # release bound heading-less logs legitimately -- the fallback scan passed
                    # at finalize time -- so re-validating them strictly would retroactively
                    # void recorded evidence in every deployed lane. Legacy manifests carry no
                    # verdict_scan and keep the semantics they were recorded under.
                    require_findings_section=(
                        trusted_log
                        and manifest.get("verdict_scan") == PLAN_REVIEW_VERDICT_SCAN_CONTRACT
                    ),
                    rerun_command=(
                        "tautline run-plan-review --target "
                        f"{guard_target_argument(target)} "
                        f"--plan {shlex.quote(str(manifest.get('plan_path') or ''))} "
                        f"--round {shlex.quote(str(manifest.get('round') or 'R1'))}"
                    ),
                )
            )

    run_meta_path = cli_path(target, str(manifest["review_run_meta_path"])).resolve(strict=False)
    if not path_is_under(run_meta_path, target):
        errors.append(f"plan review run metadata path is not target-relative: {manifest['review_run_meta_path']}")
    elif not run_meta_path.exists() or not run_meta_path.is_file():
        errors.append(f"plan review run metadata missing: {run_meta_path}")
    else:
        run_meta_hash = file_sha256(run_meta_path)
        if run_meta_hash != manifest["review_run_meta_sha256"]:
            errors.append("plan review run metadata hash mismatch")
        try:
            run_meta = json.loads(run_meta_path.read_text(encoding="utf-8"))
        except json.JSONDecodeError as exc:
            errors.append(f"plan review run metadata invalid JSON: {exc}")
        else:
            errors.extend(
                validate_plan_review_run_meta(
                    run_meta,
                    target,
                    expected_plan_rel,
                    current_plan_hash,
                    review_command,
                    log_path,
                    wrapper_exit_code,
                )
            )

    manifest_rel = path_relative_to_target(target, manifest_path)
    expected_evidence = plan_review_evidence_body(manifest, manifest_rel).strip()
    evidence_section = markdown_section(raw_plan_text, PLAN_REVIEW_EVIDENCE_HEADING)
    if not evidence_section:
        errors.append("plan is missing Cross-Model Review Evidence section")
    elif not plan_review_evidence_section_matches(evidence_section, expected_evidence):
        errors.append("plan Cross-Model Review Evidence section does not match the current manifest")

    return errors, plan_path, manifest_path




def plan_review_recovery_instruction(data: dict, target: Path, plan_path: Path | None) -> str:
    arg = guard_target_argument(target)
    if plan_path is None:
        return (
            f"run `tautline run-plan-review --target {arg} --plan <source-of-truth-plan>`, "
            "inspect/classify that one trusted log, run "
            f"`tautline finalize-plan-review --target {arg} --plan <source-of-truth-plan> "
            "--log <printed-log> --verdict <clean|clean-with-deferrals|blocked> "
            "--unresolved-critical-count <n> --unresolved-p1-count <n>`, then rerun "
            f"`tautline plan-finalization-precheck --target {arg} --plan <source-of-truth-plan>`"
        )
    try:
        plan_rel = plan_root_relative_reference(data, target, plan_path)
    except ValueError:
        plan_rel = str(plan_path)
    if plan_path.exists() and plan_review_sha_stale_at_cap(
        data, target, plan_path, plan_rel, plan_content_sha256(plan_path)
    ):
        # The run-again text below would prescribe a command the runtime cap refuses; the only
        # truthful next action in the sha-stale-at-cap state is the successor-plan path.
        return plan_review_successor_instruction(plan_rel)
    plan_arg = shlex.quote(plan_rel)
    review_command = f"tautline run-plan-review --target {arg} --plan {plan_arg}"
    precheck_command = f"tautline plan-finalization-precheck --target {arg} --plan {plan_arg}"
    return (
        f"run `{review_command}` once for the review round. Inspect/classify the printed log, "
        "then run "
        f"`tautline finalize-plan-review --target {arg} --plan {plan_arg} --log <printed-log> "
        "--verdict <clean|clean-with-deferrals|blocked> "
        "--unresolved-critical-count <n> --unresolved-p1-count <n>`. If Codex reports Critical/P1, "
        f"fix the plan and rerun the next review round. Then run `{precheck_command}`. Do not "
        "rerun Codex just to bind the manifest. Do not run `record-plan-review`, hand-edit "
        "`.plan-reviews`, disable hooks, skip ExitPlanMode, or ask the human operator to choose a "
        "bypass."
    )


def plan_finalization_goal_prompt_report(
    data: dict, target: Path, plan_path: Path | None, std_cfg: dict
) -> tuple[list[str], list[str]]:
    """`(block_errors, advisory_warnings)` for the goal-prompt-shipped requirement.

    Deliberately layered OUTSIDE `plan_finalization_precheck_errors`, not inside it: that
    shared function is also what `goal-assignment` itself consults to gate composition
    (cli.py, the `goal_assignment` verb). If "no goal prompt yet" were one of the errors that
    function returns, `goal-assignment` would refuse to compose the very artifact this check
    requires -- the tool built to close the gap would be locked out by its own gate. Layering
    this here -- called explicitly by every finalization-adjacent seam (the standalone verb,
    the ExitPlanMode hook, and goal-status readiness) but never by `goal_assignment` itself --
    avoids that deadlock while still applying uniformly everywhere a plan's build-readiness is
    actually judged (Codex R1 P1: the first version only reached the standalone verb, so
    ExitPlanMode could pass and `goal-status` could report `execution-ready` under `block` with
    no goal prompt at all).
    """
    level = std_cfg["enforcement"]
    if level == "off" or plan_path is None or not plan_path.exists():
        return [], []
    try:
        plan_ref = plan_root_relative_reference(data, target, plan_path)
    except (ValueError, SystemExit):
        plan_ref = plan_path.name
    issue = plan_authoring_module().plan_missing_goal_prompt_issue(
        plan_path, target=target, plan_ref=plan_ref
    )
    if not issue:
        guard_log_event(target, "plan.goal_prompt", False, "state", "shipped")
        return [], []
    guard_log_event(target, "plan.goal_prompt", True, "state", issue)
    if level == "block":
        return [f"plan-authoring standard not met: {issue}"], []
    if level == "advise":
        return [], [issue]
    return [], []  # observe: logged above, never printed or refused


def plan_finalization_goal_prompt_next_action(
    data: dict, target: Path, plan_path: Path | None
) -> str:
    """The goal-assignment-specific remedy for a `block`-refused goal-prompt-only failure.

    Codex R1 P2: appending the goal-prompt error to the generic `errors` list made the
    standalone verb's next-action line `plan_review_recovery_instruction`, which tells the
    operator to spend another cross-model review round -- a round that cannot create the
    missing file and can consume the capped review budget for nothing. This is the honest
    alternative for exactly the case where a goal prompt is the ONLY thing missing.
    """
    arg = guard_target_argument(target)
    plan_arg = ""
    if plan_path is not None:
        try:
            plan_ref = plan_root_relative_reference(data, target, plan_path)
            plan_arg = " --plan " + shlex.quote(plan_ref)
        except (ValueError, SystemExit):
            plan_arg = ""
    return (
        f"compose the missing goal prompt with `tautline goal-assignment --target {arg}"
        f"{plan_arg} --out <dir>/goal-<name>.txt`, then rerun this precheck. This is not a "
        "review-round failure; do not run run-plan-review or finalize-plan-review again."
    )


def plan_finalization_precheck(args: argparse.Namespace) -> int:
    data, _project_path, target = lane_project(args)
    base_errors, plan_path, manifest_path = plan_finalization_precheck_errors(
        data, target, args.plan
    )
    std_cfg = plan_authoring_module().normalize_planning_authoring_standard(data)
    goal_prompt_errors, goal_prompt_warnings = plan_finalization_goal_prompt_report(
        data, target, plan_path, std_cfg
    )
    for issue in goal_prompt_warnings:
        print(f"plan_authoring_standard_warning: {issue}", file=sys.stderr)
    errors = list(base_errors) + goal_prompt_errors
    ac_cfg = data.get("planAcceptance") or DEFAULT_PLAN_ACCEPTANCE
    if ac_cfg.get("enforcement") == "warn" and plan_path and plan_path.exists():
        for issue in plan_acceptance_binding_issues(
            plan_path.read_text(encoding="utf-8", errors="replace"), ac_cfg, _plan_pending_tags(data)
        ):
            print(f"plan_finalization_precheck_warning: {issue}", file=sys.stderr)
    if std_cfg["enforcement"] == "advise" and plan_path and plan_path.exists():
        std_text = plan_review_text(plan_path)
        for issue in plan_authoring_module().plan_authoring_standard_issues(std_text):
            print(f"plan_authoring_standard_warning: {issue}", file=sys.stderr)
    if errors:
        for error in errors:
            print(f"plan_finalization_precheck_error: {error}", file=sys.stderr)
        if plan_path:
            print(f"plan_finalization_plan: {plan_path}", file=sys.stderr)
        if manifest_path:
            print(f"plan_finalization_manifest: {manifest_path}", file=sys.stderr)
        # A goal-prompt-only failure is not a review-round failure: naming the generic review
        # recovery instruction here sent the operator to spend capped review budget on a round
        # that cannot create the missing file (Codex R1 P2).
        if goal_prompt_errors and not base_errors:
            next_action = plan_finalization_goal_prompt_next_action(data, target, plan_path)
        else:
            next_action = plan_review_recovery_instruction(data, target, plan_path)
        print("plan_finalization_next_action: " + next_action, file=sys.stderr)
        return 1
    print("plan_finalization_precheck: pass")
    print(f"plan_finalization_plan: {plan_path}")
    # D2. A lane leaving planning through the release valve leaves owing something, and the whole
    # value of carrying findings is lost if the obligation is only discoverable inside a JSON file.
    # Printed on the PASS path deliberately: this is not a refusal, it is the bill.
    for line in plan_review_carried_focus_lines(plan_review_carried_focus_items(data, target)):
        print(line)
    if manifest_path is not None:
        print(f"plan_finalization_manifest: {manifest_path}")
    else:
        print("plan_finalization_manifest: review-exempt")
    # Planning is finalized here, so the next step is handing the plan to a builder lane. Naming
    # the verb on the pass path is what makes goal-assignment fire automatically: the pass output
    # is what an agent reads next, and an unprompted agent otherwise free-authors a goal that the
    # host later refuses for length.
    emit_goal = "plan_finalization_next_action: emit the builder-lane goal with `tautline goal-assignment"
    if plan_path is not None:
        plan_arg = shlex.quote(plan_root_relative_reference(data, target, plan_path))
        emit_goal += f" --target {guard_target_argument(target)} --plan {plan_arg}"
        # Codex R1 (second confirming round) P2: under `advise` with no goal prompt shipped,
        # this hint used to print WITHOUT `--out`, so following it only printed the goal to
        # stdout and created no file -- the warning above would fire again on every future
        # precheck, forever, no matter how many times the advertised action was followed. Give
        # the pass-path hint a concrete output path too, exactly like the block-path remedy
        # already has, so following it actually clears the warning next time.
        if goal_prompt_warnings:
            emit_goal += " --out <dir>/goal-<name>.txt"
    print(emit_goal + "`")
    return 0


