            'elif [ "${TL_DISABLE_AUTO_RESCUE:-0}" = "1" ]; then',
            '  "$METHODOLOGY_CLI" sync-methodology --no-auto-rescue-local-changes --launcher-gate || launcher_gate_repair "methodology sync" "$SYNC_REMEDY"',
