            '[ -e "$METHODOLOGY_REPO/.git" ]; then',
            '  CANONICAL_HEAD12="$(git -C "$METHODOLOGY_REPO" rev-parse HEAD 2>/dev/null '
            '| cut -c1-12)"',
            '  SNAPSHOT_CURRENT12="$(basename "$SNAPSHOT_EXEC_ROOT")"',
