            '    SNAPSHOT_WARN="$SNAPSHOT_WARN HEAD $CANONICAL_HEAD12; snapshot store is stale -"',
            '    SNAPSHOT_WARN="$SNAPSHOT_WARN executing canonical checkout $METHODOLOGY_REPO"',
            "    SNAPSHOT_WARN=\"$SNAPSHOT_WARN (run 'tautline sync-methodology' to repair)\"",
            "    printf '%s\\n' \"$SNAPSHOT_WARN\" >&2",
