def github_repo_identity(target: Path) -> tuple[str | None, str | None, str | None]:
    code, payload, err = command_json(["gh", "repo", "view", "--json", "owner,name"], target, timeout=15)
    if code != 0 or not isinstance(payload, dict):
        return None, None, err or "gh repo view failed"
    owner = payload.get("owner")
    owner_login = owner.get("login") if isinstance(owner, dict) else owner
    name = payload.get("name")
    if not isinstance(owner_login, str) or not isinstance(name, str):
        return None, None, "gh repo view did not return owner/name"
    return owner_login, name, None


def github_remote_present(target: Path) -> bool:
    remotes = run_git(target, ["remote", "-v"])
    if remotes == "unavailable":
        return False
    return "github.com" in remotes.lower()


def github_pr_queue_state(target: Path, owner: str, name: str, number: int) -> tuple[bool, str, str | None]:
    query = """
query($owner: String!, $name: String!, $number: Int!) {
  repository(owner: $owner, name: $name) {
    pullRequest(number: $number) {
      isInMergeQueue
      mergeQueueEntry { state }
    }
  }
}
"""
    code, payload, err = command_json(
        [
            "gh",
            "api",
            "graphql",
            "-f",
            f"query={query}",
            "-F",
            f"owner={owner}",
            "-F",
            f"name={name}",
            "-F",
            f"number={number}",
        ],
        target,
        timeout=15,
    )
    if code != 0 or not isinstance(payload, dict):
        return False, "", err or "gh api graphql failed"
    errors = payload.get("errors")
    if errors:
        return False, "", f"GitHub GraphQL errors: {json.dumps(errors)[:500]}"
    data = payload.get("data")
    if not isinstance(data, dict):
        return False, "", "GraphQL response did not include data"
    repository = data.get("repository")
    if not isinstance(repository, dict):
        return False, "", "GraphQL response did not include repository"
    pr = repository.get("pullRequest")
    if not isinstance(pr, dict):
        return False, "", "GraphQL response did not include pullRequest"
    entry = pr.get("mergeQueueEntry")
    entry_state = entry.get("state") if isinstance(entry, dict) else ""
    return bool(pr.get("isInMergeQueue")), str(entry_state or ""), None


PR_HARD_FAILURE_CONCLUSIONS = {"FAILURE", "TIMED_OUT", "STARTUP_FAILURE", "CANCELLED"}
PR_FAILURE_STATES = {"FAILURE", "ERROR"}


def pr_failed_required_check(pr: dict, required_check_name: str) -> str | None:
    """Pure: given a PR's statusCheckRollup, return a failure reason iff the adapter's required CI
    check CONCLUDED a hard failure, else None. Opt-in -- an empty required_check_name never blocks, so
    the gate cannot over-block a lane that has not configured it. Provider-agnostic: a GitHub Actions
    CheckRun (conclusion) and a Jenkins/other commit StatusContext (state) are both honored.
    in-progress / queued / pending / neutral / skipped / missing are NOT-yet-provable and never block
    (FM3: only a concluded red required check stops the branch)."""
    want = (required_check_name or "").strip().lower()
    if not want:
        return None
    rollup = pr.get("statusCheckRollup")
    if not isinstance(rollup, list):
        return None
    for check in rollup:
        if not isinstance(check, dict):
            continue
        name = str(check.get("name") or check.get("context") or "").strip()
        if name.lower() != want:
            continue
        conclusion = str(check.get("conclusion") or "").upper()
        status = str(check.get("status") or "").upper()
        ctx_state = str(check.get("state") or "").upper()
        if conclusion in PR_HARD_FAILURE_CONCLUSIONS:
            return f"check '{name}' concluded {conclusion}"
        # Legacy commit status (e.g. Jenkins): no conclusion/status -- a state of FAILURE/ERROR is red.
        if not conclusion and not status and ctx_state in PR_FAILURE_STATES:
            return f"status check '{name}' is {ctx_state}"
    return None


def branch_liveness_required_check(target: Path) -> str:
    """Best-effort: the rendered adapter's ciTestGate.requiredCheckName ('' if unavailable). Reads
    the lane marker via adapter_marker_path so a missing/malformed adapter never wedges branch_liveness."""
    try:
        data = json.loads(adapter_marker_path(target).read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return ""
    cfg = data.get("ciTestGate") if isinstance(data, dict) else None
    name = cfg.get("requiredCheckName") if isinstance(cfg, dict) else None
    return name.strip() if isinstance(name, str) else ""


def branch_liveness_adapter_data(target: Path, project_arg: Path | None = None) -> dict:
    """Best-effort adapter read for branch-liveness branch classification.

    This must not use lane_project(): branch-liveness is a protective hook and should not wedge on
    unrelated adapter validation. Missing or malformed adapter data falls back to the strict default
    branch set.
    """
    candidates: list[Path] = []
    if project_arg is not None:
        project_path = project_arg.expanduser()
        if not project_path.is_absolute():
            project_path = target / project_path
        candidates.append(project_path)
    candidates.append(adapter_marker_path(target))
    candidates.append(repo_local_source_adapter_path(target))
    for path in candidates:
        try:
            payload = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, ValueError):
            continue
        if isinstance(payload, dict):
            return payload
    return {}


def adapter_target_is_methodology_repo(data: dict, target: Path | None = None) -> bool:
    if not adapter_is_methodology_repo(data):
        return False
    if target is None or not target_is_git_worktree(target):
        return False
    inferred = normalize_repo_slug(infer_repo_slug(target))
    return inferred in {normalize_repo_slug(slug) for slug in methodology_repo_slugs()}


def adapter_base_branch_names(data: dict, target: Path | None = None) -> set[str]:
    """Every branch name this adapter treats as an integration base, not just the built-in ones.

    A project whose integration branch is neither `main` nor `develop` -- which the adapter exists
    to declare -- would otherwise look like an ordinary feature branch to every caller of this set.
    Codex R4 P2: on a repo like that, pushing the configured base queries an open release PR from
    the base and blocks the prepush board gate on that PR's body, failing a gate on a branch it was
    never meant to police. The adapter already states the branch in its review wrapper; read it
    there rather than growing the hard-coded list once per project.
    """
    names = set(BASE_BRANCH_NAMES)
    if adapter_target_is_methodology_repo(data, target):
        names.add("experimental")
    declared = str(implementation_review_effective_base(data) or "").strip()
    # `review_wrapper_base` yields a git REF (`origin/experimental`); callers compare against a
    # bare name from `branch --show-current`, so drop the remote the ref carries.
    if declared:
        names.add(declared.split("/", 1)[1] if "/" in declared else declared)
    return names


def branch_liveness_base_branch_names(target: Path, project_arg: Path | None = None) -> set[str]:
    data = branch_liveness_adapter_data(target, project_arg)
    return adapter_base_branch_names(data, target)


def branch_liveness_check(args: argparse.Namespace) -> int:
    target = args.target.expanduser().resolve(strict=False)
    strict = bool(getattr(args, "strict", False))
    branch = run_git(target, ["branch", "--show-current"])
    if not branch or branch == "unavailable":
        message = "not on a named git branch"
        if strict:
            print(f"branch_liveness_error: {message}", file=sys.stderr)
            return 1
        print(f"branch_liveness: skipped - {message}")
        return 0
    print(f"branch_liveness_branch: {branch}")
    if branch in branch_liveness_base_branch_names(target, getattr(args, "project", None)):
        print("branch_liveness: pass - base branch")
        return 0
    if not github_remote_present(target):
        print("branch_liveness: pass - no GitHub remote detected")
        return 0
    if shutil.which("gh") is None:
        if strict:
            print("branch_liveness_error: GitHub CLI not available and current non-base branch has a GitHub remote", file=sys.stderr)
            return 1
        print("branch_liveness: skipped - GitHub CLI not available")
        return 0

    fields = "number,title,url,state,mergedAt,closedAt,headRefName,baseRefName,mergeStateStatus,autoMergeRequest,statusCheckRollup"
    code, payload, err = command_json(
        ["gh", "pr", "list", "--head", branch, "--state", "all", "--limit", "20", "--json", fields],
        target,
        timeout=15,
    )
    if code != 0:
        if not github_remote_present(target):
            print("branch_liveness: pass - non-GitHub remote")
            return 0
        print(f"branch_liveness_error: could not inspect PRs for current branch: {err}", file=sys.stderr)
        return 1
    if not isinstance(payload, list):
        print("branch_liveness_error: gh pr list returned unexpected JSON", file=sys.stderr)
        return 1
    if not payload:
        print("branch_liveness: pass - no PR found for current branch")
        return 0

    owner, repo_name, repo_err = github_repo_identity(target)
    required_check = branch_liveness_required_check(target)
    active_found = False
    hard_failures: list[str] = []
    inactive_failures: list[str] = []
    for pr in payload:
        if not isinstance(pr, dict):
            continue
        number = pr.get("number")
        state = str(pr.get("state") or "").upper()
        url = pr.get("url") or f"PR #{number}"
        merged_at = pr.get("mergedAt")
        closed_at = pr.get("closedAt")
        merge_state = str(pr.get("mergeStateStatus") or "").upper()
        auto_merge = pr.get("autoMergeRequest") is not None
        queued = False
        queue_state = ""
        queue_error = None
        if state not in {"MERGED", "CLOSED"} and not merged_at and not closed_at:
            if owner and repo_name and isinstance(number, int):
                queued, queue_state, queue_error = github_pr_queue_state(target, owner, repo_name, number)
            else:
                queue_error = repo_err or "could not resolve GitHub repository identity"
        print(
            "branch_liveness_pr: "
            + f"#{number} state={state or 'UNKNOWN'} merge_state={merge_state or 'UNKNOWN'} "
            + f"queued={str(queued).lower()} queue_state={queue_state or 'none'} "
            + f"auto_merge={str(auto_merge).lower()} url={url}"
        )
        if state == "MERGED" or merged_at:
            inactive_failures.append(f"PR #{number} is merged; current branch is dead")
        elif state == "CLOSED" or closed_at:
            inactive_failures.append(f"PR #{number} is closed; current branch is dead")
        elif queue_error:
            hard_failures.append(f"PR #{number} queue state could not be verified: {queue_error}")
        elif queued or queue_state or merge_state == "QUEUED" or auto_merge:
            hard_failures.append(f"PR #{number} is queued/auto-merge enabled; current branch is no longer active work")
        elif state == "OPEN":
            active_found = True
            check_failure = pr_failed_required_check(pr, required_check)
            if check_failure:
                hard_failures.append(
                    f"PR #{number} is not green: {check_failure}; a not-green PR must not be treated as "
                    "active work -- fix the red required check before continuing on this branch"
                )

    failures = hard_failures or ([] if active_found else inactive_failures)
    if failures:
        for failure in failures:
            print(f"branch_liveness_error: {failure}", file=sys.stderr)
        print(
            "branch_liveness_next_action: stop committing/reviewing/pushing this branch; sync main and continue from the source-of-truth next work",
            file=sys.stderr,
        )
        return 1
    print("branch_liveness: pass - current branch PR remains active")
    return 0


# --- The definition of done (batch 2026-08-11 B7) -----------------------------------------------
#
# The REGISTRY and every checker live in the leaf module `done_definition.py`, which imports no
# cli and judges only already-read facts. Everything below is the fact-GATHERING half: git, `gh`,
# the test-run store, the review ledger, the board. Splitting it this way is what makes each
# checker unit-testable with a plain dataclass instead of a fixture that needs a forge.
#
# The invariant that governs every gatherer here: when a fact cannot be read, return the block's
# `readable=False` state with a reason. Never substitute a default that happens to look healthy.


_DONE_DEFINITION_MODULE = None


def done_definition_module():
    global _DONE_DEFINITION_MODULE
    if _DONE_DEFINITION_MODULE is None:
        try:
            from tautline_methodology import done_definition
        except ModuleNotFoundError as exc:  # pragma: no cover - packaging guard
            raise SystemExit(
                "definition-of-done helpers require the framework checkout's "
                "src/tautline_methodology package; run this command from a full checkout instead "
                "of a standalone copy of bin/tautline"
            ) from exc
        _DONE_DEFINITION_MODULE = done_definition
    return _DONE_DEFINITION_MODULE


def done_definition_config(data: dict, target: Path) -> dict:
    """`definitionOfDone`, read-side, with the integration branch resolved from the adapter.

    The default comes from `lane_status_config(...)["integrationBranch"]`, which already falls
    back to `latestCode.base`. Deliberately NOT hardcoded to `main`: in this repository `main`
    is the stable channel and active development integrates on `experimental`, and any adopter
    with a different branch model would be equally mis-served by a hardcoded default.
    """
    module = done_definition_module()
    try:
        default_branch = str(lane_status_config(data).get("integrationBranch") or "")
    except Exception:  # noqa: BLE001 - a malformed laneStatus must not break the done bar
        default_branch = ""
    return module.normalize_definition_of_done(data, default_integration_branch=default_branch)


def done_definition_pr_facts(
    data: dict, target: Path, integration_branch: str, remote: str = "origin"
):
    """Read the current branch's PR state through the readers `branch_liveness_check` uses.

    Two readers, deliberately, and neither is new. `gh pr list --json` supplies state, merged,
    base and `autoMergeRequest`. Merge-queue membership comes from `github_pr_queue_state`,
    which is a GraphQL query for `isInMergeQueue` and `mergeQueueEntry { state }`.

    `mergeQueueEntry` is NOT available as a `gh pr list --json` field -- the CLI rejects it with
    `Unknown JSON field: "mergeQueueEntry"`. Asking for it there would make every read fail, and
    a failed read is `unknown`, which does not block: an unarmed open PR would sail straight
    through the bar built to catch it. Nothing here reads `estimatedTimeToMerge`; doing so trips
    the existing `stop.wrong_merge_queue_signal` guard.
    """
    module = done_definition_module()
    facts = module.PrHandoffFacts

    # Uncommitted work is in no PR and no review, so it invalidates every other verdict here.
    # Gathered FIRST, and carried even into the blind results: a lane whose PR state could not
    # be read may still be demonstrably dirty, and that is a fact worth keeping rather than one
    # to discard because a different question went unanswered.
    status = run_git(target, ["status", "--porcelain"])
    # `unavailable` is the sentinel for a FAILED read, not for a clean tree. Collapsing it into
    # `dirty=False` reported cleanliness that was never established, so a matching armed PR could
    # carry the condition to a pass -- the exact fail-open shape this module exists to refuse.
    status_readable = status != "unavailable"
    dirty = status_readable and bool(status.strip())

    def blind(reason: str):
        return facts(
            readable=False,
            detail=reason,
            integration_branch=integration_branch,
            worktree_dirty=dirty,
            worktree_status_readable=status_readable,
        )

    # Same refusal as the diff gatherer, for the same reason: these values reach a git argv.
    if integration_branch and not module.is_safe_git_ref(integration_branch):
        return blind(
            f"refusing to run git with an unsafe integrationBranch: {integration_branch!r}"
        )
    if not module.is_safe_git_ref(remote):
        return blind(f"refusing to run git with an unsafe remote: {remote!r}")

    branch = run_git(target, ["branch", "--show-current"])
    if not branch or branch == "unavailable":
        return blind("not on a named git branch, so no PR can be resolved")
    if integration_branch and branch == integration_branch:
        # Standing ON the integration branch is not the same as having handed the work off. Local
        # commits ahead of `origin/<integration>` are still only in this lane, and returning a
        # pass here -- before any remote comparison -- let a goal complete on work nobody else
        # can see. The no-PR shortcut requires an empty outgoing range.
        ahead = run_git(
            target, ["rev-list", "--count", f"{remote}/{integration_branch}..HEAD"]
        )
        if ahead == "unavailable":
            return blind(
                f"on `{branch}`, but whether it has unpushed commits could not be established"
            )
        try:
            unpushed = int(ahead.strip() or "0")
        except ValueError:
            return blind(
                f"on `{branch}`, but the unpushed-commit count could not be parsed: {ahead!r}"
            )
        return facts(
            readable=True,
            found=False,
            on_integration_branch=True,
            integration_branch=integration_branch,
            unpushed_commits=unpushed,
            worktree_dirty=dirty,
            worktree_status_readable=status_readable,
        )
    if not github_remote_present(target):
        return blind("no GitHub remote detected, so PR state cannot be read")
    if shutil.which("gh") is None:
        return blind("the GitHub CLI is not installed, so PR state cannot be read")

    fields = (
        "number,title,url,state,mergedAt,closedAt,headRefName,headRefOid,baseRefName,"
        "mergeStateStatus,autoMergeRequest"
    )
    code, payload, err = command_json(
        ["gh", "pr", "list", "--head", branch, "--state", "all", "--limit", "20", "--json", fields],
        target,
        timeout=15,
    )
    if code != 0 or not isinstance(payload, list):
        return blind(f"could not list PRs for `{branch}`: {err or 'gh pr list failed'}")
    if not payload:
        return facts(
            readable=True, found=False, reference=f"branch `{branch}`",
            integration_branch=integration_branch, worktree_dirty=dirty,
            worktree_status_readable=status_readable,
        )

    owner, repo_name, repo_err = github_repo_identity(target)
    local_head = run_git(target, ["rev-parse", "HEAD"])
    local_head = "" if local_head == "unavailable" else local_head

    def _rank(pr: dict) -> tuple[int, int]:
        """Lower sorts first. Containment beats state, and state beats nothing.

        Preferring merged outright was wrong: when a branch NAME is reused after an earlier
        merge, the historical PR sorts first, its frozen head never matches the tip, and the
        lane fails permanently even though its current PR is armed and DOES contain the work.
        A PR whose head IS the tip is the one this lane is asking about, whatever its state;
        only among PRs that are equally (un)related to the tip does merged win, because a
        merged PR is the strongest evidence of handoff.
        """
        contains = 0 if (local_head and str(pr.get("headRefOid") or "") == local_head) else 1
        merged = 0 if (str(pr.get("state") or "").upper() == "MERGED" or pr.get("mergedAt")) else 1
        return (contains, merged)

    candidates = sorted((pr for pr in payload if isinstance(pr, dict)), key=_rank)
    pr = candidates[0]
    number = pr.get("number")
    state = str(pr.get("state") or "").upper()
    merged = state == "MERGED" or bool(pr.get("mergedAt"))
    is_open = state == "OPEN" and not merged and not pr.get("closedAt")
    # CLOSED without a merge is the clearest evidence the work was NOT handed off. Left
    # unclassified it fell through to `unknown`, which never blocks -- so abandoning a PR
    # satisfied the bar.
    closed_unmerged = not merged and (state == "CLOSED" or bool(pr.get("closedAt")))
    auto_merge = pr.get("autoMergeRequest") is not None
    merge_state = str(pr.get("mergeStateStatus") or "").upper()
    queued = merge_state == "QUEUED"
    if is_open and not queued and owner and repo_name and isinstance(number, int):
        in_queue, queue_state, queue_error = github_pr_queue_state(target, owner, repo_name, number)
        if queue_error:
            # The armed states are a disjunction, so an unreadable queue leaves the answer
            # genuinely undetermined -- unless something else already armed it, in which case
            # the queue question no longer matters.
            if not auto_merge:
                return blind(f"PR #{number} merge-queue state could not be read: {queue_error}")
        else:
            queued = bool(in_queue) or bool(queue_state)
    elif is_open and not queued and not (owner and repo_name):
        if not auto_merge:
            return blind(
                f"PR #{number} merge-queue state could not be read: "
                f"{repo_err or 'could not resolve GitHub repository identity'}"
            )
    return facts(
        readable=True,
        found=True,
        merged=merged,
        is_open=is_open,
        auto_merge_armed=auto_merge,
        in_merge_queue=queued,
        reference=f"PR #{number}",
        base_ref=str(pr.get("baseRefName") or ""),
        closed_unmerged=closed_unmerged,
        head_oid=str(pr.get("headRefOid") or ""),
        local_head=local_head,
        worktree_dirty=dirty,
        worktree_status_readable=status_readable,
        integration_branch=integration_branch,
    )


def done_definition_scope_facts(data: dict, target: Path, run: dict | None):
    """Scope, from the goal run's own milestone ledger -- the same list `goal-advance` refuses
    a `goal-complete` over. One definition of "the units of work", not a second one."""
    module = done_definition_module()
    if not isinstance(run, dict):
        return module.ScopeFacts(readable=False, detail="no goal run is loaded for this lane")
    milestones = run.get("milestones")
    if not isinstance(milestones, list):
        return module.ScopeFacts(readable=False, detail="the goal run records no milestone list")
    open_units: list[str] = []
    reasonless: list[str] = []
    for item in milestones:
        if not isinstance(item, dict):
            continue
        label = f"{item.get('index')}: {item.get('title')}"
        status = str(item.get("status") or "")
        if status not in GOAL_TERMINAL_STATUSES:
            open_units.append(f"{label} ({status or 'no status'})")
        elif status == "deferred" and not [
            reason for reason in (item.get("deferralReasons") or []) if str(reason).strip()
        ]:
            reasonless.append(label)
    return module.ScopeFacts(
        readable=True,
        open_units=tuple(open_units),
        deferred_without_reason=tuple(reasonless),
        total_units=len(milestones),
    )


def done_definition_diff_facts(target: Path, integration_branch: str, remote: str = "origin"):
    """The outgoing diff's file list, for `tests_written`.

    `remote` is adapter-resolved rather than hardcoded: an adapter whose `latestCode.remote` is
    `upstream` has a stale-or-absent `origin/<branch>`, and comparing against it reports
    upstream-pushed work as missing.
    """
    module = done_definition_module()
    if not integration_branch:
        return module.DiffFacts(
            readable=False, detail="no integration branch is resolved, so there is no diff base"
        )
    # Refuse before git sees it. These are adapter STRINGS and the schema accepts any string;
    # `--output=/tmp/x` as an integration branch makes git create or truncate that file instead
    # of reading a diff. An adapter typo must not be able to write to the filesystem.
    if not module.is_safe_git_ref(integration_branch) or not module.is_safe_git_ref(remote):
        return module.DiffFacts(
            readable=False,
            detail=(
                f"refusing to run git with an unsafe ref: integrationBranch="
                f"{integration_branch!r} remote={remote!r}"
            ),
        )
    for ref in (f"{remote}/{integration_branch}", integration_branch):
        # `--name-status`, not a blanket `--diff-filter=d`. Excluding EVERY deletion was an
        # overcorrection: deleting a behavior-carrying source file then produced an empty diff
        # and a non-blocking `unknown`, so the previous round traded one hole for another.
        # Deletions are kept and their STATUS is preserved, so the checker can drop a deleted
        # TEST (which must not count as a written one) while a deleted SOURCE file still counts
        # as behavior that needs coverage.
        out = run_git(target, ["diff", "--name-status", f"{ref}...HEAD"])
        if out and out != "unavailable":
            names = []
            deleted = []
            for line in out.splitlines():
                parts = line.split("\t")
                if len(parts) < 2:
                    continue
                status, path_name = parts[0].strip(), parts[-1].strip()
                if not path_name:
                    continue
                names.append(path_name)
                if status.startswith("D"):
                    deleted.append(path_name)
                elif status.startswith("R") and len(parts) >= 3:
                    # A rename record carries BOTH paths (`R100<TAB>old<TAB>new`), and keeping
                    # only the destination loses the source entirely. Renaming `src/tool.py` to
                    # `docs/tool.txt` then looks like a lone non-behavior file, so `tests_written`
                    # passes with no test change -- while the same edit expressed as a delete plus
                    # an add correctly counts the removed source. The old path IS deleted; record
                    # it as such so one git formatting detail cannot decide the verdict.
                    source = parts[-2].strip()
                    if source:
                        names.append(source)
                        deleted.append(source)
            return module.DiffFacts(
                readable=True, changed_files=tuple(names), deleted_files=tuple(deleted)
            )
        # An EMPTY diff against a ref that resolves is a real answer, not a failure. Distinguish
        # it from an unresolvable ref by asking git whether the ref exists at all.
        #
        # `run_git` returns the sentinel string "unavailable" on a non-zero exit, which is
        # TRUTHY -- so a bare truthiness test here would read a failed rev-parse as "the ref
        # exists". It cannot bite today (a bad ref makes `git diff` fail, so `out` is the
        # sentinel rather than ""), but a control whose correctness depends on a neighbouring
        # branch never firing is one refactor from being wrong.
        probe = run_git(target, ["rev-parse", "--verify", "--quiet", ref])
        if out == "" and probe not in ("", "unavailable"):
            return module.DiffFacts(readable=True, changed_files=())
    return module.DiffFacts(
        readable=False,
        detail=f"could not diff against `{integration_branch}` or `origin/{integration_branch}`",
    )


def done_definition_test_facts(target: Path):
    """The newest recorded test run, classified by the existing evidence classifier."""
    module = done_definition_module()
    condition, record = test_evidence_module().classify_test_run_evidence(target)
    counts = (record or {}).get("counts") if isinstance(record, dict) else None
    counts = counts if isinstance(counts, dict) else {}

    def as_int(key):
        value = counts.get(key)
        return value if isinstance(value, int) else None

    return module.TestGateFacts(
        condition=condition,
        passed=as_int("passed"),
        failed=as_int("failed"),
        # Carried so the checker can weigh the REPORT, not just the exit code: a command that
        # exits 0 with failures recorded classifies `current` all the same.
        errors=as_int("errors"),
        skipped=as_int("skipped"),
        collected=as_int("collected"),
        detail=f"test-run evidence is `{condition}`",
    )


def done_definition_review_facts(data: dict, target: Path):
    """The implementation-review ledger for the current branch, and whether it is committed."""
    module = done_definition_module()
    branch = run_git(target, ["branch", "--show-current"])
    if not branch or branch == "unavailable":
        return module.ReviewFacts(
            readable=False, detail="not on a named git branch, so no review ledger can be resolved"
        )
    ledger_path = (
        implementation_review_ledger_dir(data, target) / f"{slugify(branch, 'branch')}.json"
    )
    rel = path_relative_to_target(target, ledger_path)
    if not ledger_path.is_file():
        return module.ReviewFacts(
            readable=False, detail=f"no implementation-review ledger at `{rel}`"
        )
    try:
        ledger = json.loads(ledger_path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as exc:
        return module.ReviewFacts(readable=False, detail=f"`{rel}` could not be read: {exc}")
    if not isinstance(ledger, dict):
        return module.ReviewFacts(readable=False, detail=f"`{rel}` is not an object")

    def as_int(key):
        value = ledger.get(key)
        if isinstance(value, bool):
            return None
        if isinstance(value, int):
            return value
        try:
            return int(str(value))
        except (TypeError, ValueError):
            return None

    # "Committed?" is TWO questions and `git status --porcelain` alone answers only one of them.
    # Status prints nothing for a clean tracked file -- and also nothing for a path git is not
    # tracking at all, so an IGNORED `.impl-reviews/` directory would read as "committed" on a
    # ledger that will never reach the remote. That is this framework's dominant defect exactly:
    # a control reading healthy because the thing it checks was never in scope. So: `ls-files`
    # first for tracked-ness, then status for dirtiness. An unreadable git is `None`, which the
    # checker reports as unknown rather than guessing in either direction.
    committed: bool | None
    tracked = run_git(target, ["ls-files", "--error-unmatch", "--", str(ledger_path)])
    if tracked == "unavailable":
        # `run_git` collapses every non-zero exit to one sentinel, so this cannot distinguish
        # "git says untracked" from "git itself failed". Read as untracked, and stated here
        # rather than left implied: the file was already confirmed to EXIST two branches up, so
        # a git that can stat the worktree and refuse this path is overwhelmingly reporting
        # untracked. The cost of being wrong is a FAIL a lane can see and act on, not a silent
        # pass -- which is the direction an ambiguous signal should always resolve.
        committed = False
    else:
        status = run_git(target, ["status", "--porcelain", "--", str(ledger_path)])
        committed = None if status == "unavailable" else not status.strip()
    # R1 P1: WHICH DIFF does this ledger describe? A ledger finalized on commit A stays tracked
    # and clean after commit B is added, so without this comparison a `clean` verdict for a
    # SUPERSEDED diff admits unreviewed code straight through the blocking bar -- evidence that
    # reads as proof of something it never saw. Compared against the same
    # `implementation_review_state` the finalizer itself records.
    covers: bool | None = None
    stale_reason = ""
    # THE LEDGER'S OWN BASE, not the default. `implementation_review_state(target)` falls back to
    # `origin/main`, and this repository finalizes reviews against `origin/experimental` -- so
    # recomputing with the default marks every valid ledger stale and the default BLOCKING bar
    # then refuses goal completion for the whole repo. A gate whose false-positive rate is 100%
    # on its own project is worse than no gate; it teaches the lane to disable it.
    # The recorded base_sha FIRST, and the symbolic base_ref only as a fallback. Once the PR
    # merges, the integration ref moves forward: recomputing against the SYMBOLIC ref then puts
    # the merge base at the feature HEAD, yields an empty diff, and marks a perfectly valid
    # ledger stale -- which refuses a lane whose PR has already landed, the one state
    # `pr_handed_off` most explicitly accepts. A sha is immutable and describes exactly the
    # comparison the finalizer made.
    ledger_base = str(ledger.get("base_sha") or "") or str(ledger.get("base_ref") or "") or None
    try:
        state, state_errors = implementation_review_state(target, ledger_base)
    except (SystemExit, Exception):  # noqa: BLE001 - an unreadable diff is `unknown`, never a pass
        state, state_errors = None, ["review state could not be computed"]
    if not isinstance(state, dict) or state_errors:
        covers = None
    else:
        recorded = str(ledger.get("diff_sha256") or "")
        current = str(state.get("diff_sha256") or "")
        if not recorded or not current:
            covers = None
        elif recorded != current:
            covers = False
            stale_reason = (
                f"the review ledger `{rel}` was finalized against diff "
                f"{recorded[:12]} but the outgoing diff is {current[:12]}; the current changes "
                "are unreviewed"
            )
        elif str(ledger.get("base_sha") or "") and str(ledger.get("base_sha")) != str(
            state.get("base_sha") or ""
        ):
            covers = False
            stale_reason = (
                f"the review ledger `{rel}` was finalized against base "
                f"{str(ledger.get('base_sha'))[:12]}, not the current "
                f"{str(state.get('base_sha'))[:12]}"
            )
        else:
            covers = True
    return module.ReviewFacts(
        readable=True,
        covers_current_diff=covers,
        stale_reason=stale_reason,
        finalized=bool(
            ledger.get("finalized_at") or ledger.get("finalizedAt") or ledger.get("verdict")
        ),
        verdict=str(ledger.get("verdict") or ""),
        classification_status=str(ledger.get("classification_status") or ""),
        open_critical=as_int("unresolved_critical_count"),
        open_p1=as_int("unresolved_p1_count"),
        committed=committed,
        ledger_path=rel,
    )


def done_definition_board_facts(
    data: dict,
    target: Path,
    run: dict | None,
    *,
    pending_close: bool = False,
    done_evidence: str = "",
):
    """Board state, composed from item 81's `doneEvidence` gate rather than re-implemented.

    At the pre-flight (`pending_close=True`) the question is whether the closure this command
    is about to perform carries evidence -- asking whether the item is already done would make
    the condition unsatisfiable by the very transition that satisfies it.
    """
    module = done_definition_module()
    provider_enabled = bool((data.get("backlogProvider") or {}).get("enabled"))
    if not provider_enabled:
        return module.BoardFacts(
            provider_enabled=False, readable=True, detail="no backlog provider"
        )
    if pending_close:
        # A goal sanctioned as repo-only (item 71 PR3's `allowRepoOnlyGoals`) has no board item,
        # and the sync that follows explicitly performs no board update. Reporting "this
        # transition closes the board item with evidence" would be describing something that
        # will not happen.
        try:
            ref = goal_tracker_goal_ref(data, target, run or {})
        except (SystemExit, Exception):  # noqa: BLE001
            ref = ""
        # Read exactly the way item 71 PR3's own sync and drift paths read it -- through
        # `goal_tracker_config`, with the same default -- so the allowance has ONE definition
        # rather than a second one that can drift from the first.
        allows_repo_only = bool(
            goal_tracker_config(data).get(
                "allowRepoOnlyGoals", DEFAULT_GOAL_TRACKER["allowRepoOnlyGoals"]
            )
        )
        if not ref and allows_repo_only:
            return module.BoardFacts(
                provider_enabled=False,
                readable=True,
                detail="this goal is sanctioned repo-only; there is no board item to close",
            )
        return module.BoardFacts(
            provider_enabled=True,
            readable=True,
            pending_close=True,
            has_verification_evidence=bool(str(done_evidence or "").strip()),
            reference="the board item",
        )
    try:
        tracker = goal_tracker_config(data)
        ref = goal_tracker_goal_ref(data, target, run or {})
        if not ref:
            return module.BoardFacts(
                provider_enabled=True,
                readable=False,
                detail="the goal run names no board item",
            )
        item = resolve_goal_tracker_item(data, target, ref)
        actual = goal_tracker_item_field(item, tracker["statusField"])
        at_done = goal_tracker_status_matches(actual, list(tracker.get("doneStatuses") or []))
    except (SystemExit, Exception) as exc:  # noqa: BLE001
        # SystemExit included deliberately: `resolve_goal_tracker_item` RAISES it when the
        # linked Project item was deleted, moved, or cannot be found -- the commonest real
        # failure here. Uncaught, a standalone `done-check` aborts instead of reporting
        # `board_updated unknown`, breaking this gatherer's fail-open contract.
        return module.BoardFacts(
            provider_enabled=True, readable=False, detail=f"board state could not be read: {exc}"
        )
    # The evidence question, asked SEPARATELY from the status -- and, at a standalone check,
    # currently NOT ANSWERABLE. Item 81 gates evidence at the done TRANSITION; the framework
    # has no read-side source for "this board item already carries a verification comment",
    # so an item a human or another tool moved straight to Done has an unread evidence state.
    #
    # Reported as `unknown` rather than derived from `at_done_status`. Deriving it -- which an
    # earlier version of this function did -- makes the condition unfalsifiable in the exact
    # case it exists for, because then reaching Done IS the evidence and nothing can ever fail
    # it. An honest `unknown` does not block and says plainly what was not established; a
    # derived pass says "verified" about a thing nobody verified.
    #
    # The pre-flight path (`pending_close=True`, above) DOES answer it, from the evidence the
    # transition is about to post, which is the path this condition actually gates.
    return module.BoardFacts(
        provider_enabled=True,
        readable=True,
        at_done_status=bool(at_done),
        has_verification_evidence=False,
        evidence_readable=False,
        reference=f"board item {ref}",
    )


def done_definition_observations(
    data: dict,
    target: Path,
    run: dict | None = None,
    *,
    config: dict | None = None,
    pending_close: bool = False,
    done_evidence: str = "",
    skip_board: bool = False,
):
    """Gather every fact the registry judges. One call, so no surface can silently skip a block."""
    module = done_definition_module()
    cfg = config if config is not None else done_definition_config(data, target)
    branch = str(cfg.get("integrationBranch") or "")
    # The remote the adapter actually integrates through. Hardcoding `origin` reports
    # upstream-pushed work as unpushed for any adapter whose `latestCode.remote` differs.
    try:
        remote = str(lane_status_config(data).get("remote") or "origin")
    except Exception:  # noqa: BLE001 - a malformed laneStatus must not break the done bar
        remote = "origin"
    return module.DoneObservations(
        pr=done_definition_pr_facts(data, target, branch, remote),
        scope=done_definition_scope_facts(data, target, run),
        diff=done_definition_diff_facts(target, branch, remote),
        tests=done_definition_test_facts(target),
        review=done_definition_review_facts(data, target),
        board=(
            # The Stop path passes skip_board: the board read costs up to two 30-second calls
            # and, at a standalone check, this condition reports `unknown` ANYWAY because the
            # framework has no read-side source for "this item carries verification evidence".
            # Paying a minute of session-termination latency for an answer that is `unknown`
            # before the call is made is the worst trade in the item.
            module.BoardFacts(
                provider_enabled=True,
                readable=False,
                detail="board not read at the Stop boundary (advisory path, no remote read)",
            )
            if skip_board and bool((data.get("backlogProvider") or {}).get("enabled"))
            else module.BoardFacts(provider_enabled=False, readable=True, detail="no backlog provider")
            if skip_board
            else done_definition_board_facts(
                data, target, run, pending_close=pending_close, done_evidence=done_evidence
            )
        ),
    )


def done_definition_evaluate(
    data: dict,
    target: Path,
    run: dict | None = None,
    *,
    pending_close: bool = False,
    done_evidence: str = "",
    skip_board: bool = False,
) -> tuple[dict, list]:
    module = done_definition_module()
    cfg = done_definition_config(data, target)
    observations = done_definition_observations(
        data,
        target,
        run,
        config=cfg,
        pending_close=pending_close,
        done_evidence=done_evidence,
        skip_board=skip_board,
    )
    outcomes = module.evaluate_done_conditions(
        cfg, observations, backlog_enabled=bool((data.get("backlogProvider") or {}).get("enabled"))
    )
    return cfg, outcomes


def goal_assignment_effective_conditions(data: dict, target: Path) -> list[str]:
    """The done-condition ids this project actually enforces, in registry order.

    The single source both the goal COMPOSER and the goal SHAPE CHECK read, so a generated
    goal can never state a different bar from the one `done-check` applies. That divergence is
    the defect the whole item exists to close, and re-deriving the set in two places is how it
    would come back.
    """
    module = done_definition_module()
    cfg = done_definition_config(data, target)
    backlog_enabled = bool((data.get("backlogProvider") or {}).get("enabled"))
    return [
        condition_id
        for condition_id in module.DONE_CONDITION_IDS
        if module.condition_is_enabled(cfg, condition_id, backlog_enabled=backlog_enabled)
    ]


def done_check(args: argparse.Namespace) -> int:
    """`done-check`: report the definition of done against this lane, condition by condition."""
    module = done_definition_module()
    data, _project_path, target = lane_project(args)
    run = None
    try:
        run = load_goal_run(data, target)
    except (SystemExit, Exception):  # noqa: BLE001
        # `SystemExit` explicitly: `load_goal_run` RAISES it when the ledger is missing, and it
        # derives from BaseException, so a bare `except Exception` lets it through and kills
        # `done-check` in any lane without a goal run. A reporting verb that cannot run in the
        # commonest lane state is a control nobody reaches.
        run = None
    cfg, outcomes = done_definition_evaluate(data, target, run)
    if args.json:
        print(json.dumps(module.done_check_payload(cfg, outcomes), indent=2, sort_keys=True))
    else:
        print(f"done_check_enforcement: {cfg['enforcement']}")
        print(f"done_check_integration_branch: {cfg['integrationBranch'] or 'unresolved'}")
        for line in module.render_done_check_lines(outcomes):
            print(line)
        for notice in module.done_check_unknown_notices(outcomes):
            print(f"done_check_unknown: {notice}")
    return 1 if module.done_verdict(outcomes) == module.FAIL else 0


def done_bar_goal_completion_errors(
    data: dict, target: Path, run: dict, event: str, done_evidence: str
) -> list[str]:
    """The blocking arm. Empty means the transition may proceed.

    Called from `goal_advance` at the SAME pre-flight seam as
    `goal_advance_closure_preflight` and before it -- so a refusal here mutates nothing.
    Item 81 already learned that a refusal placed after `sync_goal_issue_ui_evidence` has
    published leaves the board mutated and then refuses, which is precisely what this seam
    exists to prevent.

    `unknown` never appears in the returned list. A bar that blocked on what it could not read
    would wedge an offline lane; it is printed loudly instead.
    """
    module = done_definition_module()
    if event != "goal-complete":
        return []
    cfg, outcomes = done_definition_evaluate(
        data, target, run, pending_close=True, done_evidence=done_evidence
    )
    for line in module.render_done_check_lines(outcomes):
        print(f"done_bar_{line}")
    for notice in module.done_check_unknown_notices(outcomes):
        print(f"done_bar_unknown: {notice}")
    guard_log_event(
        target,
        "goal.done_bar",
        module.done_verdict(outcomes) == module.FAIL,
        "state",
        f"enforcement={cfg['enforcement']}",
    )
    return module.done_check_blocking_failures(cfg, outcomes)


DONE_BAR_STOP_UNKNOWN_WINDOW_SECONDS = 24 * 60 * 60


def done_bar_stop_advisory(adapter_root: Path, session_id: str) -> str:
    """The warn arm: what to say at a Stop whose goal THIS session declared complete.

    Returns "" when there is nothing to say. The caller emits the result through
    `hook_additional_context`, never through `hook_decision` -- see the note at the call site.

    Two gates before the bar is even evaluated:

    1. The goal run must be terminal. An active goal is the existing blocking path's business.
    2. The completion must belong to THIS session. A terminal `GOAL_RUN.json` records a
       timestamp and an event but, before this item, nothing that distinguishes "this session
       completed it two minutes ago" from "a session last week did". Firing without that
       correlation would warn every later unrelated session; staying silent would be a control
       that reads healthy while doing nothing. When the stamp is absent the arm reports one
       `unknown` line -- bounded to recent completions so it cannot become permanent noise --
       and asserts nothing.
    """
    module = done_definition_module()
    # `SystemExit` is named alongside `Exception` in both handlers below, and it is not
    # belt-and-braces: `load_project` and `load_goal_run` both RAISE SystemExit for the ordinary
    # missing-file case, and it derives from BaseException, so a bare `except Exception` would
    # let it escape and kill the Stop hook in any lane without an adapter or a goal run -- the
    # commonest states there are.
    try:
        data = load_project(adapter_marker_path(adapter_root))
    except (SystemExit, Exception):  # noqa: BLE001 - no adapter, nothing to say
        return ""
    try:
        run = load_goal_run(data, adapter_root)
    except (SystemExit, Exception):  # noqa: BLE001 - no goal run, nothing to say
        return ""
    if not isinstance(run, dict):
        return ""
    if str(run.get("status") or "").lower() not in GOAL_TERMINAL_STATUSES:
        return ""

    stamped = str(run.get("completedBySession") or "")
    if not stamped:
        if not done_bar_completion_is_recent(run):
            return ""
        return (
            "done_bar_stop: unknown - this lane's goal is marked complete but the run records no "
            "session, so whether THIS session declared it cannot be established and the done bar "
            "was not evaluated. Stamp it by completing goals with `tautline goal-advance --event "
            "goal-complete --session-id <id>`."
        )
    if not session_id or stamped != session_id:
        return ""

    # COST NOTE, stated rather than hidden: everything above is a local file read, and only past
    # this point does the arm reach the network (`gh pr list`, 15s timeout, plus at most one
    # GraphQL queue read). That ordering is deliberate. The two gates above narrow the network
    # path to Stops in a session that completed its OWN goal, which is at most a handful per
    # session and zero for every other lane -- unlike the SessionStart surfaces, which are
    # forbidden from shelling out at all because they run on every session. A PR-state read is
    # also not optional here: an arm that skipped it could not evaluate the one condition it
    # exists for, and would be a control reporting healthy while checking nothing.
    # skip_board: this is the Stop boundary, and the arm is ADVISORY. A board-backed lane pays
    # up to two 30-second reads here for a condition that reports `unknown` regardless, which
    # can stall session termination past a minute on a slow forge. A hook that makes stopping
    # slow is a hook people disable.
    _cfg, outcomes = done_definition_evaluate(data, adapter_root, run, skip_board=True)
    failures = [o for o in outcomes if o.status == module.FAIL]
    unknowns = module.done_check_unknown_notices(outcomes)
    passed = [o for o in outcomes if o.status == module.PASS]
    if not failures:
        # R2 P1: SILENCE IS NOT A PASS HERE EITHER. A session can complete its goal and reach
        # Stop with the PR, test and review facts all unreadable -- no condition fails, so an
        # early `return ""` said nothing at all, which is indistinguishable from a clean bar.
        # That is the same reads-healthy-while-nothing-ran defect the whole item exists to
        # close, reproduced at the one boundary built to catch it. When the run established
        # NOTHING, say so; when at least one condition genuinely passed, staying quiet is
        # honest, because the bar was evaluated and found no fault.
        if unknowns and not passed:
            return (
                "done_bar_stop: unknown - this session marked its goal complete and the done bar "
                "could not establish a single condition:\n"
                + "\n".join(f"  unknown: {notice}" for notice in unknowns)
                + "\nNothing is blocked and nothing was proven. Run `tautline done-check "
                "--target .` where the facts are readable, or declare a true blocker with "
                "`tautline blocker-declare --kind <k> --reason <r>`."
            )
        return ""

    record, _read_error = read_blocker_record(adapter_root)
    if record is not None:
        fresh, _reason = blocker_freshness(adapter_root, record)
        if fresh:
            return ""

    # The text names the failing conditions and the next action, and deliberately does NOT tell
    # the agent to consult a human -- the ladder's existing invariant, applied here rather than
    # rediscovered in review.
    lines = [
        "done_bar_stop: this session marked its goal complete, but the definition of done "
        "is not met.",
    ]
    for outcome in failures:
        condition = module.DONE_CONDITIONS[outcome.condition_id]
        lines.append(f"  {outcome.condition_id}: {outcome.reason}. Next: {condition.remedy}")
    for notice in unknowns:
        lines.append(f"  unknown: {notice}")
    lines.append(
        "Continue the next authorized action, or declare a true blocker with "
        "`tautline blocker-declare --kind <k> --reason <r>` with current evidence. This is "
        "advisory: nothing is blocked."
    )
    return "\n".join(lines)


def done_bar_completion_is_recent(run: dict) -> bool:
    """True when the goal's completion is inside the unknown-report window.

    Bounds the un-correlated `unknown` line so a long-finished goal run does not print it at
    every Stop forever. An unparseable or absent timestamp is NOT recent: this only widens
    silence, and the correlated path is unaffected.
    """
    stamp = str(run.get("completedAt") or "")
    if not stamp:
        return False
    try:
        completed = datetime.fromisoformat(stamp.replace("Z", "+00:00"))
    except ValueError:
        return False
    if completed.tzinfo is None:
        completed = completed.replace(tzinfo=timezone.utc)
    age = (datetime.now(timezone.utc) - completed).total_seconds()
    return 0 <= age <= DONE_BAR_STOP_UNKNOWN_WINDOW_SECONDS


def write_continuity_handoff(data: dict, target: Path, content: str) -> Path:
    continuity = data["continuity"]
    handoff = target / continuity["path"]
    archive_dir = target / continuity["archiveDir"]

    if handoff.exists() and handoff.read_text(encoding="utf-8").strip():
        archive_dir.mkdir(parents=True, exist_ok=True)
        stamp = time.strftime("%Y%m%d-%H%M%S")
        handoff.replace(archive_dir / f"{stamp}-NEXT_SESSION.md")

    ensure_lane_state(data, target)

    branch = run_git(target, ["branch", "--show-current"])
    head = run_git(target, ["rev-parse", "--short", "HEAD"])
    status = run_git(target, ["status", "--short", "--branch"])
    last_commit = run_git(target, ["log", "-1", "--oneline"])

    if not content:
        content = default_continuity_content()

    handoff.parent.mkdir(parents=True, exist_ok=True)
    rendered = (
        f"# Continuity Handoff - {data['project']}\n\n"
        "> Lane-local handoff for the next AI session. Read this before starting new work.\n\n"
        "## Metadata\n"
        f"- Project: {data['project']}\n"
        f"- Repo: {data['repo']}\n"
        f"- Target: {target}\n"
        f"- Methodology CLI resolver: `tautline` from `PATH`, or `${{TAUTLINE_METHODOLOGY_REPO:-$MINERVIT_METHODOLOGY_REPO}}/bin/tautline` after sourcing `$HOME/.config/tautline/tautline.env` (legacy minervit paths still resolve).\n"
        f"- Generated: {now_iso()}\n"
        f"- Branch: {branch}\n"
        f"- HEAD: {head}\n"
        f"- Last commit: {last_commit}\n\n"
        "## Git Status At Handoff\n\n"
        "```text\n"
        f"{status}\n"
        "```\n\n"
        "## Required Startup Gates\n"
        f"- This handoff is the continuity source, but it does not replace startup gates.\n"
        f"- Read this section, run the gates below in listed order, then return to `## Handoff Content`. Do not execute from Handoff Content before the gates pass.\n"
        f"- Do not ask clarifying questions, report substantive status, or start analysis from Handoff Content before the methodology gates pass. The only exception is naming a true blocker that prevents running the methodology CLI.\n"
        f"- Resolve the methodology CLI before running gates: use `tautline` (legacy `minervit-methodology`) from `PATH`, or if it is missing from `PATH` or exits 127/command-not-found, source `$HOME/.config/tautline/tautline.env` (or the legacy minervit env) when present or use `${{TAUTLINE_METHODOLOGY_REPO:-$MINERVIT_METHODOLOGY_REPO}}/bin/tautline`, then rerun the same gate. A missing `PATH` entry is not a failed methodology gate, not permission to substitute ad hoc checks, and not a reason to ask for a person-specific path.\n"
        f"- If both the `PATH` command and portable checkout fallback are unavailable, name the exact missing CLI/checkout true blocker before using Handoff Content.\n"
        f"- Methodology gate 1: run `tautline lane-start --target .`, or the resolved portable CLI equivalent if the `PATH` command is missing.\n"
        f"- Methodology gate 2: run `tautline methodology-status --target . --fail-on-drift`, or the resolved portable CLI equivalent if the `PATH` command is missing.\n"
        f"- Do not replace the methodology status gate with ad hoc `git status`, `git log`, CI checks, or local test commands.\n"
        f"- If either methodology gate is skipped or fails, stop before Handoff Content, resolve the gate failure, rerun the gate, and proceed only after it exits clean. If it cannot be resolved safely, name the exact true blocker.\n"
        f"- After the methodology status gate is clean, resume from this handoff: `{continuity['path']}`.\n"
        f"- Project gate after methodology status: `{data['commands']['mainStatus']}`.\n"
        f"- Project gate after methodology status: `{data['commands']['openPrCheck']}`.\n"
        f"- Project gate after methodology status: `{data['commands']['mergeConflictCheck']}`.\n\n"
        "## Handoff Content\n\n"
        f"{content.rstrip()}\n"
    )
    handoff.write_text(rendered, encoding="utf-8")
    return handoff


def prepare_continuity(args: argparse.Namespace) -> int:
    data = load_project(args.project)
    target = args.target.resolve()
    continuity = data["continuity"]

    content = sys.stdin.read().strip() if args.stdin else ""
    if args.content_file:
        content = args.content_file.read_text(encoding="utf-8").strip()

    handoff = write_continuity_handoff(data, target, content)
    print(f"wrote {handoff}")
    if continuity.get("gitIgnore", False):
        print(f"ignored {first_dir_pattern(continuity['path'])} via .git/info/exclude")
    try_write_event(
        data,
        target,
        event="continuity_written",
        severity="ok",
        plain=f"Continuity handoff was refreshed at {path_display(target, handoff)}.",
        next_action="Resume from the handoff next action after startup gates.",
    )
    return 0
















def unignored_committable_session_journals(data: dict, target: Path) -> list[Path]:
    """EVERY session-journal file in the local journal dir sitting in a NON-git-ignored path (pure of
    side effects) -- published-marked copies included, not only unpublished/pending ones, since a
    marker does not stop `git add` from staging the product narrative. These are product-narrative
    files a broad `git add` could commit to a remote despite narrative publication being disabled
    (an upgraded lane whose runs dir was never ignored, or a copy left by the pre-0.9.0 publication
    path). Startup surfaces them with removal/ignore guidance."""
    journal_dir = session_journal_local_dir(data, target)
    return [
        path
        for path in discover_session_journal_files(journal_dir)
        if not path_is_git_ignored(target, path)
    ]


def session_journal_leak_warning(data: dict, target: Path) -> str | None:
    """Startup leak-warning text (or None) for session-journal copies in a NON-git-ignored path. Pure:
    returns the message, never prints. Runs INDEPENDENTLY of the pending (unmarked) list -- a
    PUBLISHED-marked journal is cleared from pending_session_journals yet is just as committable by a
    broad `git add`, so the leak scan must never be gated on a non-empty pending list (that gate was
    the whole leak-detection gap: a lane whose only leakable copy is already marked warned nothing)."""
    unignored = unignored_committable_session_journals(data, target)
    if not unignored:
        return None
    return (
        "startup: WARNING these session journals are NOT git-ignored and could be "
        "committed to a remote by a broad `git add` -- narrative publication is disabled (0.9.0), "
        f"but these product-narrative copies remain a leak risk: {compact_path_list(unignored, target)}. "
        "Remove them, or add the runs dir to .gitignore (restore laneState.gitIgnore / "
        "sessionJournal.gitIgnoreLocal: true), before continuing."
    )


def event_repo_slug(data: dict) -> str:
    repo = str(data.get("repo") or data.get("project") or "repo")
    return slugify(repo, fallback="repo")




def observability_event_paths(data: dict, target: Path) -> tuple[Path, Path, Path]:
    observability = data["observabilityEvents"]
    directory = observability_state_dir(data) / event_repo_slug(data)
    human = directory / observability["humanLog"]
    jsonl = directory / observability["jsonlLog"]
    lock = directory / ".events.lock"
    return human, jsonl, lock


def print_event_log_status(data: dict, target: Path) -> None:
    human, jsonl, _lock = observability_event_paths(data, target)
    enabled = str(data["observabilityEvents"].get("enabled", True)).lower()
    print(f"event_log: enabled={enabled}")
    print(f"event_log_human: {human}")
    print(f"event_log_jsonl: {jsonl}")


def print_instrumentation_status(data: dict) -> None:
    """One status line for the sanitized-instrumentation record (0.9.0): the effective
    enabled+cadence combination. `enabled` alone permits publishing; `cadence` gates only whether
    boundary guidance prompts for emission (a disabled lane is never prompted)."""
    instrumentation = data.get("instrumentation", DEFAULT_INSTRUMENTATION)
    enabled = str(instrumentation.get("enabled", False)).lower()
    print(f"instrumentation: enabled={enabled} cadence={instrumentation.get('cadence', 'milestone')}")


iteration_review_config = _ir_mod.iteration_review_config


def iteration_review_renderer_source_dir() -> Path:
    return REPO_ROOT / "plugins/tautline-ops/skills/iteration-review/renderer-kit"


def iteration_review_renderer_dir() -> Path:
    return iteration_review_renderer_source_dir()


def iteration_review_renderer_state_dir() -> Path:
    configured = util_module().resolve_env("MINERVIT_RENDERER_KIT_STATE_DIR", "").strip()
    if configured:
        expanded = os.path.expandvars(configured.replace("$HOME", str(Path.home())))
        return Path(expanded).expanduser()
    # write-new/read-both: default to the tautline dir; keep a pre-existing legacy dir. No lock here.
    tautline = Path.home() / ".local/state/tautline/renderer-kit"
    legacy = Path.home() / ".local/state/minervit/renderer-kit"
    if not tautline.exists() and legacy.exists():
        return legacy
    return tautline


iteration_review_renderer_ignored_names = _ir_mod.iteration_review_renderer_ignored_names


def prepare_iteration_review_renderer_tree(source: Path, install_dir: Path) -> None:
    if not source.exists():
        raise SystemExit(f"iteration review renderer source is missing: {source}")
    # Containment must cover BOTH roots (B3-cat): installing npm dependencies into the canonical
    # checkout dirties the tree sync/rescue manages (rescue churn for every lane), and installing
    # into the exec root writes into an immutable snapshot. Neither is a methodology-repo path an
    # operator ever wants a node_modules tree in.
    if any(path_is_under(install_dir, root) for root in methodology_data_roots()):
        raise SystemExit(
            f"iteration review renderer install dir must be outside the methodology repo: {install_dir}"
        )
    install_dir.parent.mkdir(parents=True, exist_ok=True)
    shutil.copytree(
        source,
        install_dir,
        dirs_exist_ok=True,
        ignore=shutil.ignore_patterns(*iteration_review_renderer_ignored_names()),
    )


def setup_iteration_review_renderer(args: argparse.Namespace) -> int:
    source = iteration_review_renderer_source_dir()
    install_dir = iteration_review_renderer_state_dir()
    prepare_iteration_review_renderer_tree(source, install_dir)
    print(f"iteration_review_renderer_source: {source}")
    print(f"iteration_review_renderer_cache: {install_dir}")
    print("iteration_review_renderer_sync: ok")
    if args.no_install:
        print("iteration_review_renderer_install: skipped")
        print(f"iteration_review_renderer_next: cd {shlex.quote(str(install_dir))} && npm ci")
        return 0
    npm = shutil.which("npm")
    if not npm:
        print("iteration_review_renderer_install: blocked")
        print("iteration_review_renderer_issue: npm is not on PATH", file=sys.stderr)
        return 1
    install_command = [npm, "ci"] if (install_dir / "package-lock.json").exists() else [npm, "install"]
    code, out, err = run_command(install_command, install_dir, timeout=args.timeout_seconds)
    if code != 0:
        print("iteration_review_renderer_install: failed")
        if out:
            print(out, file=sys.stderr)
        if err:
            print(err, file=sys.stderr)
        return code
    print("iteration_review_renderer_install: ok")
    print(
        "iteration_review_renderer_render_example: "
        f"cd {shlex.quote(str(install_dir))} && npx remotion render src/index.ts IterationReview out/sample-iteration-review.mp4"
    )
    return 0


def iteration_review_record_dir(data: dict, target: Path) -> Path:
    return configured_path(target, data["iterationReview"]["recordDir"])


def print_iteration_review_status(data: dict, target: Path) -> list[str]:
    cfg = iteration_review_config(data)
    outputs = ", ".join(key for key, enabled in cfg["outputs"].items() if enabled) or "none"
    issues: list[str] = []
    renderer = iteration_review_renderer_source_dir()
    renderer_cache = iteration_review_renderer_state_dir()
    if cfg["enabled"] and cfg["outputs"].get("video") and not renderer.exists():
        issues.append(f"renderer kit missing: {renderer}")
    hosting_ready = bool(cfg["hosting"].get("bucket")) and bool(cfg["hosting"].get("baseUrl"))
    if cfg["enabled"] and cfg["outputs"].get("video") and not cfg["hosting"].get("bucket"):
        issues.append("video output enabled but iterationReview.hosting.bucket is blank")
    if cfg["enabled"] and cfg["outputs"].get("page") and not hosting_ready:
        issues.append(
            "iterationReview media hosting is not configured; page-only output may be text-only, "
            "but any screenshots, posters, clips, embedded video, or other page-referenced media require "
            "adapter-approved S3/CloudFront hosting"
        )
    if cfg["enabled"] and cfg["delivery"].get("enabled") and not cfg["delivery"].get("webhookEnv"):
        issues.append("iterationReview.delivery.enabled is true but webhookEnv is blank")
    print(f"iteration_review: enabled={str(cfg['enabled']).lower()}")
    print(f"iteration_review_targets: {', '.join(cfg['granularities'])}")
    print(f"iteration_review_outputs: {outputs}")
    print(f"iteration_review_record_dir: {iteration_review_record_dir(data, target)}")
    print(f"iteration_review_boundary_announce: {str(cfg['boundary']['announce']).lower()}")
    print(f"iteration_review_boundary_auto_run: {str(cfg['boundary']['autoRunAtBoundary']).lower()}")
    if cfg["enabled"] and "milestone" in cfg["granularities"]:
        print("iteration_review_milestone_completion_rule: customer-facing milestone reviews are explicitly enabled; otherwise milestone-complete uses milestoneUpdate")
    print(f"iteration_review_delivery: enabled={str(cfg['delivery']['enabled']).lower()} provider={cfg['delivery']['provider']} trigger={cfg['delivery']['trigger']}")
    print(f"iteration_review_delivery_webhook_env: {cfg['delivery'].get('webhookEnv') or 'not-configured'}")
    music = cfg["video"]["music"]
    print(
        "iteration_review_video_music: "
        f"enabled={str(music['enabled']).lower()} source={music['source']} "
        f"defaultUrl={music.get('defaultUrl') or 'not-configured'} volume={music['volume']:.2f}"
    )
    print(f"iteration_review_renderer_source: {renderer}")
    print(f"iteration_review_renderer_cache: {renderer_cache}")
    print(f"iteration_review_renderer_cache_ready: {str((renderer_cache / 'node_modules').exists()).lower()}")
    print(f"iteration_review_hosting: {cfg['hosting']['store']}+{cfg['hosting']['cdn']} bucket={cfg['hosting'].get('bucket') or 'not-configured'}")
    print("iteration_review_media_rule: outputs.video controls recap rendering only; setting it false does not waive hosting for page-referenced media")
    print("iteration_review_layout_rule: write each review in its own folder as <recordDir>/<review-id>/goal-review.json plus index.html")
    print("iteration_review_publish_rule: after the review lands on main, publish index.html to S3/CloudFront and post that URL to Google Chat when delivery is enabled")
    if cfg["enabled"] and cfg["boundary"]["announce"]:
        print("iteration_review_boundary_notice: non-blocking availability line only; never ask or pause")
    for issue in issues:
        print(f"iteration_review_issue: {issue}")
    return issues


def iteration_review_status(args: argparse.Namespace) -> int:
    data, _, target = lane_project(args)
    issues = print_iteration_review_status(data, target)
    cfg = iteration_review_config(data)
    # RCA O8: the webhook may be configured but not wired into the environment, so after-merge
    # delivery silently never posts. Surface this only in the dedicated `iteration-review-status
    # --strict` startup check (not in methodology-status, where an unset webhook is normal).
    delivery_webhook_env = str(cfg["delivery"].get("webhookEnv") or "").strip()
    if (
        args.strict
        and cfg["enabled"]
        and cfg["delivery"].get("enabled")
        and delivery_webhook_env
        and not webhook_env_reachable_value(delivery_webhook_env)
    ):
        print(
            "iteration_review_issue: iterationReview.delivery webhook env var "
            f"{delivery_webhook_env} is unset/empty in this environment; check the persisted "
            f"secrets store with `tautline secret-status --name {delivery_webhook_env}` before "
            "treating this as a blocker"
        )
        issues = list(issues) + ["delivery webhook env unset"]
    if issues:
        print("iteration_review_status: blocked")
        return 1 if args.strict else 0
    print("iteration_review_status: ok")
    if data["iterationReview"]["enabled"]:
        print("iteration_review_next_action: run `tautline validate-iteration-review --target . --file <record.json>` after composing a customer-facing GoalReview record")
    else:
        print("iteration_review_next_action: disabled by adapter; enable iterationReview before generating reviews")
    return 0


