def guard_check_prepush_committed_adapter(target: Path, local_sha: str) -> dict | None:
    """Load the repo-local source adapter from the COMMITTED tree at `local_sha` (never the mutable
    worktree), so an uncommitted local edit to the surface config cannot widen the exemption without
    appearing in the merge-base..local_sha diff. Fail closed (None) when no adapter is committed at
    local_sha, when the worktree copy is dirty vs local_sha, or when the committed content fails the
    real loader (which applies the broad-glob / source-of-truth surface rejection)."""
    for rel in (REPO_LOCAL_ADAPTER_FILE, LEGACY_REPO_LOCAL_ADAPTER_FILE):
        show_code, committed, _err = run_command(
            ["git", "-C", str(target), "show", f"{local_sha}:{rel}"], timeout=10
        )
        if show_code != 0:
            continue
        # Dirty check: the tracked worktree copy must match the committed tree at local_sha
        # (0 = clean, 1 = dirty, anything else = git error -> all fail closed).
        dirty_code, _out, _e = run_command(
            ["git", "-C", str(target), "diff", "--quiet", local_sha, "--", rel], timeout=10
        )
        if dirty_code != 0:
            return None
        try:
            with tempfile.NamedTemporaryFile(
                "w", suffix=".json", delete=False, encoding="utf-8"
            ) as handle:
                handle.write(committed)
                tmp_path = Path(handle.name)
        except OSError:
            return None
        try:
            return load_project(tmp_path)
        except SystemExit:
            return None
        finally:
            tmp_path.unlink(missing_ok=True)
    return None


def guard_check_prepush_pm_surface_skip(target: Path, project: str | None) -> bool:
    """True iff the pre-push review-evidence + CI gates may be skipped because the FULL branch diff
    against the configured base is PM-surfaces-only (Design 1). Fail closed to the full gate on any
    ambiguity: absent/unparseable records, multi-ref, branch DELETE, a non-branch (tag) ref, a
    non-current-branch push (local_sha != HEAD), a force/non-fast-forward push, a dirty/unreadable
    adapter at local_sha, or an undeterminable base/merge-base. The product-dev MODE is never read
    here -- path scoping is mode-independent."""
    # The exemption applies ONLY to the default pre-push hook path (`guard-check --target .
    # --boundary prepush`, no explicit --project). When an explicit --project is supplied the
    # review/board/CI gates below run against THAT adapter; granting the skip off the committed
    # .tautline/adapter.json would evaluate the exemption under a different policy/base than the
    # gates -- so fail closed.
    if project is not None:
        return False
    records_file = review_evidence_prepush_records_file()
    if records_file is None:
        return False
    try:
        text = records_file.read_text(encoding="utf-8")
    except OSError:
        return False
    records = parse_prepush_ref_records(text)
    if not records or len(records) != 1:  # absent/unparseable/multi-ref -> fail closed
        return False
    local_ref, local_sha_raw, remote_ref, remote_sha_raw = records[0]
    local_sha = local_sha_raw.strip()
    remote_sha = remote_sha_raw.strip()
    # BOTH the local and the remote ref must be branch refs: a branch->tag push (local_ref
    # refs/heads/X but remote_ref refs/tags/Y) or any other non-branch remote ref fails closed.
    if not local_ref.startswith("refs/heads/") or not remote_ref.startswith("refs/heads/"):
        return False
    if _PREPUSH_ZERO_OID_RE.fullmatch(local_sha):  # branch DELETE -> fail closed
        return False
    # The exemption applies ONLY to pushing the CURRENT checkout branch. local_sha == HEAD alone is
    # not enough: `git push origin other` while on a different branch that merely points at the same
    # commit has local_sha == HEAD too. Require local_ref to be the current symbolic branch ref
    # (a detached HEAD has none -> fail closed), AND local_sha == HEAD.
    sref_code, current_ref, _serr = run_command(
        ["git", "-C", str(target), "symbolic-ref", "--quiet", "HEAD"], timeout=10
    )
    if sref_code != 0 or not current_ref or current_ref.strip() != local_ref:
        return False
    head_code, head_sha, _err = run_command(
        ["git", "-C", str(target), "rev-parse", "HEAD"], timeout=10
    )
    if head_code != 0 or not head_sha or head_sha != local_sha:  # non-current-branch -> fail closed
        return False
    if not _PREPUSH_ZERO_OID_RE.fullmatch(remote_sha):
        # A remote tip that is not an ancestor of local_sha is a force / non-fast-forward push.
        ff_code, _out, _e = run_command(
            ["git", "-C", str(target), "merge-base", "--is-ancestor", remote_sha, local_sha],
            timeout=10,
        )
        if ff_code != 0:
            return False
    adapter = guard_check_prepush_committed_adapter(target, local_sha)
    if adapter is None:  # missing / dirty / invalid surface config at local_sha -> fail closed
        return False
    base = review_evidence_coordination_effective_base_candidate(adapter, target)
    if not base:  # undeterminable base -> fail closed
        return False
    mb_code, merge_base, _err = run_command(
        ["git", "-C", str(target), "merge-base", base, local_sha], timeout=10
    )
    if mb_code != 0 or not merge_base:  # undeterminable merge-base -> fail closed
        return False
    # FULL branch diff vs base (never the incremental remote..local range), rename detection off.
    changed = review_evidence_coordination_changed_paths(target, merge_base, local_sha)
    if changed is None:  # undeterminable diff -> fail closed
        return False
    return changed_paths_are_pm_surfaces_only(changed, adapter)


def test_run_evidence_fresh_default(target: Path, data: dict | None) -> bool:
    """Whether this lane's configured default is a fresh-checkout run. Never raises.

    Contained like everything else on this line: the caller is a report-only boundary printer, and
    an adapter that cannot be read must not break `lane-start`. Unknown resolves to False, which
    only ever costs a remedy line -- it can never claim a run was fresh when it was not.
    """
    try:
        if data is None:
            marker = adapter_marker_path(target)
            if not marker.exists():
                return False
            data = load_project(marker)
        cfg = test_evidence_config(data if isinstance(data, dict) else {})
        return bool(cfg["freshCheckout"]["default"])
    except (SystemExit, Exception):  # noqa: B036 - a reporter must never break a boundary
        return False


def test_run_evidence_lines(target: Path, data: dict | None = None) -> list[str]:
    """The report-only test-execution evidence line, plus a remedy line when it is not `current`.

    Report-only in Release 1: this NEVER changes an exit code anywhere it is printed. A fail-closed
    test-evidence gate on upgrade would recreate the 2026-07-22 startup-gate lockout, and the whole
    point is to make the gap visible first.

    Total containment: `classify_test_run_evidence` never raises by contract, but this is printed at
    `lane-start` -- a startup boundary -- so a defect here must degrade to silence rather than break
    startup.
    """
    try:
        module = test_evidence_module()
        state, record = module.classify_test_run_evidence(target)
    except (SystemExit, Exception):  # noqa: B036 - a reporter must never break a boundary
        return ["test_run_evidence: unavailable (evidence check failed)"]

    record = record or {}
    counts = record.get("counts") or {}
    if counts.get("source") and counts.get("collected") is not None:
        counts_text = f"{counts.get('passed')}/{counts.get('collected')}"
    else:
        counts_text = "unknown"
    digest_text = "n/a"
    if state == "current":
        digest_text = "match"
    elif state == "stale":
        digest_text = "differs"
    exit_code = record.get("exitCode")
    try:
        fresh_record = module.record_is_fresh_checkout(record)
    except Exception:  # noqa: BLE001 - a reporter must never break a boundary
        fresh_record = False
    lines = [
        f"test_run_evidence: {state} "
        f"recordedAt={record.get('finishedAt') or 'n/a'} "
        f"exitCode={exit_code if isinstance(exit_code, int) else 'n/a'} "
        f"counts={counts_text} digest={digest_text} "
        f"freshCheckout={'yes' if fresh_record else 'no'}"
    ]
    fresh_expected = test_run_evidence_fresh_default(target, data)
    if state == "current":
        if fresh_expected and not fresh_record:
            # The strongest local signal this lane has configured was not the one that produced
            # this record. Named rather than assumed: an in-place green is structurally blind to a
            # test that reads gitignored runtime state, and `current` alone does not say which
            # mode ran.
            lines.append(
                "test_run_evidence_next: this record is an in-place run, but the lane defaults to "
                "a fresh checkout; re-run `tautline test-run --fresh-checkout --target .` before "
                "pushing"
            )
        return lines

    # Name only a remedy that actually works right now. `test-run` is dispatch-BLOCKED while a
    # startup-remediation marker is active, so advertising it there would print a command the
    # dispatcher refuses -- the RCA control-6 defect, applied to our own output.
    try:
        remediating = startup_remediation_marker_path(target).exists()
    except OSError:
        remediating = False
    # The remedy names the mode the lane actually configured, so an operator who copies it does not
    # produce evidence the very next boundary tells them to redo.
    verb = "tautline test-run --target ."
    if fresh_expected:
        verb = "tautline test-run --fresh-checkout --target ."
    if remediating:
        lines.append(
            "test_run_evidence_next: complete startup remediation first, then run "
            f"`{verb}` (test-run is dispatch-blocked while remediation "
            "is active)"
        )
    else:
        lines.append(f"test_run_evidence_next: run `{verb}`")
    return lines


def test_evidence_enforcement_check(args: argparse.Namespace) -> int:
    """The prepush + finalize consumer of the test-execution record (item 37, Release 2).

    Reads the mode from the adapter and refuses only under `block`. Returns 0 in every other
    disposition, including `fail-open`, so a checker that cannot tell never stops a lane.

    The refusal prints the evaluator's own remedy lines verbatim rather than re-wording them:
    two copies of a remedy drift, and the drifted one is the copy the operator is reading when
    they decide `--no-verify` is easier.
    """
    target = args.target.expanduser().resolve(strict=False)
    try:
        data, _project_path, target = lane_project(args)
    except SystemExit:
        # Not adapter-backed: there is no mode to read and nothing to enforce. Never a refusal --
        # this check must not be the thing that stops a lane it was never configured for.
        return 0
    module = test_evidence_module()
    try:
        mode = test_evidence_config(data)["enforcement"]
    except SystemExit as exc:
        # A malformed knob is loud, but it is a CONFIG error, not a test failure, so it names
        # itself and stops rather than pretending the suite is bad.
        print(f"test_evidence_enforcement_error: {exc}", file=sys.stderr)
        return 1

    condition, disposition, lines = module.evaluate_test_evidence_enforcement(
        target, mode, guard_target_argument(target)
    )
    stream = sys.stderr if disposition == module.BLOCK else sys.stdout
    for line in lines:
        print(line, file=stream)
    if disposition == module.BLOCK:
        return 1
    # Codex R3 P3: `off` returns no lines BY CONTRACT -- the schema and the changelog both say it
    # is silent -- and this fallback was printing a summary anyway, so `off` was quieter than
    # `warn` but not actually silent. A knob that does not do what its own documentation says is
    # the small end of the same problem this release is about.
    if not lines and mode != "off":
        print(f"test_evidence_enforcement: {condition} (enforcement={mode})")
    return 0


def guard_check_closeout_rc(pending_data: dict, target: Path) -> int:
    """The guard's verdict on a recorded pending closeout: 1 to block, 0 to let the push through.

    ONE PREDICATE, BOTH READERS. `pending_closeout_errors` has already decided which of its
    messages are advisory (an unreadable board -- D3 fail-open) and which are verified not-done.
    Re-deciding here by "is the list non-empty" threw that decision away and blocked every push
    through a GitHub outage anyway, which is the outcome D3 exists to prevent. Codex R3 P2.
    Every message still PRINTS either way -- fail-open never means fail-silent.
    """
    pending_errors = pending_closeout_errors(pending_data, target)
    for issue in pending_errors:
        print(f"guard_check_closeout_issue: {issue}", file=sys.stderr)
    if any(not issue_is_unverifiable(issue) for issue in pending_errors):
        print(
            "guard_check: blocked - a merged PR's board closeout is still owed",
            file=sys.stderr,
        )
        return 1
    return 0


def guard_check_pending_closeout_data(target: Path, project) -> dict | None:
    """The adapter for the pending-closeout predicate, or None when there is nothing to check.

    guard-check runs on lanes that may not be adapter-backed at all, and this predicate is an
    ADDITION to an existing boundary -- so it must never be the reason the boundary crashes. No
    record means nothing to verify; no readable adapter means no lane state to resolve it against.
    """
    if not pending_closeout_record_exists(target):
        return None
    try:
        data, _, _ = lane_project(argparse.Namespace(project=project, target=target))
    except SystemExit:
        return None
    return data


def guard_check(args: argparse.Namespace) -> int:
    target = args.target.expanduser().resolve(strict=False)
    boundary = str(args.boundary or "").strip()
    print(f"guard_check_boundary: {boundary}")

    # Hoisted ABOVE the blocker gate on purpose: printed after it, this line vanishes on exactly
    # the blocked-prepush runs where the operator most needs to know the suite was never run. Pure
    # output -- no exit code below is touched.
    if boundary == "prepush":
        for line in test_run_evidence_lines(target):
            print(line)

    blocker_rc = guard_check_blocker_state(target)
    if blocker_rc:
        return blocker_rc

    # Item 79 WS1. STATUS and PREPUSH only -- deliberately not the stop seam. A merged PR whose
    # board closeout is still owed is a real blocking condition, but adding one to the Stop-guard
    # surface belongs to wave 3, which owns that surface and its aggregate false-positive budget.
    # This predicate fails OPEN with a named warning when it cannot verify the merge state, so a
    # provider outage cannot wedge every push on every lane (D3).
    if boundary in {"status", "prepush"}:
        pending_data = guard_check_pending_closeout_data(target, getattr(args, "project", None))
        if pending_data is not None:
            rc = guard_check_closeout_rc(pending_data, target)
            if rc:
                return rc

    if boundary != "prepush":
        print("guard_check: ok")
        return 0

    project = getattr(args, "project", None)
    pm_surface_skip = guard_check_prepush_pm_surface_skip(target, project)
    if pm_surface_skip:
        print(
            "guard_check_pm_surface: full branch diff vs base is PM-surfaces-only; "
            "skipping review-evidence + CI gates (board check still enforced)"
        )
    checks: list[tuple[str, object, argparse.Namespace]] = []
    if not pm_surface_skip:
        checks.append(
            (
                "review evidence",
                review_evidence_check,
                argparse.Namespace(
                    project=project, target=target, strict=True, scope_strict=False, base=None
                ),
            )
        )
    checks.append(
        (
            "board currency",
            backlog_provider_board_check,
            argparse.Namespace(project=project, target=target, strict=False),
        )
    )
    if not pm_surface_skip:
        checks.append(
            (
                "ci test gate",
                ci_health_check,
                argparse.Namespace(project=project, target=target, strict=False),
            )
        )
        # Item 37 Release 2. The fourth check, and the first one that reads an EXECUTION rather
        # than a declaration. Skipped under the PM-surfaces-only allowance for the same reason
        # review-evidence and the CI gate are: a docs-only push has no suite to have run.
        checks.append(
            (
                "test evidence",
                test_evidence_enforcement_check,
                argparse.Namespace(project=project, target=target),
            )
        )
    for label, func, check_args in checks:
        rc = guard_check_call(label, func, check_args)
        if rc:
            return rc
    print("guard_check: ok")
    return 0


