def load_goal_run(data: dict, target: Path) -> dict:
    path = goal_run_path(data, target)
    if not path.exists():
        raise SystemExit(f"goal run missing: {path}. Start one with goal-start --target . --goal <source-of-truth-goal-plan>.")
    try:
        run = json.loads(path.read_text(encoding="utf-8"))
    except json.JSONDecodeError as exc:
        raise SystemExit(f"goal run invalid JSON: {path}: {exc}") from exc
    if run.get("schema") != GOAL_RUN_SCHEMA:
        raise SystemExit(f"goal run has unsupported schema: {run.get('schema')}")
    action = goal_next_action_record(run)
    run["percentComplete"] = goal_percent_complete(run)
    run["nextAction"] = action
    run["status"] = goal_status_from_action(action, run.get("status"))
    return run


def save_goal_run(data: dict, target: Path, run: dict) -> Path:
    path = goal_run_path(data, target)
    path.parent.mkdir(parents=True, exist_ok=True)
    run["updatedAt"] = now_iso()
    action = goal_next_action_record(run)
    run["percentComplete"] = goal_percent_complete(run)
    run["nextAction"] = action
    run["status"] = goal_status_from_action(action, run.get("status"))
    path.write_text(json.dumps(run, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    return path


def initial_goal_run(data: dict, target: Path, goal_path: Path) -> dict:
    milestones = goal_milestones_from_plan(goal_path)
    now = now_iso()
    return {
        "schema": GOAL_RUN_SCHEMA,
        "createdAt": now,
        "updatedAt": now,
        "project": data["project"],
        "repo": data["repo"],
        "goalId": slugify(goal_path.stem, "goal"),
        "sourceGoal": path_relative_to_target(target, goal_path),
        "currentMilestoneIndex": 1,
        "status": "active",
        "percentComplete": 0,
        "validationProof": [],
        "multiSession": goal_plan_is_multi_session(goal_path),
        "knownOperatorDependencies": goal_operator_dependency_entries(goal_path),
        "milestones": [
            {
                "index": index + 1,
                "title": title,
                "status": "in_progress" if index == 0 else "pending",
                "sourcePlan": None,
                "milestoneRun": None,
                "prRefs": [],
                "validationEvidence": [],
                "blockers": [],
                "updatedAt": now,
            }
            for index, title in enumerate(milestones)
        ],
        "events": [
            {"timestamp": now, "event": "goal-start", "detail": f"started from {path_relative_to_target(target, goal_path)}"}
        ],
        "nextAction": {},
    }


def refresh_goal_run(data: dict, target: Path, run: dict, goal_path: Path) -> dict:
    source_goal = path_relative_to_target(target, goal_path)
    existing_source_goal = run.get("sourceGoal")
    if existing_source_goal and existing_source_goal != source_goal:
        raise SystemExit(
            "goal refresh would retarget an existing ledger from "
            f"{existing_source_goal} to {source_goal}. Finish/archive the current goal run or start a new goal run intentionally."
        )
    titles = goal_milestones_from_plan(goal_path)
    existing = {str(item.get("title", "")).strip().lower(): item for item in run.get("milestones", [])}
    now = now_iso()
    refreshed = []
    refreshed_keys = set()
    for index, title in enumerate(titles, 1):
        key = title.strip().lower()
        refreshed_keys.add(key)
        previous = existing.get(key)
        if previous:
            milestone = {**previous, "index": index, "title": title}
        else:
            milestone = {
                "index": index,
                "title": title,
                "status": "pending",
                "sourcePlan": None,
                "milestoneRun": None,
                "prRefs": [],
                "validationEvidence": [],
                "blockers": [],
                "updatedAt": now,
            }
        refreshed.append(milestone)
    dropped = []
    dropped_pending = []
    for key, milestone in existing.items():
        if key in refreshed_keys:
            continue
        has_state = (
            milestone.get("status") in (GOAL_TERMINAL_STATUSES | {"in_progress", "blocked"})
            or bool(milestone.get("sourcePlan"))
            or bool(milestone.get("milestoneRun"))
            or bool(milestone.get("prRefs"))
            or bool(milestone.get("blockers"))
            or bool(milestone.get("validationEvidence"))
        )
        if has_state:
            dropped.append(f"{milestone.get('index')}: {milestone.get('title')} ({milestone.get('status')})")
        else:
            dropped_pending.append(f"{milestone.get('index')}: {milestone.get('title')}")
    if dropped:
        raise SystemExit(
            "goal refresh would drop existing milestone state: "
            + "; ".join(dropped)
            + ". Preserve the milestone title, finish/archive the current goal run, or start a new goal run intentionally."
        )
    run.update(
        {
            "project": data["project"],
            "repo": data["repo"],
            "goalId": slugify(goal_path.stem, "goal"),
            "sourceGoal": source_goal,
            "multiSession": goal_plan_is_multi_session(goal_path),
            "knownOperatorDependencies": goal_operator_dependency_entries(goal_path),
            "milestones": refreshed,
        }
    )
    if not any(item.get("status") == "in_progress" for item in refreshed):
        for item in refreshed:
            if item.get("status") in GOAL_ACTIVE_STATUSES:
                item["status"] = "in_progress"
                item["updatedAt"] = now
                run["currentMilestoneIndex"] = item["index"]
                break
    run.setdefault("events", []).append(
        {"timestamp": now, "event": "goal-refresh", "detail": f"refreshed from {path_relative_to_target(target, goal_path)}"}
    )
    for dropped_item in dropped_pending:
        run.setdefault("events", []).append(
            {
                "timestamp": now,
                "event": "goal-refresh-dropped-pending",
                "detail": f"dropped pending milestone with no state: {dropped_item}",
            }
        )
    return run


def print_goal_run(run: dict, path: Path) -> None:
    action = goal_next_action_record(run)
    current = next((item for item in run.get("milestones", []) if item.get("status") == "in_progress"), None)
    pending = next((item for item in run.get("milestones", []) if item.get("status") == "pending"), None)
    print(f"goal_run: {path}")
    print(f"goal_id: {run.get('goalId')}")
    print(f"source_goal: {run.get('sourceGoal')}")
    print(f"status: {run.get('status')}")
    print(f"percent_complete: {run.get('percentComplete', goal_percent_complete(run))}")
    print(f"multi_session: {str(bool(run.get('multiSession'))).lower()}")
    print(f"current_milestone: {current['index']} - {current['title']}" if current else "current_milestone: none")
    print(f"next_pending_milestone: {pending['index']} - {pending['title']}" if pending else "next_pending_milestone: none")
    dependencies = run.get("knownOperatorDependencies") or []
    print(f"known_operator_dependencies: {len(dependencies)}")
    for dependency in dependencies[:5]:
        print(f"known_operator_dependency: {dependency}")
    if len(dependencies) > 5:
        print(f"known_operator_dependencies_omitted: {len(dependencies) - 5}")
    if current:
        current_dependencies = goal_dependencies_for_milestone(run, current)
        print(f"current_milestone_operator_dependencies: {len(current_dependencies)}")
        for dependency in current_dependencies[:5]:
            print(f"current_milestone_operator_dependency: {dependency}")
        if len(current_dependencies) > 5:
            print(f"current_milestone_operator_dependencies_omitted: {len(current_dependencies) - 5}")
    print(f"next_action_type: {action['type']}")
    print(f"next_action: {action['instruction']}")


def goal_start(args: argparse.Namespace) -> int:
    data, _, target = lane_project(args)
    ensure_lane_state(data, target)
    goal_path = resolve_goal_plan_path(data, target, args.goal)
    path = goal_run_path(data, target)
    if path.exists():
        run = refresh_goal_run(data, target, load_goal_run(data, target), goal_path)
    else:
        run = initial_goal_run(data, target, goal_path)
    goal_tracker_sync_transition(data, target, run, "goal-start")
    save_goal_run(data, target, run)
    saved = load_goal_run(data, target)
    print_goal_run(saved, path)
    try_write_event(
        data,
        target,
        event="goal_run_active",
        severity="ok",
        plain=f"Goal ledger is active for {saved.get('goalId') or path_display(target, goal_path)}.",
        next_action=goal_next_action_record(saved)["instruction"],
        refs={"goal_plan": path_display(target, goal_path), "goal_run": path_display(target, path)},
    )
    return 0


def goal_status(args: argparse.Namespace) -> int:
    data, _, target = lane_project(args)
    ensure_lane_state(data, target)
    path = goal_run_path(data, target)
    run = load_goal_run(data, target)
    print_goal_run(run, path)
    for issue in goal_tracker_drift_issues(data, target, run):
        print(f"goal_tracker_issue: {issue}")
    return 0






def goal_advance(args: argparse.Namespace) -> int:
    if args.event not in GOAL_ADVANCE_EVENTS:
        raise SystemExit(f"unsupported goal event: {args.event}")
    if args.event == "milestone-blocked" and not args.reason:
        raise SystemExit("--reason is required for milestone-blocked")
    if args.event == "milestone-deferred" and not args.reason:
        raise SystemExit("--reason is required for milestone-deferred")
    data, _, target = lane_project(args)
    ensure_lane_state(data, target)
    path = goal_run_path(data, target)
    run = load_goal_run(data, target)
    ui_blocker, ui_manifest_path, ui_manifest = ui_evidence_completion_blocker(
        data,
        target,
        args.event,
        args.ui_evidence_manifest,
    )
    if ui_blocker:
        raise SystemExit(ui_blocker)
    now = now_iso()
    event_detail = args.detail or ""
    transitioned_milestone = None
    milestone_ac_text = ""
    if args.event == "startup":
        if not any(item.get("status") == "in_progress" for item in run.get("milestones", [])):
            promote_next_goal_milestone(run, now)
            event_detail = event_detail or "resumed next pending milestone"
    elif args.event == "goal-complete":
        open_items = [
            f"{item.get('index')}: {item.get('title')} ({item.get('status')})"
            for item in run.get("milestones", [])
            if item.get("status") not in GOAL_TERMINAL_STATUSES
        ]
        if open_items:
            raise SystemExit("goal cannot complete while milestones are non-terminal: " + "; ".join(open_items))
        if not args.detail:
            raise SystemExit("--detail is required for goal-complete and must summarize validation proof")
        iteration_review_blocker = iteration_review_goal_completion_blocker(
            data,
            target,
            args.iteration_review_record,
            goal_id=str(run.get("goalId") or ""),
        )
        if iteration_review_blocker:
            raise SystemExit(iteration_review_blocker)
        if args.iteration_review_record:
            run["iterationReviewRecord"] = path_relative_to_target(
                target,
                cli_path(target, str(args.iteration_review_record)).resolve(strict=False),
            )
        run.setdefault("validationProof", []).append(args.detail)
        run["status"] = "complete"
        # Batch 2026-08-11 B7 WS3: stamp WHO completed this, so the Stop arm can tell "this
        # session declared its own goal done" from "a session last week did". Without it the
        # arm either warns on every later unrelated session or never fires at all.
        run["completedAt"] = now
        # Read through the resolver, not os.environ: MINERVIT_-prefixed names have TAUTLINE_
        # aliases that must win, and the shipped-source gate enforces one read path for all of
        # them. CLAUDE_CODE_SESSION_ID is the harness's own name and passes through unchanged.
        completed_by = str(
            getattr(args, "session_id", "")
            or util_module().resolve_env("CLAUDE_CODE_SESSION_ID")
            or util_module().resolve_env("MINERVIT_SESSION_ID")
            or ""
        ).strip()
        if completed_by:
            run["completedBySession"] = completed_by
        else:
            # A rerun in a LATER session with no resolvable id must not inherit the previous
            # session's stamp. Leaving it makes the Stop arm correlate this completion to a
            # session that has ended, so it suppresses the advisory for the session actually
            # standing at the boundary -- the arm reporting healthy because the fact it keys
            # on is stale rather than absent.
            run.pop("completedBySession", None)
        event_detail = args.detail
    else:
        milestone = selected_goal_milestone(run, args.milestone_index)
        transitioned_milestone = milestone
        if args.milestone_plan:
            milestone["sourcePlan"] = path_relative_to_target(target, cli_path(target, args.milestone_plan))
        if args.milestone_run:
            milestone["milestoneRun"] = path_relative_to_target(target, cli_path(target, args.milestone_run))
        if args.pr:
            refs = milestone.setdefault("prRefs", [])
            if str(args.pr) not in refs:
                refs.append(str(args.pr))
        if args.event == "milestone-started":
            milestone["status"] = "in_progress"
            run["currentMilestoneIndex"] = milestone["index"]
            event_detail = event_detail or f"started milestone {milestone['index']}"
        elif args.event == "milestone-complete":
            # Resolved ONCE, here, and this exact string is both what the guard weighs and what
            # composition appends below. Codex R2 P2(a): a raw truthiness check on the KEY let an
            # empty or whitespace-only file satisfy the guard while composition contributed
            # nothing, so the command could publish the required UI-proof comment and only then
            # refuse for missing verification evidence -- the no-mutation-on-refusal property,
            # broken by resolving one value twice and getting two answers.
            #
            # Resolved for THIS event only. Codex R2 P2(b): milestone-started, -blocked, and
            # -deferred never use AC verification, and a stale or out-of-tree path must not be able
            # to block the very transitions a lane uses to report that something is wrong.
            milestone_ac_text = milestone_ac_verification_text(target, milestone)
            if not (
                args.detail
                or args.milestone_run
                or milestone.get("milestoneRun")
                or milestone.get("validationEvidence")
                # An AC verdict table IS completion evidence -- the strongest form this command
                # accepts. Codex R1 P2: without it here the no-flag channel below is unreachable,
                # because a lane that authored the table into the milestone and supplied nothing
                # else is refused by this guard before composition ever runs. A feature whose only
                # entry point is closed by a guard one block up is not a feature.
                or milestone_ac_text
            ):
                emptied = " The milestone's acVerification is set but resolves to no text." if (
                    milestone.get("acVerification")
                ) else ""
                raise SystemExit(
                    "--detail or --milestone-run is required for milestone-complete "
                    "(or an AC verdict table in the milestone's acVerification key; "
                    "`tautline ac-verify --item <item-ref> --target . --out <path>` writes one)."
                    + emptied
                )
            update_blocker = milestone_update_completion_blocker(data, target, milestone)
            if update_blocker:
                raise SystemExit(update_blocker)
            milestone["status"] = "complete"
            if args.detail:
                milestone.setdefault("validationEvidence", []).append(args.detail)
            event_detail = event_detail or f"completed milestone {milestone['index']}"
            promote_next_goal_milestone(run, now)
        elif args.event == "milestone-deferred":
            milestone["status"] = "deferred"
            milestone.setdefault("deferralReasons", []).append(args.reason)
            event_detail = event_detail or args.reason
            promote_next_goal_milestone(run, now)
        elif args.event == "milestone-blocked":
            milestone["status"] = "blocked"
            milestone.setdefault("blockers", []).append(args.reason)
            run["currentMilestoneIndex"] = milestone["index"]
            event_detail = event_detail or args.reason
        milestone["updatedAt"] = now
    # Item 81: goal-advance is the primary AUTONOMOUS closure path and had no operator evidence
    # channel at all -- its evidence was machine-composed. Without this channel the
    # oracle-discipline gate would dead-end exactly the path it most needs to hold. It is composed
    # through the same `backlog_provider_done_evidence_text` the other two done verbs use, so file
    # reading and URL validation keep one definition.
    #
    # Resolved and GATED here, above the UI-evidence block, not below it. Codex R3 P2: this command
    # posts a required UI-proof comment before the transition, so a closure refused for a missing or
    # failing AC table used to happen AFTER that comment was already public -- the same "a refused
    # done move mutates nothing" property the pre-flight seam exists to hold, broken one caller up.
    # The transition is then told the gate has already run, so the issue body is fetched once.
    # Two sources, both appended, milestone first. There is no precedence rule and deliberately so:
    # the gate resolves verdicts by criterion, taking the LAST one recorded, so a flag correction
    # supplied at the command line lands after the milestone's table and decides. An earlier design
    # tried to rank these at compose time and could not -- the composer has no criteria, and two
    # rows can name the same criterion without naming each other.
    supplied = "\n\n".join(
        part
        for part in (
            milestone_ac_text,
            backlog_provider_done_evidence_text(args, target),
        )
        if part
    )
    done_evidence = goal_tracker_done_evidence_for_transition(
        args.event, args.detail or "", transitioned_milestone, ac_verification=supplied
    )
    # Batch 2026-08-11 B7 WS2: the definition of done, at the SAME pre-flight seam and BEFORE
    # the closure gate, so a refusal here mutates nothing at all. `pending_close=True` tells
    # `board_updated` to ask whether this transition carries closure evidence rather than
    # whether the item is already done -- the latter would be unsatisfiable by the very
    # command that satisfies it.
    done_bar_failures = done_bar_goal_completion_errors(
        data, target, run, args.event, done_evidence
    )
    if done_bar_failures:
        raise SystemExit(
            "goal cannot complete: the definition of done is not met. "
            + " ".join(done_bar_failures)
            + " Legal exits: satisfy the condition, disable it for this project under "
            "`definitionOfDone.conditions`, or declare a true blocker with "
            "`tautline blocker-declare --kind <k> --reason <r>`."
        )
    goal_advance_closure_preflight(data, target, run, args.event, transitioned_milestone, done_evidence)
    ui_evidence_comment_output: list[str] = []
    ui_comments = data["uiEvidence"]["issueComments"]
    ui_comment_required = (
        data["uiEvidence"]["enabled"]
        and ui_comments["enabled"]
        and ui_comments["required"]
        and args.event in ui_comments["triggerEvents"]
    )
    if ui_comment_required:
        ui_evidence_comment_output, ui_comment_ok = sync_goal_issue_ui_evidence(
            data,
            target,
            run,
            args.event,
            ui_manifest_path,
            ui_manifest,
        )
        if not ui_comment_ok:
            raise SystemExit("; ".join(ui_evidence_comment_output) or "ui evidence issue comment failed")
    goal_tracker_sync_transition(
        data,
        target,
        run,
        args.event,
        transitioned_milestone,
        done_evidence=done_evidence,
        ac_checked=True,
    )
    run.setdefault("events", []).append({"timestamp": now, "event": args.event, "detail": event_detail})
    save_goal_run(data, target, run)
    saved = load_goal_run(data, target)
    print_goal_run(saved, path)
    for line in sync_goal_issue_milestone_progress(data, target, saved):
        print(line)
    if not ui_comment_required:
        ui_evidence_comment_output, _ui_comment_ok = sync_goal_issue_ui_evidence(
            data,
            target,
            saved,
            args.event,
            ui_manifest_path,
            ui_manifest,
        )
    for line in ui_evidence_comment_output:
        print(line)
    if args.event == "goal-complete":
        source_goal_path = goal_run_source_path(data, target, saved)
        excluded = {source_goal_path} if source_goal_path else set()
        print_next_goal_candidate(data, target, exclude_paths=excluded)
    next_action = goal_next_action_record(saved)["instruction"]
    try_write_event(
        data,
        target,
        event=f"goal_advance_{args.event.replace('-', '_')}",
        severity="block" if args.event == "milestone-blocked" else "ok",
        plain=f"Goal transition recorded: {args.event}. {event_detail}",
        next_action=next_action,
        pr=args.pr,
        refs={"goal_run": path_display(target, path)},
    )
    return 0


def goal_next(args: argparse.Namespace) -> int:
    data, _, target = lane_project(args)
    ensure_lane_state(data, target)
    path = goal_run_path(data, target)
    run = load_goal_run(data, target)
    run["nextAction"] = goal_next_action_record(run)
    run["percentComplete"] = goal_percent_complete(run)
    print_goal_run(run, path)
    return 0


def goal_condition(args: argparse.Namespace) -> int:
    data, _, target = lane_project(args)
    ensure_lane_state(data, target)
    run = load_goal_run(data, target)
    path = goal_run_path(data, target)
    rotation = data["contextRotation"]
    boundary_clause = ""
    if run.get("multiSession") or run.get("knownOperatorDependencies"):
        boundary_clause = (
            " If the goal plan is explicitly multi-session or has known operator-input blockers, the current "
            "session may also end after an authorized increment is delivered, continuity is refreshed, journal work "
            "is handled or queued, and the boundary is a true blocker or genuine scope boundary with goal-ledger "
            "evidence. Context exhaustion by itself does not satisfy the goal; it requires continuity, journal handling, "
            "host compact/restart, and resumption of this same goal."
        )
    # `goal-condition` is a SECOND goal-emitting surface -- the documented Claude `/goal` path --
    # and WS4 only fixed the assignment path. Left alone it kept printing the pre-B7 completion
    # text, so the command the operator actually runs would still authorize a stop at an open
    # unarmed PR while `done-check` and `goal-advance` applied the new bar. Two surfaces deriving
    # the bar separately IS the divergence this item exists to close, so this reads the same
    # single source rather than restating it: a project that disables a condition sees the
    # printed goal drop that clause too.
    done_clause = goal_assignment_module().compose_done_clause(
        goal_assignment_effective_conditions(data, target)
    )
    ui_clause = ""
    if data["uiEvidence"]["enabled"] and data["uiEvidence"]["enforcement"] == "block":
        ui_clause = (
            " configured UI evidence is satisfied with a Playwright screenshot manifest passed to "
            "`goal-advance --ui-evidence-manifest` or discovered in the adapter evidence directory, and the GitHub issue proof comment succeeds when the adapter requires it,"
        )
    condition = (
        f"{data['goalExecution']['preferredClaudeCommand']} Complete goal `{run.get('goalId')}` from "
        f"`{run.get('sourceGoal')}`. Completion means every milestone in `{data['laneState']['goalRun']}` "
        "is complete or policy-deferred, required validation proof is surfaced in this conversation, no open Critical/P1 "
        "blockers remain, required iteration-review delivery has passed when the adapter enables goal reviews,"
        f"{ui_clause} no active PR branch is being edited after queue/merge/close, continuity and session journal "
        "evidence are refreshed, and `tautline goal-status --target .` reports goal complete or ready for "
        f"goal completion.{done_clause}{boundary_clause} Use `tautline goal-next --target .` before milestone/PR work; if Claude `/goal` is unavailable "
        "or cleared, continue with the same goal ledger instead of stopping. During long `/goal` work, after each "
        f"meaningful subtask and at least every {rotation['heartbeatMinutes']} minutes, inspect the visible context "
        f"indicator and run `tautline context-rotation-check --target . --boundary {rotation['heartbeatBoundary']} "
        "--context-percent <visible-percent> --context-percent-source estimate` when the host exposes a percent (pass "
        "--context-percent-source host only if the host literally exposes a context-window counter; an estimate can "
        "recommend rotation but never make it mandatory); when the CLI says recommended or "
        "mandatory, refresh continuity and journal evidence, invoke `/compact` or the strongest host compact/restart "
        "path when available, or if this agent turn cannot invoke `/compact` directly, state the exact fresh-session "
        "startup action without opt-in language; then resume this same goal instead of stopping."
    )
    print(f"goal_run: {path}")
    print("goal_condition_scope: claude-lanes; Codex and non-Claude lanes should use goal-next and goal-status directly")
    print(f"goal_condition: {condition}")
    print("proof_commands:")
    print("- tautline goal-status --target .")
    print("- tautline milestone-status --target .")
    print("- tautline methodology-status --target . --fail-on-drift")
    if data["uiEvidence"]["enabled"]:
        print("- tautline goal-advance --target . --event <milestone-complete|goal-complete> --ui-evidence-manifest <manifest>")
    return 0


def goal_assignment(args: argparse.Namespace) -> int:
    """Emit (or check) the assignable goal that hands a finalized plan to the builder lane.

    Fails closed on length. The cap is the host's, not ours: a goal over it is refused at
    paste time, long after the planning session that wrote it has ended.
    """
    data, _project_path, target = lane_project(args)
    module = goal_assignment_module()
    limit = args.char_limit
    if limit < module.GOAL_ASSIGNMENT_MIN_CHARS:
        print(
            "goal_assignment_error: --char-limit must be at least "
            f"{module.GOAL_ASSIGNMENT_MIN_CHARS}",
            file=sys.stderr,
        )
        return 1

    plan_rel: str | None = None
    plan_path: Path | None = None
    if args.plan is not None:
        plan_path = plan_root_resolve(data, target, args.plan)
        # Containment is checked BEFORE the reference is rendered, which raises on a path under no
        # configured root. A fail-closed surface must refuse with an actionable message, never a
        # traceback (Codex T2 R1 P2). What WIDENED is the question: "under this lane" became
        # "under any configured plan root", because a plan the lane just reviewed externally must
        # be assignable to the builder who will execute it. Codex R2 P2 -- the handoff was
        # unusable for the very workflow this item adds.
        if not plan_is_under_a_configured_root(data, target, plan_path):
            print(
                f"goal_assignment_error: plan is outside every configured plan root: {plan_path} "
                f"not under {target} or a configured planRepo",
                file=sys.stderr,
            )
            return 1
        plan_rel = plan_root_relative_reference(data, target, plan_path)

    if args.check is not None:
        # Checking an authored goal: the plan is optional context, so an operator can vet a
        # pasted goal without one. Reading '-' from stdin keeps this pipeable from an agent.
        if str(args.check) == "-":
            text = sys.stdin.read()
        else:
            check_path = cli_path(target, str(args.check)).resolve(strict=False)
            if not check_path.is_file():
                print(f"goal_assignment_error: goal file missing: {check_path}", file=sys.stderr)
                return 1
            text = check_path.read_text(encoding="utf-8", errors="replace")
        text = text.strip()
        conditions = goal_assignment_effective_conditions(data, target)
        issues = module.goal_assignment_issues(
            text,
            plan_ref=plan_rel,
            limit=limit,
            require_handoff="pr_handed_off" in conditions,
        )
        authoring_limit = module.goal_assignment_authoring_limit(limit)
        print(f"goal_assignment_char_count: {len(text)}")
        print(f"goal_assignment_char_limit: {limit}")
        print(f"goal_assignment_authoring_limit: {authoring_limit}")
        print(f"goal_assignment_headroom: {authoring_limit - len(text)}")
        if plan_rel is None:
            # Say what was NOT checked. Passing --check without --plan cannot verify the goal
            # names a source-of-truth plan, and a silent skip would read as a clean bill of
            # health on a check the run never ran (Codex T2 R1 P2).
            print(
                "goal_assignment_plan_reference_check: skipped (no --plan given); "
                "pass --plan <plan> to verify the goal names its source-of-truth plan"
            )
        if issues:
            for issue in issues:
                print(f"goal_assignment_error: {issue}", file=sys.stderr)
            print(
                "goal_assignment_next_action: shorten the goal to point at the plan instead of "
                "restating it, or regenerate it with `tautline goal-assignment --target "
                f"{guard_target_argument(target)} --plan <plan>`",
                file=sys.stderr,
            )
            return 1
        print("goal_assignment_check: pass")
        return 0

    if plan_path is None:
        print(
            "goal_assignment_error: --plan is required when composing a goal assignment "
            "(use --check <file|-> to validate an already-authored goal)",
            file=sys.stderr,
        )
        return 1

    source_root = planning_source_root(data, target)
    if not plan_path.is_file():
        print(f"goal_assignment_error: plan missing: {plan_path}", file=sys.stderr)
        return 1
    if not plan_is_under_a_configured_root(data, target, plan_path):
        print(
            "goal_assignment_error: plan outside source-of-truth path: "
            f"{plan_path} not under {source_root}",
            file=sys.stderr,
        )
        return 1

    # The workflow this verb sits in is "planning complete and finalized" THEN "goal
    # assigned". Composing from an unfinalized plan would hand the builder lane work whose
    # review evidence is still moving, so the precheck gates composition rather than merely
    # advising it. --allow-unfinalized exists for dry-running the wording mid-planning and
    # says so in its own output.
    finalized_errors, _plan, _manifest = plan_finalization_precheck_errors(data, target, args.plan)
    if finalized_errors and not args.allow_unfinalized:
        for error in finalized_errors:
            print(f"goal_assignment_error: plan is not finalized: {error}", file=sys.stderr)
        print(
            "goal_assignment_next_action: "
            + plan_review_recovery_instruction(data, target, plan_path),
            file=sys.stderr,
        )
        return 1

    plan_text = plan_path.read_text(encoding="utf-8", errors="replace")
    milestones = module.plan_assignment_milestones(plan_text)
    # The operator asked for a goal focused on acceptance criteria and the composer stated only
    # the adapter's definition of done, so every goal read the same regardless of which plan it
    # came from. The plan's own bar leads the clause; the definition-of-done floor stays behind
    # it. A plan with no acceptance section yields none and composes with the floor alone.
    # The adapter's own acceptance headings, not a second hardcoded list: `planAcceptance`
    # already tells plan finalization which section holds this project's criteria, and a
    # composer that ignored it would report "no acceptance section" for the very section the
    # finalization gate just graded.
    ac_headings = (data.get("planAcceptance") or DEFAULT_PLAN_ACCEPTANCE).get("acHeadings")
    criteria = module.plan_acceptance_criteria(plan_text, ac_headings)
    criteria_heading = module.plan_acceptance_criteria_heading(plan_text, ac_headings)
    # Batch 2026-08-11 B7 T4.1: the composed clause states the EFFECTIVE enabled condition set,
    # not a second hardcoded bar. A fixed sentence would keep demanding a PR from a project
    # that has disabled `pr_handed_off` for a no-PR workflow -- a generated goal contradicting
    # the enforcement the same adapter configures.
    conditions = goal_assignment_effective_conditions(data, target)
    try:
        text, meta = module.compose_goal_assignment(
            command=data["goalExecution"]["preferredClaudeCommand"],
            title=goal_plan_title(plan_path),
            plan_ref=plan_rel or str(plan_path),
            milestones=milestones,
            criteria=criteria,
            # Compose to the AUTHORING ceiling, not the delivered cap: a goal composed right up
            # to the host limit fails its own checker one line later, and the reserve exists to
            # absorb indentation a renderer adds between here and the paste.
            limit=module.goal_assignment_authoring_limit(limit),
            conditions=conditions,
        )
    except ValueError as exc:
        print(f"goal_assignment_error: {exc}", file=sys.stderr)
        return 1

    if args.out is not None:
        out_path = cli_path(target, str(args.out)).resolve(strict=False)
        try:
            out_path.parent.mkdir(parents=True, exist_ok=True)
            # No fence, no label, no trailing newline beyond the one that terminates the line.
            # What lands in the file is exactly what `char_count` certified.
            out_path.write_text(text + "\n", encoding="utf-8")
        except OSError as exc:
            print(f"goal_assignment_error: could not write {out_path}: {exc}", file=sys.stderr)
            return 1
        # NOT under --raw. `--raw` promises stdout is exactly the goal's bytes so `> goal.txt`
        # round-trips; two metadata lines ahead of it corrupt the artifact for any caller that
        # pipes. The file is still written -- only the chatter is suppressed.
        if not args.raw:
            print(f"goal_assignment_out: {out_path}")
            print(f"goal_assignment_copy_command: pbcopy < {shlex.quote(str(out_path))}")

    if args.raw:
        # Exactly the certified bytes on stdout, nothing else, so `> goal.txt` round-trips
        # through --check without the caller having to strip anything.
        print(text)
        return 0
    if finalized_errors:
        print("goal_assignment_finalized: no (--allow-unfinalized); do not assign this yet")
    else:
        print("goal_assignment_finalized: yes")
    print(f"goal_assignment_plan: {plan_rel}")
    print(f"goal_assignment_char_count: {meta['char_count']}")
    print(f"goal_assignment_char_limit: {limit}")
    print(f"goal_assignment_authoring_limit: {meta['limit']}")
    print(f"goal_assignment_headroom: {meta['headroom']}")
    print(f"goal_assignment_done_conditions: {', '.join(meta['conditions']) or 'none'}")
    print(
        "goal_assignment_milestones: "
        f"{meta['milestones_included']} of {meta['milestones_total']} included"
        + (f"; {meta['milestones_omitted']} omitted to fit" if meta["milestones_omitted"] else "")
        + (f"; {meta['milestones_shortened']} shortened" if meta["milestones_shortened"] else "")
    )
    # Reported for the same reason the milestone line is: a criterion the budget dropped is
    # named as a count here and in the goal itself, never silently absent.
    #
    # The SOURCE is named alongside the count because `0 of 0` alone is two different facts
    # wearing one string: a plan that names no criteria, and a plan whose section this parser
    # could not read. The second wants someone to look; the first does not.
    if criteria_heading:
        source = f"read from `{criteria_heading}`"
    else:
        source = "no acceptance-criteria section found in the plan; the generic bar applies"
    print(
        "goal_assignment_acceptance_criteria: "
        f"{meta['criteria_included']} of {meta['criteria_total']} included"
        + (f"; {meta['criteria_omitted']} summarised by count" if meta["criteria_omitted"] else "")
        + (f"; {meta['criteria_shortened']} shortened" if meta["criteria_shortened"] else "")
        + f" ({source})"
    )
    # A delimited block, NOT a `goal_assignment: <text>` label. char_count certifies the goal
    # text alone, so a labelled line invites pasting the prefix too and can push a certified
    # goal over the host limit (Codex T2 R2 P2). What sits between the markers is exactly the
    # certified bytes. --raw prints those bytes and nothing else, for piping.
    print("goal_assignment_begin")
    print(text)
    print("goal_assignment_end")
    return 0


def goal_kickoff_prompt(args: argparse.Namespace) -> int:
    target = shlex.quote(str(args.target))
    # Capture loader diagnostics so the standing directive is the FIRST output; replay verbatim
    # after, on the original channel (see _replay_loader_streams).
    buf_out, buf_err = io.StringIO(), io.StringIO()
    try:
        with redirect_stdout(buf_out), redirect_stderr(buf_err):
            data, _, resolved_target = lane_project(args)
    except SystemExit as exc:
        out_text, err_text = buf_out.getvalue(), buf_err.getvalue()
        if not str(exc).startswith(NO_ADAPTER_SENTINEL):
            # Real loader error: no directive; replay diagnostics, then the existing error branch.
            _replay_loader_streams(out_text, err_text)
            print(str(exc), file=sys.stderr)
            return 1
        # No adapter (any onboarding state): the adapterless directive is still the first output,
        # followed by the state-aware guided-onboarding offer instead of the generic goal template.
        print_autonomy_directive(None, None)
        sys.stdout.flush()
        _replay_loader_streams(out_text, err_text)
        info = onboarding_info_for_offer(Path(args.target).resolve(), Path.cwd())
        offer = "\n".join(onboarding_offer_lines(info))
        print(CLAUDE_ONBOARDING_KICKOFF_PROMPT_TEMPLATE.format(offer_lines=offer))
        return 0
    print_autonomy_directive(data, resolved_target)
    sys.stdout.flush()
    _replay_loader_streams(buf_out.getvalue(), buf_err.getvalue())
    goal_path = goal_run_path(data, resolved_target)
    if goal_path.exists():
        try:
            run = load_goal_run(data, resolved_target)
        except SystemExit as exc:
            print("goal_kickoff_mode: invalid-goal-ledger")
            print(f"goal_kickoff_blocker: {exc}")
            print(CLAUDE_GOAL_KICKOFF_PROMPT_TEMPLATE.format(target=target))
            return 0
        if run.get("status") != "complete":
            print("goal_kickoff_mode: active-goal")
            goal_condition(args)
            return 0
        print("goal_kickoff_mode: completed-goal-next")
        source_goal_path = goal_run_source_path(data, resolved_target, run)
        excluded = {source_goal_path} if source_goal_path else set()
        print_next_goal_candidate(data, resolved_target, exclude_paths=excluded)
        return 0
    print("goal_kickoff_mode: no-active-goal")
    print_next_goal_candidate(data, resolved_target)
    return 0


