def goal_tracker_gh_json(args: list[str], target: Path, timeout: int = 30) -> object:
    return github_provider_client_json(
        github_operation_name(args),
        args,
        target,
        timeout=timeout,
        cacheable=github_args_are_cacheable_read(args),
    )


def github_rest_json(endpoint: str, target: Path, extra_args: list[str] | None = None, timeout: int = 30) -> object:
    command = ["api", endpoint]
    command.extend(extra_args or [])
    return github_provider_client_json(github_operation_name(command), command, target, timeout=timeout, resource="core")


def github_rest_list_paginated(endpoint: str, target: Path, *, limit: int = 100, timeout: int = 30) -> list[dict]:
    if limit <= 0:
        return []
    per_page = 100
    separator = "&" if "?" in endpoint else "?"
    results: list[dict] = []
    page = 1
    max_pages = max(1, (limit + per_page - 1) // per_page + 5)
    while len(results) < limit and page <= max_pages:
        payload = github_rest_json(f"{endpoint}{separator}per_page={per_page}&page={page}", target, timeout=timeout)
        if not isinstance(payload, list):
            raise SystemExit(f"gh api {endpoint} returned unexpected JSON; expected an array")
        results.extend(item for item in payload if isinstance(item, dict))
        if len(payload) < per_page:
            break
        page += 1
    return results[:limit]


def github_issue_list_rest(repo: str, target: Path, *, state: str = "open", label: str = "", limit: int = 100) -> list[dict]:
    requested = max(0, int(limit or 100))
    if requested <= 0:
        return []
    endpoint = f"repos/{repo}/issues?state={quote(state)}"
    if label:
        endpoint += f"&labels={quote(label)}"
    payload = github_rest_list_paginated(endpoint, target, limit=requested + 100)
    issues = [item for item in payload if not item.get("pull_request")]
    return issues[:requested]


def github_issue_view_rest(repo: str, target: Path, issue_number: str) -> dict:
    issue = github_rest_json(f"repos/{repo}/issues/{issue_number}", target)
    comments = github_rest_list_paginated(f"repos/{repo}/issues/{issue_number}/comments", target, limit=500)
    if not isinstance(issue, dict):
        raise SystemExit("gh api issue view returned unexpected JSON")
    return {
        "number": issue.get("number"),
        "title": issue.get("title"),
        "url": issue.get("html_url") or issue.get("url"),
        "labels": issue.get("labels") if isinstance(issue.get("labels"), list) else [],
        "comments": [
            {
                "body": comment.get("body"),
                "url": comment.get("html_url") or comment.get("url"),
                "htmlUrl": comment.get("html_url") or comment.get("url"),
            }
            for comment in comments
            if isinstance(comment, dict)
        ],
    }


def github_issue_comment_rest(repo: str, target: Path, issue_number: str, body: str) -> str:
    with tempfile.NamedTemporaryFile("w", encoding="utf-8", delete=False) as tmp:
        json.dump({"body": body}, tmp)
        tmp_path = Path(tmp.name)
    try:
        payload = github_rest_json(
            f"repos/{repo}/issues/{issue_number}/comments",
            target,
            extra_args=["--method", "POST", "--input", str(tmp_path)],
            timeout=30,
        )
    finally:
        try:
            tmp_path.unlink()
        except OSError:
            pass
    if not isinstance(payload, dict):
        return ""
    return str(payload.get("html_url") or payload.get("url") or "")


def goal_tracker_auth_issues(target: Path) -> list[str]:
    if shutil.which("gh") is None:
        return ["gh CLI missing; install GitHub CLI before using goalTracker provider github-projects"]
    code, out, err = github_provider_client_run("auth.status", ["auth", "status"], target, timeout=20, resource="core")
    text = "\n".join(part for part in [out, err] if part)
    if code != 0:
        return [f"gh auth status failed: {text or 'not authenticated'}"]
    scope_lines = [
        line
        for line in text.splitlines()
        if "token scopes" in line.lower() or re.search(r"\bscopes:\s*", line, flags=re.IGNORECASE)
    ]
    if not scope_lines:
        return ["gh auth status did not confirm `project` scope; run `gh auth refresh -s project`"]
    scope_tokens = {
        token.lower()
        for line in scope_lines
        for token in re.findall(r"[A-Za-z][A-Za-z0-9:_-]*", line)
    }
    if "project" not in scope_tokens:
        return ["gh auth token missing `project` scope; run `gh auth refresh -s project`"]
    return []


def goal_tracker_gh_query_issues(tracker: dict, target: Path) -> list[str]:
    if not tracker.get("scopeQuery"):
        return []
    code, out, err = run_command(["gh", "project", "item-list", "--help"], cwd=target, timeout=20)
    help_text = "\n".join(part for part in [out, err] if part)
    if code != 0:
        return [f"gh project item-list --help failed while validating goalTracker.scopeQuery: {help_text or 'no help output'}"]
    if "--query" not in help_text:
        return ["gh project item-list does not support `--query`; upgrade GitHub CLI or clear goalTracker.scopeQuery"]
    return []


def goal_tracker_project_fields(data: dict, target: Path) -> list[dict]:
    tracker = goal_tracker_config(data)
    payload = goal_tracker_gh_json(
        [
            "project",
            "field-list",
            str(tracker["projectNumber"]),
            "--owner",
            tracker["owner"],
            "--format",
            "json",
            "--limit",
            "100",
        ],
        target,
    )
    if not isinstance(payload, dict) or not isinstance(payload.get("fields"), list):
        raise SystemExit("gh project field-list returned unexpected JSON; expected {fields:[...]}")
    return [field for field in payload["fields"] if isinstance(field, dict)]


def goal_tracker_project_view(data: dict, target: Path) -> dict:
    tracker = goal_tracker_config(data)
    payload = goal_tracker_gh_json(
        [
            "project",
            "view",
            str(tracker["projectNumber"]),
            "--owner",
            tracker["owner"],
            "--format",
            "json",
        ],
        target,
    )
    if not isinstance(payload, dict):
        raise SystemExit("gh project view returned unexpected JSON")
    return payload




goal_tracker_field_options = _goal_mod.goal_tracker_field_options


goal_tracker_option_by_name = _goal_mod.goal_tracker_option_by_name


def goal_tracker_status_issues(data: dict, target: Path) -> list[str]:
    tracker = goal_tracker_config(data)
    if not tracker["enabled"]:
        return []
    issues = goal_tracker_auth_issues(target)
    if issues:
        return issues
    issues.extend(goal_tracker_gh_query_issues(tracker, target))
    if issues:
        return issues
    try:
        fields = goal_tracker_project_fields(data, target)
    except SystemExit as exc:
        return [str(exc)]
    status_field = goal_tracker_field_by_name(fields, tracker["statusField"])
    if not status_field:
        issues.append(f"GitHub Project status field missing: {tracker['statusField']}")
    return issues


def board_schema_mismatch(fields: list, tracker: dict, type_field: str = "", epic_field: str = "", order_field: str = "") -> list[str]:
    """Pure: the adapter-declared statuses / optional fields the board does NOT have. This is a SCHEMA
    MISMATCH that routes to board-adopt (the adapter conforms to the board, never the reverse), NOT a
    hard error -- so a taxonomy drift can no longer fail the sanctioned status-write path closed and
    pressure a raw-gh bypass (operator decision + private lane RCA, 2026-06-25; a declared status
    the board lacks must not block writing a status it DOES have). Assumes the Status field is present
    -- auth and Status-field-absence are hard issues from goal_tracker_status_issues."""
    status_field = goal_tracker_field_by_name(fields, tracker.get("statusField", ""))
    if not status_field:
        return []
    mismatch: list[str] = []
    options = {str(option.get("name", "")).strip().lower() for option in goal_tracker_field_options(status_field)}
    if options:
        for status in goal_tracker_allowed_statuses(tracker):
            if status.lower() not in options:
                mismatch.append(f"GitHub Project status value missing from {tracker['statusField']}: {status}")
    for optional_key in ["priorityField", "milestoneField"]:
        field_name = tracker.get(optional_key)
        if field_name and not goal_tracker_field_by_name(fields, field_name):
            mismatch.append(f"GitHub Project {optional_key} missing: {field_name}")
    if type_field and not goal_tracker_field_by_name(fields, type_field):
        mismatch.append(f"GitHub Project typeField missing: {type_field}")
    if epic_field and not goal_tracker_field_by_name(fields, epic_field):
        mismatch.append(f"GitHub Project epicField missing: {epic_field}")
    if order_field and not goal_tracker_field_by_name(fields, order_field):
        mismatch.append(f"GitHub Project orderField missing: {order_field}")
    return mismatch


_BOARD_BUILTIN_FIELDS = {
    "title", "assignees", "labels", "linked pull requests", "milestone", "repository",
    "reviewers", "parent issue", "sub-issues progress", "created", "updated", "closed",
}


def board_profile(fields: list) -> dict:
    """Pure read-model of a board's schema for adoption: status columns (in order), all single-select
    fields, candidate priority/order signals, and custom (non-builtin) fields."""
    status_field = None
    columns: list[str] = []
    single_selects: dict[str, list[str]] = {}
    custom: list[str] = []
    priority_c: list[str] = []
    order_c: list[str] = []
    for field in fields or []:
        if not isinstance(field, dict):
            continue
        name = str(field.get("name") or "")
        low = name.strip().lower()
        opts = [str(o.get("name") or "") for o in (field.get("options") or []) if isinstance(o, dict)]
        if "singleselect" in str(field.get("type") or "").lower():
            single_selects[name] = opts
            if low == "status" and status_field is None:
                status_field, columns = name, opts
        if low not in _BOARD_BUILTIN_FIELDS:
            custom.append(name)
        if any(k in low for k in ("priority",)):
            priority_c.append(name)
        if any(k in low for k in ("order", "rank")):
            order_c.append(name)
    return {
        "statusField": status_field,
        "columns": columns,
        "singleSelects": single_selects,
        "priorityCandidates": priority_c,
        "orderCandidates": order_c,
        "customFields": custom,
        "schemaHash": board_schema_hash(fields or []),
    }














def goal_tracker_schema_mismatch_issues(data: dict, target: Path) -> list[str]:
    """Adapter-declared statuses/fields the board lacks, for surfacing as NON-blocking warnings that
    route to board-adopt. Empty when there is a hard issue (auth / Status field absent) -- those block
    on their own via goal_tracker_status_issues."""
    tracker = goal_tracker_config(data)
    if not tracker["enabled"]:
        return []
    if goal_tracker_status_issues(data, target):
        return []
    try:
        fields = goal_tracker_project_fields(data, target)
    except SystemExit:
        return []
    return board_schema_mismatch(
        fields,
        tracker,
        type_field=backlog_provider_config(data).get("typeField", ""),
        epic_field=board_epic_field(data),
        order_field=board_order_field(data),
    )


def goal_tracker_items(data: dict, target: Path, limit: int = 100) -> list[dict]:
    tracker = goal_tracker_config(data)
    return goal_tracker_items_for_scope(data, target, limit=limit, use_scope_query=True)


# Int, not an UPPER_CASE list of str, so the policy-phrases SSOT collector ignores it.
GOAL_TRACKER_BOARD_READ_CEILING = 5000


def goal_tracker_items_for_scope(data: dict, target: Path, limit: int = 100, use_scope_query: bool = True) -> list[dict]:
    """A board read is verifiably complete or it fails closed.

    RCA 2026-07-31: one page was fetched and the payload's `totalCount` discarded, so "not in the
    first page" and "not on the board" were indistinguishable -- `goal-start` refused an item that
    was present. A miss over a truncated read is not evidence of absence.
    """
    tracker = goal_tracker_config(data)

    def fetch(page_limit: int) -> tuple[list[dict], int | None]:
        command = [
            "project",
            "item-list",
            str(tracker["projectNumber"]),
            "--owner",
            tracker["owner"],
            "--format",
            "json",
            "--limit",
            str(page_limit),
        ]
        if use_scope_query and tracker["scopeQuery"]:
            command.extend(["--query", tracker["scopeQuery"]])
        payload = goal_tracker_gh_json(command, target)
        if not isinstance(payload, dict) or not isinstance(payload.get("items"), list):
            raise SystemExit(
                "gh project item-list returned unexpected JSON; expected {items:[...]}"
            )
        total = payload.get("totalCount")
        return (
            [item for item in payload["items"] if isinstance(item, dict)],
            total if isinstance(total, int) and total >= 0 else None,
        )

    # totalCount semantics under --query are NOT assumed. gh's --query support is already
    # version-dependent here (goal_tracker_gh_query_issues probes item-list --help for it), and if
    # gh reports the PROJECT-WIDE total while --query filters the returned items, a strict
    # `total > len(items)` comparison would fail closed forever on every scoped read that is
    # actually complete -- bricking goal-start and the blocking board-currency gate. So scoped
    # reads treat totalCount as an escalation hint only and decide completeness by the
    # non-full-page heuristic; only unscoped reads trust it as the filtered-connection count.
    # The live probe that would settle the semantics was unavailable at branch cut (recorded via
    # decision-record); this split is correct under either answer.
    scoped = bool(use_scope_query and tracker["scopeQuery"])

    def trusted(total: int | None) -> int | None:
        return total if (total is not None and not scoped) else None

    items, total = fetch(limit)
    if trusted(total) is not None and len(items) >= trusted(total):
        return items
    if trusted(total) is None and len(items) < limit:
        return items  # non-full page: complete for scoped reads and totalCount-less gh alike
    # A total we refuse to TRUST cannot bound the retry either. On a scoped read the only honest
    # bound is the real ceiling: escalating to `total` and then declaring truncation because the
    # answer filled it would accuse a complete board of being unreadable -- for instance a broad
    # scope where every project item matches. Unscoped reads may bound by the total they trust.
    # ONE rule, derived rather than enumerated: a total we cannot TRUST cannot bound the retry
    # either, so without one the only honest bound is the real ceiling. That covers both ways a
    # trusted total goes missing -- a scoped read (where totalCount may count the whole project)
    # and a gh/host combination that omits totalCount entirely. Bounding by `limit * 4` in either
    # case declares truncation the moment the answer fills a window we chose, which accuses a
    # complete board below the ceiling of being unreadable and blocks goal-start with it.
    trusted_total = trusted(total)
    retry_limit = (
        GOAL_TRACKER_BOARD_READ_CEILING
        if trusted_total is None
        else min(max(trusted_total, limit * 4), GOAL_TRACKER_BOARD_READ_CEILING)
    )
    if retry_limit > limit:
        items, total = fetch(retry_limit)
    verified_total = trusted(total)
    if (verified_total is not None and verified_total > len(items)) or (
        verified_total is None and len(items) >= retry_limit
    ):
        raise SystemExit(
            f"GitHub Project board read truncated at {len(items)} of "
            f"{verified_total if verified_total is not None else 'unknown'} items "
            f"(project {tracker['owner']}/{tracker['projectNumber']}); refusing to act on a "
            "partial board read -- a miss here is NOT 'not on the board'. Narrow "
            "backlogProvider.scopeQuery to fit the read ceiling."
        )
    return items


def board_work_order(data: dict) -> str:
    """Whether the next workable item is chosen by the board's physical top-to-bottom ordering
    ('board', the default) or by the priority field ('priority'). When provider/goalTracker is
    backed by GitHub Projects, the human's manual ordering of the board IS the precise order of
    work — the priority tag does not override it unless the product explicitly opts into
    'priority'."""
    provider = backlog_provider_config(data)
    tracker = goal_tracker_config(data)
    raw = str((provider.get("workOrder") if provider.get("enabled") else tracker.get("workOrder")) or "board").strip().lower()
    return raw if raw in {"board", "priority"} else "board"


goal_tracker_next_sort_key = _goal_mod.goal_tracker_next_sort_key


def board_epic_field(data: dict) -> str:
    provider = backlog_provider_config(data)
    tracker = goal_tracker_config(data)
    return str((provider.get("epicField") if provider.get("enabled") else tracker.get("epicField")) or "").strip()


def board_feature_series(data: dict) -> dict:
    """The configured feature-numbering series {field, pattern} (or {} when unset). Follows the
    same provider-if-enabled-else-tracker selection as board_epic_field. 'field' names the board
    field holding a feature number; 'pattern' (optional) constrains valid numbers."""
    provider = backlog_provider_config(data)
    tracker = goal_tracker_config(data)
    series = provider.get("featureSeries") if provider.get("enabled") else tracker.get("featureSeries")
    return series if isinstance(series, dict) else {}


def board_order_field(data: dict) -> str:
    provider = backlog_provider_config(data)
    tracker = goal_tracker_config(data)
    return str((provider.get("orderField") if provider.get("enabled") else tracker.get("orderField")) or "").strip()




def goal_tracker_board_position_map(data: dict, target: Path) -> dict[str, int]:
    """Authoritative board (drag) order. GitHub exposes the manual board position ONLY through the
    items connection `orderBy: {field: POSITION}` — there is no readable position field on a
    ProjectV2Item, and `gh project item-list` does not request POSITION ordering. So query it
    directly via GraphQL and return {item_id: board_index}. Empty dict when unavailable (callers
    fall back to the item-list order)."""
    project = goal_tracker_project_view(data, target)
    project_id = goal_tracker_value_text(project.get("id"))
    if not project_id:
        return {}
    # Item 71 T1.4 / wave-0 deferred finding 3. This used to be ONE `items(first:100)` page with no
    # cursor, so on any board with more than 100 items every item past the first hundred was
    # missing from the map -- and the selection site then ranked it by `len(position_map) +
    # position`, a synthetic number that put real board order and fallback order in the same sort
    # key. The board was not misread; it was read completely and then only a hundred items of it
    # were believed.
    query = (
        "query($id:ID!,$cursor:String){node(id:$id){... on ProjectV2{items(first:100,after:$cursor,"
        "orderBy:{field:POSITION,direction:ASC}){nodes{id} pageInfo{hasNextPage endCursor}}}}}"
    )
    positions: dict[str, int] = {}
    cursor = ""
    while True:
        args = ["api", "graphql", "-f", f"query={query}", "-f", f"id={project_id}"]
        if cursor:
            args += ["-f", f"cursor={cursor}"]
        try:
            payload = goal_tracker_gh_json(args, target)
        except SystemExit:
            # A PARTIAL map is worse than none. Callers document a fallback to item-list order and
            # act on it honestly; a half-filled map looks authoritative and silently ranks the
            # items it happens to contain above every item it does not.
            return {}
        container = payload.get("data", payload) if isinstance(payload, dict) else {}
        node = container.get("node") if isinstance(container, dict) else None
        items = ((node or {}).get("items") or {}) if isinstance(node, dict) else {}
        nodes = items.get("nodes")
        if not isinstance(nodes, list):
            return {}
        for entry in nodes:
            if isinstance(entry, dict) and goal_tracker_value_text(entry.get("id")):
                positions[goal_tracker_value_text(entry.get("id"))] = len(positions)
        page = items.get("pageInfo") if isinstance(items.get("pageInfo"), dict) else {}
        cursor = goal_tracker_value_text(page.get("endCursor"))
        if not page.get("hasNextPage") or not cursor:
            return positions
        if len(positions) >= GOAL_TRACKER_BOARD_READ_CEILING:
            # The same ceiling the verified read uses. Stopping here is a truncation, and a
            # truncated map is exactly the partial the fallback exists to avoid.
            return {}


def lane_assigned_epics(args: argparse.Namespace) -> list[str]:
    """Epics this lane is assigned to work, from --epic flags (repeatable) or the
    MINERVIT_LANE_EPICS env var (comma-separated). Empty means no epic is assigned, in which case
    selection falls back to the top of the board and says so."""
    raw: list[str] = []
    for value in getattr(args, "epic", None) or []:
        raw.extend(str(value).split(","))
    if not any(part.strip() for part in raw):
        raw.extend(util_module().resolve_env("MINERVIT_LANE_EPICS", "").split(","))
    seen: set[str] = set()
    ordered: list[str] = []
    for part in raw:
        name = part.strip()
        if name and name.lower() not in seen:
            seen.add(name.lower())
            ordered.append(name)
    return ordered


def print_board_selection_mode(data: dict, args: argparse.Namespace, prefix: str) -> list[str]:
    """Print how the next item is chosen (board vs priority order) and which epics this lane is
    assigned. With no epic assigned, the framework states that and defaults to the top of the
    board stack."""
    epics = lane_assigned_epics(args)
    work_order = board_work_order(data)
    order_field = board_order_field(data)
    if work_order == "board":
        source = f"orderField={order_field}" if order_field else "github-item-order (arrange the project's item order)"
        print(f"{prefix}_work_order: board ({source})")
    else:
        print(f"{prefix}_work_order: {work_order}")
    if epics:
        print(f"{prefix}_assigned_epics: {', '.join(epics)} (selecting the top board item within these epics)")
        print(
            f"{prefix}_epic_scope: board items outside the assigned epic(s) are out of scope - do not consider, "
            "recommend, rank, or pull them, even when ordering is set aside, without explicit operator direction "
            "that names the epic or lifts the scope"
        )
    else:
        print(f"{prefix}_assigned_epics: none - no epic assigned; defaulting to the top of the board stack")
    return epics


def goal_tracker_select_next_item(data: dict, target: Path, item_type: str = "", epics: list[str] | None = None) -> dict | None:
    tracker = goal_tracker_config(data)
    provider = backlog_provider_config(data)
    work_order = board_work_order(data)
    item_type = item_type.strip().lower()
    if item_type and item_type not in provider.get("itemTypes", []):
        raise SystemExit(f"backlogProvider.itemTypes does not allow item type: {item_type}")
    if item_type and not provider.get("typeField"):
        raise SystemExit("backlogProvider.typeField must be configured to filter GitHub Project items by type")
    epic_set = {epic.strip().lower() for epic in (epics or []) if epic.strip()}
    epic_field = board_epic_field(data)
    if epic_set and not epic_field:
        raise SystemExit("an epic is assigned to this lane but backlogProvider.epicField is not configured; set epicField or clear the lane epic assignment")
    order_field = board_order_field(data)
    # Board work order without an explicit orderField uses GitHub's authoritative POSITION order
    # (the operator's drag-order), not the undocumented item-list order.
    position_map = goal_tracker_board_position_map(data, target) if (work_order == "board" and not order_field) else {}
    ready = {status.lower() for status in tracker["readyStatuses"]}
    status_order = {status.lower(): index for index, status in enumerate(tracker["readyStatuses"])}
    items = []
    for position, item in enumerate(goal_tracker_items(data, target)):
        status = goal_tracker_item_field(item, tracker["statusField"])
        if status.lower() not in ready:
            continue
        if epic_set:
            item_epic = goal_tracker_item_field(item, epic_field).strip().lower()
            if item_epic not in epic_set:
                continue
        if item_type:
            actual_type = goal_tracker_item_field(item, provider["typeField"]).strip().lower()
            if actual_type != item_type:
                continue
        priority = goal_tracker_item_field(item, tracker["priorityField"]) if tracker["priorityField"] else ""
        if order_field:
            order_value = board_order_value(goal_tracker_item_field(item, order_field))
        elif position_map:
            order_value = float(position_map.get(goal_tracker_item_id(item), len(position_map) + position))
        else:
            order_value = float(position)
        items.append(
            (
                status_order.get(status.lower(), 999),
                goal_tracker_priority_rank(priority),
                order_value,
                position,
                item,
            )
        )
    if not items:
        return None
    return sorted(items, key=lambda row: goal_tracker_next_sort_key(work_order, row[0], row[1], row[2], row[3]))[0][4]


def print_goal_tracker_item(data: dict, item: dict, prefix: str = "goal_tracker_next") -> None:
    tracker = goal_tracker_config(data)
    provider = backlog_provider_config(data)
    status = goal_tracker_item_field(item, tracker["statusField"])
    priority = goal_tracker_item_field(item, tracker["priorityField"]) if tracker["priorityField"] else ""
    milestone = goal_tracker_item_field(item, tracker["milestoneField"]) if tracker["milestoneField"] else ""
    item_type = goal_tracker_item_field(item, provider["typeField"]) if provider.get("typeField") else ""
    print(f"{prefix}_item_id: {goal_tracker_item_id(item)}")
    print(f"{prefix}_title: {goal_tracker_item_title(item)}")
    print(f"{prefix}_url: {goal_tracker_item_url(item) or 'none'}")
    print(f"{prefix}_type: {item_type or 'none'}")
    print(f"{prefix}_status: {status or 'none'}")
    print(f"{prefix}_priority: {priority or 'none'}")
    print(f"{prefix}_milestone: {milestone or 'none'}")


def resolve_goal_tracker_item(data: dict, target: Path, item_ref: str) -> dict:
    """A miss reports WHAT WAS SEARCHED, because the read it searched is now verifiably complete.

    The old message said "not found in configured query/list", which is what an agent reads as
    "not on the board" -- the exact misreading the 2026-07-31 RCA turned into a refusal of a
    present item. A truncated read can no longer reach this message at all: goal_tracker_items_
    for_scope raises first.
    """
    scanned = goal_tracker_items(data, target)
    for item in scanned:
        if goal_tracker_item_matches(item, item_ref):
            return item
    if goal_tracker_config(data).get("scopeQuery"):
        unscoped = goal_tracker_items_for_scope(data, target, use_scope_query=False)
        for item in unscoped:
            if goal_tracker_item_matches(item, item_ref):
                return item
        scanned = unscoped
    tracker = goal_tracker_config(data)
    raise SystemExit(
        f"GitHub Project item not found among the {len(scanned)} items of a complete board read "
        f"(project {tracker['owner']}/{tracker['projectNumber']}): {item_ref}"
    )


def goal_tracker_plan_path(data: dict, target: Path, item: dict) -> Path:
    title = goal_tracker_item_title(item)
    item_id = slugify(goal_tracker_item_id(item), "item")
    default_slug = "github-project-item" if provider_item_completion_enabled(data) else "github-project-goal"
    slug = slugify(title, default_slug)
    suffix = f"-{item_id}" if item_id and item_id != "item" and item_id not in slug else ""
    return goal_source_root(data, target) / f"{slug}{suffix}.md"


def goal_tracker_source_body(data: dict, item: dict) -> str:
    tracker = goal_tracker_config(data)
    status = goal_tracker_item_field(item, tracker["statusField"])
    priority = goal_tracker_item_field(item, tracker["priorityField"]) if tracker["priorityField"] else ""
    milestone = goal_tracker_item_field(item, tracker["milestoneField"]) if tracker["milestoneField"] else ""
    lines = [
        "- provider: github-projects",
        f"- owner: {tracker['owner']}",
        f"- project_number: {tracker['projectNumber']}",
        f"- project_item_id: {goal_tracker_item_id(item)}",
        f"- project_item_url: {goal_tracker_item_url(item) or 'none'}",
        f"- status: {status or 'none'}",
        f"- priority: {priority or 'none'}",
        f"- milestone: {milestone or 'none'}",
        f"- authoritative_for: {', '.join(tracker['authoritativeFor'])}",
        f"- link_policy: {tracker['linkPolicy']}",
        f"- synced_at: {now_iso()}",
    ]
    return "\n".join(lines)


goal_tracker_project_guidance_body = _goal_mod.goal_tracker_project_guidance_body


def goal_tracker_new_plan_text(data: dict, item: dict) -> str:
    title = goal_tracker_item_title(item)
    tracker = goal_tracker_config(data)
    milestone = goal_tracker_item_field(item, tracker["milestoneField"]) if tracker["milestoneField"] else ""
    first_milestone = milestone or title
    if provider_item_completion_enabled(data):
        return (
            f"# {title}\n\n"
            "## GitHub Project Source\n\n"
            f"{goal_tracker_source_body(data, item)}\n\n"
            "## What This Delivers\n\n"
            f"Deliver the outcome described by the linked GitHub issue/Project item: {title}.\n\n"
            "## Why It Matters\n\n"
            "Preserve or translate the stakeholder-facing value from the GitHub issue before execution.\n\n"
            "## Acceptance Criteria\n\n"
            "Copy or refine the issue acceptance criteria during reviewed planning before tactical implementation starts.\n\n"
            "## Non-Goals\n\n"
            "- Add non-goals during reviewed planning.\n\n"
            "## Milestones\n\n"
            f"- [ ] {first_milestone}\n\n"
            "## Dependencies And Safe Parallelism\n\n"
            "- GitHub Projects controls priority, status, and completion state for this work item.\n"
            "- Repo source-of-truth plans control implementation detail and review evidence.\n\n"
            "## Risks And True Blockers\n\n"
            "- Unknowns from the GitHub issue/Project item must be resolved or marked as true blockers before execution.\n\n"
            "## Review Gates\n\n"
            "- Cross-model plan review is required before execution unless the adapter declares a valid exemption.\n"
            "- Tactical PR plans still require the normal plan-review and implementation-review gates.\n\n"
            "## Verification\n\n"
            "- The GitHub issue/Project item remains current through planning, PR, milestone, blocked, and closeout boundaries.\n"
            "- Required validation evidence and UI evidence are posted to the linked GitHub issue when configured.\n"
            "- Required product/project validation evidence proves the acceptance criteria.\n\n"
            "## Completion Criteria\n\n"
            "- The linked GitHub issue/work item acceptance criteria are complete.\n"
            "- No Critical/P1 blockers remain.\n"
            "- The GitHub Project item, issue comments/body, and repo continuity/session evidence agree on final state.\n\n"
            "## Project Guidance\n\n"
            f"{goal_tracker_project_guidance_body(item)}\n"
        )
    return (
        f"# {title}\n\n"
        "## GitHub Project Source\n\n"
        f"{goal_tracker_source_body(data, item)}\n\n"
        "## Desired Outcome\n\n"
        f"Deliver the outcome described by the linked GitHub Project item: {title}.\n\n"
        "## User / Business Benefit\n\n"
        "Translate the GitHub Project item guidance into a concrete user, operator, business, or delivery benefit before execution.\n\n"
        "## Success Condition\n\n"
        "Define the measurable success condition during reviewed goal planning before tactical implementation starts.\n\n"
        "## Non-Goals\n\n"
        "- Add non-goals during reviewed goal planning.\n\n"
        "## Milestones\n\n"
        f"- [ ] {first_milestone}\n\n"
        "## Dependencies And Safe Parallelism\n\n"
        "- GitHub Projects controls big-picture priority and status for this goal.\n"
        "- Repo source-of-truth goal and tactical PR plans control implementation details.\n\n"
        "## Risks And True Blockers\n\n"
        "- Unknowns from the GitHub Project item must be resolved or marked as true blockers before execution.\n\n"
        "## Review Gates\n\n"
        "- Cross-model goal-plan review is required before execution unless the adapter declares a valid exemption.\n"
        "- Tactical PR plans still require the normal plan-review and implementation-review gates.\n\n"
        "## Validation Proof Required For Completion\n\n"
        "- Goal ledger reports complete or ready for completion.\n"
        "- Required product/project validation evidence is attached to the milestone or goal summary.\n"
        "- GitHub Project status is updated through `tautline goal-tracker-update` when appropriate.\n\n"
        "## Completion Criteria\n\n"
        "- All reviewed milestones are complete or policy-deferred.\n"
        "- No Critical/P1 blockers remain.\n"
        "- The GitHub Project item and repo continuity/session evidence agree on final state.\n\n"
        "## Project Guidance\n\n"
        f"{goal_tracker_project_guidance_body(item)}\n"
    )


def goal_tracker_sync_text(data: dict, target: Path, item: dict, path: Path) -> str:
    if not path.exists():
        return goal_tracker_new_plan_text(data, item)
    text = path.read_text(encoding="utf-8", errors="replace")
    if not text.lstrip().startswith("#"):
        text = f"# {goal_tracker_item_title(item)}\n\n{text.strip()}\n"
    text = replace_markdown_section(text, "## GitHub Project Source", goal_tracker_source_body(data, item))
    text = replace_markdown_section(text, "## Project Guidance", goal_tracker_project_guidance_body(item))
    return text


def goal_tracker_status(args: argparse.Namespace) -> int:
    data, _, target = lane_project(args)
    tracker = goal_tracker_config(data)
    print(goal_tracker_status_summary(data))
    if not tracker["enabled"]:
        print("goal_tracker_status: disabled")
        return 0
    issues = goal_tracker_status_issues(data, target)
    if issues:
        for issue in issues:
            print(f"goal_tracker_issue: {issue}")
        print("goal_tracker_status: blocked")
        return 1
    fields = goal_tracker_project_fields(data, target)
    print("goal_tracker_status: ok")
    print(f"goal_tracker_fields: {', '.join(str(field.get('name')) for field in fields if field.get('name'))}")
    print("goal_tracker_next_action: run `tautline goal-tracker-next --target .` when no active goal ledger exists")
    return 0


def goal_tracker_next(args: argparse.Namespace) -> int:
    data, _, target = lane_project(args)
    tracker = goal_tracker_config(data)
    if not tracker["enabled"]:
        print("goal_tracker_next: disabled")
        return 0
    issues = goal_tracker_status_issues(data, target)
    if issues:
        for issue in issues:
            print(f"goal_tracker_issue: {issue}", file=sys.stderr)
        return 1
    epics = print_board_selection_mode(data, args, "goal_tracker_next")
    item = goal_tracker_select_next_item(data, target, epics=epics)
    if item is None:
        print("goal_tracker_next: none")
        scope = f" within assigned epics: {', '.join(epics)}" if epics else ""
        print(f"goal_tracker_next_action: no ready GitHub Project goal item matched the adapter query/status mapping{scope}")
        return 1
    print("goal_tracker_next: found")
    print_goal_tracker_item(data, item)
    print(
        "goal_tracker_next_action: run `tautline goal-tracker-sync --target . "
        f"--item {shlex.quote(goal_tracker_item_id(item) or goal_tracker_item_url(item) or goal_tracker_item_title(item))} --write`, "
        "to claim the board item active, then review the repo goal plan before goal-start"
    )
    return 0


def goal_tracker_sync_claim_active(
    data: dict,
    target: Path,
    item_ref: str,
    item: dict,
    prefix: str,
    write: bool,
) -> None:
    tracker = goal_tracker_config(data)
    active_status = goal_tracker_primary_status(tracker, "activeStatuses")
    print(f"{prefix}_active_status: {active_status}")
    if not write:
        print(f"{prefix}_active_claim: dry_run")
        return
    outcome = goal_tracker_claim_single_item_active(data, target, item_ref, item, prefix, active_status)
    if outcome not in {"ok", "already_active"}:
        return
    goal_tracker_claim_board_backed_subtasks_active(data, target, item, item_ref, prefix, active_status)
    goal_tracker_claim_parent_items_active_for_subtask(data, target, item, item_ref, active_status, context=prefix, prefix=prefix)


def goal_tracker_claim_single_item_active(
    data: dict,
    target: Path,
    item_ref: str,
    item: dict,
    prefix: str,
    active_status: str,
) -> str:
    tracker = goal_tracker_config(data)
    current_status = goal_tracker_item_field(item, tracker["statusField"])
    print(f"{prefix}_active_current_status: {current_status or 'none'}")
    if goal_tracker_status_matches(current_status, list(tracker.get("activeStatuses") or [])):
        print(f"{prefix}_active_claim: already_active")
        print(f"{prefix}_active_item_ref: {item_ref}")
        item_id = goal_tracker_item_id(item)
        if item_id:
            print(f"{prefix}_active_item_id: {item_id}")
        return "already_active"
    terminal_or_blocked = list(tracker.get("doneStatuses") or []) + list(tracker.get("blockedStatuses") or [])
    if goal_tracker_status_matches(current_status, terminal_or_blocked):
        print(f"{prefix}_active_claim: skipped_terminal_status")
        print(f"{prefix}_active_item_ref: {item_ref}")
        return "skipped_terminal_status"
    try:
        content_state = board_item_fetch_state(item, target)
    except SystemExit as exc:
        raise SystemExit(f"cannot verify GitHub Project item state before active claim: {exc}") from exc
    if content_state and content_state != "OPEN":
        print(f"{prefix}_active_claim: skipped_non_open_state")
        print(f"{prefix}_active_item_ref: {item_ref}")
        print(f"{prefix}_active_item_state: {content_state}")
        return "skipped_non_open_state"
    result = goal_tracker_update_status(data, target, item_ref, active_status)
    print(f"{prefix}_active_claim: ok")
    print(f"{prefix}_active_item_ref: {item_ref}")
    print(f"{prefix}_active_item_id: {result['item_id']}")
    if result.get("output"):
        print(f"{prefix}_active_output: {result['output']}")
    return "ok"


def goal_tracker_claim_board_backed_subtasks_active(
    data: dict,
    target: Path,
    parent_item: dict,
    parent_ref: str,
    prefix: str,
    active_status: str,
) -> None:
    subtasks = goal_tracker_board_backed_subtasks(data, target, parent_item, parent_ref, prefix, "active")
    for subtask in subtasks:
        subtask_ref = goal_tracker_subtask_ref(subtask)
        if not subtask_ref:
            print(f"{prefix}_subtask_active_warn: board-backed subtask has no stable item reference")
            continue
        print(f"{prefix}_subtask_active_parent_ref: {parent_ref}")
        goal_tracker_claim_single_item_active(data, target, subtask_ref, subtask, f"{prefix}_subtask", active_status)


goal_tracker_subtask_ref = _goal_mod.goal_tracker_subtask_ref


def goal_tracker_board_backed_subtasks(
    data: dict,
    target: Path,
    parent_item: dict,
    parent_ref: str,
    prefix: str,
    action: str,
    *,
    require: bool = False,
) -> list[dict]:
    content = parent_item.get("content") if isinstance(parent_item.get("content"), dict) else {}
    if not goal_tracker_value_text(content.get("id")):
        return []
    try:
        items = goal_tracker_items(data, target, limit=400)
    except SystemExit as exc:
        message = f"board item list unavailable; subtask {action} status not updated: {exc}"
        if require:
            raise SystemExit(f"board-backed subtask {action} status could not be verified for {parent_ref}: {message}") from exc
        print(f"{prefix}_subtask_{action}_warn: {message}")
        return []
    subtasks, unavailable, unmatched = board_backed_subtask_items(parent_item, items, target)
    if unavailable:
        message = f"native sub-issue enumeration unavailable for {parent_ref}; board-backed subtask {action} status not updated"
        if require:
            raise SystemExit(f"board-backed subtask {action} status could not be verified for {parent_ref}: {message}")
        print(f"{prefix}_subtask_{action}_warn: {message}")
        return []
    if unmatched:
        shown = ", ".join(unmatched[:5])
        suffix = " ..." if len(unmatched) > 5 else ""
        message = (
            f"native sub-issue(s) are not board items for {parent_ref}: {shown}{suffix}; "
            f"subtask {action} status cannot be updated"
        )
        if require:
            raise SystemExit(f"board-backed subtask {action} status could not be verified for {parent_ref}: {message}")
        print(f"{prefix}_subtask_{action}_warn: {message}")
    return subtasks


def goal_tracker_preflight_done_subtask_ac_evidence(
    data: dict,
    target: Path,
    subtasks: list[dict],
    status: str,
    evidence: str,
    context: str,
) -> None:
    """Oracle discipline for the subtasks a parent closure will AUTO-CLOSE (item 81).

    ONE definition, two callers -- the done-move pre-flight and `goal_advance`'s hoist -- because
    the whole point is that this refusal lands before ANY mutation, and `goal-advance` posts a
    required UI-proof comment before it reaches the transition. Codex R2 found that gap: the parent
    was hoisted, the subtasks were not, so a strict refusal on a subtask's criteria could land after
    the UI proof was already public.

    Only the subtasks this command will actually auto-close are judged. Codex R1: judging one that
    is already terminal -- which the status-update loop skips rather than moving or commenting --
    could block the parent forever on criteria settled when that subtask was closed, and it punished
    the exact remedy this gate's own refusal recommends. The skip conditions mirror the mutation
    loop's, so the two cannot disagree about which subtasks this command touches.
    """
    tracker = goal_tracker_config(data)
    done_statuses = goal_tracker_done_statuses(data)
    for subtask in subtasks:
        current_status = goal_tracker_item_field(subtask, tracker["statusField"])
        if goal_tracker_status_matches(current_status, done_statuses):
            continue
        if goal_tracker_status_matches(current_status, [status]):
            continue
        goal_tracker_preflight_done_ac_evidence(
            data, target, subtask, goal_tracker_subtask_ref(subtask), evidence, f"{context} subtask"
        )


def goal_tracker_preflight_done_subtasks(
    data: dict,
    target: Path,
    parent_item: dict,
    parent_ref: str,
    status: str,
    context: str,
    prefix: str,
    evidence: str = "",
    ac_checked: bool = False,
) -> list[dict]:
    subtasks = goal_tracker_board_backed_subtasks(
        data, target, parent_item, parent_ref, prefix, "done", require=True
    )
    tracker = goal_tracker_config(data)
    for subtask in subtasks:
        subtask_ref = goal_tracker_subtask_ref(subtask)
        if not subtask_ref:
            raise SystemExit(f"{context} cannot move {parent_ref} to {status}: board-backed subtask has no stable item reference")
        current_status = goal_tracker_item_field(subtask, tracker["statusField"])
        print(f"{prefix}_subtask_done_current_status: {current_status or 'none'}")
        try:
            content_state = board_item_fetch_state(subtask, target)
        except SystemExit as exc:
            raise SystemExit(
                f"{context} cannot move {parent_ref} to {status}: board-backed subtask {subtask_ref} state could not be verified: {exc}"
            ) from exc
        if content_state not in {"CLOSED", "MERGED"}:
            raise SystemExit(
                f"{context} cannot move {parent_ref} to {status}: board-backed subtask {subtask_ref} "
                f"is {content_state or 'unknown'}, not closed/merged; finish or close the subtask before closing the parent"
            )
    # Item 81 / Codex R4. An auto-closed subtask IS closed by this command and nowhere else, so
    # packet fork F9's premise -- "each subtask's ACs are checked when IT moves to done through the
    # same funnel" -- does not hold for it, and without this the headline gate had a bypass: a
    # parent's AC table posted as a subtask's verification while the subtask's own criteria went
    # unmeasured by anything, ever. F9's CORRECT half survives: the parent's own move is never
    # refused on a subtask's criteria, because the parent's pre-flight runs against the parent item.
    #
    # The check lives HERE, in the pre-flight, and not in the status-update loop where it was first
    # written. That loop is preflight -> post comment -> item-edit PER SUBTASK, so a refusal on
    # subtask k left subtasks 1..k-1 already commented and moved to Done -- a PARTIAL mutation by a
    # gate whose whole claim is that a refused done move mutates nothing. Every subtask is judged
    # here, before the first write.
    if not ac_checked:
        goal_tracker_preflight_done_subtask_ac_evidence(
            data, target, subtasks, status, evidence, context
        )
    return subtasks


def goal_tracker_update_board_backed_subtasks_status(
    data: dict,
    target: Path,
    parent_item: dict,
    parent_ref: str,
    status: str,
    *,
    evidence: str = "",
    context: str = "goal-tracker-update",
    prefix: str = "goal_tracker_update",
    subtasks: list[dict] | None = None,
) -> None:
    tracker = goal_tracker_config(data)
    if subtasks is None:
        subtasks = goal_tracker_board_backed_subtasks(data, target, parent_item, parent_ref, prefix, "status")
    done = goal_tracker_status_matches(status, goal_tracker_done_statuses(data))
    done_statuses = list(tracker.get("doneStatuses") or [])
    blocked_statuses = list(tracker.get("blockedStatuses") or [])
    target_is_active = goal_tracker_status_matches(status, list(tracker.get("activeStatuses") or []))
    target_is_blocked = goal_tracker_status_matches(status, blocked_statuses)
    for subtask in subtasks:
        subtask_ref = goal_tracker_subtask_ref(subtask)
        if not subtask_ref:
            message = "board-backed subtask has no stable item reference"
            if done:
                raise SystemExit(f"{context} could not update done status for {parent_ref}: {message}")
            print(f"{prefix}_subtask_status_warn: {message}")
            continue
        current_status = goal_tracker_item_field(subtask, tracker["statusField"])
        print(f"{prefix}_subtask_status_parent_ref: {parent_ref}")
        print(f"{prefix}_subtask_status_current_status: {current_status or 'none'}")
        if goal_tracker_status_matches(current_status, [status]):
            print(f"{prefix}_subtask_status_update: already_{status}")
            print(f"{prefix}_subtask_status_item_ref: {subtask_ref}")
            continue
        if goal_tracker_status_matches(current_status, done_statuses):
            print(f"{prefix}_subtask_status_update: skipped_terminal_status")
            print(f"{prefix}_subtask_status_item_ref: {subtask_ref}")
            continue
        if target_is_active and goal_tracker_status_matches(current_status, blocked_statuses):
            print(f"{prefix}_subtask_status_update: skipped_terminal_status")
            print(f"{prefix}_subtask_status_item_ref: {subtask_ref}")
            continue
        try:
            content_state = board_item_fetch_state(subtask, target)
        except SystemExit as exc:
            raise SystemExit(f"{context} could not verify board-backed subtask {subtask_ref} state before status update: {exc}") from exc
        if done:
            if content_state not in {"CLOSED", "MERGED"}:
                raise SystemExit(
                    f"{context} cannot move {parent_ref} to {status}: board-backed subtask {subtask_ref} "
                    f"is {content_state or 'unknown'}, not closed/merged; finish or close the subtask before closing the parent"
                )
            comment_url = goal_tracker_post_done_evidence(data, target, subtask, evidence, f"{context} subtask")
            if comment_url:
                print(f"{prefix}_subtask_status_verification_comment: {comment_url}")
        elif content_state and content_state != "OPEN":
            print(f"{prefix}_subtask_status_update: skipped_non_open_state")
            print(f"{prefix}_subtask_status_item_ref: {subtask_ref}")
            print(f"{prefix}_subtask_status_item_state: {content_state}")
            continue
        elif target_is_blocked and not blocked_statuses:
            print(f"{prefix}_subtask_status_update: skipped_no_blocked_status")
            print(f"{prefix}_subtask_status_item_ref: {subtask_ref}")
            continue
        result = goal_tracker_update_status(data, target, subtask_ref, status)
        print(f"{prefix}_subtask_status_update: ok")
        print(f"{prefix}_subtask_status_item_ref: {subtask_ref}")
        print(f"{prefix}_subtask_status_item_id: {result['item_id']}")
        if result.get("output"):
            print(f"{prefix}_subtask_status_output: {result['output']}")


def goal_tracker_claim_parent_items_active_for_subtask(
    data: dict,
    target: Path,
    subtask_item: dict,
    subtask_ref: str,
    active_status: str,
    *,
    context: str = "goal-tracker-update",
    prefix: str = "goal_tracker_update",
) -> None:
    tracker = goal_tracker_config(data)
    subtask_keys = board_item_ref_values(subtask_item)
    if not subtask_keys:
        print(f"{prefix}_parent_active_warn: subtask has no strong issue reference")
        return
    try:
        items = goal_tracker_items(data, target, limit=400)
    except SystemExit as exc:
        print(f"{prefix}_parent_active_warn: board item list unavailable; parent status not updated: {exc}")
        return
    for parent in items:
        parent_ref = goal_tracker_subtask_ref(parent)
        if not parent_ref or parent_ref == subtask_ref:
            continue
        content = parent.get("content") if isinstance(parent.get("content"), dict) else {}
        if not goal_tracker_value_text(content.get("id")):
            continue
        sub_issues = grooming_sub_issues(parent, target)
        if sub_issues == GROOMING_SUBISSUES_UNAVAILABLE:
            continue
        parent_matches_child = False
        for sub_issue in sub_issues:
            if not isinstance(sub_issue, dict):
                continue
            sub_issue_keys = {
                value.strip()
                for value in [
                    goal_tracker_value_text(sub_issue.get("id")),
                    goal_tracker_value_text(sub_issue.get("url")),
                ]
                if value and value.strip()
            }
            if subtask_keys.intersection(sub_issue_keys):
                parent_matches_child = True
                break
        if not parent_matches_child:
            continue
        print(f"{prefix}_parent_active_subtask_ref: {subtask_ref}")
        print(f"{prefix}_parent_active_parent_ref: {parent_ref}")
        outcome = goal_tracker_claim_single_item_active(data, target, parent_ref, parent, f"{prefix}_parent", active_status)
        if outcome in {"ok", "already_active"}:
            continue
        if outcome in {"skipped_terminal_status", "skipped_non_open_state"}:
            print(f"{prefix}_parent_active_skip: {outcome}")
            continue
        current_status = goal_tracker_item_field(parent, tracker["statusField"])
        print(
            f"{prefix}_parent_active_warn: {context} left parent {parent_ref} at "
            f"{current_status or 'none'} because active claim returned {outcome}"
        )


def goal_tracker_claim_plan_active(data: dict, target: Path, plan_path: Path, prefix: str) -> None:
    tracker = goal_tracker_config(data)
    provider = backlog_provider_config(data)
    if not (tracker.get("enabled") or provider.get("enabled")):
        return
    item_ref = goal_tracker_ref_from_plan(plan_path)
    if not item_ref:
        print(f"{prefix}_active_claim: no_project_source")
        return
    issues = goal_tracker_status_issues(data, target)
    if issues:
        raise SystemExit("; ".join(issues))
    item = resolve_goal_tracker_item(data, target, item_ref)
    goal_tracker_sync_claim_active(data, target, item_ref, item, prefix, True)


def goal_tracker_sync(args: argparse.Namespace) -> int:
    data, _, target = lane_project(args)
    tracker = goal_tracker_config(data)
    if not tracker["enabled"]:
        raise SystemExit("goalTracker is disabled in this project adapter")
    issues = goal_tracker_status_issues(data, target)
    if issues:
        raise SystemExit("; ".join(issues))
    item = resolve_goal_tracker_item(data, target, args.item)
    item_ref = goal_tracker_item_id(item) or goal_tracker_item_url(item) or goal_tracker_item_title(item)
    path = goal_tracker_plan_path(data, target, item)
    text = goal_tracker_sync_text(data, target, item, path)
    print("goal_tracker_sync: ready")
    print_goal_tracker_item(data, item, "goal_tracker_sync")
    print(f"goal_tracker_sync_plan: {path_display(target, path)}")
    if args.write:
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(text, encoding="utf-8")
        print(f"goal_tracker_sync_written: {path}")
    else:
        print("goal_tracker_sync_write: false")
    goal_tracker_sync_claim_active(data, target, item_ref, item, "goal_tracker_sync", bool(args.write))
    print("goal_tracker_sync_next_action: run cross-model review for the repo goal plan before goal-start; do not execute directly from the GitHub Project item")
    return 0


def goal_tracker_update(args: argparse.Namespace) -> int:
    data, _, target = lane_project(args)
    evidence = backlog_provider_done_evidence_text(args, target)
    result, comment_url = goal_tracker_update_status_with_done_evidence(
        data,
        target,
        args.item,
        args.status,
        evidence=evidence,
        context="goal-tracker-update",
    )
    if comment_url:
        print(f"goal_tracker_update_verification_comment: {comment_url}")
    print("goal_tracker_update: ok")
    print(f"goal_tracker_update_item_id: {result['item_id']}")
    print(f"goal_tracker_update_status: {result['status']}")
    if result.get("output"):
        print(f"goal_tracker_update_output: {result['output']}")
    return 0


def goal_tracker_update_status(data: dict, target: Path, item_ref: str, status: str) -> dict:
    tracker = goal_tracker_config(data)
    if not tracker["enabled"]:
        raise SystemExit("goalTracker is disabled in this project adapter")
    status = status.strip()
    allowed = {value.lower() for value in goal_tracker_allowed_statuses(tracker)}
    if status.lower() not in allowed:
        raise SystemExit(f"status is not adapter-approved for goalTracker: {status}")
    issues = goal_tracker_status_issues(data, target)
    if issues:
        raise SystemExit("; ".join(issues))
    item = resolve_goal_tracker_item(data, target, item_ref)
    fields = goal_tracker_project_fields(data, target)
    status_field = goal_tracker_field_by_name(fields, tracker["statusField"])
    if not status_field or not status_field.get("id"):
        raise SystemExit(f"GitHub Project status field has no id: {tracker['statusField']}")
    option = goal_tracker_option_by_name(status_field, status)
    if not option or not option.get("id"):
        raise SystemExit(f"GitHub Project status option has no id: {status}")
    project = goal_tracker_project_view(data, target)
    project_id = goal_tracker_value_text(project.get("id"))
    if not project_id:
        raise SystemExit("gh project view did not return a project id")
    item_id = goal_tracker_item_id(item)
    if not item_id:
        raise SystemExit("GitHub Project item has no id")
    code, out, err = run_command(
        [
            "gh",
            "project",
            "item-edit",
            "--id",
            item_id,
            "--project-id",
            project_id,
            "--field-id",
            str(status_field["id"]),
            "--single-select-option-id",
            str(option["id"]),
        ],
        cwd=target,
        timeout=30,
    )
    if code != 0:
        raise SystemExit(err or out or "gh project item-edit failed")
    github_cache_invalidate_project()
    return {"item_id": item_id, "status": status, "output": out}


def goal_tracker_done_statuses(data: dict) -> list[str]:
    provider = backlog_provider_config(data)
    tracker = goal_tracker_config(data)
    return list(provider.get("doneStatuses") or tracker.get("doneStatuses") or [])


def goal_tracker_item_issue_number(item: dict) -> str:
    for url in [goal_tracker_item_content_url(item), goal_tracker_item_url(item)]:
        issue_number = github_issue_number_from_url(url)
        if issue_number:
            return issue_number
    # Fall back to the ONE definition of where an item's issue/PR link lives, which also knows the
    # top-level `contentUrl` shape (Codex R4 P2). Purely additive: every payload that resolved
    # before still resolves the same way here, and the only items whose behavior changes are ones
    # that used to resolve to "" and refuse despite carrying a real link.
    for url in board_item_issue_pr_urls(item):
        issue_number = github_issue_number_from_url(url)
        if issue_number:
            return issue_number
    return ""


def done_evidence_ac_table_mode(data: dict) -> str:
    """`off` | `warn` | `strict` for the oracle-discipline closure gate (item 81)."""
    provider = data.get("backlogProvider") if isinstance(data, dict) else None
    raw = provider.get("doneEvidence") if isinstance(provider, dict) else None
    mode = str((raw or {}).get("acTable", "warn")).strip().lower()
    return mode if mode in DONE_EVIDENCE_AC_TABLE_MODES else "warn"


def done_evidence_ac_headings(data: dict) -> list[str]:
    """The AC headings to look for on a linked issue -- ONE definition, three call sites.

    Reuses rec #13's `planAcceptance.acHeadings` for its heading list only (not its enforcement),
    plus the built-in `acceptance` fallback, so a project that already told the framework what its
    AC sections are called does not have to say it twice.
    """
    return list(normalize_plan_acceptance(data)["acHeadings"]) + ["acceptance"]


def goal_tracker_item_issue_body(data: dict, target: Path, item: dict) -> tuple[str, str]:
    """(issue body, unavailable-reason). Exactly one of the two is ever non-empty-ish.

    The repo comes from the ITEM'S OWN issue URL, never from `data["repo"]`: the adapter repo is the
    LANE's repo, and reading issue #5 of the wrong repository does not fail -- it succeeds and
    returns somebody else's prose.
    """
    # `board_item_issue_pr_urls` is the ONE definition of "where this item's issue/PR link lives",
    # and it already knows the three payload shapes -- including a top-level `contentUrl`, which a
    # hand-rolled two-field walk here missed. Codex R4 P2: those items reported "no linked GitHub
    # issue/PR URL", so warn mode recorded `unknown` and strict mode refused a perfectly valid
    # closure, on a shape `board_item_fetch_state` has handled all along.
    url, repo, issue_number = board_item_repo_and_issue_number(item)
    if not issue_number:
        issue_number = goal_tracker_item_issue_number(item)
        if not issue_number:
            return "", "the item has no linked GitHub issue/PR URL"
        return "", f"issue #{issue_number} carries no owner/name in its URL"
    # `gh issue view` on a PULL REQUEST number fails, so a PR-backed board item would report its
    # body as permanently unavailable -- `unknown` under warn, a refusal of a perfectly valid
    # closure under strict. Both URL helpers accept `/pull/` by design (item URLs are routinely
    # PRs), so the read has to follow suit. Codex R1 P2.
    subcommand = "pr" if re.search(r"/pull/\d+", url) else "issue"
    try:
        code, out, err = run_command(
            [
                "gh", subcommand, "view", issue_number,
                "--repo", repo, "--json", "body", "--jq", '.body // ""',
            ],
            cwd=target,
            timeout=30,
        )
    except OSError as exc:
        return "", f"gh unavailable ({exc})"
    if code != 0:
        detail = (err or out or f"gh {subcommand} view failed").strip()[:160]
        return "", f"could not read {subcommand} #{issue_number} from {repo} ({detail})"
    # Defensive, mirroring sync_goal_issue_milestone_progress: `gh ... --jq .body` emits the
    # literal string "null" for some empty bodies, and parsing that as prose would be worse than
    # reading nothing -- it looks like content.
    return ("" if out.strip() == "null" else out), ""


def goal_tracker_preflight_done_ac_evidence(
    data: dict,
    target: Path,
    item: dict,
    item_ref: str,
    evidence: str,
    context: str,
) -> list[str]:
    """Oracle discipline, run as a PRE-FLIGHT on the done-move funnel (item 81).

    Placement is the load-bearing part. `goal_tracker_update_board_backed_subtasks_status` issues a
    `gh project item-edit` per board-backed subtask and posts each subtask's evidence comment, so a
    gate that fires inside `goal_tracker_post_done_evidence` -- the shape the first draft of this
    item specified -- refuses only after the mutations it exists to prevent have already happened.
    Called before `goal_tracker_preflight_done_subtasks`, this refuses with the board untouched.
    """
    mode = done_evidence_ac_table_mode(data)
    if mode == "off":
        return []
    body, unavailable = goal_tracker_item_issue_body(data, target, item)
    if unavailable:
        # Fail-open prints `unknown`, never a clean state: a degrade indistinguishable from a pass
        # cannot be counted, and the `strict` ratchet is gated on counting it.
        if mode == "strict":
            raise SystemExit(
                f"done_evidence_ac_error: issue body unavailable ({unavailable}), so closure "
                f"verification for {item_ref} cannot be measured against its written acceptance "
                "criteria. Remedy: re-run this command once the issue is readable, or read the "
                "criteria with "
                "`tautline ac-verify --item <item-ref> --target .` and pass the filled table with "
                "--verification-evidence-file."
            )
        print(
            f"done_evidence_ac_warning: issue body unavailable ({unavailable}); closure "
            "verification was not measured against the written acceptance criteria. "
            "Remedy: `tautline ac-verify --item <item-ref> --target .`"
        )
        print("done_evidence_ac_state: unknown")
        return []
    issues = done_evidence_ac_table_issues(evidence, body, done_evidence_ac_headings(data))
    if not issues:
        print("done_evidence_ac_state: pass")
        return []
    if mode == "strict":
        # Named, because an unnamed refusal on this path is unactionable: the subtask call site
        # passes the PARENT's evidence with a SUBTASK item, so "which item is this about" is the
        # first thing a lane needs and `ac-verify` on the wrong ref returns the wrong criteria.
        # Codex R4: `item_ref` and `context` were already parameters here and went unused.
        raise SystemExit(f"{context}: {item_ref}\n" + "\n".join(issues))
    for issue in issues:
        # The item ref goes into the MESSAGE, not into the print template. A template of
        # `done_evidence_ac_warning: {}: {}` stops being a passthrough to the closure refusal walk
        # -- it starts counting as a refusal of its own, with a body of interpolations that carries
        # no continuation and so fails the no-dead-ends check. The substance belongs at the builder,
        # which is where the walk reads it; this site stays a dispatcher.
        message = f"{item_ref}: {issue.split(':', 1)[1].strip()}"
        print(f"done_evidence_ac_warning: {message}")
    print("done_evidence_ac_state: fail")
    return issues


def goal_tracker_done_evidence_target(item: dict, context: str) -> tuple[str, str]:
    """`(repo, issue_number)` a done-evidence comment for `item` must go to, or a refusal.

    Both values come from the SAME resolver result, and that is the point of returning a pair.
    Codex R1 P1: resolving them separately reintroduced this release's own defect by another
    route. An item can carry several URL candidates, and `goal_tracker_item_issue_number` accepts
    the first that yields a NUMBER while the repo lookup takes the first that yields BOTH. Given
    an enterprise URL ending `/issues/5` followed by a valid `correct/repo/issues/6`, the number
    came from the first and the repo from the second, and the evidence posted to `correct/repo#5`
    -- a real issue, in the right repository, with nothing to do with this item.

    Batch 2026-08-11 B5. There is deliberately NO fallback to the lane's repo. The fallback that
    used to be proposed here was unreachable for the case it was written for and dangerous in the
    only case that reaches it:

    - An item with no linked URL has no issue NUMBER either -- `goal_tracker_item_issue_number`
      derives the number only from URLs -- so `goal_tracker_post_done_evidence` has already refused
      it one line earlier and never gets here.
    - What does get here is a URL that yields a number while its repo will not parse (an
      enterprise host, an API-shaped URL). There the lane's repo is a GUESS, and the guess posts a
      third party's verification claim onto the lane's own same-numbered issue -- the exact defect
      this item exists to remove, restored as a default.

    So: resolve it or refuse it. Naming the URL matters because the operator has to be able to see
    which link could not be parsed.
    """
    _, repo, issue_number = board_item_repo_and_issue_number(item)
    if repo and issue_number:
        return repo, issue_number
    # Two distinct causes, and they get two distinct sentences. The pre-flight reaches this for a
    # SUBTASK that has no linked URL at all, where "carries an issue number but no owner/name"
    # would simply be false -- and a refusal that misdescribes its own cause sends the operator to
    # fix the wrong thing.
    urls = board_item_issue_pr_urls(item)
    cause = (
        f"its linked URL carries an issue number but no owner/name ({', '.join(urls)})"
        if urls
        else "it has no linked GitHub issue/PR URL"
    )
    raise SystemExit(
        f"{context} to a done status cannot determine which repository to post verification "
        f"evidence to: {cause}. Posting to this lane's repository would write the claim onto a "
        f"different issue that happens to share the number, so no comment was attempted. Remedy: "
        f"give the board item a github.com issue/PR URL such as "
        f"https://github.com/example-org/example-saas/issues/12 — an owner/name pair is what makes "
        f"the target unambiguous."
    )


def goal_tracker_preflight_done_evidence_targets(
    data: dict,
    target: Path,
    item: dict,
    item_ref: str,
    context: str,
    subtasks: list[dict] | None = None,
    status: str = "",
) -> None:
    """Refuse an unresolvable evidence target BEFORE the done move mutates anything.

    Batch 2026-08-11 B5. `goal_tracker_update_board_backed_subtasks_status` comments on and marks
    every board-backed subtask done BEFORE the parent's evidence is posted, and each subtask's
    comment now resolves to its own repo. Without this, an unresolvable parent -- or an
    unresolvable subtask reached late in that loop -- raises only after earlier subtasks have
    already been moved to Done, leaving a partial completion behind a refusal. That is the same
    principle item 81 already wrote into this funnel: a refused done move must mutate nothing.

    This is PURE URL RESOLUTION over payloads the caller already holds. It performs no network
    call and no write-permission probe, so a single-repo adopter pays nothing for it. Whether a
    correctly addressed repo will ACCEPT the write is a different question that no read-only check
    can answer, and it is deliberately out of scope here -- see the foreign-repo failure-mode
    successor plan.
    """
    goal_tracker_done_evidence_target(item, context)
    if subtasks is None:
        return
    # Mirror the skips the MUTATION loop makes, so this refuses only targets that will actually be
    # written. `goal_tracker_update_board_backed_subtasks_status` skips a subtask already at the
    # target status (`already_<status>`) or already terminal (`skipped_terminal_status`) and posts
    # it no comment. Refusing on one of those would block a parent forever over a target nothing
    # writes to -- a compatibility case turned into a permanent block. Plan-review P2.
    tracker = goal_tracker_config(data)
    done_statuses = list(tracker.get("doneStatuses") or [])
    for subtask in subtasks:
        current_status = goal_tracker_item_field(subtask, tracker["statusField"])
        if status and goal_tracker_status_matches(current_status, [status]):
            continue
        if goal_tracker_status_matches(current_status, done_statuses):
            continue
        subtask_ref = goal_tracker_subtask_ref(subtask) or "(unreferenced subtask)"
        try:
            goal_tracker_done_evidence_target(subtask, f"{context} subtask {subtask_ref}")
        except SystemExit as exc:
            raise SystemExit(
                f"{context} to a done status refused before any status edit: board-backed subtask "
                f"{subtask_ref} of {item_ref} has no resolvable evidence target. {exc}"
            ) from exc


def goal_tracker_post_done_evidence(data: dict, target: Path, item: dict, evidence: str, context: str) -> str:
    evidence = evidence.strip()
    if not evidence:
        raise SystemExit(
            f"{context} to a done status requires verification evidence: pass --verification-evidence, "
            "--verification-evidence-file, or --verification-evidence-url"
        )
    if not goal_tracker_item_issue_number(item):
        raise SystemExit(f"{context} to a done status requires a linked GitHub issue/PR URL so verification evidence can be posted")
    # BOTH from one result. Taking the number here and the repo separately is what Codex R1 P1
    # showed posts to the right repository's WRONG issue when an item carries several URLs.
    repo, issue_number = goal_tracker_done_evidence_target(item, context)
    # `ac_checked=True`: this comment's AC verdict was already decided by the done-move pre-flight
    # against the PARENT item, so re-running the check here would both double-fetch and -- at the
    # board-backed subtask call site below -- evaluate the parent's evidence against a SUBTASK's
    # acceptance criteria, which is meaningless. Each subtask's own ACs are checked when that
    # subtask is itself moved to done through this same funnel.
    return stakeholder_issue_post_comment(
        data,
        target,
        issue_number,
        backlog_provider_done_evidence_comment(evidence),
        repo=repo,
        ac_checked=True,
    ) or "posted"


def goal_tracker_update_status_with_done_evidence(
    data: dict,
    target: Path,
    item_ref: str,
    status: str,
    *,
    evidence: str = "",
    context: str = "goal-tracker-update",
    ac_checked: bool = False,
) -> tuple[dict, str]:
    comment_url = ""
    item = resolve_goal_tracker_item(data, target, item_ref)
    done = goal_tracker_status_matches(status, goal_tracker_done_statuses(data))
    tracker = goal_tracker_config(data)
    active = goal_tracker_status_matches(status, list(tracker.get("activeStatuses") or []))
    done_subtasks: list[dict] | None = None
    if done:
        # Item 81: FIRST, before the subtask pre-flight and therefore before any `gh project
        # item-edit` or evidence comment. A refused done move must mutate nothing.
        #
        # `ac_checked` is set only by `goal_advance`, which runs this very pre-flight one caller up
        # so its refusal lands ahead of the UI-proof comment it would otherwise post first. Skipping
        # here avoids a second issue-body fetch and a duplicate state line; every other entry point
        # leaves it false and is gated here.
        if not ac_checked:
            goal_tracker_preflight_done_ac_evidence(data, target, item, item_ref, evidence, context)
        done_subtasks = goal_tracker_preflight_done_subtasks(
            data,
            target,
            item,
            item_ref,
            status,
            context,
            context.replace("-", "_").replace(" ", "_"),
            evidence=evidence,
            ac_checked=ac_checked,
        )
        # Batch 2026-08-11 B5. Both pre-flights above are read-only, so this is still ahead of every
        # mutation -- and it must be, because the subtask loop below writes a comment and an
        # item-edit PER SUBTASK. An unresolvable target discovered inside that loop would refuse
        # with earlier subtasks already moved to Done. Same seam, same reason, as the AC pre-flight.
        goal_tracker_preflight_done_evidence_targets(
            data, target, item, item_ref, context, subtasks=done_subtasks, status=status
        )
        goal_tracker_update_board_backed_subtasks_status(
            data,
            target,
            item,
            item_ref,
            status,
            evidence=evidence,
            context=context,
            prefix=context.replace("-", "_").replace(" ", "_"),
            subtasks=done_subtasks,
        )
        comment_url = goal_tracker_post_done_evidence(data, target, item, evidence, context)
        result = goal_tracker_update_status(data, target, item_ref, status)
    else:
        result = goal_tracker_update_status(data, target, item_ref, status)
        goal_tracker_update_board_backed_subtasks_status(
            data,
            target,
            item,
            item_ref,
            status,
            evidence=evidence,
            context=context,
            prefix=context.replace("-", "_").replace(" ", "_"),
            subtasks=done_subtasks,
        )
        if active:
            goal_tracker_claim_parent_items_active_for_subtask(
                data,
                target,
                item,
                item_ref,
                goal_tracker_primary_status(tracker, "activeStatuses"),
                context=context,
                prefix=context.replace("-", "_").replace(" ", "_"),
            )
    return result, comment_url


goal_tracker_primary_status = _goal_mod.goal_tracker_primary_status


def goal_tracker_status_for_goal_run(data: dict, run: dict) -> str:
    tracker = goal_tracker_config(data)
    if run.get("status") == "complete":
        return goal_tracker_primary_status(tracker, "doneStatuses")
    if any(item.get("status") == "blocked" for item in run.get("milestones", [])):
        return goal_tracker_primary_status(tracker, "blockedStatuses")
    return goal_tracker_primary_status(tracker, "activeStatuses")


def goal_tracker_status_for_milestone(data: dict, milestone: dict) -> str:
    tracker = goal_tracker_config(data)
    status = str(milestone.get("status") or "").strip()
    if status == "complete":
        return goal_tracker_primary_status(tracker, "doneStatuses")
    if status in {"blocked", "deferred"}:
        return goal_tracker_primary_status(tracker, "blockedStatuses")
    if status == "pending":
        return goal_tracker_primary_status(tracker, "readyStatuses")
    return goal_tracker_primary_status(tracker, "activeStatuses")


def goal_tracker_source_values_from_plan(path: Path) -> dict:
    # is_file() (not exists()) so a `.md` path that resolves to a DIRECTORY (e.g. a symlink-to-dir
    # surfaced by `git status`) is skipped, not read -- read_text on a dir raises IsADirectoryError
    # and would crash the pre-push board gate (same crash class as the P1-B gh fix).
    if not path.is_file() or path.suffix.lower() != ".md":
        return {}
    text = path.read_text(encoding="utf-8", errors="replace")
    section = markdown_section(text, "## GitHub Project Source")
    if not section:
        return {}
    values: dict[str, str] = {}
    for line in section.splitlines():
        match = re.match(r"^\s*[-*]\s*([A-Za-z0-9_-]+)\s*:\s*(.*?)\s*$", line)
        if match:
            values[match.group(1)] = match.group(2).strip()
    return values


def goal_tracker_ref_from_plan(path: Path) -> str:
    values = goal_tracker_source_values_from_plan(path)
    for key in ["project_item_id", "project_item_url", "title"]:
        value = values.get(key, "").strip()
        if value and value.lower() != "none":
            return value
    return ""


def goal_tracker_goal_ref(data: dict, target: Path, run: dict) -> str:
    source_goal = goal_run_source_path(data, target, run)
    if not source_goal:
        return ""
    return goal_tracker_ref_from_plan(source_goal)


def goal_tracker_milestone_ref(target: Path, milestone: dict | None) -> str:
    if not milestone:
        return ""
    source_plan = str(milestone.get("sourcePlan") or "").strip()
    if not source_plan:
        return ""
    return goal_tracker_ref_from_plan(cli_path(target, source_plan))


goal_tracker_print_sync_result = _goal_mod.goal_tracker_print_sync_result


goal_tracker_done_evidence_for_transition = _goal_mod.goal_tracker_done_evidence_for_transition


def goal_tracker_sync_status_update(
    data: dict,
    target: Path,
    item_ref: str,
    status: str,
    event: str,
    done_evidence: str,
    *,
    ac_checked: bool = False,
) -> tuple[dict, str]:
    return goal_tracker_update_status_with_done_evidence(
        data,
        target,
        item_ref,
        status,
        evidence=done_evidence,
        context=f"goal-tracker sync for {event}",
        ac_checked=ac_checked,
    )


def goal_tracker_transition_done_ref(
    data: dict,
    target: Path,
    run: dict,
    event: str,
    milestone: dict | None,
) -> tuple[str, str]:
    """(ref, status) for a transition that will move an item to a DONE status, or ("", "").

    Derived from the same three functions `goal_tracker_sync_transition` uses to pick its ref and
    its status, so the closure pre-flight in `goal_advance` cannot drift from the transition it is
    guarding -- a second copy of this selection would go stale the first time either changed.
    """
    tracker = goal_tracker_config(data)
    if not tracker["enabled"]:
        return "", ""
    done_statuses = goal_tracker_done_statuses(data)
    if event == "goal-complete":
        ref = goal_tracker_goal_ref(data, target, run)
        status = goal_tracker_primary_status(tracker, "doneStatuses")
    elif event.startswith("milestone-"):
        ref = goal_tracker_milestone_ref(target, milestone)
        if ref:
            status = goal_tracker_status_for_milestone(data, milestone or {})
        else:
            ref = goal_tracker_goal_ref(data, target, run)
            status = goal_tracker_status_for_goal_run(data, run)
    else:
        return "", ""
    if ref and goal_tracker_status_matches(status, done_statuses):
        return ref, status
    return "", ""


def goal_advance_closure_preflight(
    data: dict,
    target: Path,
    run: dict,
    event: str,
    milestone: dict | None,
    done_evidence: str,
) -> None:
    """Run the item-81 closure gate BEFORE any comment `goal-advance` posts.

    Covers the parent item AND every board-backed subtask this transition will auto-close. Codex R2:
    hoisting only the parent left the subtask refusal inside the transition, which runs after
    `sync_goal_issue_ui_evidence` has already published the required UI proof -- so a strict refusal
    on a subtask's criteria mutated GitHub before refusing, which is the one thing the pre-flight
    seam exists to prevent.

    Raises only what the funnel itself would raise, and earlier: the subtask enumeration below is
    the same `require=True` call the transition makes, so a native sub-issue that is not a board
    item is now reported before the UI comment rather than after it.
    """
    ref, status = goal_tracker_transition_done_ref(data, target, run, event, milestone)
    if not ref:
        return
    context = f"goal-tracker sync for {event}"
    item = resolve_goal_tracker_item(data, target, ref)
    goal_tracker_preflight_done_ac_evidence(data, target, item, ref, done_evidence, context)
    subtasks = goal_tracker_board_backed_subtasks(
        data, target, item, ref, context.replace("-", "_").replace(" ", "_"), "done", require=True
    )
    goal_tracker_preflight_done_subtask_ac_evidence(
        data, target, subtasks, status, done_evidence, context
    )
    # Batch 2026-08-11 B5, and the same argument this docstring already makes for the subtask AC
    # check: `goal_tracker_update_status_with_done_evidence` runs AFTER
    # `sync_goal_issue_ui_evidence`, so a target check placed only in that funnel would let the
    # required UI-proof comment publish before an unresolvable evidence target is refused. The
    # earliest seam is the correct one, not the most obvious one.
    goal_tracker_preflight_done_evidence_targets(
        data, target, item, ref, context, subtasks=subtasks, status=status
    )


def goal_tracker_sync_transition(
    data: dict,
    target: Path,
    run: dict,
    event: str,
    milestone: dict | None = None,
    *,
    done_evidence: str = "",
    ac_checked: bool = False,
) -> list[str]:
    tracker = goal_tracker_config(data)
    if not tracker["enabled"]:
        return []
    issues: list[str] = []
    goal_ref = goal_tracker_goal_ref(data, target, run)
    if not goal_ref:
        # RCA 2026-07-31 control 4. This used to raise UNCONDITIONALLY and name no way out, so a
        # lane whose work genuinely has no board item -- a repo-only goal -- had two exits, both
        # bad: disable the tracker wholesale, or hand-edit the ledger. A refusal that names no
        # sanctioned alternative is where bypasses get invented, and the bypass is worse than the
        # allowance. The knob is off by default, so a lane that never sets it sees no change.
        if not tracker.get("allowRepoOnlyGoals", DEFAULT_GOAL_TRACKER["allowRepoOnlyGoals"]):
            raise SystemExit(
                "goalTracker is enabled but the source goal plan has no GitHub Project Source "
                "project_item_id/project_item_url. Sync the external backlog item into the repo "
                "plan with `tautline backlog-provider-sync --target . --item <item> --write` "
                "before goal-start/advance. If this goal legitimately has no board item, set "
                "`goalTracker.allowRepoOnlyGoals` (or `backlogProvider.allowRepoOnlyGoals`) to "
                "true in the source adapter and re-render -- that is the sanctioned repo-only "
                "path, and it is deliberately explicit rather than inferred from a missing ref."
            )
        print(
            "goal_tracker_repo_only_goal: no GitHub Project Source item; proceeding repo-only "
            "because allowRepoOnlyGoals is set. Board status is not updated for this goal.",
        )
    # NOT an early return. Codex R1 P2: the allowance sanctions the missing GOAL item and nothing
    # else, so a board-backed MILESTONE under a repo-only parent must still sync. Returning here
    # turned a parent-goal allowance into a milestone-sync opt-out -- silently, since the run
    # reported success. `goal_ref` is falsy on this path, so every goal-level branch below is
    # skipped by the same condition that already guards them, and only the milestone branch runs.
    milestone_ref = goal_tracker_milestone_ref(target, milestone)
    if goal_ref and event in {"goal-start", "startup"}:
        status = goal_tracker_primary_status(tracker, "activeStatuses")
        result, _ = goal_tracker_sync_status_update(data, target, goal_ref, status, event, "")
        goal_tracker_print_sync_result(goal_ref, status, result)
    elif goal_ref and event == "goal-complete":
        status = goal_tracker_primary_status(tracker, "doneStatuses")
        result, comment_url = goal_tracker_sync_status_update(
            data, target, goal_ref, status, event, done_evidence, ac_checked=ac_checked
        )
        if comment_url:
            print(f"goal_tracker_sync_verification_comment: {comment_url}")
        goal_tracker_print_sync_result(goal_ref, status, result)
    elif event.startswith("milestone-"):
        if milestone_ref:
            status = goal_tracker_status_for_milestone(data, milestone or {})
            result, comment_url = goal_tracker_sync_status_update(
                data, target, milestone_ref, status, event, done_evidence, ac_checked=ac_checked
            )
            if comment_url:
                print(f"goal_tracker_sync_verification_comment: {comment_url}")
            goal_tracker_print_sync_result(milestone_ref, status, result)
        elif goal_ref:
            # The pre-existing fallback: an unmapped milestone rolls up to the parent goal item.
            # Guarded on `goal_ref` because a repo-only parent has no item to roll up TO, and
            # calling the update with an empty ref would be a board write against nothing.
            status = goal_tracker_status_for_goal_run(data, run)
            result, comment_url = goal_tracker_sync_status_update(
                data, target, goal_ref, status, event, done_evidence, ac_checked=ac_checked
            )
            if comment_url:
                print(f"goal_tracker_sync_verification_comment: {comment_url}")
            goal_tracker_print_sync_result(goal_ref, status, result)
            if event == "milestone-complete":
                issues.append(
                    "completed milestone has no GitHub Project Source item mapping; parent goal item stayed current, "
                    "but milestone-level board status/checklist must be reconciled."
                )
    for issue in issues:
        print(f"goal_tracker_sync_issue: {issue}")
    return issues


goal_tracker_status_matches = _goal_mod.goal_tracker_status_matches


def goal_tracker_drift_issues(data: dict, target: Path, run: dict) -> list[str]:
    tracker = goal_tracker_config(data)
    if not tracker["enabled"]:
        return []
    issues = [f"goalTracker provider unavailable: {issue}" for issue in goal_tracker_status_issues(data, target)]
    if issues:
        return issues
    goal_ref = goal_tracker_goal_ref(data, target, run)
    if not goal_ref:
        # The same allowance the sync path takes, and it has to be the same: a lane that may
        # legitimately run repo-only must not be told it is drifting for the exact state the knob
        # sanctions. One knob, both paths -- a gate and its sync disagreeing about what is allowed
        # is how a sanctioned path becomes unusable in practice.
        if not tracker.get("allowRepoOnlyGoals", DEFAULT_GOAL_TRACKER["allowRepoOnlyGoals"]):
            return [
                "goalTracker is enabled but active goal has no GitHub Project Source "
                "project_item_id/project_item_url; sync a backlog provider item into the "
                "source-of-truth goal plan before continuing, "
                "or set `goalTracker.allowRepoOnlyGoals` for a goal that legitimately has no "
                "board item."
            ]
        # NOT an early return, for the same reason the sync path is not one (Codex R1 P2): the
        # allowance covers the missing GOAL item only, and an adapter that tracks milestones still
        # has board-backed milestones to check under a repo-only parent. Skipping the loop would
        # report a clean board for milestones nobody looked at.
    if goal_ref:
        try:
            item = resolve_goal_tracker_item(data, target, goal_ref)
        except SystemExit as exc:
            return [f"GitHub Project goal item cannot be resolved for active goal: {exc}"]
        actual = goal_tracker_item_field(item, tracker["statusField"])
        expected_status = goal_tracker_status_for_goal_run(data, run)
        if not goal_tracker_status_matches(actual, [expected_status]):
            issues.append(
                f"GitHub Project goal item status drift: item {goal_ref} is "
                f"`{actual or 'none'}`, expected `{expected_status}`; run `tautline "
                f"goal-tracker-update --target . --item {shlex.quote(goal_ref)} "
                f"--status {shlex.quote(expected_status)}`"
            )
    provider = backlog_provider_config(data)
    enforce_milestone_mapping = bool(provider.get("enabled")) and "milestone" in provider.get("itemTypes", [])
    for milestone in run.get("milestones", []):
        milestone_ref = goal_tracker_milestone_ref(target, milestone)
        if milestone_ref:
            try:
                milestone_item = resolve_goal_tracker_item(data, target, milestone_ref)
            except SystemExit as exc:
                issues.append(f"GitHub Project milestone item cannot be resolved for milestone {milestone.get('index')}: {exc}")
                continue
            actual_milestone = goal_tracker_item_field(milestone_item, tracker["statusField"])
            expected_milestone = goal_tracker_status_for_milestone(data, milestone)
            if not goal_tracker_status_matches(actual_milestone, [expected_milestone]):
                issues.append(
                    f"GitHub Project milestone item status drift: milestone {milestone.get('index')} item {milestone_ref} is `{actual_milestone or 'none'}`, expected `{expected_milestone}`; "
                    f"run `tautline goal-tracker-update --target . --item {shlex.quote(milestone_ref)} --status {shlex.quote(expected_milestone)}`"
                )
        elif enforce_milestone_mapping and milestone.get("status") in {"complete", "blocked", "deferred"}:
            issues.append(
                f"milestone {milestone.get('index')} `{milestone.get('title')}` is {milestone.get('status')} but has no GitHub Project Source item mapping; "
                "sync or link a milestone Project item so stakeholder board status reflects completed/deferred/blocked work."
            )
    return issues


def board_item_content_state(item: dict) -> str:
    """The underlying issue/PR state (OPEN/CLOSED/MERGED) for a GitHub Project item, when the
    payload exposes it. Returns '' when no state is present (older gh output) so the generic
    state reconciliation never guesses."""
    content = item.get("content") if isinstance(item.get("content"), dict) else {}
    for source in (item, content):
        if not isinstance(source, dict):
            continue
        for key in ("state", "issueState", "prState", "stateReason"):
            text = goal_tracker_value_text(source.get(key)).strip().upper()
            if text in {"OPEN", "CLOSED", "MERGED"}:
                return text
    for source in (content, item):
        if isinstance(source, dict) and source.get("closed") is True:
            return "CLOSED"
    return ""


def github_issue_or_pr_state_rest(target: Path, url: str) -> str:
    match = re.search(r"github\.com/([^/]+)/([^/]+)/(issues|pull)/([0-9]+)", str(url or ""))
    if not match:
        return ""
    owner, repo, kind, number = match.groups()
    endpoint = f"repos/{owner}/{repo}/{'pulls' if kind == 'pull' else 'issues'}/{number}"
    code, payload, _error = command_json(["gh", "api", endpoint], cwd=target, timeout=15)
    if code != 0 or not isinstance(payload, dict):
        return ""
    state = str(payload.get("state") or "").strip().upper()
    if kind == "pull" and payload.get("merged") is True:
        return "MERGED"
    if state == "CLOSED":
        return "CLOSED"
    if state == "OPEN":
        return "OPEN"
    return ""


def board_item_fetch_state(item: dict, target: Path) -> str:
    """The underlying issue/PR state (OPEN/CLOSED/MERGED) for a project item. `gh project
    item-list --format json` omits issue/PR state (Codex Critical), so when the payload does not
    already carry one we fetch it explicitly with `gh issue/pr view <url> --json state`. Returns
    '' for draft items, items with no issue/PR URL, or when the state cannot be read."""
    inline = board_item_content_state(item)
    if inline:
        return inline
    content = item.get("content") if isinstance(item.get("content"), dict) else {}
    url = goal_tracker_value_text(content.get("url") or item.get("contentUrl")).strip()
    ctype = goal_tracker_value_text(content.get("type")).strip().lower()
    if not url or "draft" in ctype or "/issues/" not in url and "/pull/" not in url:
        return ""
    rest_state = github_issue_or_pr_state_rest(target, url)
    if rest_state:
        return rest_state
    subcommand = "pr" if ("pull" in ctype or "/pull/" in url) else "issue"
    # A real issue/PR whose state cannot be read is NOT treated as clean (Codex P1): the gh failure
    # propagates so the caller records it as drift rather than silently passing the board gate.
    payload = goal_tracker_gh_json([subcommand, "view", url, "--json", "state"], target)
    if isinstance(payload, dict):
        return goal_tracker_value_text(payload.get("state")).strip().upper()
    return ""








# `owner/repo#123` is GitHub's supported CROSS-REPOSITORY closing form and auto-closes exactly
# like `#123`. Codex R1 P2: requiring `#` immediately after the keyword reported
# `missing_closing_ref` on bodies GitHub would happily act on -- the gate refusing correct work,
# which is the most expensive kind of false positive a blocking gate can have.
# All three forms GitHub actually honors: bare `#123`, cross-repo `owner/repo#123`, and the full
# issue URL. Codex R2 P2 named the third; refusing any of them is the gate rejecting work GitHub
# would auto-close, which is the most expensive false positive a blocking gate can have.
_CLOSING_REF = (
    r"(?:https?://github\.com/[\w.-]+/[\w.-]+/issues/\d+|(?:[\w.-]+/[\w.-]+)?#\d+)"
)
CLOSING_KEYWORD_LIST_RE = re.compile(
    r"\b(close[sd]?|fix(?:es|ed)?|resolve[sd]?)\b[ \t]*:?[ \t]*"
    rf"({_CLOSING_REF}(?:[ \t]*,[ \t]*{_CLOSING_REF})+)",
    re.IGNORECASE,
)
CLOSING_KEYWORD_SINGLE_RE = re.compile(
    rf"\b(close[sd]?|fix(?:es|ed)?|resolve[sd]?)\b[ \t]*:?[ \t]*{_CLOSING_REF}",
    re.IGNORECASE,
)


# The scope is an ISSUE NUMBER only when it is bare digits or an explicitly qualified reference.
# Anything dotted is not: `release(0.75.0): ...` is this repository's own release-PR title shape,
# and reading its version as issue #0.75.0 would bind every release PR to an issue that does not
# exist. A word scope (`feat(board):`) is likewise not a reference.
def closing_reference_checks_apply(data: dict) -> bool:
    """Whether closing-reference enforcement applies to this repository at all. Item 101 T-B.

    ONE reader for a fact BOTH boundaries need, because they answered it differently and the
    disagreement had a measured cost. The prepush side sits inside a verb that early-returns when
    no provider or tracker is enabled; `merge_command_closing_refs` had no such guard at all, so
    the merge boundary demanded closing keywords from repositories that have no issue backlog to
    reference. That is what drove this framework's own lanes to satisfy the gate with `Resolves #N`
    against unrelated merged PRs -- rule 4's harm manufactured by a blocking gate.

    ISSUE-BACKED, not merely `enabled`: the generated adapter renders the PR-reference contract
    only when an enabled provider also carries `owner` and `projectNumber` (see `render_adapter`),
    so enforcing on `enabled` alone would enforce an obligation the adapter deliberately withheld
    from the very repo being checked. The predicate and the renderer answer the same question, so
    they read the same fields.
    """
    for config in (goal_tracker_config(data), backlog_provider_config(data)):
        if config.get("enabled") and config.get("owner") and config.get("projectNumber"):
            return True
    return False


def closing_reference_exemption(data: dict, target: Path) -> str:
    """The lane's standing reason a PR body need not bind an issue, or "" if it has none.

    ONE resolver, called by BOTH boundaries. Codex R1 P2: prepush exempted a non-development work
    profile and merge did not, so a docs PR passed prepush and then refused at `tautline merge` --
    the same gate answering the same question two different ways depending on where you met it.
    That is the one-fact-two-readers failure this codebase keeps paying for, and the fix is never
    to add the missing branch in the second place: it is to have one place.

    Each exemption is a lane that has already SAID the obligation does not apply -- a work profile
    that is not development, a recorded `board-binding` decision, or `allowRepoOnlyGoals`, the
    sanctioned no-board-item path. None of them excuses a MALFORMED closing reference; they answer
    "must this PR bind an issue?", never "may it bind one wrongly?".
    """
    tracker = goal_tracker_config(data)
    provider = backlog_provider_config(data)
    if tracker.get("allowRepoOnlyGoals") or provider.get("allowRepoOnlyGoals"):
        return "allowRepoOnlyGoals"
    # NO `board-binding` DECISION EXEMPTION. It shipped in four successive drafts and was wrong in
    # four different ways -- unscoped across the whole repo, compared as text across timezones,
    # grantable by any log event carrying the surface, anchored on the wrong branch, and finally
    # still exempting a CONCURRENT lane's PR from one lane's decision. Every fix narrowed it and
    # none made it correct, which is the signal that the escape hatch needs its own design rather
    # than another scoping predicate bolted onto this gate. Filed as its own backlog item; the
    # refusal below no longer advertises an exit that does not work.
    #
    # An adapter that declares no work profiles has no non-development profile to be exempt BY.
    # Guarded rather than assumed: this resolver runs on every prepush of every provider-backed
    # lane, and it must never be the reason a boundary crashes.
    if not isinstance(data.get("workProfiles"), dict):
        return ""
    profile, _reason, _issues = read_work_profile_lock(data, target)
    if profile != "development":
        return f"work profile {profile}"
    return ""


def outgoing_pr_closing_ref_issues(data: dict, target: Path, branch: str) -> list[str]:
    """Closing-reference problems in the current branch's open PR body, for the prepush gate.

    Item 79 WS2, D4(a). Three boundary-honesty rules, each of which is a decision rather than an
    omission:

    - **No PR yet, no refusal.** There is no body to check, and refusing here would block the very
      push that creates the PR. The merge-verb wiring is the backstop for that case.
    - **An unreadable body warns, never blocks and never passes silently.** A provider outage must
      not wedge a push over a body only GitHub holds; but silently treating "could not read" as
      "fine" is how a gate becomes decorative.
    - **The missing-reference check is exempt where the lane has already said so:** a doc-only work
      profile, a recorded `board-binding` decision, or `allowRepoOnlyGoals` -- the sanctioned
      no-board-item path shipped in 0.64.0. Inventing a parallel bypass around a knob that already
      exists is what item 71's successor interface forbids.
    """
    # The ADAPTER's base branches, not the hard-coded set. Codex R3 P2: a repo that declares an
    # integration branch outside the built-in names (this one integrates on `experimental`) had it
    # treated as a feature branch, so a push to the base could inspect an open release PR's body
    # and block the board gate -- on a branch every other gate already exempts.
    if (
        not branch
        or branch in adapter_base_branch_names(data, target)
        or shutil.which("gh") is None
        # Item 101 T-B: the same issue-backed question the merge boundary now asks, asked here
        # through the same reader rather than inferred from the enclosing verb's own early return.
        or not closing_reference_checks_apply(data)
    ):
        return []
    code, payload, _ = command_json(
        ["gh", "pr", "list", "--head", branch, "--state", "open", "--limit", "1",
         "--json", "number,body"],
        target,
        timeout=15,
    )
    if code != 0 or not isinstance(payload, list):
        print(
            "pr_closing_refs_warn: PR body unreadable (provider unreachable); closing-reference "
            "checks did not run for this push",
            file=sys.stderr,
        )
        return []
    if not payload:
        return []
    entry = payload[0] if isinstance(payload[0], dict) else {}
    if "body" not in entry:
        # A MISSING KEY IS NOT AN EMPTY BODY. The provider did not answer the question -- some `gh`
        # versions and response shapes simply omit the field -- and treating that absence as "no
        # closing reference" would refuse a PR whose body was never read. Same trap the
        # github-projects-reads skill documents for `item-list --format json` dropping
        # `fieldValues`: a null there is an unanswered question, not an empty field. Warn and
        # proceed, per D4(a): never block on a fact we do not hold, never pass silently.
        print(
            "pr_closing_refs_warn: PR body absent from the provider response; closing-reference "
            "checks did not run for this push",
            file=sys.stderr,
        )
        return []
    body = str(entry.get("body") or "")
    issues = list(pr_body_closing_reference_errors(body))
    exemption = closing_reference_exemption(data, target)
    if exemption:
        print(f"missing_closing_ref_exempt: {exemption}")
        return issues
    missing = pr_body_missing_closing_reference_error(body)
    if missing:
        issues.append(missing)
    return issues


def pr_body_closing_reference_errors(body: str) -> list[str]:
    """GitHub honors a closing keyword for the FIRST following ref only.

    `Resolves #A, #B` merges with #B silently left open -- RCA 2026-06-15 (#307/#260). Nothing
    warns, because from GitHub's side nothing went wrong: it did exactly what one keyword means.
    One error per offending keyword, each carrying the compliant per-ref rewrite, because "use one
    keyword per issue" without the rewritten line is a rule the author still has to translate.
    """
    errors: list[str] = []
    for match in CLOSING_KEYWORD_LIST_RE.finditer(text_without_code_spans(body or "")):
        refs = re.findall(_CLOSING_REF, match.group(2))
        keyword = match.group(1).capitalize()
        rewrite = ", ".join(f"`{keyword} {ref}`" for ref in refs)
        errors.append(
            f"pr_closing_refs: `{match.group(0).strip()}` auto-closes only {refs[0]}; "
            f"GitHub drops the rest. Use one keyword per issue: {rewrite}. Then re-run."
        )
    return errors


def pr_body_missing_closing_reference_error(body: str) -> str:
    """A body that binds no auto-close at all. RCA 2026-07-18 control 3: 18 of 60 merged PRs.

    Their issues never auto-closed, so no completion-moment gate could fire -- there were no refs
    for it to check. The comma-list check above cannot catch this: zero refs yields zero list
    errors, which is why both predicates exist.

    Pure body question. The caller applies the doc-only work-profile exemption, the recorded
    `board-binding` decision exit, and the `allowRepoOnlyGoals` exemption BEFORE calling; this
    answers only "does the body bind an auto-close?".
    """
    if CLOSING_KEYWORD_SINGLE_RE.search(text_without_code_spans(body or "")):
        return ""
    return (
        "missing_closing_ref: PR body has no `Closes/Fixes/Resolves #NNN` closing "
        "reference, so merging will auto-close nothing and the board closeout check has "
        "no refs to verify. Add `Resolves #<issue>` to the body -- GitHub's `#123`, "
        "`owner/repo#123`, and full-issue-URL forms all count. A lane whose work legitimately has "
        "no board item sets `allowRepoOnlyGoals`, and a non-development work profile is exempt "
        "already. Then re-run."
    )


def lane_outgoing_issue_refs(target: Path, branch: str, base_branch_names: set[str] | None = None) -> list[str]:
    """Issue numbers the current branch's outgoing work maps to: every issue its OPEN PR(s)
    close (via gh closingIssuesReferences) plus a trailing issue number in the branch name.
    Deduped, order-stable. Empty on a base/numberless branch or when gh cannot be reached --
    the caller degrades gracefully (no credit, not a crash)."""
    refs: list[str] = []
    bases = base_branch_names or BASE_BRANCH_NAMES
    if branch and branch not in bases and shutil.which("gh") is not None:
        code, payload, _ = command_json(
            ["gh", "pr", "list", "--head", branch, "--state", "open", "--limit", "10",
             "--json", "number,closingIssuesReferences"],
            target,
            timeout=15,
        )
        if code == 0 and isinstance(payload, list):
            for pr in payload:
                if not isinstance(pr, dict):
                    continue
                for ref in pr.get("closingIssuesReferences") or []:
                    if not isinstance(ref, dict):
                        continue  # Codex review: a non-dict entry must not crash the gate.
                    num = str(ref.get("number") or "").strip()
                    if num and num not in refs:
                        refs.append(num)
    branch_num = branch_issue_number(branch)
    if branch_num and branch_num not in refs:
        refs.append(branch_num)
    return refs


def lane_changed_plan_refs(target: Path) -> list[str]:
    """Project-item refs declared in the `## GitHub Project Source` section of any working-tree-changed
    markdown plan/spec. RCA Jun-16 #234: a lane drafting a milestone spec is actively working that
    spec's board item before any PR exists. Only `.md` files that actually carry the mapping
    contribute (goal_tracker_ref_from_plan returns '' otherwise), so this is naturally scoped to
    mapped source-of-truth plans. Empty when git is unavailable."""
    changed = run_git(target, ["status", "--porcelain"])
    if not changed or changed == "unavailable":
        return []
    refs: list[str] = []
    for line in changed.splitlines():
        path_part = line[3:].strip() if len(line) > 3 else ""
        if " -> " in path_part:  # porcelain rename "old -> new"
            path_part = path_part.split(" -> ", 1)[1].strip()
        path_part = path_part.strip('"')
        if not path_part.lower().endswith(".md"):
            continue
        try:
            ref = goal_tracker_ref_from_plan(target / path_part)
        except OSError:
            # Never let a weird working-tree path (unreadable/odd `.md`) crash the board gate.
            continue
        if ref and ref not in refs:
            refs.append(ref)
    return refs


def lane_work_scope(data: dict, target: Path) -> dict:
    """Read-only: which board items the lane's current work touches. `ledger_ref` is the active
    goal ledger's mapped project item (or '' when none/unlinked); `outgoing_issue_numbers` are the
    issues the current branch/PR closes; `working_tree_refs` are board items mapped by a
    working-tree-changed source-of-truth plan/spec (RCA Jun-16 #234); `unresolved_ledger` is True
    when a goal ledger exists but carries no project link (RCA Jun-17: an unlinked ledger must not
    hard-block outgoing work)."""
    branch = run_git(target, ["branch", "--show-current"])
    outgoing = lane_outgoing_issue_refs(target, branch, branch_liveness_base_branch_names(target))
    ledger_ref = ""
    unresolved_ledger = False
    if goal_run_path(data, target).exists():
        run = load_goal_run(data, target)
        ledger_ref = goal_tracker_goal_ref(data, target, run)
        unresolved_ledger = not ledger_ref
    return {
        "ledger_ref": ledger_ref,
        "outgoing_issue_numbers": outgoing,
        "working_tree_refs": lane_changed_plan_refs(target),
        "unresolved_ledger": unresolved_ledger,
    }


def board_item_issue_pr_urls(item: dict) -> list[str]:
    """Issue/PR URLs linked to a Project item, preferring content URLs over project-item pane URLs."""
    content = item.get("content") if isinstance(item.get("content"), dict) else {}
    urls: list[str] = []
    for value in [
        goal_tracker_value_text(content.get("url")),
        goal_tracker_value_text(item.get("contentUrl")),
        goal_tracker_item_url(item),
    ]:
        value = value.strip()
        if value and ("/issues/" in value or "/pull/" in value) and value not in urls:
            urls.append(value)
    return urls


def board_item_repo_and_issue_number(item: dict) -> tuple[str, str, str]:
    """`(url, owner/name, number)` for the item's own issue/PR link, or `("", "", "")`.

    ONE resolver, called by the READ side (`goal_tracker_item_issue_body`) and the WRITE side
    (`goal_tracker_post_done_evidence`). Batch 2026-08-11 B5: those two sides each resolved the
    target repo their own way, so the same command read a cross-repo item's acceptance criteria
    from the item's repo and posted its verification evidence to the LANE's -- onto a real,
    unrelated issue that happened to share the number. Two parsers for one concept is how they
    diverged; a shared one is why they cannot diverge again.

    A candidate counts only when it yields BOTH a repo and a number. `github_issue_number_from_url`
    succeeds on URL forms `github_repo_from_issue_url` cannot parse (enterprise hosts, API-shaped
    URLs), and a number without a repo is precisely the ambiguity that produced the defect -- so it
    is reported as unresolved here and refused by the caller, never completed with a guess.
    """
    for candidate in board_item_issue_pr_urls(item):
        candidate_repo = github_repo_from_issue_url(candidate)
        candidate_number = github_issue_number_from_url(candidate)
        if candidate_repo and candidate_number:
            return candidate, candidate_repo, candidate_number
    return "", "", ""


def board_item_display_ref(item: dict) -> str:
    """Human-actionable item reference for board-currency messages."""
    urls = board_item_issue_pr_urls(item)
    return urls[0] if urls else (goal_tracker_item_url(item) or goal_tracker_item_title(item))


def board_item_matches_issue_numbers(item: dict, issue_numbers: list[str]) -> bool:
    """True when a project item's issue/PR URL ends in one of the given issue numbers."""
    urls = board_item_issue_pr_urls(item)
    for num in issue_numbers:
        for url in urls:
            if url.rstrip("/").endswith(f"/{num}"):
                return True
    return False


def board_item_matches_strong_ref(item: dict, ref: str) -> bool:
    """True when a board item matches a ledger/plan ref by a STRONG identifier (project node id or
    issue/PR url) ONLY -- never by title. Used on the blocking active-work path so a title-only
    ledger/plan ref (goal_tracker_ref_from_plan falls back to the plan `title:`) cannot over-match a
    DIFFERENT board item via a title-suffix collision and produce a spurious block (P3)."""
    needle = (ref or "").strip()
    if not needle:
        return False
    content = item.get("content") if isinstance(item.get("content"), dict) else {}
    strong = {goal_tracker_item_id(item), goal_tracker_item_url(item), goal_tracker_value_text(content.get("url"))}
    strong = {value for value in strong if value}
    return needle in strong or any(needle.endswith(value) or value.endswith(needle) for value in strong)


def board_item_ref_values(item: dict) -> set[str]:
    """Strong identifiers for a Project item, used for current-work matching without title guesses."""
    content = item.get("content") if isinstance(item.get("content"), dict) else {}
    values = {
        goal_tracker_item_id(item),
        goal_tracker_item_url(item),
        goal_tracker_item_content_url(item),
        goal_tracker_value_text(content.get("id")),
        goal_tracker_value_text(item.get("contentId")),
    }
    return {value.strip() for value in values if value and value.strip()}


def board_item_scope_current_work(item: dict, scope: dict) -> bool:
    """True when the item is verified current lane work from branch/PR, changed plan, or ledger."""
    has_outgoing_refs = bool(scope["outgoing_issue_numbers"])
    has_working_tree_refs = bool(scope.get("working_tree_refs", []))
    is_outgoing_work = board_item_matches_issue_numbers(item, scope["outgoing_issue_numbers"])
    is_changed_plan_work = any(board_item_matches_strong_ref(item, ref) for ref in scope.get("working_tree_refs", []))
    is_ledger_current_work = (
        bool(scope["ledger_ref"])
        and not has_outgoing_refs
        and not has_working_tree_refs
        and board_item_matches_strong_ref(item, scope["ledger_ref"])
    )
    return is_outgoing_work or is_changed_plan_work or is_ledger_current_work


def board_backed_subtask_items(parent_item: dict, items: list[dict], target: Path) -> tuple[list[dict], bool, list[str]]:
    """Native sub-issues of current work that are also visible board items.

    The parent issue's status is not a substitute for subtask status. Matching uses strong native
    issue IDs/URLs only. The unmatched return lets closeout block instead of silently ignoring a
    native subtask that is not represented on the board.
    """
    content = parent_item.get("content") if isinstance(parent_item.get("content"), dict) else {}
    if not goal_tracker_value_text(content.get("id")):
        return [], False, []
    sub_issues = grooming_sub_issues(parent_item, target)
    if sub_issues == GROOMING_SUBISSUES_UNAVAILABLE:
        return [], True, []
    sub_issue_keys: list[tuple[dict, set[str]]] = []
    for sub_issue in sub_issues:
        if not isinstance(sub_issue, dict):
            continue
        keys: set[str] = set()
        for value in [
            goal_tracker_value_text(sub_issue.get("id")),
            goal_tracker_value_text(sub_issue.get("url")),
        ]:
            if value:
                keys.add(value.strip())
        if keys:
            sub_issue_keys.append((sub_issue, keys))
    if not sub_issue_keys:
        return [], False, []
    matches: list[dict] = []
    seen: set[str] = set()
    matched_indexes: set[int] = set()
    for item in items:
        item_keys = board_item_ref_values(item)
        matching_indexes = {
            index for index, (_sub_issue, keys) in enumerate(sub_issue_keys) if item_keys.intersection(keys)
        }
        if not matching_indexes:
            continue
        matched_indexes.update(matching_indexes)
        item_id = goal_tracker_item_id(item) or goal_tracker_item_content_url(item) or goal_tracker_item_url(item)
        if item_id in seen:
            continue
        seen.add(item_id)
        matches.append(item)
    unmatched = [
        goal_tracker_value_text(sub_issue.get("url"))
        or goal_tracker_value_text(sub_issue.get("id"))
        or goal_tracker_value_text(sub_issue.get("title"))
        or "unknown-subtask"
        for index, (sub_issue, _keys) in enumerate(sub_issue_keys)
        if index not in matched_indexes
    ]
    return matches, False, unmatched




def provider_board_currency_issues(data: dict, target: Path, goal_run: dict | None) -> tuple[list[str], list[str], list[str]]:
    """Always-on board-currency reconciliation for provider-backed lanes. Returns
    (drift_issues, unavailable_issues, warnings). RCA: runs whenever goalTracker/backlogProvider is
    enabled. `drift_issues` are BLOCKING and cover integrity-critical board currency: every
    in-scope item's closed/merged-vs-done state, adapter-unconfigured statuses, and verified current
    lane work whose board item is not in an active status. `warnings` are NON-blocking
    board-currency nudges for active-goal-ledger reconciliation when it is not the lane's current
    work item. `unavailable_issues` mean the board could
    not be reached (gh missing/unauthed/offline), surfaced as warnings that re-block once
    connectivity returns."""
    tracker = goal_tracker_config(data)
    provider = backlog_provider_config(data)
    if not (tracker.get("enabled") or provider.get("enabled")):
        return [], [], []
    # Only gh-missing / not-authenticated is treated as transient unavailability (offline). Any
    # other deterministic provider problem (query capability, status field/options config) is a
    # blocking config error, so the board gate cannot be bypassed by a misconfigured project (Codex P2).
    unavailable = goal_tracker_auth_issues(target)
    if unavailable:
        return [], unavailable, []
    config_errors = goal_tracker_status_issues(data, target)
    if config_errors:
        return [f"board provider config error: {issue}" for issue in config_errors], unavailable, []
    drift: list[str] = []
    # A taxonomy/schema mismatch (the adapter declares statuses/fields the board lacks) is NON-
    # blocking and routes to board-adopt -- it must never fail the sanctioned status-write path
    # closed, because that fail-closed pressure is exactly what drove the raw-gh board bypass
    # (operator decision + private lane RCA, 2026-06-25). The lane keeps the board's item status
    # accurate against the columns that DO exist; the adapter is realigned to the board, never the
    # board to the adapter.
    warnings: list[str] = [
        f"board schema mismatch — run 'tautline backlog-board-examine', answer the unknowns, then 'backlog-board-adopt --apply'; do NOT change the board: {issue}"
        for issue in goal_tracker_schema_mismatch_issues(data, target)
    ]
    # Resolve the lane's current work once (read-only): the outgoing branch/PR's board items and
    # the active ledger's mapped item. RCA Jun-16 #234 / Jun-17: the gate must reason about the
    # work actually in flight, not an unrelated ledger or a blind whole-project scan.
    scope = lane_work_scope(data, target)
    active_statuses = list(tracker.get("activeStatuses") or [])
    # Auth + config already passed, so a failure to LIST items is a deterministic project error.
    board_item_scan_limit = 400
    try:
        items = goal_tracker_items(data, target, limit=board_item_scan_limit)
    except SystemExit as exc:
        drift.append(f"GitHub Project item list could not be read for board reconciliation: {exc}")
        return drift, unavailable, warnings
    # Truncation hides stale items past the page, defeating "every in-scope board item" (Codex P2)
    # -- but as of the verified read layer (item 71 WS1) `goal_tracker_items` either returns a
    # COMPLETE set or raises, and the raise is already caught above and reported as drift. A
    # length heuristic here is now not just redundant but WRONG: the read escalates past the
    # requested page, so any board between this scan limit and the read ceiling would come back
    # complete and then be accused of truncation. Completeness is the read layer's guarantee; this
    # gate consumes it rather than re-deriving it from a page size it no longer controls.
    done_statuses = list(tracker.get("doneStatuses") or [])
    status_field = tracker.get("statusField", "")
    # The adapter enumerates every approved workflow status; an item in any other status (e.g. an
    # ad-hoc `In review`/QA column) is drift, independent of issue/PR state and checkable without a
    # fetch. RCA: lanes must ship straight to done, never park items in an unconfigured review column.
    configured_statuses = (
        list(tracker.get("readyStatuses") or [])
        + list(tracker.get("activeStatuses") or [])
        + done_statuses
        + list(tracker.get("blockedStatuses") or [])
    )
    active_work_refs: set[str] = set()
    subtask_parent_by_ref: dict[str, str] = {}
    for item in items:
        if not board_item_scope_current_work(item, scope):
            continue
        active_work_refs.update(board_item_ref_values(item))
        parent_ref = board_item_display_ref(item)
        subtasks, unavailable_subtasks, unmatched_subtasks = board_backed_subtask_items(item, items, target)
        if unavailable_subtasks:
            warnings.append(
                f"GitHub Project subtask status could not be verified for current work item {parent_ref}: "
                "native sub-issue enumeration unavailable"
            )
        if unmatched_subtasks:
            shown = ", ".join(unmatched_subtasks[:5])
            suffix = " ..." if len(unmatched_subtasks) > 5 else ""
            warnings.append(
                f"GitHub Project subtask status could not be tracked for current work item {parent_ref}: "
                f"native sub-issue(s) are not board items: {shown}{suffix}"
            )
        for subtask in subtasks:
            subtask_refs = board_item_ref_values(subtask)
            active_work_refs.update(subtask_refs)
            for subtask_ref in subtask_refs:
                subtask_parent_by_ref[subtask_ref] = parent_ref
    if goal_run is not None:
        # RCA Jun-17 + Codex review: the broad active-goal-ledger reconciliation is a NON-blocking
        # warning when it is not the current work item, so it does not block a push whose own board
        # item is current. The narrower active-work detector below blocks only on verified current
        # lane work.
        warnings.extend(f"active goal ledger: {issue}" for issue in goal_tracker_drift_issues(data, target, goal_run))
    for item in items:
        ref = board_item_display_ref(item)
        board_status = goal_tracker_item_field(item, status_field)
        unconfigured = board_item_unconfigured_status_drift(
            goal_tracker_item_title(item), board_item_display_ref(item), board_status, configured_statuses
        )
        if unconfigured:
            drift.append(unconfigured)
        try:
            state = board_item_fetch_state(item, target)
        except SystemExit as exc:
            # A real issue/PR whose state cannot be read is not assumed clean (Codex P1).
            drift.append(f"GitHub Project board item state could not be verified for {ref}: {exc}")
            continue
        message = board_item_state_drift(
            goal_tracker_item_title(item),
            board_item_display_ref(item),
            board_status,
            state,
            done_statuses,
        )
        if message:
            drift.append(message)
        # An item the lane is actively working must sit in an active status. RCA Jun-16 #234. Strong
        # current-work signals block: the outgoing branch/PR closes it, or a working-tree-changed
        # source-of-truth plan/spec maps to it. The ledger's mapped item also blocks when it is the
        # only current-work signal. When a branch/plan points elsewhere, ledger drift stays a warning
        # so a stale unrelated ledger cannot block a board-current branch. Board-backed native
        # subtasks of verified current work inherit the same status obligation: parent issue status
        # is not a substitute for subtask status.
        item_refs = board_item_ref_values(item)
        is_active_work = bool(item_refs.intersection(active_work_refs))
        subtask_parent_ref = next((subtask_parent_by_ref[ref] for ref in item_refs if ref in subtask_parent_by_ref), "")
        active_work_msg = board_item_active_work_drift(
            goal_tracker_item_title(item),
            board_item_display_ref(item),
            board_status,
            state,
            is_active_work,
            active_statuses,
            "subtask" if subtask_parent_ref else "item",
            subtask_parent_ref,
        )
        if active_work_msg:
            drift.append(active_work_msg)
    return drift, unavailable, warnings


def provider_board_business_lead_gaps(data: dict, target: Path) -> list[str]:
    """Non-blocking backfill: in-scope board items whose body does NOT lead with a plain-language
    business justification (`## What this delivers` / `## Why it matters`). Surfaced as warnings so
    existing rote/technical-only items get fixed over time, while new items are hard-blocked at
    export. Items with no body in the list payload are skipped (cannot judge -> never guess).
    Returns [] when the provider is disabled or unreachable. RCA: stakeholder items must lead with
    what is delivered and why it matters, not pure technical detail."""
    tracker = goal_tracker_config(data)
    provider = backlog_provider_config(data)
    if not (tracker.get("enabled") or provider.get("enabled")):
        return []
    if goal_tracker_auth_issues(target) or goal_tracker_status_issues(data, target):
        return []
    try:
        items = goal_tracker_items(data, target, limit=400)
    except SystemExit as exc:
        # DEGRADE LOUDLY. This returns [] either way -- the path is warning-only by design -- but
        # an empty list from "the board says nothing is missing" and an empty list from "the board
        # could not be read" are different facts, and silence made them identical. That is the same
        # confident-nothing this whole item is about, in the quietest place it appears.
        print(f"backlog_provider_board_lead_warn: board read incomplete ({exc})", file=sys.stderr)
        return []
    gaps: list[str] = []
    for item in items:
        body = goal_tracker_item_body(item)
        if not body.strip():
            continue
        if backlog_item_missing_business_lead(body):
            gaps.append(goal_tracker_item_url(item) or goal_tracker_item_title(item))
    return gaps


def print_provider_board_business_lead_warnings(data: dict, target: Path) -> list[str]:
    gaps = provider_board_business_lead_gaps(data, target)
    for ref in gaps:
        print(
            f"backlog_provider_board_lead_warn: {ref} does not lead with a business justification "
            "(`## What this delivers` / `## Why it matters`); update it so stakeholders see what it delivers and why it matters"
        )
    return gaps


def lane_unplaced_customer_facing_issues(data: dict, target: Path) -> list[str]:
    """RCA Jun-16 #316/#317: OPEN repo issues that read as customer-facing but are not on the
    Project board. 'Customer-facing' reuses board_export_non_customer_facing_signal (an issue that
    trips a tech-debt/internal marker is ignored) -- the same definition the board uses at export,
    so a bug filed with `gh issue create` (no label needed) is still caught. Returns issue URLs.
    [] on disabled/unreachable provider or unreadable issue list: this is a warning-only path and
    never blocks."""
    tracker = goal_tracker_config(data)
    provider = backlog_provider_config(data)
    if not (tracker.get("enabled") or provider.get("enabled")):
        return []
    if goal_tracker_auth_issues(target) or goal_tracker_status_issues(data, target):
        return []
    try:
        board_items = goal_tracker_items(data, target, limit=400)
    except SystemExit as exc:
        # Same degrade-loudly rule as the lead-gap scan above, and it matters more here: this one
        # reports issues MISSING from the board, so an unreadable board produces the most
        # reassuring possible answer -- nothing is missing -- from the least evidence.
        print(f"lane_unplaced_customer_facing_warn: board read incomplete ({exc})", file=sys.stderr)
        return []
    board_urls = {goal_tracker_item_url(it).rstrip("/") for it in board_items}
    try:
        payload = goal_tracker_gh_json(
            ["issue", "list", "--state", "open", "--limit", "200", "--json", "url,title,body"], target
        )
    except SystemExit:
        # P1-B: a non-zero `gh issue list` (restricted token / rate limit / transient) must not crash
        # the pre-push gate -- this is a warning-only path, so degrade to [] like the board fetch above.
        return []
    if not isinstance(payload, list):
        return []
    unplaced: list[str] = []
    for issue in payload:
        if not isinstance(issue, dict):
            continue
        url = str(issue.get("url") or "").rstrip("/")
        if not url or url in board_urls:
            continue
        if board_export_non_customer_facing_signal(str(issue.get("title") or ""), str(issue.get("body") or "")):
            continue  # tech-debt / internal -> not a board item
        unplaced.append(url)
    return unplaced


def print_unplaced_customer_facing_issue_warnings(data: dict, target: Path) -> list[str]:
    unplaced = lane_unplaced_customer_facing_issues(data, target)
    for url in unplaced:
        print(
            f"backlog_provider_board_unplaced_warn: {url} reads as customer-facing but is not on the "
            "stakeholder board; place it (`backlog-provider-export ...` or `gh project item-add`) with an "
            "Item Type + Status before the delivery boundary",
            file=sys.stderr,
        )
    return unplaced


# A board the gate cannot READ is not a board it can vouch for. gh auth login's
# DEFAULT scopes exclude read:project, so warn-on-unavailable turned every board
# gate into unread stderr noise on normally-authenticated machines -- months of
# "keep the board current" rules sat on a read that never succeeded (2026-07-17
# operator escalation; RCA 20260717T015328Z was one symptom). Dict, not list[str]:
# stays out of the policy-phrases SSOT collector.
BOARD_UNAVAILABLE_BLOCK = {
    "remedy": (
        "cannot verify the stakeholder board (provider unavailable); an authoritative "
        "board that cannot be read is NOT current -- fix auth with: "
        "gh auth refresh --hostname github.com -s read:project -s project "
        "(deliberate offline work: set backlogProvider.unavailablePolicy: warn)"
    ),
}


def backlog_provider_unavailable_policy(data: dict) -> str:
    """block (default): provider-unavailable fails the board gates. warn: explicit,
    audit-visible adapter opt-down for deliberate offline work."""
    provider = backlog_provider_config(data)
    tracker = goal_tracker_config(data)
    raw = (
        (provider.get("unavailablePolicy") if provider.get("enabled") else None)
        or (tracker.get("unavailablePolicy") if tracker.get("enabled") else None)
        or "block"
    )
    value = str(raw).strip().lower()
    if value not in {"block", "warn"}:
        raise SystemExit(
            "Project adapter backlogProvider.unavailablePolicy must be block or warn"
        )
    return value


def board_identity_mismatches(data: dict, target: Path) -> list[str]:
    """Synced goal sources whose recorded board identity disagrees with the adapter's pin.

    Item 71 WS2 / RCA 2026-07-02. Every synced source records the owner and project number it was
    read from; the adapter pins the board the lane is supposed to be reading. When those disagree,
    the lane has been reading a DIFFERENT BOARD and reporting on it confidently -- which is the
    incident, not a hypothetical: an ad-hoc discovery query resolved the wrong project and every
    downstream read inherited it.

    Never guesses. A source with no board lines at all predates this record or came from another
    path, and silence is the only honest answer for it -- inventing a mismatch from an absent fact
    would make the guard the same kind of confident-wrong this closes.
    """
    tracker = goal_tracker_config(data)
    pinned_owner = str(tracker.get("owner") or "").strip()
    pinned_number = str(tracker.get("projectNumber") or "").strip()
    if not pinned_owner or not pinned_number or pinned_number == "0":
        return []
    # A lane with no goal-source root has no synced sources to compare, and an adapter that does
    # not declare one is not misconfigured -- it is a lane that does not use this surface. Fail
    # open rather than crash a gate that every provider-backed push runs: the guard's whole
    # premise is that it only speaks when it has a recorded fact to speak about.
    if not data.get("goalArtifacts", {}).get("sourceOfTruth"):
        return []
    root = goal_source_root(data, target)
    if not root.is_dir():
        return []
    mismatches: list[str] = []
    for path in sorted(root.rglob("*.md")):
        # SECTION-SCOPED, through the parser the rest of this surface already uses. Codex R1 P2: a
        # whole-document regex reads any `- owner:` bullet a plan happens to contain -- a
        # requirements list, a stakeholder table -- and this gate BLOCKS, so a false positive stops
        # a lane over prose. `goal_tracker_source_values_from_plan` scopes to the generated
        # `## GitHub Project Source` section, and reusing it also means the guard reads identity
        # exactly where the sync writes it, rather than from a second parser that can drift.
        values = goal_tracker_source_values_from_plan(path)
        # `.get(...)` returning None, not truthiness, and that is the whole no-guessing rule: an
        # ABSENT field means the source predates this record or came from another path, and silence
        # is the only honest answer for it. Inventing a mismatch from a fact nobody wrote down
        # would make this guard the same confident-wrong it exists to catch. (An earlier draft
        # carried an explicit skip for sources with neither field; a mutation showed it changed no
        # behavior, so it is gone -- a defensive line no test can kill only misleads its reader.)
        owner = values.get("owner")
        number = values.get("project_number")
        if owner is not None and owner != pinned_owner:
            mismatches.append(
                f"{path_display(target, path)} was synced from owner {owner!r} but the adapter "
                f"pins {pinned_owner!r}; the lane has been reading a different board"
            )
        if number is not None and number != pinned_number:
            mismatches.append(
                f"{path_display(target, path)} was synced from project number {number} but the "
                f"adapter pins {pinned_number}; the lane has been reading a different board"
            )
    return mismatches


PENDING_CLOSEOUT_SCHEMA = "pending-closeout/v1"
PENDING_CLOSEOUT_FILENAME = "PENDING_CLOSEOUT.json"


def pending_closeout_path(data: dict, target: Path) -> Path:
    """Beside the goal run, resolved through `laneState` like every other lane artifact.

    Item 79 WS1. Pure lane state: written, read and cleared with no network at all, so the
    lane-local half of this control works on a plane. Only the boundary predicate's merge lookup
    touches the provider.
    """
    return goal_run_path(data, target).parent / PENDING_CLOSEOUT_FILENAME


def pending_closeout_record_exists(target: Path) -> bool:
    """Cheap, adapter-free existence probe, mirroring `goal_run_path_for_target`'s idiom.

    guard-check must not pay for adapter resolution on every boundary just to learn there is no
    record -- which is the common case.
    """
    try:
        return (goal_run_path_for_target(target).parent / PENDING_CLOSEOUT_FILENAME).is_file()
    except (OSError, KeyError, TypeError, json.JSONDecodeError):
        return False


def write_pending_closeout(
    data: dict, target: Path, pr_number: int, refs: list[str], repo: str | None = None
) -> Path:
    path = pending_closeout_path(data, target)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(
        json.dumps(
            {
                "schema": PENDING_CLOSEOUT_SCHEMA,
                "pr": int(pr_number),
                "recordedAt": now_iso(),
                # THE REPO TRAVELS WITH THE DEBT. A queued or cross-repo merge is settled by a
                # LATER boundary that has no `--repo` to pass, so without this the record's PR
                # number gets resolved against whatever PR shares it in the local checkout --
                # enforcing or clearing against the wrong PR entirely. Codex R3 P2.
                "repo": str(repo) if repo else None,
                "refs": [str(ref) for ref in refs],
            },
            indent=2,
            sort_keys=True,
        )
        + "\n",
        encoding="utf-8",
    )
    return path


def read_pending_closeout(data: dict, target: Path) -> dict | None:
    path = pending_closeout_path(data, target)
    if not path.is_file():
        return None
    try:
        record = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return None
    if not isinstance(record, dict) or record.get("schema") != PENDING_CLOSEOUT_SCHEMA:
        return None
    return record


def clear_pending_closeout(data: dict, target: Path) -> None:
    pending_closeout_path(data, target).unlink(missing_ok=True)


def closeout_pr_closing_refs(
    target: Path, pr_number: int, repo: str | None = None
) -> list[str] | None:
    """Issue numbers the given PR closes, via the same `gh` query shape lane_outgoing_issue_refs
    uses -- keyed on the PR number rather than the branch, because after a merge the branch may
    already be gone."""
    if shutil.which("gh") is None:
        return None
    code, payload, _ = command_json(
        ["gh", "pr", "view", str(pr_number), "--json", "closingIssuesReferences,url"]
        + (["--repo", repo] if repo else []),
        target,
        timeout=15,
    )
    if code != 0 or not isinstance(payload, dict):
        # UNREADABLE, NOT EMPTY. Returning [] here made a transient auth/network failure
        # indistinguishable from a PR that genuinely closes nothing -- so a merged PR with real
        # board drift would pass the fail-closed check and clear its own pending record on the way
        # through. None is the third answer the caller needs: "I could not find out." Codex R1 P2.
        return None
    # KEYED BY REPOSITORY, NOT BY BARE NUMBER. Issue 123 exists in every repository that has 123
    # issues; collapsing a cross-repo `owner/repo#123` to "123" let a board card from a DIFFERENT
    # repo satisfy this closeout while the real referenced issue stayed unreconciled. Codex R2 P2.
    # Format is `owner/repo#number`, which is also GitHub's own cross-repo notation.
    refs: list[str] = []
    for ref in payload.get("closingIssuesReferences") or []:
        if not isinstance(ref, dict):
            continue
        number = str(ref.get("number") or "").strip()
        if not number:
            continue
        key = f"{closeout_ref_repo(ref) or ''}#{number}".lstrip("#")
        if key not in refs:
            refs.append(key)
    return refs


def closeout_ref_repo(ref: dict) -> str | None:
    """`owner/repo` for a closing reference, from whichever shape the provider answered with."""
    repository = ref.get("repository")
    if isinstance(repository, dict):
        owner = repository.get("owner")
        owner_name = owner.get("login") if isinstance(owner, dict) else owner
        name = str(repository.get("name") or "").strip()
        if owner_name and name:
            return f"{str(owner_name).strip()}/{name}"
        full = str(repository.get("nameWithOwner") or "").strip()
        if full:
            return full
    return closeout_repo_from_url(str(ref.get("url") or ""))


def closeout_repo_from_url(url: str) -> str | None:
    """`owner/repo` out of an issue URL, or None when the URL is not one."""
    match = re.search(r"github\.com/([\w.-]+)/([\w.-]+)/issues/\d+", str(url or ""))
    return f"{match.group(1)}/{match.group(2)}" if match else None


def closeout_pr_merge_state(
    target: Path, pr_number: int, repo: str | None = None
) -> str | None:
    """`merged` / `closed` / `open`, or None when the provider could not answer.

    None is NOT a state -- it is the absence of one, and the boundary predicate treats it as such
    (D3: warn, never block). Collapsing it into `open` would silently mean "nothing owed".
    """
    if shutil.which("gh") is None:
        return None
    code, payload, _ = command_json(
        ["gh", "pr", "view", str(pr_number), "--json", "state,mergedAt"]
        + (["--repo", repo] if repo else []),
        target,
        timeout=15,
    )
    if code != 0 or not isinstance(payload, dict):
        return None
    if payload.get("mergedAt"):
        return "merged"
    return str(payload.get("state") or "").strip().lower() or None


def issue_is_unverifiable(issue: str) -> bool:
    """True when a closeout issue says "I could not look", not "the board is not done".

    The two boundaries in this feature answer an unreadable board differently on purpose (D3), so
    they need to be able to TELL them apart. Keyed on the phrases the fail-closed paths emit, kept
    beside them so a new refusal wording has to touch this list in the same edit.
    """
    text = str(issue or "")
    return any(
        marker in text
        for marker in (
            "could not be read",
            "is unavailable",
            "could not be read for closeout",
            "could not be verified",
        )
    )


def provider_closeout_issues(
    data: dict, target: Path, pr_number: int, repo: str | None = None
) -> list[str]:
    """Closing-ref issues of a merged PR that are not in a done status. FAIL-CLOSED (D1).

    Item 79 WS1 / the RCA cluster: work merged, the board never moved to done, and nothing
    noticed -- because the only check that could have ran BEFORE the merge, when the honest answer
    was still "not yet". This is the check that runs after.

    Fail-closed is the whole posture of the explicit verb: an unreachable provider is a FAILURE,
    not a pass, because "I could not look" and "nothing is owed" must never share an exit code.
    (The passive boundary predicate below is deliberately the opposite -- see D3.)

    CONSUMES the verified read layer (item 71): `goal_tracker_items` returns the complete set or
    raises, `limit` is a first-page hint and never a truncation guard, and completeness is never
    inferred from a count. A truncation surfaces as blocking, exactly as
    `provider_board_currency_issues` surfaces it.
    """
    tracker = goal_tracker_config(data)
    provider = backlog_provider_config(data)
    if not (tracker.get("enabled") or provider.get("enabled")):
        return []
    unavailable = goal_tracker_auth_issues(target) or goal_tracker_status_issues(data, target)
    if unavailable:
        return [
            "GitHub Project board is unavailable, so the closeout of PR "
            f"{pr_number} cannot be verified: {'; '.join(unavailable)}. This gate is fail-closed "
            "on purpose -- a board it could not read is not a board with nothing owed."
        ]
    refs = closeout_pr_closing_refs(target, pr_number, repo)
    if refs is None:
        # "I could not look" is the one answer this fail-closed verb must never round down to
        # "nothing is owed" -- the same distinction the docstring above draws for the provider.
        return [
            f"PR {pr_number}'s closing references could not be read, so whether the board owes a "
            "closeout is unknown. Fail-closed on purpose: re-run once `gh` can read the PR."
        ]
    if not refs:
        # Nothing to reconcile. `allowRepoOnlyGoals` lanes reach this legitimately and so does any
        # PR that closes no issue; either way there is no obligation to report.
        print(f"closeout_refs: none (PR {pr_number} closes no board-backed issue)")
        return []
    try:
        items = goal_tracker_items(data, target)
    except SystemExit as exc:
        return [
            f"GitHub Project item list could not be read for closeout of PR {pr_number}: {exc}"
        ]
    done_statuses = tracker.get("doneStatuses") or provider.get("doneStatuses") or []
    primary_done = done_statuses[0] if done_statuses else "Done"
    status_field = tracker.get("statusField") or provider.get("statusField") or "Status"
    # The board side is keyed the SAME way, or the two sides can never meet. A board item whose
    # repository cannot be determined is registered under its bare number too, so a single-repo
    # board (the common case, where the provider may not echo a repository at all) still matches.
    by_number: dict[str, dict] = {}
    # A bare number is only ever an ANSWER when it is unambiguous. Indexing every item under its
    # bare number let `other/repo#123` match `local/repo#123` -- the exact collision the qualified
    # key exists to prevent (Codex R3 P2). Counting first means a bare ref still matches the single
    # obvious item on a board that does not echo repositories, and matches NOTHING once two repos
    # both carry that number, which is the honest answer there.
    bare_counts: dict[str, int] = {}
    bare_items: dict[str, dict] = {}
    for item in items:
        content = item.get("content") if isinstance(item, dict) else None
        if not isinstance(content, dict):
            continue
        number = str(content.get("number") or "").strip()
        if not number:
            continue
        item_repo = closeout_ref_repo(content)
        if item_repo:
            by_number.setdefault(f"{item_repo}#{number}", item)
        bare_counts[number] = bare_counts.get(number, 0) + 1
        bare_items.setdefault(number, item)
    issues: list[str] = []
    for ref in refs:
        item = by_number.get(str(ref))
        if item is None:
            bare = str(ref).split("#", 1)[1] if "#" in str(ref) else str(ref)
            if bare_counts.get(bare) == 1:
                item = bare_items.get(bare)
        if item is None:
            issues.append(
                f"PR {pr_number} closes issue {ref}, but that issue is not on the board; place it "
                "or correct the closing reference before the closeout can be verified"
            )
            continue
        actual = goal_tracker_item_field(item, status_field)
        if not goal_tracker_status_matches(actual, done_statuses):
            issues.append(
                f"PR {pr_number} merged but issue {ref} is `{actual or 'none'}`, not a done "
                f"status; move it with `tautline backlog-provider-update --target . --item {ref} "
                f"--status {primary_done}`"
            )
    return issues


def pending_closeout_errors(data: dict, target: Path) -> list[str]:
    """Boundary predicate for the recorded pending closeout. FAILS OPEN, loudly (D3).

    The deliberate asymmetry with the verb above: this one runs passively at every status and
    prepush boundary, so a GitHub outage here would wedge every push on every lane over a fact
    only GitHub holds. It therefore blocks ONLY when it can verify the recorded PR is merged AND
    the closeout still fails. It never fails SILENTLY -- an unverifiable state prints a named
    warning saying the closeout is still owed.

    Scope fence (item 79 wave 2.1): called from the `status` and `prepush` boundaries only. The
    stop seam belongs to wave 3, which owns the Stop-guard surface and its aggregate false-positive
    budget; adding a blocking Stop condition from here is out of scope by construction.
    """
    record = read_pending_closeout(data, target)
    if not record:
        return []
    pr_number = record.get("pr")
    # The repo the debt was recorded AGAINST. This boundary has no `--repo` to be given, which is
    # exactly why the merge wrote it down. Codex R3 P2.
    record_repo = record.get("repo") or None
    state = (
        closeout_pr_merge_state(target, int(pr_number), record_repo) if pr_number else None
    )
    if state is None:
        print(
            f"pending_closeout_warn: cannot verify PR {pr_number} merge state (provider "
            f"unreachable); board closeout still owed -- run `tautline "
            f"backlog-provider-closeout-check --pr {pr_number}` when the provider returns.",
            file=sys.stderr,
        )
        return []
    if state == "closed":
        clear_pending_closeout(data, target)
        print(f"pending_closeout_cleared: PR {pr_number} closed without merging")
        return []
    if state != "merged":
        return []
    issues = provider_closeout_issues(data, target, int(pr_number), record_repo)
    if not issues:
        clear_pending_closeout(data, target)
        return []
    # D3: THIS boundary fails OPEN on an unverifiable read, and the explicit verb fails CLOSED.
    # That asymmetry is deliberate and it is the whole reason both exist -- a lane must be able to
    # keep pushing through a GitHub outage, while `backlog-provider-closeout-check` still refuses
    # to CERTIFY a closeout it could not see. Codex R2 P2: making the fail-closed diagnostics
    # blocking here wedged every push during an auth or API outage. The debt is NOT cleared on
    # this path -- it stays owed, and the next readable boundary enforces it.
    if all(issue_is_unverifiable(issue) for issue in issues):
        return [
            f"PR {pr_number} merged and its board closeout is still owed, but the board could not "
            f"be read to verify it: {issues[0]} (advisory -- the record stays until a readable "
            "check settles it; the board could not be read)"
        ]
    return [
        f"PR {pr_number} merged but its board closeout is not reconciled: {issue}"
        for issue in issues
    ] + [
        f"run `tautline backlog-provider-closeout-check --pr {pr_number}` once the board is "
        "current; this record clears when that check passes."
    ]


def backlog_provider_closeout_check(args: argparse.Namespace) -> int:
    """Explicit post-merge closeout gate: every issue a merged PR closes must be in a done status.

    FAIL-CLOSED by design (D1). Its green means verified, so an unreadable board is a failure
    rather than a pass. It ASSERTS and PRINTS -- there is no board write on this path, because a
    gate that fixes what it finds cannot be trusted to report honestly about it. Board-write
    authority stays with the sanctioned update commands.
    """
    data, _, target = lane_project(args)
    # The explicit verb honours an explicit `--repo`, and otherwise falls back to the repo the
    # merge recorded WITH the debt -- so settling a cross-repo closeout needs no extra flag.
    record = read_pending_closeout(data, target)
    recorded_repo = record.get("repo") if isinstance(record, dict) else None
    repo = getattr(args, "repo", None) or recorded_repo or None
    issues = provider_closeout_issues(data, target, int(args.pr), repo)
    for issue in issues:
        print(f"backlog_provider_closeout_issue: {issue}", file=sys.stderr)
    if issues:
        print(
            "backlog_provider_closeout_check: blocked - the board is not reconciled with the "
            f"merged PR {args.pr}; move the named item(s) to a done status and re-run",
            file=sys.stderr,
        )
        return 1
    # CLEAR ONLY THE DEBT THIS CHECK SETTLED. An unconditional clear meant a successful check for
    # PR B deleted PR A's pending record -- the still-unreconciled merge then had nothing left to
    # enforce it, which is the exact failure the record exists to prevent. Codex R1 P2.
    recorded_pr = record.get("pr") if isinstance(record, dict) else None
    if recorded_pr is not None and int(recorded_pr) != int(args.pr):
        print(
            f"backlog_provider_closeout_check: ok - PR {args.pr} closeout is reconciled; the "
            f"pending record for PR {recorded_pr} is untouched and still owed",
            file=sys.stderr,
        )
        return 0
    clear_pending_closeout(data, target)
    print(f"backlog_provider_closeout_check: ok - PR {args.pr} closeout is reconciled")
    return 0


def backlog_provider_board_check(args: argparse.Namespace) -> int:
    """Explicit board-currency gate for provider-backed lanes (used at boundaries and by the
    pre-push hook). Blocks on board drift AND (by default) on provider-unavailable -- an
    unreadable authoritative board is not current. unavailablePolicy: warn is the explicit
    adapter opt-down; --strict blocks on unavailability regardless of policy."""
    data, _, target = lane_project(args)
    tracker = goal_tracker_config(data)
    provider = backlog_provider_config(data)
    if not (tracker.get("enabled") or provider.get("enabled")):
        print("backlog_provider_board_check: provider not enabled; no board to keep current")
        return 0
    goal_run = load_goal_run(data, target) if goal_run_path(data, target).exists() else None
    drift, unavailable, warnings = provider_board_currency_issues(data, target, goal_run)
    for issue in unavailable:
        print(f"backlog_provider_board_warn: {issue}", file=sys.stderr)
    # RCA Jun-17: broad active-goal-ledger reconciliation remains a non-blocking warning when it is
    # not the current work item. Verified active-work status drift is returned as `drift` above and
    # blocks.
    for issue in warnings:
        print(f"backlog_provider_board_warn: {issue}", file=sys.stderr)
    # Non-blocking backfill: surface existing items missing the business-justification lead so they
    # get fixed over time (new items are hard-blocked at export). Does not fail the gate.
    print_provider_board_business_lead_warnings(data, target)
    # RCA Jun-16 #316/#317: warn (non-blocking) about customer-facing issues missing from the board.
    print_unplaced_customer_facing_issue_warnings(data, target)
    # Item 71 WS2. Blocks on the same exit-1 path as drift, and for the same reason: a board that
    # is not the pinned board is not "out of date", it is the wrong board, and every currency
    # answer computed from it is confidently wrong.
    # Item 79 WS2, D4(a). Closing-reference problems are blocking drift at prepush: a body that
    # binds nothing, or binds only the first of several, means the merge will auto-close nothing
    # and the post-merge closeout check will have no refs to verify. Cheapest to fix while the PR
    # is still editable, which is the whole reason this rides the prepush gate rather than waiting.
    branch_name = run_git(target, ["branch", "--show-current"]) or ""
    closing_ref_issues = outgoing_pr_closing_ref_issues(data, target, branch_name)
    for issue in closing_ref_issues:
        print(f"backlog_provider_board_issue: {issue}", file=sys.stderr)
    identity_mismatches = board_identity_mismatches(data, target)
    for issue in identity_mismatches:
        print(f"backlog_provider_board_identity: {issue}", file=sys.stderr)
    for issue in drift:
        print(f"backlog_provider_board_issue: {issue}", file=sys.stderr)
    if closing_ref_issues:
        print(
            "backlog_provider_board_check: blocked - the outgoing PR body does not bind the "
            "issues it closes; each line above carries its own fix",
            file=sys.stderr,
        )
        return 1
    if identity_mismatches:
        print(
            "backlog_provider_board_check: blocked - the recorded board identity does not match "
            "the adapter pin; re-sync the named sources from the pinned board, or correct "
            "`backlogProvider.owner`/`projectNumber` if the pin itself is wrong",
            file=sys.stderr,
        )
        return 1
    if drift:
        print("backlog_provider_board_check: blocked - the stakeholder board is out of date; see backlog_provider_board_issue lines above for the specific item(s) and fix", file=sys.stderr)
        return 1
    if unavailable and (
        getattr(args, "strict", False)
        or backlog_provider_unavailable_policy(data) == "block"
    ):
        print(
            f"backlog_provider_board_check: blocked - {BOARD_UNAVAILABLE_BLOCK['remedy']}",
            file=sys.stderr,
        )
        return 1
    tracker_owner = str(goal_tracker_config(data).get("owner") or "").strip()
    tracker_number = str(goal_tracker_config(data).get("projectNumber") or "").strip()
    if tracker_owner and tracker_number and tracker_number != "0":
        print(f"board_identity: {tracker_owner}/projects/{tracker_number}")
    print("backlog_provider_board_check: ok")
    return 0


def backlog_provider_active_check(args: argparse.Namespace) -> int:
    """Fast hook gate for active local work still showing Ready/Backlog on the stakeholder board."""
    data, _, target = lane_project(args)
    tracker = goal_tracker_config(data)
    provider = backlog_provider_config(data)
    if not (tracker.get("enabled") or provider.get("enabled")):
        print("backlog_provider_active_check: provider not enabled; no board to keep current")
        return 0
    goal_run = load_goal_run(data, target) if goal_run_path(data, target).exists() else None
    drift, unavailable, warnings = provider_board_currency_issues(data, target, goal_run)
    for issue in unavailable:
        print(f"backlog_provider_active_warn: {issue}", file=sys.stderr)
    if unavailable and (
        getattr(args, "strict", False)
        or backlog_provider_unavailable_policy(data) == "block"
    ):
        print(
            f"backlog_provider_active_check: blocked - {BOARD_UNAVAILABLE_BLOCK['remedy']}",
            file=sys.stderr,
        )
        return 1
    for issue in warnings:
        print(f"backlog_provider_active_warn: {issue}", file=sys.stderr)
    active_drift = [issue for issue in drift if "understates progress" in issue]
    for issue in active_drift:
        print(f"backlog_provider_active_issue: {issue}", file=sys.stderr)
    if active_drift:
        print("backlog_provider_active_check: blocked - active local work is not in an active board status", file=sys.stderr)
        return 1
    print("backlog_provider_active_check: ok")
    return 0


def ci_test_gate_config(data: dict) -> dict:
    return {**DEFAULT_CI_TEST_GATE, **(data.get("ciTestGate") or {})}


def normalize_ci_test_gate(data: dict) -> dict:
    """Validate + normalize the adapter ciTestGate block. Type-checks rather than coerces, so an
    invalid value (a non-dict block, events:[1], requiredWorkflow:null) is rejected, not silently
    normalized into a bogus string (Codex P3)."""
    raw = data.get("ciTestGate")
    if raw is not None and not isinstance(raw, dict):
        raise SystemExit("Project adapter ciTestGate must be an object")
    cfg = {**DEFAULT_CI_TEST_GATE, **(raw or {})}
    if not isinstance(cfg.get("enabled"), bool):
        raise SystemExit("Project adapter ciTestGate.enabled must be boolean")
    if cfg["enforcement"] not in {"warn", "block"}:
        raise SystemExit("Project adapter ciTestGate.enforcement must be warn or block")
    events = cfg.get("events", [])
    if not isinstance(events, list) or not events or any(not isinstance(ev, str) or not ev.strip() for ev in events):
        raise SystemExit("Project adapter ciTestGate.events must be a non-empty array of non-blank strings")
    cfg["events"] = [ev.strip() for ev in events]
    markers = cfg.get("testCommandMarkers", [])
    if not isinstance(markers, list) or any(not isinstance(m, str) or not m.strip() for m in markers):
        raise SystemExit("Project adapter ciTestGate.testCommandMarkers must be an array of non-blank strings")
    cfg["testCommandMarkers"] = [m.strip() for m in markers]
    required_workflow = cfg.get("requiredWorkflow", "")
    if not isinstance(required_workflow, str):
        raise SystemExit("Project adapter ciTestGate.requiredWorkflow must be a string")
    cfg["requiredWorkflow"] = required_workflow.strip()
    if Path(cfg["requiredWorkflow"]).is_absolute():
        raise SystemExit("Project adapter ciTestGate.requiredWorkflow must be a workflow filename, not an absolute path")
    if "expectTests" in cfg and not isinstance(cfg["expectTests"], bool):
        raise SystemExit("Project adapter ciTestGate.expectTests must be boolean")
    if not isinstance(cfg.get("requiredCheckName", ""), str):
        raise SystemExit("Project adapter ciTestGate.requiredCheckName must be a string")
    cfg["requiredCheckName"] = str(cfg.get("requiredCheckName", "")).strip()
    return cfg


def normalize_ui_evidence(data: dict) -> dict:
    raw = data.get("uiEvidence")
    if raw is not None and not isinstance(raw, dict):
        raise SystemExit("Project adapter uiEvidence must be an object")
    cfg = {**DEFAULT_UI_EVIDENCE, **(raw or {})}
    issue_raw = (raw or {}).get("issueComments", {}) if isinstance(raw, dict) else {}
    if issue_raw is not None and not isinstance(issue_raw, dict):
        raise SystemExit("Project adapter uiEvidence.issueComments must be an object")
    cfg["issueComments"] = {**DEFAULT_UI_EVIDENCE["issueComments"], **(issue_raw or {})}

    if not isinstance(cfg.get("enabled"), bool):
        raise SystemExit("Project adapter uiEvidence.enabled must be boolean")
    if cfg["enforcement"] not in {"off", "warn", "block"}:
        raise SystemExit("Project adapter uiEvidence.enforcement must be off, warn, or block")
    if str(cfg.get("tool", "")).strip() != "playwright":
        raise SystemExit("Project adapter uiEvidence.tool must be playwright")
    cfg["tool"] = "playwright"
    for key in ("evidenceDir", "manifestGlob", "captureCommand"):
        if not isinstance(cfg.get(key, ""), str):
            raise SystemExit(f"Project adapter uiEvidence.{key} must be a string")
        cfg[key] = str(cfg.get(key, "")).strip()
    if not cfg["evidenceDir"]:
        raise SystemExit("Project adapter uiEvidence.evidenceDir must be non-blank")
    if Path(cfg["evidenceDir"]).is_absolute() or ".." in Path(cfg["evidenceDir"]).parts:
        raise SystemExit("Project adapter uiEvidence.evidenceDir must stay inside the project")
    if not cfg["manifestGlob"]:
        raise SystemExit("Project adapter uiEvidence.manifestGlob must be non-blank")

    allowed_events = UI_EVIDENCE_EVENTS
    required_events = cfg.get("requiredEvents", [])
    if not isinstance(required_events, list) or any(not isinstance(ev, str) or not ev.strip() for ev in required_events):
        raise SystemExit("Project adapter uiEvidence.requiredEvents must be an array of non-blank strings")
    cfg["requiredEvents"] = [ev.strip() for ev in required_events]
    invalid_required = sorted(set(cfg["requiredEvents"]) - allowed_events)
    if invalid_required:
        raise SystemExit(
            "Project adapter uiEvidence.requiredEvents may contain only "
            "milestone-complete, goal-complete, and work-item-complete"
        )

    comments = cfg["issueComments"]
    if not isinstance(comments.get("enabled"), bool):
        raise SystemExit("Project adapter uiEvidence.issueComments.enabled must be boolean")
    if comments.get("provider") != "github-issues":
        raise SystemExit("Project adapter uiEvidence.issueComments.provider must be github-issues")
    if not isinstance(comments.get("required"), bool):
        raise SystemExit("Project adapter uiEvidence.issueComments.required must be boolean")
    trigger_events = comments.get("triggerEvents", [])
    if not isinstance(trigger_events, list) or any(not isinstance(ev, str) or not ev.strip() for ev in trigger_events):
        raise SystemExit("Project adapter uiEvidence.issueComments.triggerEvents must be an array of non-blank strings")
    comments["triggerEvents"] = [ev.strip() for ev in trigger_events]
    invalid_triggers = sorted(set(comments["triggerEvents"]) - allowed_events)
    if invalid_triggers:
        raise SystemExit(
            "Project adapter uiEvidence.issueComments.triggerEvents may contain only "
            "milestone-complete, goal-complete, and work-item-complete"
        )
    if comments["enabled"] and not comments["triggerEvents"]:
        raise SystemExit("Project adapter uiEvidence.issueComments.triggerEvents must be non-empty when comments are enabled")
    return cfg


def ui_evidence_config(data: dict) -> dict:
    return normalize_ui_evidence(data)


adapter_command_is_configured = _adapters_mod.adapter_command_is_configured


adapter_test_command_tokens = _adapters_mod.adapter_test_command_tokens


adapter_test_run_command_tokens = _adapters_mod.adapter_test_run_command_tokens


CI_TEST_FILE_PRUNE_DIRS = {
    ".git", "node_modules", "vendor", "dist", "build", "out", ".next", ".turbo", ".cache",
    "__pycache__", ".venv", "venv", "target", "coverage", ".pytest_cache", ".mypy_cache",
}



def runtime_config(data: dict) -> dict:
    return {**DEFAULT_RUNTIME_CONFIG, **(data.get("runtimeConfig") or {})}


# Runner names that mark a preflight command as exercising a rendered user surface. A TUPLE, not a
# list: UPPER_CASE list-of-str constants are collected into the policy-phrase SSOT, and this is
# detection vocabulary, not policy phrasing (test_policy_phrases_ssot).
UI_SURFACE_RUNNER_MARKERS = ("playwright", "cypress", "e2e", "selenium", "puppeteer", "storybook")

# Every state but `block` is posture drift. Ordered for the summary tally.
CONTROL_POSTURE_STATES = ("block", "warn", "off", "empty", "unreachable")


def posture_config_text(value: object) -> str:
    """Read an adapter text field: a JSON null is an ABSENT value, not the word "None".

    `str(None)` is `"None"` -- truthy, 4 characters long, and indistinguishable from a real
    setting. The same trap cost the classified-findings contract a round (0.52.0), and every
    field this engine reads comes from adapter JSON where `null` is a legal way to write
    "unset". Reporting a control as configured because its value is null would be a false green
    in the one surface that exists to make false greens visible.
    """
    return "" if value is None else str(value).strip()


def posture_enforcement_state(cfg: dict) -> str:
    """The enforcement string of a control, with null and blank both meaning off."""
    return posture_config_text(cfg.get("enforcement")) or "off"


# A command routed through a generic runner ("npm run e2e", "make ui-capture") says nothing
# distinctive in its FIRST word: every other command using the same runner matches it, so
# `captureCommand: "npm run e2e"` would be satisfied by `fullPreflight: "npm ci && pytest"`.
# A tuple, deliberately, so it stays out of the policy-phrase SSOT.
# Generic TEST runners belong here for the same reason as the package managers: `pytest
# tests/e2e` and `pytest tests/unit` share their first word, so keeping `pytest` would report
# the unit preflight as exercising the UI surface. The runners that DO name a surface --
# playwright, cypress and the rest of UI_SURFACE_RUNNER_MARKERS -- are deliberately absent.
GENERIC_COMMAND_RUNNERS = (
    "npm", "pnpm", "yarn", "npx", "bun", "bunx", "make", "just", "task", "poetry", "uv",
    "pipenv", "pip", "python", "python3", "node", "deno", "go", "cargo", "dotnet", "mvn",
    "gradle", "bundle", "rake", "docker", "compose", "run", "exec", "&&", "-m",
    "pytest", "tox", "nox", "unittest", "jest", "vitest", "mocha", "jasmine", "karma",
    "rspec", "minitest", "phpunit", "pest", "junit", "test",
)


def surface_command_token(command: str) -> str:
    """The first word of `command` that names something, not the runner it is routed through."""
    for word in command.split():
        token = word.strip().lower()
        if token and token not in GENERIC_COMMAND_RUNNERS and not token.startswith("-"):
            return token
    return ""


def preflight_exercises_token(preflight: str, preflight_words: set[str], token: str) -> bool:
    """Does the binding preflight actually run this surface token?

    A bare substring test is too generous for a short token -- "ui" is a substring of "build",
    so a plain `npm run build` would report a UI surface as exercised. Short tokens must match a
    WORD of the preflight; a long one (a criticalJourneys featurePath such as `app/checkout`)
    can only ever appear as a substring, so it keeps that path.
    """
    if not token:
        return False
    if token in preflight_words:
        return True
    return len(token) >= 4 and token in preflight


def ci_test_gate_posture_row(data: dict, target: Path | None = None) -> dict:
    """The ciTestGate row, which has to answer a question its `enforcement` string cannot.

    `ci_test_gate_issues` short-circuits to `[]` in two ways, and in both the gate is OFF no
    matter what its enforcement says: `enabled: false`, and the expectTests self-disable taken
    when no tests are detected. Reporting `block` for either is exactly the
    off-control-looks-healthy bug this engine exists to kill.

    The self-disable is conditional on a filesystem fact, so it is resolved exactly when a target
    is available and reported from configuration alone otherwise -- and with no target, only an
    EXPLICIT `expectTests: false` counts, because an absent flag on an unseen repo is not evidence
    of anything.
    """
    cfg = ci_test_gate_config(data)
    if not cfg.get("enabled", True):
        return {"control": "ciTestGate", "state": "off",
                "detail": "ciTestGate.enabled=false: the gate never runs"}
    expect_tests = cfg.get("expectTests")
    if expect_tests is None:
        expect_tests = bool(data.get("deploymentTargets"))
    if not expect_tests:
        if target is None:
            if cfg.get("expectTests") is False:
                return {"control": "ciTestGate", "state": "off",
                        "detail": "expectTests=false: the gate self-disables on a test-less repo"}
        elif not repo_has_tests(data, target)[0]:
            return {"control": "ciTestGate", "state": "off",
                    "detail": "no tests detected and expectTests is not set: "
                              "the gate self-disables"}
    return {"control": "ciTestGate", "state": posture_enforcement_state(cfg), "detail": ""}


def readiness_posture_row(data: dict) -> dict:
    """The detection-baseline gate is readiness.ENFORCEMENT (schema: "Default off"; consumed by
    `readiness_review`). `readiness.sources` is only a required file list, so keying the row on it
    reports a false green for the control the go-live RCA cared most about: canary, errorId alarms
    and branch protection all off."""
    readiness = data.get("readiness") or {}
    state = posture_enforcement_state(readiness).lower()
    # `sources` is in the REACHABILITY list and never in the state: readiness_review refuses
    # outright without it, so an opted-in lane with no sources cannot run the gate at all -- but
    # a populated sources list is only a file inventory and is no evidence that anything is
    # enforced, which is the false green this row exists to stop reporting.
    missing = [
        name for name, value in (
            ("sources", readiness.get("sources") or []),
            ("canaryWorkflow", posture_config_text(readiness.get("canaryWorkflow"))),
            ("alarmSources", readiness.get("alarmSources") or []),
            ("requiredChecks", readiness.get("requiredChecks") or []),
        ) if not value
    ]
    if state == "block" and missing:
        # Opted in, but the gate has nothing to check: unreachable, not healthy.
        state = "unreachable"
    detail = ""
    if missing:
        detail = ("detection baseline incomplete: " + ", ".join(missing)
                  + " unset (readiness-review refuses without sources; canary + errorId alarms "
                  + "+ branch-protection checks are its substance)")
    return {"control": "readiness", "state": state, "detail": detail}


def binding_preflight_row(data: dict) -> dict:
    """The cluster spec's named dangerous shape: a BINDING preflight that cannot exercise the
    declared primary user surface. The binding gate is commands.fastPreflight/fullPreflight,
    rendered as the before-commit/before-push gate -- a distinct row from "uiEvidence off on a
    UI-bearing project", which is about evidence capture rather than about what the gate runs."""
    commands = data.get("commands") or {}
    preflight = " ".join(
        posture_config_text(commands.get(key)) for key in ("fastPreflight", "fullPreflight")
    ).lower()
    preflight_words = {word for word in re.split(r"[^a-z0-9]+", preflight) if word}
    ui = {**DEFAULT_UI_EVIDENCE, **(data.get("uiEvidence") or {})}
    surface_tokens: list[str] = []
    capture = posture_config_text(ui.get("captureCommand"))
    if ui.get("enabled") and capture:
        surface_tokens.append(surface_command_token(capture))
    surface_tokens.extend(
        posture_config_text(j.get("featurePath") or j.get("name")).lower()
        for j in (data.get("criticalJourneys") or []) if isinstance(j, dict)
    )
    surface_tokens.extend(UI_SURFACE_RUNNER_MARKERS)
    declares_surface = bool(
        ui.get("enabled")
        or (data.get("criticalJourneys") or [])
        or (data.get("deploymentTargets") or [])
    )
    if not preflight.strip():
        return {"control": "bindingPreflight", "state": "unreachable",
                "detail": "commands.fastPreflight/fullPreflight are empty: "
                          "the binding gate runs nothing"}
    if not declares_surface:
        return {"control": "bindingPreflight", "state": "unreachable",
                "detail": ("no declared user surface for the binding preflight "
                           "(commands.fullPreflight) to exercise: uiEvidence disabled, "
                           "criticalJourneys empty, no deploymentTargets")}
    if not any(preflight_exercises_token(preflight, preflight_words, t) for t in surface_tokens):
        return {"control": "bindingPreflight", "state": "unreachable",
                "detail": ("binding preflight (commands.fastPreflight/fullPreflight) runs no check "
                           "that exercises the declared primary user surface")}
    return {"control": "bindingPreflight", "state": "block", "detail": ""}


def gate_reachability_row(control: str, cfg: dict, gap: str) -> dict:
    """A control whose gate cannot run is `empty`, whatever its enforcement string claims.

    `enforcement: block` over an unset scan path is the off-control-looks-healthy bug wearing
    the strongest word in the vocabulary. When enforcement is already `off` that is the stronger
    and simpler truth, so it wins -- both read as drift either way.
    """
    state = posture_enforcement_state(cfg)
    if gap and state != "off":
        state = "empty"
    return {"control": control, "state": state, "detail": gap}


def remediation_ledger_gap(cfg: dict, target: Path | None) -> str:
    """`remediation_issues` returns [] outright when the ledger file is absent, so an enforcing
    remediation gate over a missing ledger checks nothing. Requires a target to observe."""
    if target is None:
        return ""
    ledger = posture_config_text(cfg.get("ledgerPath")) or DEFAULT_REMEDIATION["ledgerPath"]
    try:
        exists = configured_path(target, ledger).exists()
    except (SystemExit, OSError, ValueError):
        # A path the containment check refuses is another gate's business; a DIAGNOSTIC that
        # raises here would take the whole status surface down over a config error.
        return f"remediation.ledgerPath {ledger!r} is unusable: the obligation check runs nothing"
    return "" if exists else (
        f"no remediation ledger at {ledger}: the obligation check returns nothing"
    )


def go_live_profile_active(data: dict) -> bool:
    """Has this lane opted in to the go-live profile?

    Deliberately strict about the shape: a non-object block or a misspelled profile value is NOT an
    active profile, so this never reports an opt-in that `go_live_posture_issues` is about to refuse
    as malformed. It answers "is this lane held to the six gates", nothing more.
    """
    raw = data.get("goLiveReadiness")
    if not isinstance(raw, dict):
        return False
    return raw.get("profile") == "live-tenant"


def go_live_posture_issues(data: dict, rows: list[dict]) -> tuple[list[str], list[str]]:
    """Returns ``(failing_issues, warn_lines)`` for the go-live readiness profile (policy 16a).

    THE ENFORCEMENT BOUNDARY IS THE DESIGN, and it is chosen against a measured constraint rather
    than out of caution. `methodology-status --target . --fail-on-drift` is the mandated lane-start
    command rendered into every generated adapter, and `adapters/projects/example-saas.json`
    already carries a `milestoneClose` deployment target. A drift failure keyed on "milestone-close
    target without the profile" would therefore red every live-surface lane at session start on
    upgrade, with no migration -- the adapter-removal 0.6.115 class, where a control shipped faster
    than the lanes could adopt it and had to be reverted.

    So:

    * A lane that has OPTED IN (`profile: live-tenant`) is held to the gates: every go-live control
      must be at `block`, or carry a recorded decline with a real reason.
    * A lane that has NOT opted in gets at most one WARN line, which never enters any `*_failures`
      list at any flag combination -- including `--strict` and `--fail-on-drift`.
    * The forcing function is a shipped, tested switch rather than silence: `enforcement: block`
      turns the un-opted live-surface case into drift. It ships now and defaults to `warn`; flipping
      the default is a separately released change gated on the adoption checklist.

    A decline is not a loophole: it is a recorded, reviewable statement that this lane has weighed
    the control and declined it, with a reason long enough to be a reason.
    """
    # Normalize BEFORE consuming. Adapter validation deliberately continues with semantic checks
    # when the installed schema is unreadable, so a malformed value reaches here -- and a truthy
    # non-object like `goLiveReadiness: "live-tenant"` used to raise TypeError out of
    # methodology-status. A crash is not an actionable adapter error: it tells the adopter nothing
    # about which key is wrong, and it takes down the surface that would have told them.
    raw = data.get("goLiveReadiness")
    if raw is not None and not isinstance(raw, dict):
        return (
            [
                "goLiveReadiness must be an object with `profile`/`enforcement`/`declines` "
                f"(found {type(raw).__name__}); fix it in the SOURCE adapter and re-render"
            ],
            [],
        )
    cfg = {**DEFAULT_GO_LIVE_READINESS, **(raw or {})}
    raw_declines = cfg.get("declines") or []
    if not isinstance(raw_declines, list):
        return (
            [
                "goLiveReadiness.declines must be an array of {control, reason} objects "
                f"(found {type(raw_declines).__name__}); fix it in the SOURCE adapter and re-render"
            ],
            [],
        )
    # Malformed entries grant NO exemption, and the types are checked rather than coerced.
    #
    # Codex R2: `str()` coercion turned any value into a candidate reason, so `reason: 123456789012`
    # or a list of words cleared the twelve-character floor and silenced a control -- malformed
    # configuration DISABLING enforcement, which is the fail-open shape this program keeps finding.
    # The schema requires strings; when the schema is unreadable (a supported fail-open path) this
    # is the only thing standing between a typo and a disabled gate.
    declines = {
        item["control"]: item["reason"].strip()
        for item in raw_declines
        if isinstance(item, dict)
        and isinstance(item.get("control"), str)
        and isinstance(item.get("reason"), str)
    }
    live_surface = any(
        isinstance(entry, dict) and entry.get("milestoneClose")
        for entry in (data.get("deploymentTargets") or [])
    )
    # Validate the SCALARS against their enums before branching on them, and fail toward the
    # stricter reading. Codex R3, and it is the third round to find a fail-open in this same
    # input-validation surface -- so this closes the CLASS rather than the field: a typo such as
    # `profile: "live_tenant"` used to read as the un-opted case and, with the default warn
    # enforcement, contributed no failure at all while enforcing none of the go-live controls. An
    # intended `enforcement: "blocK"` similarly fell back to warning.
    #
    # A misspelled opt-in is the most dangerous input here, because the lane that wrote it BELIEVES
    # it is covered. Refusing it by name is the only answer that leaves the adopter better off than
    # silence.
    # An UNKNOWN key is the same defect one level up, and the enum check above cannot see it: a
    # lane that writes `{"profil": "live-tenant"}` merges cleanly over the defaults, reads as
    # profile `off`, and is told nothing -- while believing it opted in. Rejecting by name is the
    # only outcome that leaves that adopter better off than silence, and on the unreadable-schema
    # path this is again the only thing between a typo and a disabled gate. Codex R2.
    unknown = sorted(set(raw or {}) - set(DEFAULT_GO_LIVE_READINESS))
    if unknown:
        return [
            f"goLiveReadiness has unknown key(s) {', '.join(repr(k) for k in unknown)}; supported "
            f"keys are {', '.join(sorted(DEFAULT_GO_LIVE_READINESS))}. A misspelled key reads as "
            "un-opted and enforces nothing -- fix it in the SOURCE adapter and re-render"
        ], []
    invalid: list[str] = []
    for field, allowed in (("profile", GO_LIVE_PROFILES), ("enforcement", GO_LIVE_ENFORCEMENTS)):
        value = cfg.get(field)
        if not isinstance(value, str) or value not in allowed:
            invalid.append(
                f"goLiveReadiness.{field} must be one of {'/'.join(allowed)} (found {value!r}); "
                "fix it in the SOURCE adapter and re-render"
            )
    if invalid:
        return invalid, []
    if cfg.get("profile") != "live-tenant":
        declined = declines.get(GO_LIVE_PROFILE_DECLINE_KEY, "")
        if not live_surface or len(declined) >= GO_LIVE_DECLINE_MIN_REASON:
            return [], []
        message = (
            "milestone-close deployment target without goLiveReadiness.profile live-tenant: "
            "declare the profile, or record a goLiveReadiness.profile decline with a reason of "
            f"at least {GO_LIVE_DECLINE_MIN_REASON} characters (policy 16a). Adopt with "
            "`goLiveReadiness: {\"profile\": \"live-tenant\"}` in the "
            "SOURCE adapter, then re-render"
        )
        if str(cfg.get("enforcement", "warn")) == "block":
            return [message], []
        return [], [message]
    issues: list[str] = []
    by_control = {row["control"]: row for row in rows}
    for control in GO_LIVE_CONTROLS:
        state = (by_control.get(control) or {"state": "off"})["state"]
        if state == "block":
            continue
        if len(declines.get(control, "")) >= GO_LIVE_DECLINE_MIN_REASON:
            continue
        # Codex R1 P2: "set it to enforcement block" is a DEAD END for a control that has no
        # enforcement field -- `criticalJourneys` is an array, and `readiness`/`flakyQuarantine`
        # report `unreachable` until their paths or sources exist. The posture row already carries
        # the specific detail and default status output hides it, so the refusal carries it here.
        # A refusal naming a fix the adopter cannot perform is the dead-end class this program
        # exists to delete.
        detail = str((by_control.get(control) or {}).get("detail") or "").strip()
        remedy = f" ({detail})" if detail else ""
        issues.append(
            f"go-live control {control} is {state} with no recorded decline{remedy}: bring the "
            "control to `block` -- for enforcement-keyed controls set `enforcement: block`, for "
            "the others populate what the detail names -- or record a "
            f"`goLiveReadiness.declines` entry naming {control} with a reason of at least "
            f"{GO_LIVE_DECLINE_MIN_REASON} characters (policy 16a)"
        )
    return issues, []


def control_posture_rows(data: dict, target: Path | None = None) -> list[dict]:
    """One row per known quality control: {control, state, detail}.

    `state` is one of CONTROL_POSTURE_STATES, and anything but `block` is posture drift on a
    live-surface lane (go-live readiness; the gating profile and its policy module ship in PR-C).
    Diagnostic here: no row produced by this function enters any `*_failures` list, at any flag
    combination, in this release.
    """
    rows: list[dict] = []

    def enforcement_row(control: str, cfg: dict, detail: str = "") -> None:
        rows.append(
            {"control": control, "state": posture_enforcement_state(cfg), "detail": detail}
        )

    rows.append(ci_test_gate_posture_row(data, target))
    ui = {**DEFAULT_UI_EVIDENCE, **(data.get("uiEvidence") or {})}
    if ui.get("enabled"):
        enforcement_row("uiEvidence", ui)
    else:
        rows.append({
            "control": "uiEvidence",
            "state": "off",
            "detail": ("disabled while deploymentTargets declare a user surface"
                       if data.get("deploymentTargets") else "disabled"),
        })
    rows.append(binding_preflight_row(data))
    rc = runtime_config(data)
    # A registry nothing checks is not a control. Naming the secrets is half the gate; the other
    # half is the command that asserts them at boot -- with neither command set, this row would
    # report `block` while nothing on the lane ever verifies a single declared secret, which is the
    # precise shape the #448 class produced. Treated as `empty` (the missing-INPUT state) rather
    # than as weak enforcement, because the enforcement string is not what is missing.
    rc_asserted = bool(rc.get("bootAssertionCommand") or rc.get("secretParityCommand"))
    if not rc.get("requiredSecrets"):
        rc_state, rc_detail = "empty", (
            "no required runtime secrets registered (boot-time secret assertion is unguarded)"
        )
    elif not rc_asserted:
        rc_state, rc_detail = "empty", (
            "secrets are registered but neither bootAssertionCommand nor secretParityCommand is "
            "set: nothing asserts them, so the registry records an intention, not a check"
        )
    else:
        rc_state, rc_detail = posture_enforcement_state(rc), ""
    rows.append({
        "control": "runtimeConfig.requiredSecrets",
        "state": rc_state,
        "detail": rc_detail,
    })
    journeys = data.get("criticalJourneys") or []
    rows.append({
        "control": "criticalJourneys",
        "state": "block" if journeys else "empty",
        "detail": "" if journeys
                  else "no declared critical journeys: the pending ratchet guards nothing",
    })
    fq = {**DEFAULT_FLAKY_QUARANTINE, **(data.get("flakyQuarantine") or {})}
    try:
        max_markers = int(fq.get("maxMarkers", -1))
    except (TypeError, ValueError):
        # normalize_flaky_quarantine rejects a non-integer at load, so a lane never reaches here
        # with one -- but this function is public and PR-C consumes it, and a DIAGNOSTIC that
        # raises on a malformed field takes the whole status surface down with it.
        max_markers = -1
    unbounded = max_markers < 0 or not posture_config_text(fq.get("scanPath"))
    rows.append({
        "control": "flakyQuarantine",
        "state": "empty" if unbounded else posture_enforcement_state(fq),
        "detail": "no repo-wide marker ratchet (maxMarkers<0 or scanPath unset)"
                  if unbounded else "",
    })
    rows.append(readiness_posture_row(data))
    # Two gates short-circuit on a missing INPUT rather than on their enforcement string, so
    # `enforcement: block` over an unset path or an absent ledger scans nothing at all.
    ms = {**DEFAULT_MIGRATION_SAFETY, **(data.get("migrationSafety") or {})}
    rows.append(gate_reachability_row(
        "migrationSafety", ms,
        "" if posture_config_text(ms.get("migrationsPath"))
        else "migrationSafety.migrationsPath unset: migration_safety_issues scans nothing",
    ))
    rem = {**DEFAULT_REMEDIATION, **(data.get("remediation") or {})}
    rows.append(gate_reachability_row("remediation", rem, remediation_ledger_gap(rem, target)))
    for key, default in (
        ("healthContract", DEFAULT_HEALTH_CONTRACT),
        ("sideEffectProof", DEFAULT_SIDE_EFFECT_PROOF),
        ("planAcceptance", DEFAULT_PLAN_ACCEPTANCE),
        ("coverageFloor", DEFAULT_COVERAGE_FLOOR),
    ):
        enforcement_row(key, {**default, **(data.get(key) or {})})
    return rows


def control_posture_summary_line(rows: list[dict]) -> str:
    counts = dict.fromkeys(CONTROL_POSTURE_STATES, 0)
    drift = []
    for row in rows:
        counts[row["state"]] = counts.get(row["state"], 0) + 1
        if row["state"] != "block":
            drift.append(f"{row['control']}={row['state']}")
    tally = " ".join(f"{key}={counts[key]}" for key in CONTROL_POSTURE_STATES)
    return f"control_posture: {tally} drift={','.join(drift) if drift else 'none'}"


def control_posture_detail_line(row: dict, prefix: str) -> str:
    suffix = f" - {row['detail']}" if row.get("detail") else ""
    return f"{prefix}: {row['control']} {row['state']}{suffix}"


def normalize_development_environment(data: dict) -> dict:
    raw = data.get("developmentEnvironment")
    if raw is not None and not isinstance(raw, dict):
        raise SystemExit("Project adapter developmentEnvironment must be an object")
    windows_raw = (raw or {}).get("windows") or {}
    if not isinstance(windows_raw, dict):
        raise SystemExit("Project adapter developmentEnvironment.windows must be an object")
    line_endings_raw = (raw or {}).get("lineEndings") or {}
    if not isinstance(line_endings_raw, dict):
        raise SystemExit("Project adapter developmentEnvironment.lineEndings must be an object")
    cfg = {
        **DEFAULT_DEVELOPMENT_ENVIRONMENT,
        **(raw or {}),
    }
    cfg["windows"] = {
        **DEFAULT_DEVELOPMENT_ENVIRONMENT["windows"],
        **windows_raw,
    }
    cfg["lineEndings"] = {
        **DEFAULT_DEVELOPMENT_ENVIRONMENT["lineEndings"],
        **line_endings_raw,
    }
    runtimes = cfg.get("supportedRuntimes", [])
    if not isinstance(runtimes, list):
        raise SystemExit("Project adapter developmentEnvironment.supportedRuntimes must be an array")
    normalized_runtimes: list[str] = []
    for runtime in runtimes:
        if not isinstance(runtime, str) or not runtime.strip():
            raise SystemExit("Project adapter developmentEnvironment.supportedRuntimes must contain non-blank strings")
        runtime = runtime.strip().lower()
        if runtime not in SUPPORTED_DEVELOPMENT_RUNTIMES:
            raise SystemExit(
                "Project adapter developmentEnvironment.supportedRuntimes may contain only "
                "linux, darwin, wsl1, wsl2, or win32"
            )
        if runtime not in normalized_runtimes:
            normalized_runtimes.append(runtime)
    cfg["supportedRuntimes"] = normalized_runtimes
    windows = cfg["windows"]
    if windows["native"] not in {"unspecified", "unsupported", "supported", "diagnostic-only"}:
        raise SystemExit("Project adapter developmentEnvironment.windows.native must be unspecified, unsupported, supported, or diagnostic-only")
    if windows["supportedRuntime"] not in {"wsl2", "win32"}:
        raise SystemExit("Project adapter developmentEnvironment.windows.supportedRuntime must be wsl2 or win32")
    if windows["native"] in {"unsupported", "diagnostic-only"} and "win32" in cfg["supportedRuntimes"]:
        raise SystemExit(
            "Project adapter developmentEnvironment cannot include win32 in supportedRuntimes "
            f"when windows.native is {windows['native']}"
        )
    if windows["native"] == "supported" and "win32" not in cfg["supportedRuntimes"]:
        raise SystemExit(
            "Project adapter developmentEnvironment must include win32 in supportedRuntimes "
            "when windows.native is supported"
        )
    for key in ("setup", "reason"):
        if not isinstance(windows.get(key, ""), str):
            raise SystemExit(f"Project adapter developmentEnvironment.windows.{key} must be a string")
        windows[key] = windows.get(key, "").strip()
    line_endings = cfg["lineEndings"]
    if line_endings["policy"] not in {"", "lf", "crlf", "mixed"}:
        raise SystemExit("Project adapter developmentEnvironment.lineEndings.policy must be lf, crlf, mixed, or blank")
    if not isinstance(line_endings.get("windowsGuidance", ""), str):
        raise SystemExit("Project adapter developmentEnvironment.lineEndings.windowsGuidance must be a string")
    line_endings["windowsGuidance"] = line_endings.get("windowsGuidance", "").strip()
    return cfg


def development_environment_status(data: dict, runtime: str | None = None) -> dict:
    cfg = normalize_development_environment({"developmentEnvironment": data.get("developmentEnvironment")})
    runtime = runtime or detected_development_runtime()
    supported = cfg.get("supportedRuntimes") or []
    issues: list[str] = []
    warnings: list[str] = []
    if supported and runtime not in supported:
        if runtime == "win32" and cfg["windows"]["native"] == "unsupported":
            setup = cfg["windows"].get("setup") or "Run lane gates from WSL2, not native Windows PowerShell/CMD."
            reason = cfg["windows"].get("reason")
            detail = f"; {reason}" if reason else ""
            issues.append(
                "native Windows is not a supported lane runtime for this adapter; "
                f"{setup}{detail}"
            )
        else:
            issues.append(
                "detected runtime "
                f"{runtime} is not in adapter-supported runtimes: {', '.join(supported)}"
            )
    elif not supported:
        warnings.append("adapter does not declare supported development runtimes; using compatibility mode")
    if runtime == "win32" and cfg["windows"]["native"] == "diagnostic-only":
        warnings.append("native Windows is diagnostic-only for this adapter; use WSL2 for lane gates and release evidence")
    line_policy = cfg.get("lineEndings", {}).get("policy", "")
    line_guidance = cfg.get("lineEndings", {}).get("windowsGuidance", "")
    return {
        "runtime": runtime,
        "supportedRuntimes": supported,
        "windowsNative": cfg["windows"]["native"],
        "windowsSupportedRuntime": cfg["windows"]["supportedRuntime"],
        "lineEndingPolicy": line_policy,
        "lineEndingGuidance": line_guidance,
        "issues": issues,
        "warnings": warnings,
    }


def print_development_environment_status(data: dict) -> list[str]:
    status = development_environment_status(data)
    supported = ",".join(status["supportedRuntimes"]) if status["supportedRuntimes"] else "unspecified"
    print(
        "development_environment: "
        f"runtime={status['runtime']} supported={supported} "
        f"windows_native={status['windowsNative']} windows_runtime={status['windowsSupportedRuntime']}"
    )
    if status["lineEndingPolicy"]:
        print(f"development_environment_line_endings: policy={status['lineEndingPolicy']}")
    if status["lineEndingGuidance"]:
        print(f"development_environment_windows_guidance: {status['lineEndingGuidance']}")
    for warning in status["warnings"]:
        print(f"development_environment_warn: {warning}")
    for issue in status["issues"]:
        print(f"development_environment_issue: {issue}")
    return status["issues"]


def normalize_runtime_config(data: dict) -> dict:
    """Validate + normalize the optional runtimeConfig block (required-runtime-secret registry).
    Type-checks rather than coerces; never SystemExits merely because a customer-facing adapter has no
    registry (that is an advisory surfaced by runtime_secret_fallback_issues, not a load-time wedge)."""
    raw = data.get("runtimeConfig")
    if raw is not None and not isinstance(raw, dict):
        raise SystemExit("Project adapter runtimeConfig must be an object")
    cfg = {**DEFAULT_RUNTIME_CONFIG, **(raw or {})}
    if cfg["enforcement"] not in {"warn", "block"}:
        raise SystemExit("Project adapter runtimeConfig.enforcement must be warn or block")
    secrets = cfg.get("requiredSecrets", [])
    if not isinstance(secrets, list):
        raise SystemExit("Project adapter runtimeConfig.requiredSecrets must be an array")
    norm: list[dict] = []
    for entry in secrets:
        if not isinstance(entry, dict):
            raise SystemExit("Project adapter runtimeConfig.requiredSecrets[] entries must be objects")
        name = entry.get("name")
        if not isinstance(name, str) or not name.strip():
            raise SystemExit("Project adapter runtimeConfig.requiredSecrets[].name must be a non-blank string")
        norm.append({**entry, "name": name.strip()})
    cfg["requiredSecrets"] = norm
    for key in ("bootAssertionCommand", "secretParityCommand"):
        if not isinstance(cfg.get(key, ""), str):
            raise SystemExit(f"Project adapter runtimeConfig.{key} must be a string")
        cfg[key] = str(cfg.get(key, "")).strip()
    return cfg


def required_secret_names(data: dict) -> list[str]:
    return [s["name"] for s in runtime_config(data)["requiredSecrets"] if isinstance(s, dict) and s.get("name")]




def runtime_secret_fallback_issues(data: dict, target: Path) -> list[str]:
    """Issues for the required-runtime-secret registry (FM3/P4, the #448 class): (1) a customer-facing
    adapter (deploymentTargets) that declares NO required-secret registry is advised to declare one;
    (2) any source file that reads a registered required secret with a degrade-to-empty fallback
    (?? '' / || '') -- the idiom that turns a missing secret into a silent 500."""
    issues: list[str] = []
    names = required_secret_names(data)
    if not names:
        if data.get("deploymentTargets"):
            issues.append(
                "runtimeConfig.requiredSecrets is empty for a customer-facing product: declare the secrets that "
                "must be present at runtime so a missing one fails the deploy loudly (boot fail-fast / secret-parity) "
                "instead of silently degrading to an empty string and 500ing (the #448 class)"
            )
        return issues
    scanned = 0
    try:
        for root, dirs, files in os.walk(target):
            dirs[:] = [d for d in dirs if d not in CI_TEST_FILE_PRUNE_DIRS and not d.startswith(".")]
            for filename in files:
                if not filename.endswith(RUNTIME_SECRET_SCAN_EXTENSIONS):
                    continue
                scanned += 1
                if scanned > 20000:
                    return issues
                path = Path(root) / filename
                try:
                    text = path.read_text(encoding="utf-8", errors="replace")
                except OSError:
                    continue
                for name in required_secret_fallback_findings(text, names):
                    issues.append(
                        f"required secret `{name}` is read with a degrade-to-empty fallback (?? '' / || '') in "
                        f"{path.relative_to(target)}: a missing required secret must fail loudly, not silently "
                        "become an empty string"
                    )
    except OSError:
        pass
    return issues


def print_runtime_secret_status(data: dict, target: Path) -> list[str]:
    cfg = runtime_config(data)
    issues = runtime_secret_fallback_issues(data, target)
    print(
        f"runtime_secret_registry: enforcement={cfg['enforcement']} "
        f"required_secrets={len(cfg['requiredSecrets'])} status={'drift' if issues else 'ok'}"
    )
    for issue in issues:
        print(f"runtime_secret_issue: {issue}")
    return issues


DESTRUCTIVE_SQL_PATTERNS = [
    (r"\bdrop\s+table\b", "DROP TABLE"),
    (r"\bdrop\s+column\b", "DROP COLUMN"),
    (r"\bdrop\s+constraint\b", "DROP CONSTRAINT"),
    (r"\btruncate\b", "TRUNCATE"),
    (r"\bset\s+not\s+null\b", "SET NOT NULL"),
]


def destructive_sql_findings(text: str) -> list[str]:
    """Pure: which classes of un-guarded destructive DDL appear in a SQL migration (DROP TABLE/COLUMN/
    CONSTRAINT, TRUNCATE, SET NOT NULL). Line comments are stripped so commented-out SQL is ignored."""
    low = re.sub(r"--[^\n]*", " ", text.lower())
    found: list[str] = []
    for pattern, label in DESTRUCTIVE_SQL_PATTERNS:
        if label not in found and re.search(pattern, low):
            found.append(label)
    return found


def normalize_migration_safety(data: dict) -> dict:
    raw = data.get("migrationSafety")
    if raw is not None and not isinstance(raw, dict):
        raise SystemExit("Project adapter migrationSafety must be an object")
    cfg = {**DEFAULT_MIGRATION_SAFETY, **(raw or {})}
    if cfg["enforcement"] not in {"warn", "block"}:
        raise SystemExit("Project adapter migrationSafety.enforcement must be warn or block")
    for key in ("migrationsPath", "ackMarker"):
        if not isinstance(cfg.get(key, ""), str):
            raise SystemExit(f"Project adapter migrationSafety.{key} must be a string")
        cfg[key] = str(cfg.get(key, "")).strip()
    if not cfg["ackMarker"]:
        cfg["ackMarker"] = DEFAULT_MIGRATION_SAFETY["ackMarker"]
    return cfg


def migration_safety_issues(data: dict, target: Path) -> list[str]:
    """Opt-in (migrationSafety.migrationsPath): flag any .sql migration with un-guarded destructive DDL
    that lacks an expand-contract acknowledgement marker (FM1/data-durability)."""
    cfg = {**DEFAULT_MIGRATION_SAFETY, **(data.get("migrationSafety") or {})}
    path_glob = str(cfg.get("migrationsPath") or "").strip()
    if not path_glob:
        return []
    ack = str(cfg.get("ackMarker") or DEFAULT_MIGRATION_SAFETY["ackMarker"]).strip().lower()
    files: list[Path] = []
    for candidate in sorted(target.glob(path_glob)):
        if candidate.is_file() and candidate.suffix == ".sql":
            files.append(candidate)
        elif candidate.is_dir():
            files.extend(sorted(p for p in candidate.rglob("*.sql") if p.is_file()))
    issues: list[str] = []
    for migration in files:
        try:
            text = migration.read_text(encoding="utf-8", errors="replace")
        except OSError:
            continue
        findings = destructive_sql_findings(text)
        if findings and ack not in text.lower():
            issues.append(
                f"migration {migration.relative_to(target)} has un-guarded destructive DDL "
                f"({', '.join(findings)}) with no expand-contract acknowledgement: make it reversible/"
                f"expand-contract or add a reviewed '{cfg.get('ackMarker') or DEFAULT_MIGRATION_SAFETY['ackMarker']}' marker comment"
            )
    return issues


def print_migration_safety_status(data: dict, target: Path) -> list[str]:
    cfg = {**DEFAULT_MIGRATION_SAFETY, **(data.get("migrationSafety") or {})}
    issues = migration_safety_issues(data, target)
    print(f"migration_safety: enforcement={cfg['enforcement']} path={cfg.get('migrationsPath') or 'none'} status={'drift' if issues else 'ok'}")
    for issue in issues:
        print(f"migration_safety_issue: {issue}")
    return issues


